def final_province_names() -> list[str]:
    """Return exactly 100 unique names with capitals/cities on planned IDs."""
    special = set(SPECIAL_PROVINCE_NAMES.values())
    generic = [name for name in PROVINCE_NAMES if name not in special]
    result = [""] * MAX_PROVINCES
    for pid, name in SPECIAL_PROVINCE_NAMES.items():
        result[pid - 1] = name
    pos = 0
    for i in range(MAX_PROVINCES):
        if result[i]:
            continue
        result[i] = generic[pos]
        pos += 1
    if len(set(result)) != MAX_PROVINCES:
        raise RuntimeError("Карта: имена провинций не уникальны")
    return result


def format_money(value: int | float) -> str:
    sign = "-" if value < 0 else ""
    return sign + "$" + f"{abs(int(value)):,}".replace(",", " ")


def format_number(value: int | float) -> str:
    return f"{int(value):,}".replace(",", " ")


def country_display(code: str) -> str:
    return f"{COUNTRY_FLAGS.get(code, '🌍')} {COUNTRY_NAMES.get(code, code)}"


def game_time_text(world: "WorldState") -> str:
    minutes = max(0, int(world.game_minutes))
    days, rem = divmod(minutes, 1440)
    hours, mins = divmod(rem, 60)
    return f"День {days + 1}, {hours:02d}:{mins:02d}"


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def ensure_dict(value: Any, fallback: Optional[dict] = None) -> dict:
    return value if isinstance(value, dict) else (fallback or {})


@dataclass
class Province:
    id: int
    name: str
    country: str
    neighbors: list[int] = field(default_factory=list)
    city: bool = False
    capital: bool = False
    sea_access: bool = False
    terrain: str = "plain"
    river: bool = False
    bridge: bool = False
    road_level: int = 2
    rail_level: int = 2
    road_condition: float = 100.0
    rail_condition: float = 100.0
    industrial_level: int = 1
    condition: float = 100.0
    buildings: dict[str, int] = field(default_factory=dict)
    building_condition: dict[str, float] = field(default_factory=dict)
    armies: list[str] = field(default_factory=list)
    air_groups: list[str] = field(default_factory=list)
    pvo_units: list[str] = field(default_factory=list)
    fleets: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Province":
        data = dict(d)
        data["id"] = int(data.get("id", 0))
        data["name"] = str(data.get("name", f"Провинция {data['id']}"))
        data["country"] = str(data.get("country", COUNTRY_RAZBAGARE))
        data["neighbors"] = [int(x) for x in data.get("neighbors", [])]
        data["building_condition"] = {k: float(v) for k, v in data.get("building_condition", {}).items()}
        data.setdefault("road_condition", 100.0)
        data.setdefault("rail_condition", 100.0)
                                                                               
        payload = {name: data[name] for name in cls.__dataclass_fields__ if name in data}
        return cls(**payload)

    def building_level(self, key: str) -> int:
        return int(self.buildings.get(key, 0))

    def condition_of(self, key: str) -> float:
        return float(self.building_condition.get(key, 100.0))

    def is_building_operational(self, key: str) -> bool:
        return self.building_level(key) > 0 and self.condition_of(key) > 0

    def owner_name(self) -> str:
        return country_display(self.country)

    def add_building(self, key: str, amount: int = 1) -> None:
        self.buildings[key] = self.building_level(key) + int(amount)
        self.building_condition[key] = 100.0

    def damage(self, key: str, amount: float) -> float:
        self.building_condition[key] = clamp(self.condition_of(key) - abs(float(amount)), 0, 100)
        return self.building_condition[key]

    def repair(self, key: str, amount: float) -> float:
        self.building_condition[key] = clamp(self.condition_of(key) + abs(float(amount)), 0, 100)
        return self.building_condition[key]


@dataclass
class Country:
    code: str
    name: str
    flag: str
    population: int
    manpower: int
    budget: int
    income_daily: int
    civilian_factories: int
    military_factories: int
    power_plants: int
    power_capacity: int
    substations: int
    substation_capacity: int
    stability: float
    war_support: float
    resources: dict[str, int] = field(default_factory=lambda: copy.deepcopy(INITIAL_RESOURCES))
    warehouse: dict[str, int] = field(default_factory=lambda: copy.deepcopy(INITIAL_WAREHOUSE))
    province_ids: list[int] = field(default_factory=list)
    production_lines: dict[str, dict[str, Any]] = field(default_factory=dict)
    active_decisions: dict[str, dict[str, Any]] = field(default_factory=dict)
    message_history: list[dict[str, Any]] = field(default_factory=list)
    relations: dict[str, int] = field(default_factory=dict)
    infinite_weapons: bool = False
    industry_modifier: float = 1.0
    construction_modifier: float = 1.0
    repair_modifier: float = 1.0
    business_centers: int = 0
    war_exhaustion: float = 0.0

    @classmethod
    def new(cls, code: str) -> "Country":
                                                                           
                                                                                   
        meta = BASE_COUNTRY_STATS.copy()
        c = cls(code, COUNTRY_NAMES[code], COUNTRY_FLAGS[code], **meta)
        c.relations = {other: 0 for other in PLAYABLE_COUNTRIES if other != code}
        return c

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Country":
        raw = dict(d)
        for k, default in {
            "resources": INITIAL_RESOURCES, "warehouse": INITIAL_WAREHOUSE, "province_ids": [],
            "production_lines": {}, "active_decisions": {}, "message_history": [], "relations": {},
        }.items():
            raw.setdefault(k, copy.deepcopy(default))
        for k in RESOURCE_KEYS: raw["resources"].setdefault(k, 0)
        for k in EQUIPMENT_KEYS: raw["warehouse"].setdefault(k, 0)
        return cls(**{name: raw.get(name) for name in cls.__dataclass_fields__})

    def ensure_warehouse(self) -> None:
        for key in EQUIPMENT_KEYS:
            self.warehouse.setdefault(key, 0)

    def ensure_resources(self) -> None:
        for key in RESOURCE_KEYS:
            self.resources.setdefault(key, 0)

    def change_budget(self, delta: int) -> int:
        self.budget += int(delta)
        return self.budget

    def can_spend(self, amount: int) -> bool:
        return self.budget >= int(amount)

    def spend(self, amount: int) -> bool:
        if not self.can_spend(amount): return False
        self.budget -= int(amount); return True

    def add_resource(self, key: str, amount: int) -> int:
        self.ensure_resources(); self.resources[key] = self.resources.get(key, 0) + int(amount); return self.resources[key]

    def take_resource(self, key: str, amount: int) -> bool:
        self.ensure_resources(); amount=max(0,int(amount))
        if self.resources.get(key,0) < amount: return False
        self.resources[key]-=amount; return True

    def add_equipment(self, key: str, amount: int) -> int:
        self.ensure_warehouse(); self.warehouse[key]=self.warehouse.get(key,0)+int(amount); return self.warehouse[key]

    def has_equipment(self, key: str, amount: int) -> bool:
        self.ensure_warehouse(); return self.infinite_weapons or self.warehouse.get(key,0) >= int(amount)

    def take_equipment(self, key: str, amount: int) -> bool:
        self.ensure_warehouse(); amount=max(0,int(amount))
        if self.infinite_weapons: return True
        if self.warehouse.get(key,0) < amount: return False
        self.warehouse[key]-=amount; return True


@dataclass
class Player:
    user_id: int
    username: str = ""
    country: Optional[str] = None
                                                                        
                                                                   
    active_country: Optional[str] = None
                                                                            
                                                     
    admin_mode: bool = False
    role: str = "player"
    banned: bool = False
    online: bool = True
    current_screen: str = "home"
    current_message_id: Optional[int] = None
    pending_input: Optional[str] = None
    pending_data: dict[str, Any] = field(default_factory=dict)
    last_seen: float = field(default_factory=time.time)

    @property
    def is_admin(self) -> bool:
        return self.role == "admin" and not self.banned

    def touch(self, username: str = "") -> None:
        if username: self.username = username
        self.online = True
        self.last_seen = time.time()

    def clear_input(self) -> None:
        self.pending_input = None
        self.pending_data = {}

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Player":
        data = dict(d)
        data.setdefault("user_id", 0)
        data.setdefault("username", "")
        data.setdefault("country", None)
        data.setdefault("active_country", None)
        data.setdefault("admin_mode", bool(data.get("role") == "admin" and data.get("country") is None))
        data.setdefault("role", "player")
        data.setdefault("banned", False)
        data.setdefault("online", False)
        data.setdefault("current_screen", "home")
        data.setdefault("current_message_id", None)
        data.setdefault("pending_input", None)
        data.setdefault("pending_data", {})
        data.setdefault("last_seen", time.time())
        payload = {name: data[name] for name in cls.__dataclass_fields__ if name in data}
        return cls(**payload)


@dataclass
class War:
    id: str
    attacker: str
    defender: str
    active: bool = True
    started: int = 0
    ended: Optional[int] = None
    goal: str = ""
    attacker_score: float = 0.0
    defender_score: float = 0.0

    def involves(self, country: str) -> bool:
        return country in (self.attacker, self.defender)

    def opponent(self, country: str) -> Optional[str]:
        if country == self.attacker: return self.defender
        if country == self.defender: return self.attacker
        return None


class WorldState:
    """Single in-memory world. All mutable systems share this object."""
    def __init__(self) -> None:
        self.simulation_lock = asyncio.Lock()
        self.state_lock = RLock()
        self.settings: dict[str, Any] = {
            "autosave_enabled": True,
            "autosave_minutes": 30,
            "warehouse_update_minutes": WAREHOUSE_UPDATE_MINUTES,
            "movement_cells_per_day": MOVEMENT_CELLS_PER_DAY,
            "combat_tick_minutes": 5,
            "air_tick_minutes": 10,
            "trade_tick_minutes": 60,
        }
        self.speed: float = 1.0
        self.paused: bool = False
        self.game_minutes: float = 0.0
        self.dirty: bool = False
        self.countries: dict[str, Country] = {}
        self.provinces: dict[int, Province] = {}
        self.players: dict[int, Player] = {}
        self.divisions: dict[str, dict[str, Any]] = {}
        self.generals: dict[str, dict[str, Any]] = {}
        self.air_groups: dict[str, dict[str, Any]] = {}
        self.pvo_units: dict[str, dict[str, Any]] = {}
        self.fleets: dict[str, dict[str, Any]] = {}
        self.wars: dict[str, War] = {}
        self.war_goals: dict[str, dict[str, Any]] = {}
        self.treaties: dict[str, dict[str, Any]] = {}
        self.trades: dict[str, dict[str, Any]] = {}
        self.decisions: dict[str, dict[str, Any]] = {}
        self.construction_projects: dict[str, dict[str, Any]] = {}
        self.repairs: dict[str, dict[str, Any]] = {}
        self.news: dict[str, dict[str, Any]] = {}
        self.events: dict[str, dict[str, Any]] = {}
        self.journal: list[dict[str, Any]] = []
        self.logs: list[dict[str, Any]] = []
        self._ids: dict[str, int] = {}
        self._reset_world()

    def _next_id(self, prefix: str) -> str:
        self._ids[prefix] = int(self._ids.get(prefix, 0)) + 1
        return f"{prefix}-{self._ids[prefix]}"

    def _reset_world(self) -> None:
        with self.state_lock:
            self.countries = {code: Country.new(code) for code in PLAYABLE_COUNTRIES}
            self.provinces = {}
            self.players = {}
            self.divisions = {}; self.generals = {}; self.air_groups = {}; self.pvo_units = {}; self.fleets = {}
            self.wars = {}; self.war_goals = {}; self.treaties = {}; self.trades = {}; self.decisions = {}
            self.construction_projects = {}; self.repairs = {}; self.news = {}; self.events = {}; self.journal=[]; self.logs=[]; self._ids={}
            self.game_minutes = 0.0; self.dirty = False; self.paused=False; self.speed=1.0
            self._make_map()
            self._seed_industry()

    def _make_map(self) -> None:
        names = final_province_names()
        if len(MAP_OWNERS) != 10 or any(len(row) != 10 for row in MAP_OWNERS):
            raise RuntimeError("Карта должна быть 10x10")

                                                                             
                                                         
        for i in range(1, MAX_PROVINCES + 1):
            row, col = divmod(i - 1, 10)
            symbol = MAP_OWNERS[row][col]
            owner = MAP_SYMBOL_TO_COUNTRY[symbol]
            neigh = []
            if row > 0: neigh.append(i - 10)
            if row < 9: neigh.append(i + 10)
            if col > 0: neigh.append(i - 1)
            if col < 9: neigh.append(i + 1)

            terrain = MAP_TERRAIN_BY_ROW[row]
            if i in set(SPECIAL_PROVINCE_NAMES):
                terrain = "urban"
            p = Province(
                id=i,
                name=names[i - 1],
                country=owner,
                neighbors=neigh,
                city=i in {x for ids in SPECIAL_CITY_IDS.values() for x in ids},
                capital=i in set(SPECIAL_CAPITAL_IDS.values()),
                                                                              
                                                                                
                sea_access=row in (0, 9) or col in (0, 9),
                terrain=terrain,
                river=(i % 7 == 0),
                bridge=(i % 11 == 0),
                road_level=2 + (i % 3),
                rail_level=1 + ((i + 1) % 3),
                industrial_level=1,
            )
            p.buildings = {k: 0 for k in (
                "civ_factory", "mil_factory", "mine", "npz", "metallurgy",
                "oilwell", "oil_processing", "components", "power", "substation",
                "airfield", "naval_base", "fort", "radar", "business"
            )}
            p.building_condition = {k: 100.0 for k in p.buildings}
            self.provinces[i] = p
            self.countries[owner].province_ids.append(i)

                                                                               
                                                               
        counts = {code: len(c.province_ids) for code, c in self.countries.items()}
        if counts != {COUNTRY_RAZBAGARE: 34, COUNTRY_PEDAGOG: 33, COUNTRY_MARKLAND: 33}:
            raise RuntimeError(f"Неверное распределение карты: {counts}")
        for a in PLAYABLE_COUNTRIES:
            for b in PLAYABLE_COUNTRIES:
                if a < b and not self.country_share_border(a, b):
                    raise RuntimeError(f"Страны не граничат: {a} / {b}")
        for code in PLAYABLE_COUNTRIES:
            if not any(self.provinces[pid].sea_access for pid in self.countries[code].province_ids):
                raise RuntimeError(f"У {code} нет выхода к морю")

                                                                              
                                                                  
        for code, c in self.countries.items():
            capital_pid = SPECIAL_CAPITAL_IDS[code]
            self.provinces[capital_pid].add_building("airfield", 1)

                                                                                 
                                                                               
                                                              
            border_candidates = [
                pid for pid in c.province_ids
                if any(self.provinces[n].country != code for n in self.provinces[pid].neighbors)
            ]
            border_candidates = [pid for pid in border_candidates if pid != capital_pid]
            if border_candidates:
                second_airfield = min(border_candidates, key=lambda pid: abs(pid - capital_pid))
            else:
                second_airfield = SPECIAL_CITY_IDS[code][0]
            self.provinces[second_airfield].add_building("airfield", 1)

            sea = next((pid for pid in c.province_ids if self.provinces[pid].sea_access), None)
            if sea is None:
                raise RuntimeError(f"Нет морской провинции для {code}")
            self.provinces[sea].add_building("naval_base", 1)

    def _seed_industry(self) -> None:
        for code,c in self.countries.items():
            ids=c.province_ids
            for kind,count in (("mine",6),("npz",4),("metallurgy",2),("oil_processing",1)):
                for pid in ids[:count]: self.provinces[pid].add_building(kind,1)
            for pid in ids:
                p=self.provinces[pid]
                if p.capital:
                    p.add_building("civ_factory",2); p.add_building("mil_factory",8); p.add_building("power",1)
                elif p.city:
                    p.add_building("civ_factory",1); p.add_building("mil_factory",3)

    def mark_dirty(self) -> None:
        self.dirty=True

    def add_log(self, kind: str, user_id: Optional[int], data: dict[str, Any]) -> None:
        entry={"time":self.game_minutes,"kind":kind,"user_id":user_id,"data":copy.deepcopy(data)}
        self.logs.append(entry); self.logs=self.logs[-5000:]; self.dirty=True

    def add_journal(self, category: str, title: str, text: str, country: Optional[str]=None) -> str:
        jid=self._next_id("journal")
        self.journal.append({"id":jid,"time":self.game_minutes,"category":category,"title":title,"text":text,"country":country})
        self.journal=self.journal[-5000:]; self.dirty=True
        return jid

    def register_player(self, user_id: int, username: str="") -> Player:
        player=self.players.get(user_id)
        if player is None:
            player=Player(user_id=user_id,username=username or str(user_id)); self.players[user_id]=player
        else: player.touch(username)
        return player

    def set_country(self, user_id: int, code: Optional[str]) -> bool:
        """Assign a player to one country; a playable country has one human owner."""
        player = self.register_player(user_id)
        if code is not None and code not in PLAYABLE_COUNTRIES:
            return False
        if code is not None and player.role != "admin":
            for other in self.players.values():
                if other.user_id != player.user_id and not other.banned and other.role != "admin" and other.country == code:
                    return False
        old = player.country
        player.country = code
        if code in PLAYABLE_COUNTRIES:
            player.active_country = code
        elif code is None:
            player.active_country = None
        if player.role != "admin":
            player.role = "player"
        player.clear_input()
        self.dirty = True
        self.add_log("country_switch", user_id, {"old": old, "new": code})
        return True

    def set_admin(self, user_id: int, enabled: bool) -> None:
        player=self.register_player(user_id)
        player.role="admin" if enabled else "player"
        if enabled: player.country=None
        player.clear_input(); self.dirty=True

    def player_for_country(self, code: str) -> list[Player]:
        return [p for p in self.players.values() if p.country==code and not p.banned]

    def country(self, code: str) -> Country:
        if code not in self.countries: raise KeyError(code)
        return self.countries[code]

    def province(self, pid: int) -> Province:
        pid=int(pid)
        if pid not in self.provinces: raise KeyError(pid)
        return self.provinces[pid]

    def country_share_border(self, a: str, b: str) -> bool:
        if a==b: return False
        for p in self.provinces.values():
            if p.country!=a: continue
            if any(self.provinces[n].country==b for n in p.neighbors): return True
        return False

    def countries_share_border(self,a:str,b:str)->bool: return self.country_share_border(a,b)

    def border_provinces(self, country: str) -> list[int]:
        result=[]
        for p in self.provinces.values():
            if p.country!=country: continue
            if any(self.provinces[n].country!=country for n in p.neighbors): result.append(p.id)
        return result

    def adjacent_enemies(self, pid: int, country: str) -> list[int]:
        return [n for n in self.province(pid).neighbors if self.province(n).country!=country]

    def active_wars_for(self, country: str) -> list[War]:
        return [w for w in self.wars.values() if w.active and w.involves(country)]

    def next_entity_id(self, prefix: str) -> str: return self._next_id(prefix)

    def advance_minutes(self, minutes: float) -> None:
        self.game_minutes += max(0.0,float(minutes)); self.dirty=True

    def set_speed(self,speed:float)->None: self.speed=max(0,float(speed)); self.dirty=True
    def set_pause(self,paused:bool)->None: self.paused=bool(paused); self.dirty=True

    def validate(self) -> list[str]:
        errors=[]
        if len(self.provinces)!=MAX_PROVINCES: errors.append(f"provinces={len(self.provinces)}")
        ids=[p.id for p in self.provinces.values()]
        if len(ids)!=len(set(ids)): errors.append("duplicate province id")
        for p in self.provinces.values():
            if any(n not in self.provinces for n in p.neighbors): errors.append(f"invalid neighbor at {p.id}")
        for c in PLAYABLE_COUNTRIES:
            if c not in self.countries: errors.append(f"missing country {c}")
            else:
                ids=set(self.countries[c].province_ids)
                actual={p.id for p in self.provinces.values() if p.country==c}
                if ids!=actual: errors.append(f"territory mismatch {c}")
                if self.countries[c].budget<0: errors.append(f"negative budget {c}")
                if any(v<0 for v in self.countries[c].resources.values()): errors.append(f"negative resources {c}")
        if any(p.country==COUNTRY_TEST for p in self.provinces.values()): errors.append("TEST owns province")
                                                                                                     
        for code in PLAYABLE_COUNTRIES:
            owned=[p for p in self.provinces.values() if p.country==code]
            capitals=[p for p in owned if p.capital]
            if len(capitals)!=1: errors.append(f"capital count {code}={len(capitals)}")
            if not any(p.sea_access for p in owned): errors.append(f"no sea access {code}")
                                                                                    
        for code in PLAYABLE_COUNTRIES:
            ids=self.countries[code].province_ids if code in self.countries else []
            if len(ids)!=len(set(ids)): errors.append(f"duplicate province index {code}")
        for gid,g in self.generals.items():
            if len(g.get("divisions",[]))>MAX_DIVISIONS_PER_GENERAL: errors.append(f"general {gid} >24")
        for did,d in self.divisions.items():
            if d.get("province") not in self.provinces: errors.append(f"division {did} bad province")
            else:
                pid = int(d.get("province"))
                if did not in self.provinces[pid].armies:
                    errors.append(f"division {did} missing from province index")
            gid = d.get("general")
            if gid is not None and gid not in self.generals:
                errors.append(f"division {did} bad general")
        for gid,g in self.generals.items():
            for did in g.get("divisions", []):
                if did not in self.divisions: errors.append(f"general {gid} bad division {did}")
                elif self.divisions[did].get("general") != gid: errors.append(f"general/division link mismatch {gid}/{did}")
        for gid,g in self.air_groups.items():
            pid=g.get("airfield_province")
            if pid not in self.provinces: errors.append(f"air {gid} bad airfield")
            # UAV models are valid air groups too; keep diagnostics in sync with Aviation.validate().
            if g.get("model") not in AIR_MODELS and g.get("model") not in UAV_MODELS: errors.append(f"air {gid} bad model")
        for fid,f in self.fleets.items():
            if f.get("base_province") not in self.provinces: errors.append(f"fleet {fid} bad base")
        for tid,t in self.trades.items():
            if t.get("status") in {"active","in_transit"} and (t.get("sender") not in PLAYABLE_COUNTRIES or t.get("receiver") not in PLAYABLE_COUNTRIES):
                errors.append(f"trade {tid} bad active participants")
        return errors

    def to_dict(self)->dict[str,Any]:
        return {
            "version":GAME_VERSION,"save_version":SAVE_VERSION,"game_minutes":self.game_minutes,"speed":self.speed,"paused":self.paused,
            "dirty":False,"settings":copy.deepcopy(self.settings),"countries":{k:v.to_dict() for k,v in self.countries.items()},
            "provinces":{str(k):v.to_dict() for k,v in self.provinces.items()},"players":{str(k):v.to_dict() for k,v in self.players.items()},
            "divisions":copy.deepcopy(self.divisions),"generals":copy.deepcopy(self.generals),"air_groups":copy.deepcopy(self.air_groups),
            "pvo_units":copy.deepcopy(self.pvo_units),"fleets":copy.deepcopy(self.fleets),"wars":{k:asdict(v) for k,v in self.wars.items()},
            "war_goals":copy.deepcopy(self.war_goals),"treaties":copy.deepcopy(self.treaties),"trades":copy.deepcopy(self.trades),
            "decisions":copy.deepcopy(self.decisions),"construction_projects":copy.deepcopy(self.construction_projects),"repairs":copy.deepcopy(self.repairs),
            "news":copy.deepcopy(self.news),"events":copy.deepcopy(self.events),"journal":copy.deepcopy(self.journal),"logs":copy.deepcopy(self.logs),"ids":copy.deepcopy(self._ids),
        }

    def from_dict(self,data:dict[str,Any])->None:
        self.game_minutes=float(data.get("game_minutes",0)); self.speed=float(data.get("speed",1)); self.paused=bool(data.get("paused",False)); self.settings.update(data.get("settings",{}))
        self.settings.setdefault("warehouse_update_minutes", WAREHOUSE_UPDATE_MINUTES)
        self.countries={k:Country.from_dict(v) for k,v in data.get("countries",{}).items() if k in PLAYABLE_COUNTRIES}
        for c in PLAYABLE_COUNTRIES:
            if c not in self.countries: self.countries[c]=Country.new(c)
        self.provinces={int(k):Province.from_dict(v) for k,v in data.get("provinces",{}).items()}
        for p in self.provinces.values():
            if not hasattr(p, "road_condition"): p.road_condition=100.0
            if not hasattr(p, "rail_condition"): p.rail_condition=100.0
        self.players={int(k):Player.from_dict(v) for k,v in data.get("players",{}).items()}
        self.divisions=copy.deepcopy(data.get("divisions",{})); self.generals=copy.deepcopy(data.get("generals",{})); self.air_groups=copy.deepcopy(data.get("air_groups",{})); self.pvo_units=copy.deepcopy(data.get("pvo_units",{})); self.fleets=copy.deepcopy(data.get("fleets",{}))
        self.wars={k:War(**v) for k,v in data.get("wars",{}).items()}; self.war_goals=copy.deepcopy(data.get("war_goals",{})); self.treaties=copy.deepcopy(data.get("treaties",{})); self.trades=copy.deepcopy(data.get("trades",{})); self.decisions=copy.deepcopy(data.get("decisions",{})); self.construction_projects=copy.deepcopy(data.get("construction_projects",{})); self.repairs=copy.deepcopy(data.get("repairs",{})); self.news=copy.deepcopy(data.get("news",{})); self.events=copy.deepcopy(data.get("events",{})); self.journal=copy.deepcopy(data.get("journal",[])); self.logs=copy.deepcopy(data.get("logs",[])); self._ids=copy.deepcopy(data.get("ids",{})); self.dirty=False
        self._migrate_loaded_state()

    def _migrate_loaded_state(self)->None:
        for c in self.countries.values():
            c.ensure_resources(); c.ensure_warehouse()
        for p in self.provinces.values():
            p.buildings=ensure_dict(p.buildings); p.building_condition=ensure_dict(p.building_condition)
            p.road_condition = float(getattr(p, "road_condition", 100.0))
            p.rail_condition = float(getattr(p, "rail_condition", 100.0))
            for k in p.buildings: p.building_condition.setdefault(k,100.0)
                                                                            
        for c in self.countries.values(): c.province_ids=[]
        for p in self.provinces.values():
            if p.country in self.countries: self.countries[p.country].province_ids.append(p.id)


class SaveManager:
    def __init__(self, directory: str | Path = "saves") -> None:
        self.directory=Path(directory); self.directory.mkdir(parents=True,exist_ok=True)
        self.primary=self.directory/"world.json"; self.backup=self.directory/"world.backup.json"; self.previous=self.directory/"world.previous.json"
        self.lock=RLock()

    def _write_atomic(self,path:Path,data:dict[str,Any])->None:
        fd,tmp=tempfile.mkstemp(prefix="ws_",suffix=".tmp",dir=str(path.parent))
        try:
            with os.fdopen(fd,"w",encoding="utf-8") as f:
                json.dump(data,f,ensure_ascii=False,indent=2); f.flush(); os.fsync(f.fileno())
            os.replace(tmp,path)
        finally:
            if os.path.exists(tmp): os.unlink(tmp)

    def save(self,world:WorldState,make_backup:bool=True)->None:
        with self.lock:
            data=world.to_dict()
            if make_backup and self.primary.exists():
                try: os.replace(self.primary,self.previous)
                except OSError: pass
                self._write_atomic(self.primary,data)
                shutil_copy(self.primary,self.backup)
            else: self._write_atomic(self.primary,data)

    def load(self,world:WorldState)->list[str]:
        with self.lock:
            warnings=[]
            source=self.primary
            if not source.exists() and self.backup.exists(): source=self.backup; warnings.append("primary save missing; loaded backup")
            if not source.exists(): return warnings
            try:
                data=json.loads(source.read_text(encoding="utf-8")); world.from_dict(data); warnings.extend(world.validate())
            except Exception as exc:
                warnings.append(f"save load failed: {exc}")
            return warnings

    def create_backup(self)->Path:
        with self.lock:
            if self.primary.exists(): shutil_copy(self.primary,self.backup)
            return self.backup

    def restore(self)->bool:
        with self.lock:
            if not self.backup.exists(): return False
            shutil_copy(self.backup,self.primary); return True

    def reset(self,world:WorldState)->None:
        with self.lock:
            if self.primary.exists(): shutil_copy(self.primary,self.previous)
            world._reset_world(); world.dirty=True; self.save(world,make_backup=False)


def shutil_copy(src:Path,dst:Path)->None:
    dst.write_bytes(src.read_bytes())


def country_stats_text(country: Country) -> str:
    return (f"{country.flag} <b>{country.name}</b>\n\n"
            f"💰 Бюджет: {format_money(country.budget)}\n"
            f"📈 Доход: {format_money(country.income_daily)}/день\n"
            f"👥 Население: {format_number(country.population)}\n"
            f"🪖 Резерв: {format_number(country.manpower)}\n"
            f"🏭 ГЗ: {country.civilian_factories} | ВЗ: {country.military_factories}\n"
            f"📊 Стабильность: {country.stability:.0f}%\n"
            f"🔥 Поддержка войны: {country.war_support:.0f}%")


def province_text(world: WorldState, pid: int) -> str:
    p=world.province(pid)
    buildings=", ".join(f"{k}:{v}" for k,v in p.buildings.items() if v>0)
    return (f"🗺️ <b>{p.name}</b> #{p.id}\n\n"
            f"Владелец: {country_display(p.country)}\n"
            f"Тип: {p.terrain}\n"
            f"🌊 Море: {'да' if p.sea_access else 'нет'}\n"
            f"🌊 Река: {'да' if p.river else 'нет'} | 🌉 Мост: {'да' if p.bridge else 'нет'}\n"
            f"🛣️ Дорога: {p.road_level} | 🚆 ЖД: {p.rail_level}\n"
            f"🏗️ Здания: {buildings or 'нет'}\n"
            f"🪖 Армия: {len(p.armies)} | ✈️ Авиация: {len(p.air_groups)} | 🛡️ ПВО: {len(p.pvo_units)} | ⚓ Флот: {len(p.fleets)}")

                                                                             
                                  
                                                                             

def country_codes() -> tuple[str, ...]:
    """Public immutable list of playable country codes."""
    return PLAYABLE_COUNTRIES


def playable_country_names() -> dict[str, str]:
    return {code: COUNTRY_NAMES[code] for code in PLAYABLE_COUNTRIES}


def territory_size(world: WorldState, country_code: str) -> int:
    return len(world.country(country_code).province_ids)


def coastline_size(world: WorldState, country_code: str) -> int:
    return sum(1 for pid in world.country(country_code).province_ids if world.province(pid).sea_access)


def city_provinces(world: WorldState, country_code: str) -> list[int]:
    return [pid for pid in world.country(country_code).province_ids if world.province(pid).city]


def capital_province(world: WorldState, country_code: str) -> Optional[int]:
    capitals = [pid for pid in world.country(country_code).province_ids if world.province(pid).capital]
    return capitals[0] if capitals else None


def map_integrity(world: WorldState) -> dict[str, Any]:
    errors = []
    if len(world.provinces) != MAX_PROVINCES:
        errors.append("wrong province count")
    if not all(world.countries_share_border(a, b) for a in PLAYABLE_COUNTRIES for b in PLAYABLE_COUNTRIES if a < b):
        errors.append("not all playable countries share borders")
    if not all(coastline_size(world, code) > 0 for code in PLAYABLE_COUNTRIES):
        errors.append("missing coastline")
    return {"ok": not errors, "errors": errors, "territory": {code: territory_size(world, code) for code in PLAYABLE_COUNTRIES}, "coastline": {code: coastline_size(world, code) for code in PLAYABLE_COUNTRIES}}


def province_neighbors_with_owners(world: WorldState, province_id: int) -> list[dict[str, Any]]:
    p = world.province(int(province_id))
    return [
        {"id": n, "name": world.province(n).name, "country": world.province(n).country}
        for n in p.neighbors
    ]


def border_pairs(world: WorldState) -> list[tuple[str, str]]:
    pairs = set()
    for p in world.provinces.values():
        for n in p.neighbors:
            other = world.province(n)
            if p.country != other.country and p.country in PLAYABLE_COUNTRIES and other.country in PLAYABLE_COUNTRIES:
                pairs.add(tuple(sorted((p.country, other.country))))
    return sorted(pairs)


def map_layout_ascii() -> str:
    """Compact human-readable preview of the designed country silhouettes."""
    return "\n".join(MAP_OWNERS)


def map_summary(world: WorldState) -> dict[str, Any]:
    return {
        "provinces": len(world.provinces),
        "countries": {code: territory_size(world, code) for code in PLAYABLE_COUNTRIES},
        "borders": border_pairs(world),
        "capitals": {code: capital_province(world, code) for code in PLAYABLE_COUNTRIES},
        "cities": {code: city_provinces(world, code) for code in PLAYABLE_COUNTRIES},
        "coastline": {code: coastline_size(world, code) for code in PLAYABLE_COUNTRIES},
    }


def first_owned_province(world: WorldState, country_code: str) -> Optional[int]:
    ids = sorted(world.country(country_code).province_ids)
    return ids[0] if ids else None


def country_has_capital(world: WorldState, country_code: str) -> bool:
    return capital_province(world, country_code) is not None


def all_playable_borders_valid(world: WorldState) -> bool:
    return all(world.countries_share_border(a, b) for index, a in enumerate(PLAYABLE_COUNTRIES) for b in PLAYABLE_COUNTRIES[index + 1:])


def province_owner(world: WorldState, province_id: int) -> str:
    return world.province(int(province_id)).country


def neighboring_countries(world: WorldState, country_code: str) -> set[str]:
    result = set()
    for pid in world.country(country_code).province_ids:
        for nid in world.province(pid).neighbors:
            owner = world.province(nid).country
            if owner != country_code and owner in PLAYABLE_COUNTRIES:
                result.add(owner)
    return result

                                                                               
