def safe_positive_int(value: Any, default: int = 0) -> int:
    try:
        return max(0, int(value))
    except (TypeError, ValueError):
        return default


def safe_positive_float(value: Any, default: float = 0.0) -> float:
    try:
        return max(0.0, float(value))
    except (TypeError, ValueError):
        return default


def building_count(world: Any, country_code: str, building: str) -> int:
    country = world.country(country_code)
    return sum(world.province(pid).building_level(building) for pid in country.province_ids)


def building_capacity(world: Any, country_code: str, building: str) -> int:
    total = 0
    for pid in world.country(country_code).province_ids:
        province = world.province(pid)
        level = province.building_level(building)
        cond = province.condition_of(building) / 100.0
        if province.is_building_operational(building):
            total += int(round(level * max(0.0, cond)))
    return total


def operational_industry(world: Any, country_code: str) -> float:
    country = world.country(country_code)
    modifier = max(0.10, float(getattr(country, "industry_modifier", 1.0)))
    electricity = electricity_ratio(country_code, world)
    roads = 0.0
    if country.province_ids:
        roads = sum(world.province(pid).road_level for pid in country.province_ids) / (2.0 * len(country.province_ids))
    return max(0.10, min(1.25, modifier * electricity * (0.75 + min(0.5, roads))))


def electricity_ratio(country_code: str, world: Any) -> float:
    country = world.country(country_code)
    operational_power_buildings = 0.0
    for pid in country.province_ids:
        p = world.province(pid)
        if p.building_level("power") > 0 and p.is_building_operational("power"):
            operational_power_buildings += p.condition_of("power") / 100.0
                                                                                     
                                                                                               
    generated = max(0.0, float(country.power_plants) * 180.0)
                                                                                 
                                                                             
    if operational_power_buildings < 0.5 and country.power_plants > 0:
        generated *= 0.88
    demand = max(1.0, country.civilian_factories * 0.85 + country.military_factories * 1.05 + building_count(world, country_code, "components") * 0.20)
    sub_capacity = max(1.0, float(country.substation_capacity) * 4.0)
    ratio = min(1.0, generated / demand)
    ratio *= min(1.0, sub_capacity / max(1.0, demand))
                                                   
    bonus = 0.0
    for active in country.active_decisions.values():
        if not active.get("finished"):
            bonus += float((active.get("effects") or {}).get("energy_bonus", 0.0))
    return max(0.0, min(1.0, ratio + bonus))


def daily_income(country_code: str, world: Any) -> int:
    country = world.country(country_code)
    active_business = sum(
        world.province(pid).building_level("business")
        for pid in country.province_ids
        if world.province(pid).condition_of("business") > 0
    )
    stability_mod = 0.75 + max(0.0, min(1.0, country.stability / 100.0)) * 0.50
    war_mod = max(0.60, 1.0 - country.war_exhaustion * 0.01)
    electricity_mod = 0.70 + 0.30 * electricity_ratio(country_code, world)
    industry_mod = 0.85 + 0.15 * max(0.5, float(country.industry_modifier))
    base = int(country.income_daily * stability_mod * war_mod * electricity_mod * industry_mod)
    return max(0, base + active_business * 5_000_000)


def economy_snapshot(world: Any, country_code: str) -> dict[str, Any]:
    c = world.country(country_code)
    return {
        "budget": c.budget,
        "income_daily": daily_income(country_code, world),
        "electricity": electricity_ratio(country_code, world),
        "population": c.population,
        "manpower": c.manpower,
        "civilian_factories": c.civilian_factories,
        "military_factories": c.military_factories,
        "resources": copy.deepcopy(c.resources),
        "warehouse": copy.deepcopy(c.warehouse),
        "industry_modifier": c.industry_modifier,
        "war_exhaustion": c.war_exhaustion,
    }


def economy_text(economy: "Economy", country_code: str) -> str:
    c = economy.world.country(country_code)
    snap = economy.snapshot(country_code)
    resource_lines = []
    for key in RESOURCE_KEYS:
        resource_lines.append(f"{RESOURCE_DISPLAY.get(key, key)}: {format_number(snap['resources'].get(key, 0))}")
    return (
        f"💰 <b>{c.name}</b>\n\n"
        f"Бюджет: {format_money(c.budget)}\n"
        f"Доход: {format_money(snap['income_daily'])}/день\n"
        f"Население: {format_number(c.population)}\n"
        f"Резерв: {format_number(c.manpower)}\n"
        f"Гражданские заводы: {c.civilian_factories}\n"
        f"Военные заводы: {c.military_factories}\n"
        f"Электроэнергия: {snap['electricity'] * 100:.0f}%\n"
        f"Стабильность: {c.stability:.0f}%\n"
        f"Поддержка войны: {c.war_support:.0f}%\n"
        f"Истощение войны: {c.war_exhaustion:.1f}%\n\n"
        + "\n".join(resource_lines)
    )


def production_model_text(model: ProductionModel, current: int = 0, free: int = 0) -> str:
    return (
        f"🏭 <b>{model.name}</b>\n\n"
        f"Категория: {PRODUCTION_CATEGORIES.get(model.category, model.category)}\n"
        f"Расчётная стоимость: {format_money(model.cost)}\n"
        f"Выпуск одним заводом: {model.output_per_factory_day:.2f}/день\n"
        f"Требование энергии: {model.power:.2f}\n"
        f"Описание: {model.description}\n\n"
        f"Заводов на линии: {current}\n"
        f"Свободно военных заводов: {free}"
    )


                                                                             
                 
                                                                             

class Economy:
    """National economy. Mutations are intentionally small and O(owned provinces)."""

    def __init__(self, world: Any) -> None:
        self.world = world

    def ensure(self, country_code: str) -> None:
        country = self.world.country(country_code)
        country.ensure_resources()
        country.ensure_warehouse()
        if not hasattr(country, "business_centers"):
            country.business_centers = 0
        if not hasattr(country, "war_exhaustion"):
            country.war_exhaustion = 0.0

    def snapshot(self, country_code: str) -> dict[str, Any]:
        self.ensure(country_code)
        return economy_snapshot(self.world, country_code)

    def daily_income(self, country_code: str) -> int:
        self.ensure(country_code)
        return daily_income(country_code, self.world)

    def electricity_ratio(self, country_code: str) -> float:
        self.ensure(country_code)
        return electricity_ratio(country_code, self.world)

    def spend_money(self, country_code: str, amount: int) -> tuple[bool, str]:
        self.ensure(country_code)
        amount = safe_positive_int(amount)
        if amount <= 0:
            return False, "Сумма должна быть больше нуля."
        country = self.world.country(country_code)
        if not country.can_spend(amount):
            return False, f"Недостаточно денег: нужно {format_money(amount)}."
        country.spend(amount)
        self.world.mark_dirty()
        return True, f"Списано {format_money(amount)}."

    def add_money(self, country_code: str, amount: int) -> tuple[bool, str]:
        self.ensure(country_code)
        amount = int(amount)
        country = self.world.country(country_code)
        country.change_budget(amount)
        self.world.mark_dirty()
        return True, f"Бюджет изменён на {format_money(amount)}."

    def add_resource(self, country_code: str, resource: str, amount: int) -> tuple[bool, str]:
        self.ensure(country_code)
        if resource not in RESOURCE_KEYS:
            return False, "Неизвестный ресурс."
        amount = int(amount)
        self.world.country(country_code).add_resource(resource, amount)
        self.world.mark_dirty()
        return True, f"Ресурс изменён: {RESOURCE_DISPLAY.get(resource, resource)} {amount:+d}."

    def spend_resource(self, country_code: str, resource: str, amount: int) -> tuple[bool, str]:
        self.ensure(country_code)
        amount = safe_positive_int(amount)
        c = self.world.country(country_code)
        if resource not in RESOURCE_KEYS:
            return False, "Неизвестный ресурс."
        if c.resources.get(resource, 0) < amount:
            return False, f"Недостаточно ресурса: {RESOURCE_DISPLAY.get(resource, resource)}."
        c.resources[resource] -= amount
        self.world.mark_dirty()
        return True, "Ресурс списан."

    def process_resource(self, country_code: str, product: str, batches: int = 1) -> tuple[bool, str]:
        """Manual conversion for decisions/admin/testing; normal industry also produces it."""
        self.ensure(country_code)
        batches = max(1, int(batches))
        recipe = RESOURCE_CONVERSION.get(product)
        if not recipe:
            return False, "Для этого ресурса нет рецепта."
        c = self.world.country(country_code)
        for res, amount in recipe.items():
            if c.resources.get(res, 0) < amount * batches:
                return False, f"Недостаточно {RESOURCE_DISPLAY.get(res, res)}."
        for res, amount in recipe.items():
            c.resources[res] -= amount * batches
        c.resources[product] = c.resources.get(product, 0) + batches
        self.world.mark_dirty()
        return True, f"Получено {batches} ед. {RESOURCE_DISPLAY.get(product, product)}."

    def apply_daily_tick(self, country_code: str) -> None:
        self.ensure(country_code)
        c = self.world.country(country_code)
        income = self.daily_income(country_code)
        c.budget += income

        ratio = self.electricity_ratio(country_code)
        manpower_bonus_pct = 0.0
        for active in c.active_decisions.values():
            if not active.get("finished"):
                manpower_bonus_pct += float((active.get("effects") or {}).get("manpower_daily_pct", 0.0))
        manpower_gain = int(max(0, c.population * 0.000015 * (0.8 + ratio * 0.2) * (1.0 + manpower_bonus_pct / 100.0)))
        c.manpower = min(c.population // 5, c.manpower + manpower_gain)
        c.stability = max(0.0, min(100.0, c.stability + (0.08 * ratio) - (0.04 * c.war_exhaustion)))
        c.war_support = max(0.0, min(100.0, c.war_support + (0.03 if c.war_exhaustion > 0 else 0.0)))

                                     
                                                                             
                                                                               
                                                                      
        raw = {k: 0 for k in ("iron", "coal", "oil", "aluminum")}
        process_capacity = {"metallurgy": 0, "components": 0, "npz": 0, "oil_processing": 0}
        for pid in list(c.province_ids):
            p = self.world.province(pid)
            if p.condition <= 0:
                continue
            condition_mod = ratio * (0.85 + p.industrial_level * 0.05)
            for building, yields in RESOURCE_YIELDS.items():
                level = p.building_level(building)
                if level <= 0 or not p.is_building_operational(building):
                    continue
                building_mod = condition_mod * (p.condition_of(building) / 100.0)
                if building in ("mine", "oilwell"):
                    for resource, base in yields.items():
                        raw[resource] = raw.get(resource, 0) + int(level * base * building_mod)
                elif building in process_capacity:
                    process_capacity[building] += max(0.0, float(level) * building_mod)
        for resource, amount in raw.items():
            c.resources[resource] = c.resources.get(resource, 0) + amount

                                                                           
        steel_batches = min(process_capacity["metallurgy"] * 28, c.resources.get("iron",0)//2, c.resources.get("coal",0))
        if steel_batches > 0:
            c.resources["iron"] -= steel_batches * 2; c.resources["coal"] -= steel_batches; c.resources["steel"] += steel_batches
                                                          
        component_batches = min(process_capacity["components"] * 24, c.resources.get("aluminum",0)//2, c.resources.get("steel",0))
        if component_batches > 0:
            c.resources["aluminum"] -= component_batches * 2; c.resources["steel"] -= component_batches; c.resources["components"] += component_batches
                                                                          
        fuel_batches = min((process_capacity["npz"] * 90) + (process_capacity["oil_processing"] * 70), c.resources.get("oil",0))
        if fuel_batches > 0:
            c.resources["oil"] -= fuel_batches; c.resources["fuel"] += fuel_batches

                                                                                            
        c.business_centers = building_count(self.world, country_code, "business")
        c.war_exhaustion = max(0.0, c.war_exhaustion - 0.08)
        self.world.add_log("economy_daily", None, {"country": country_code, "income": income})

    def monthly_maintenance(self, country_code: str) -> int:
        """Small abstract maintenance charge, used only by longer simulation tests."""
        self.ensure(country_code)
        c = self.world.country(country_code)
        factories = c.civilian_factories + c.military_factories
        maintenance = int(factories * 45_000 + building_count(self.world, country_code, "power") * 30_000)
        return max(0, maintenance)

    def national_factory_totals(self, country_code: str) -> dict[str, int]:
        return {
            "civ_factory": building_count(self.world, country_code, "civ_factory"),
            "mil_factory": building_count(self.world, country_code, "mil_factory"),
            "mine": building_count(self.world, country_code, "mine"),
            "npz": building_count(self.world, country_code, "npz"),
            "metallurgy": building_count(self.world, country_code, "metallurgy"),
            "oilwell": building_count(self.world, country_code, "oilwell"),
            "oil_processing": building_count(self.world, country_code, "oil_processing"),
            "components": building_count(self.world, country_code, "components"),
            "power": building_count(self.world, country_code, "power"),
            "substation": building_count(self.world, country_code, "substation"),
            "airfield": building_count(self.world, country_code, "airfield"),
            "naval_base": building_count(self.world, country_code, "naval_base"),
        }

    def country_capacity(self, country_code: str) -> dict[str, float]:
        c = self.world.country(country_code)
        ratio = self.electricity_ratio(country_code)
        return {
            "civilian": c.civilian_factories * ratio,
            "military": c.military_factories * operational_industry(self.world, country_code),
            "air": building_capacity(self.world, country_code, "airfield"),
            "naval": building_capacity(self.world, country_code, "naval_base"),
        }


                                                                             
                    
                                                                             

class Production:
    """Military production with 3-minute warehouse delivery ticks."""

    def __init__(self, world: Any) -> None:
        self.world = world

    def model(self, key: str) -> ProductionModel:
        if key not in PRODUCTION_CATALOG:
            raise KeyError(key)
        return PRODUCTION_CATALOG[key]

    def models(self, category: Optional[str] = None) -> list[ProductionModel]:
        if category:
            keys = MODELS_BY_CATEGORY.get(category, [])
            return [PRODUCTION_CATALOG[k] for k in keys]
        return list(PRODUCTION_CATALOG.values())

    def free_factories(self, country_code: str) -> int:
        c = self.world.country(country_code)
        used = sum(max(0, int(v.get("factories", 0))) for v in c.production_lines.values())
                                                                                                            
        return max(0, int(c.military_factories) - used)

    def line(self, country_code: str, model_key: str) -> dict[str, Any]:
        self.world.country(country_code).production_lines.setdefault(model_key, {"factories": 0, "accumulator": 0.0})
        return self.world.country(country_code).production_lines[model_key]

    def set_line(self, country_code: str, model_key: str, factories: int) -> tuple[bool, str]:
        if model_key not in PRODUCTION_CATALOG:
            return False, "Модель не найдена."
        factories = max(0, int(factories))
        line = self.line(country_code, model_key)
        old = int(line.get("factories", 0))
        available_without_old = self.free_factories(country_code) + old
        if factories > available_without_old:
            return False, f"Свободных военных заводов недостаточно: доступно {available_without_old}."
        line["factories"] = factories
        line.setdefault("accumulator", 0.0)
        line["enabled"] = factories > 0
        self.world.mark_dirty()
        self.world.add_log("production_line", None, {"country": country_code, "model": model_key, "factories": factories})
        return True, f"Линия обновлена: {factories} заводов."

    def units_per_day(self, country_code: str, model_key: str, current: Optional[int] = None) -> float:
        if model_key not in PRODUCTION_CATALOG:
            return 0.0
        line = self.line(country_code, model_key)
        factories = int(line.get("factories", 0) if current is None else current)
        if factories <= 0:
            return 0.0
        industry_mod = operational_industry(self.world, country_code)
        return factories * PRODUCTION_CATALOG[model_key].output_per_factory_day * industry_mod

    def resource_efficiency(self, country_code: str) -> float:
        c = self.world.country(country_code)
        ratio = 1.0
                                                                                         
                                                                                       
        if c.resources.get("fuel", 0) < 1000:
            ratio *= 0.92
        return ratio

    def warehouse(self, country_code: str, category: Optional[str] = None) -> dict[str, int]:
        c = self.world.country(country_code)
        if category is None:
            return {key: int(c.warehouse.get(key, 0)) for key in EQUIPMENT_KEYS}
        allowed = WEAPON_CATEGORIES.get(category, set())
        return {key: int(c.warehouse.get(key, 0)) for key in allowed}

    def stock(self, country_code: str, key: str) -> int:
        return int(self.world.country(country_code).warehouse.get(key, 0))

    def can_consume(self, country_code: str, key: str, amount: int) -> bool:
        return self.world.country(country_code).has_equipment(key, amount)

    def consume(self, country_code: str, key: str, amount: int) -> tuple[bool, str]:
        amount = max(0, int(amount))
        c = self.world.country(country_code)
        if c.infinite_weapons:
            return True, "Бесконечное вооружение: склад не списан."
        if not c.has_equipment(key, amount):
            return False, f"Недостаточно {key} на складе."
        c.take_equipment(key, amount)
        self.world.mark_dirty()
        return True, "Техника списана со склада."

    def deliver(self, country_code: str, key: str, amount: int) -> int:
        amount = max(0, int(amount))
        c = self.world.country(country_code)
        result = c.add_equipment(key, amount)
        self.world.mark_dirty()
        return result

    def _consume_factory_resources(self, country_code: str, model: ProductionModel, units: int) -> bool:
        if units <= 0:
            return True
        c = self.world.country(country_code)
                                                                               
                                                                                 
        fuel_need = units * (1 if model.category in {"air", "fighter", "bomber", "heli", "uav", "navy", "vehicles", "tanks", "artillery", "support"} else 0)
        if fuel_need and c.resources.get("fuel", 0) < fuel_need:
            return False
        if fuel_need:
            c.resources["fuel"] -= fuel_need
        return True

    def tick(self, country_code: str, minutes: float) -> dict[str, int]:
        c = self.world.country(country_code)
        delivered: dict[str, int] = {}
        efficiency = self.resource_efficiency(country_code)
        industry_mod = operational_industry(self.world, country_code) * efficiency
        for key, line in list(c.production_lines.items()):
            if key not in PRODUCTION_CATALOG:
                continue
            factories = max(0, int(line.get("factories", 0)))
            if factories <= 0:
                continue
            line.setdefault("accumulator", 0.0)
            model = PRODUCTION_CATALOG[key]
                                                                    
            rate_per_minute = model.output_per_factory_day / 1440.0 * factories * industry_mod
            line["accumulator"] += max(0.0, float(minutes)) * rate_per_minute
            whole = int(line["accumulator"])
            if whole <= 0:
                continue
            line["accumulator"] -= whole
            if not self._consume_factory_resources(country_code, model, whole):
                                                                                                           
                line["accumulator"] += whole
                continue
            equip_key = next(iter(model.equipment.keys()), key)
            c.add_equipment(equip_key, whole)
            delivered[equip_key] = delivered.get(equip_key, 0) + whole
        if delivered:
            self.world.add_log("production_tick", None, {"country": country_code, "delivered": delivered})
        return delivered

    def stop_all_lines(self, country_code: str) -> None:
        c = self.world.country(country_code)
        for line in c.production_lines.values():
            line["factories"] = 0
            line["enabled"] = False
        self.world.mark_dirty()

    def total_daily_output(self, country_code: str) -> dict[str, float]:
        output: dict[str, float] = {}
        for key, line in self.world.country(country_code).production_lines.items():
            amount = self.units_per_day(country_code, key, int(line.get("factories", 0)))
            equip = next(iter(PRODUCTION_CATALOG.get(key, ProductionModel(key, key, "", 0, 0, 0)).equipment.keys()), key)
            output[equip] = output.get(equip, 0.0) + amount
        return output

    def summary(self, country_code: str) -> dict[str, Any]:
        c = self.world.country(country_code)
        lines = {}
        for key, line in c.production_lines.items():
            if key in PRODUCTION_CATALOG:
                lines[key] = {
                    "factories": int(line.get("factories", 0)),
                    "output_daily": self.units_per_day(country_code, key),
                    "accumulator": float(line.get("accumulator", 0.0)),
                    "category": PRODUCTION_CATALOG[key].category,
                }
        return {
            "lines": lines,
            "free_factories": self.free_factories(country_code),
            "military_factories": c.military_factories,
            "daily_output": self.total_daily_output(country_code),
            "electricity": electricity_ratio(country_code, self.world),
        }

    def validate_catalog(self) -> list[str]:
        errors = []
        for key, model in PRODUCTION_CATALOG.items():
            if key not in EQUIPMENT_KEYS:
                errors.append(f"catalog:{key} missing equipment key")
            if model.category not in PRODUCTION_CATEGORIES:
                errors.append(f"catalog:{key} bad category")
            if model.output_per_factory_day <= 0:
                errors.append(f"catalog:{key} nonpositive output")
            if model.cost < 0:
                errors.append(f"catalog:{key} negative cost")
        return errors


                                                          
def initialize_production_country(world: Any, country_code: str) -> None:
    c = world.country(country_code)
    for key in PRODUCTION_CATALOG:
        c.production_lines.setdefault(key, {"factories": 0, "accumulator": 0.0, "enabled": False})


def normalize_production_lines(world: Any) -> None:
    for code in PLAYABLE_COUNTRIES:
        initialize_production_country(world, code)
        c = world.country(code)
        used = 0
        for key, line in c.production_lines.items():
            if key not in PRODUCTION_CATALOG:
                line["factories"] = 0
                continue
            line["factories"] = max(0, int(line.get("factories", 0)))
            used += line["factories"]
        if used > c.military_factories:
            overflow = used - c.military_factories
            for line in reversed(list(c.production_lines.values())):
                if overflow <= 0:
                    break
                cut = min(overflow, int(line.get("factories", 0)))
                line["factories"] -= cut
                overflow -= cut


