def resource_balance(world: Any, country_code: str) -> dict[str, int]:
    c = world.country(country_code)
    c.ensure_resources()
    return {k: int(c.resources.get(k, 0)) for k in RESOURCE_KEYS}


def warehouse_balance(world: Any, country_code: str) -> dict[str, int]:
    c = world.country(country_code)
    c.ensure_warehouse()
    return {k: int(c.warehouse.get(k, 0)) for k in EQUIPMENT_KEYS}


def national_building_condition(world: Any, country_code: str, key: str) -> float:
    levels = 0
    weighted = 0.0
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        level = p.building_level(key)
        if level <= 0:
            continue
        levels += level
        weighted += level * p.condition_of(key)
    return weighted / levels if levels else 0.0


def resource_production_preview(world: Any, country_code: str, minutes: float = 1440) -> dict[str, int]:
    """Estimate the real raw/processed resource flow without mutating the world."""
    days = max(0.0, float(minutes) / 1440.0)
    c = world.country(country_code); ratio = electricity_ratio(country_code, world)
    raw = {k: 0 for k in ("iron", "coal", "oil", "aluminum")}
    cap = {"metallurgy": 0.0, "components": 0.0, "npz": 0.0, "oil_processing": 0.0}
    for pid in c.province_ids:
        p = world.province(pid)
        mod = ratio * (0.85 + p.industrial_level * 0.05)
        for building, yields in RESOURCE_YIELDS.items():
            level = p.building_level(building)
            if level <= 0 or not p.is_building_operational(building): continue
            m = mod * p.condition_of(building) / 100.0 * days
            if building in ("mine", "oilwell"):
                for resource, base in yields.items(): raw[resource] += level * base * m
            elif building in cap: cap[building] += level * mod * p.condition_of(building) / 100.0 * days
    result = {k: 0 for k in RESOURCE_KEYS}
    for k,v in raw.items(): result[k] = int(v)
    steel = min(int(cap["metallurgy"]*28), int(c.resources.get("iron",0)+result["iron"])//2, int(c.resources.get("coal",0)+result["coal"]))
    aluminum_available=int(c.resources.get("aluminum",0))+result["aluminum"]
    steel_available=int(c.resources.get("steel",0))+steel
    components=min(int(cap["components"]*24), aluminum_available//2, steel_available)
    oil_available=int(c.resources.get("oil",0))+result["oil"]
    fuel=min(int(cap["npz"]*90+cap["oil_processing"]*70), oil_available)
    result["steel"]=steel-components
    result["components"]=components
    result["oil"]-=fuel
    result["fuel"]=fuel
    return result


def production_capacity_by_category(world: Any, country_code: str) -> dict[str, int]:
    c = world.country(country_code)
    result = {category: 0 for category in PRODUCTION_CATEGORIES}
    for key, line in c.production_lines.items():
        model = PRODUCTION_CATALOG.get(key)
        if model:
            result[model.category] += int(line.get("factories", 0))
    return result


def line_efficiency(world: Any, country_code: str, model_key: str) -> float:
    if model_key not in PRODUCTION_CATALOG:
        return 0.0
    return operational_industry(world, country_code) * resource_efficiency(world, country_code)


def resource_efficiency(world: Any, country_code: str) -> float:
    c = world.country(country_code)
    factor = 1.0
    thresholds = (("fuel", 1000, 0.92),)
    for resource, threshold, modifier in thresholds:
        if int(c.resources.get(resource, 0)) < threshold:
            factor *= modifier
    return factor


def estimate_output(world: Any, country_code: str, model_key: str, days: float = 1.0) -> float:
    model = PRODUCTION_CATALOG.get(model_key)
    if not model:
        return 0.0
    c = world.country(country_code)
    line = c.production_lines.get(model_key, {})
    factories = int(line.get("factories", 0))
    return max(0.0, factories * model.output_per_factory_day * max(0.0, days) * line_efficiency(world, country_code, model_key))


def factory_usage(world: Any, country_code: str) -> dict[str, Any]:
    c = world.country(country_code)
    used = sum(max(0, int(v.get("factories", 0))) for v in c.production_lines.values())
    return {"used": used, "free": max(0, c.military_factories - used), "capacity": c.military_factories}


def production_plan(world: Any, country_code: str, desired: dict[str, int]) -> dict[str, Any]:
    """Return a safe allocation plan without applying it."""
    free = factory_usage(world, country_code)["free"]
    plan = {}
    rejected = {}
    for key, factories in desired.items():
        factories = max(0, int(factories))
        if key not in PRODUCTION_CATALOG:
            rejected[key] = "unknown model"
            continue
        if factories > free:
            plan[key] = free
            rejected[key] = f"requested {factories}, allocated {free}"
            free = 0
        else:
            plan[key] = factories
            free -= factories
    return {"plan": plan, "unused_factories": free, "rejected": rejected}


def apply_production_plan(production: Production, country_code: str, plan: dict[str, int]) -> dict[str, Any]:
    changes = []
    errors = []
    for key, factories in plan.items():
        ok, reason = production.set_line(country_code, key, int(factories))
        if ok:
            changes.append((key, int(factories)))
        else:
            errors.append((key, reason))
    return {"changed": changes, "errors": errors}


def warehouse_categories(country_code: str, world: Any) -> dict[str, dict[str, int]]:
    c = world.country(country_code)
    return {
        "infantry": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["infantry"]},
        "vehicles": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["vehicles"]},
        "tanks": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["tanks"]},
        "artillery": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["artillery"]},
        "air": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["air"]},
        "uav": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["uav"]},
        "pvo": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["pvo"]},
        "navy": {k: c.warehouse.get(k, 0) for k in WEAPON_CATEGORIES["navy"]},
    }


def compare_economies(world: Any, countries: Iterable[str]) -> list[dict[str, Any]]:
    rows = []
    for code in countries:
        snap = economy_snapshot(world, code)
        rows.append({
            "country": code,
            "budget": snap["budget"],
            "income": snap["income_daily"],
            "civ": snap["civilian_factories"],
            "mil": snap["military_factories"],
            "population": snap["population"],
            "manpower": snap["manpower"],
            "energy": snap["electricity"],
        })
    return sorted(rows, key=lambda x: x["budget"], reverse=True)


def normalize_resources(world: Any) -> None:
    for code in PLAYABLE_COUNTRIES:
        c = world.country(code)
        c.ensure_resources()
        for key in RESOURCE_KEYS:
            c.resources[key] = max(0, int(c.resources[key]))


def normalize_warehouse(world: Any) -> None:
    for code in PLAYABLE_COUNTRIES:
        c = world.country(code)
        c.ensure_warehouse()
        for key in EQUIPMENT_KEYS:
            c.warehouse[key] = max(0, int(c.warehouse[key]))


def economy_validate(world: Any) -> list[str]:
    errors = []
    for code in PLAYABLE_COUNTRIES:
        c = world.country(code)
        if c.budget < 0:
            errors.append(f"{code}: negative budget")
        for key, value in c.resources.items():
            if value < 0:
                errors.append(f"{code}: negative resource {key}")
        for key, value in c.warehouse.items():
            if value < 0:
                errors.append(f"{code}: negative equipment {key}")
        if c.military_factories < 0 or c.civilian_factories < 0:
            errors.append(f"{code}: negative factories")
    return errors


def building_output_table(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    for building, yields in RESOURCE_YIELDS.items():
        level = building_count(world, country_code, building)
        condition = national_building_condition(world, country_code, building)
        rows.append({"building": building, "level": level, "condition": condition, "yields": copy.deepcopy(yields)})
    return rows


def equipment_value(world: Any, country_code: str) -> int:
    total = 0
    for key, amount in world.country(country_code).warehouse.items():
        model = PRODUCTION_CATALOG.get(key)
        if model:
            total += int(amount) * model.cost
    return total


def economic_score(world: Any, country_code: str) -> float:
    snap = economy_snapshot(world, country_code)
    value = snap["budget"] / 1_000_000_000
    value += snap["income_daily"] / 10_000_000
    value += snap["civilian_factories"] * 0.15
    value += snap["military_factories"] * 0.05
    value += snap["population"] / 100_000_000
    value += equipment_value(world, country_code) / 10_000_000_000
    value *= 0.75 + 0.25 * snap["electricity"]
    return value


def economic_ranking(world: Any) -> list[tuple[str, float]]:
    result = [(code, economic_score(world, code)) for code in PLAYABLE_COUNTRIES]
    return sorted(result, key=lambda x: x[1], reverse=True)

                                                                             
                                   
                                                                             

def resource_flow_report(world: Any, country_code: str, days: float = 1.0) -> dict[str, dict[str, float]]:
    days = max(0.0, float(days))
    production_preview = resource_production_preview(world, country_code, days * 1440.0)
    return {
        key: {
            "stock": float(world.country(country_code).resources.get(key, 0)),
            "expected_gain": float(production_preview.get(key, 0)),
            "after": float(world.country(country_code).resources.get(key, 0) + production_preview.get(key, 0)),
        }
        for key in RESOURCE_KEYS
    }


def factory_allocation_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    c = world.country(country_code)
    for key, line in sorted(c.production_lines.items()):
        model = PRODUCTION_CATALOG.get(key)
        if not model:
            continue
        factories = int(line.get("factories", 0))
        rows.append({
            "model": key,
            "name": model.name,
            "category": model.category,
            "factories": factories,
            "daily_output": estimate_output(world, country_code, key),
            "enabled": bool(line.get("enabled", factories > 0)),
            "accumulator": float(line.get("accumulator", 0)),
        })
    return rows


def reallocate_factories(production: Production, country_code: str, assignments: dict[str, int]) -> dict[str, Any]:
    """Apply all line assignments transactionally enough for UI use.

    The original plan is validated first; if it requests more factories than exist,
    no line is modified.
    """
    country = production.world.country(country_code)
    requested = sum(max(0, int(v)) for v in assignments.values())
    if requested > country.military_factories:
        return {"ok": False, "reason": "План требует больше военных заводов, чем есть.", "changed": []}
    invalid = [k for k in assignments if k not in PRODUCTION_CATALOG]
    if invalid:
        return {"ok": False, "reason": "Неизвестные модели: " + ", ".join(invalid), "changed": []}
    old = {k: int(v.get("factories", 0)) for k, v in country.production_lines.items()}
    changed = []
                                     
    for key in list(old):
        if key not in assignments:
            production.set_line(country_code, key, 0)
    for key, factories in assignments.items():
        ok, reason = production.set_line(country_code, key, int(factories))
        if not ok:
                                                                    
            for restore_key, restore_value in old.items():
                production.set_line(country_code, restore_key, restore_value)
            return {"ok": False, "reason": reason, "changed": []}
        changed.append((key, int(factories)))
    return {"ok": True, "reason": "План производства применён.", "changed": changed}


def production_queue_summary(world: Any, country_code: str) -> dict[str, Any]:
    c = world.country(country_code)
    queue = []
    for key, line in c.production_lines.items():
        model = PRODUCTION_CATALOG.get(key)
        if not model or int(line.get("factories", 0)) <= 0:
            continue
        queue.append({
            "key": key,
            "title": model.name,
            "factories": int(line.get("factories", 0)),
            "daily": estimate_output(world, country_code, key),
            "category": model.category,
        })
    queue.sort(key=lambda x: x["factories"], reverse=True)
    return {"queue": queue, "total_lines": len(queue), "free_factories": factory_usage(world, country_code)["free"]}


def resource_sufficiency(world: Any, country_code: str) -> dict[str, str]:
    c = world.country(country_code)
    status = {}
    for key in RESOURCE_KEYS:
        value = int(c.resources.get(key, 0))
        status[key] = "high" if value >= 10_000 else "normal" if value >= 2_000 else "low" if value > 0 else "empty"
    return status


def factory_distribution_by_province(world: Any, country_code: str) -> list[dict[str, Any]]:
    result = []
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        civ = p.building_level("civ_factory")
        mil = p.building_level("mil_factory")
        if civ or mil:
            result.append({"province": pid, "name": p.name, "civ": civ, "mil": mil, "condition_civ": p.condition_of("civ_factory"), "condition_mil": p.condition_of("mil_factory")})
    return sorted(result, key=lambda x: x["mil"], reverse=True)


def power_grid_report(world: Any, country_code: str) -> dict[str, Any]:
    ratio = electricity_ratio(country_code, world)
    power = building_capacity(world, country_code, "power")
    substations = building_capacity(world, country_code, "substation")
    c = world.country(country_code)
    demand = c.civilian_factories + c.military_factories * 1.35
    return {"ratio": ratio, "power": power, "substations": substations, "estimated_demand": demand, "deficit": max(0.0, demand - power)}


def economy_export(world: Any, country_code: str) -> dict[str, Any]:
    return {
        "snapshot": economy_snapshot(world, country_code),
        "buildings": building_output_table(world, country_code),
        "factories": factory_distribution_by_province(world, country_code),
        "production": factory_allocation_report(world, country_code),
        "resources": resource_balance(world, country_code),
        "warehouse": warehouse_balance(world, country_code),
        "power": power_grid_report(world, country_code),
    }

                                                                      
