def clamp(value: float, low: float = 0.0, high: float = 100.0) -> float:
    return max(low, min(high, float(value)))


def _airfield_capacity(world: Any, pid: int) -> int:
    p = world.province(int(pid))
    level = p.building_level("airfield")
    cond = p.condition_of("airfield") / 100.0
    return max(0, int(level * 24 * cond))


def _naval_capacity(world: Any, pid: int) -> int:
    p = world.province(int(pid))
    level = p.building_level("naval_base")
    cond = p.condition_of("naval_base") / 100.0
    return max(0, int(level * 8 * cond))


def _province_owned(world: Any, code: str, pid: int) -> bool:
    return int(pid) in world.country(code).province_ids


def _at_war(world: Any, a: str, b: str) -> bool:
    return any(w.active and w.involves(a) and w.involves(b) for w in world.wars.values())


                                                                             
          
                                                                             

class Aviation:
    def __init__(self, world: Any, production: Any) -> None:
        self.world = world
        self.production = production
        self._rng = random.Random(228)

    def airfields(self, country_code: str) -> list[int]:
        return [pid for pid in self.world.country(country_code).province_ids if self.world.province(pid).is_building_operational("airfield")]

    def active_groups(self, country_code: str) -> list[dict[str, Any]]:
        return [g for g in self.world.air_groups.values() if g.get("country") == country_code]

    def summary(self, country_code: str) -> dict[str, Any]:
        groups = self.active_groups(country_code)
        aircraft = sum(int(g.get("quantity", 0)) for g in groups)
        ready = sum(float(g.get("readiness", 0)) * int(g.get("quantity", 0)) for g in groups) / max(1, aircraft)
        return {
            "groups": len(groups),
            "aircraft": aircraft,
            "ready": ready,
            "airfields": len(self.airfields(country_code)),
            "uav": sum(int(g.get("quantity", 0)) for g in groups if g.get("model") in UAV_MODELS),
        }

    def _stock_before_airfield(self, country_code: str, model_key: str, quantity: int) -> tuple[bool, str]:
        if model_key not in AIR_MODELS and model_key not in UAV_MODELS:
            return False, "Модель авиации не найдена."
        if quantity <= 0:
            return False, "Количество должно быть больше нуля."
                                                                                  
        available = self.production.stock(country_code, model_key)
        c = self.world.country(country_code)
        if c.infinite_weapons:
            available = max(available, quantity)
        if available < quantity:
            return False, f"На складе только {available} ед."
        return True, ""

    def create_group(self, country_code: str, model_key: str, quantity: int, province_id: int) -> tuple[bool, str, Optional[str]]:
        quantity = int(quantity)
        ok, reason = self._stock_before_airfield(country_code, model_key, quantity)
        if not ok:
            return False, reason, None
        province_id = int(province_id)
        fields = self.airfields(country_code)
        if province_id not in fields:
            return False, "На этой провинции нет рабочего аэродрома.", None
        if _airfield_capacity(self.world, province_id) < quantity:
            return False, "На аэродроме недостаточно мест.", None
        if not self.world.country(country_code).infinite_weapons:
            self.production.consume(country_code, model_key, quantity)
        model = AIR_MODELS.get(model_key) or UAV_MODELS.get(model_key)
        gid = self.world.next_entity_id("air")
        self.world.air_groups[gid] = {
            "id": gid,
            "name": f"Авиагруппа {gid}",
            "country": country_code,
            "model": model_key,
            "quantity": quantity,
            "airfield_province": province_id,
            "readiness": 100.0,
            "condition": 100.0,
            "mission": "stop",
            "target_country": None,
            "target_province": None,
            "manual": False,
            "created_at": self.world.game_minutes,
            "strength": float(model.strength),
        }
        p = self.world.province(province_id)
        p.air_groups.append(gid)
        self.world.mark_dirty()
        self.world.add_log("air_group_created", None, {"country": country_code, "group": gid, "model": model_key, "quantity": quantity})
        return True, f"Создана авиагруппа: {model.name} × {quantity}.", gid

    def rebase(self, group_id: str, province_id: int) -> tuple[bool, str]:
        g = self.world.air_groups.get(group_id)
        if not g:
            return False, "Авиагруппа не найдена."
        province_id = int(province_id)
        if province_id not in self.airfields(g["country"]):
            return False, "Это не ваш рабочий аэродром."
        old = int(g["airfield_province"])
        if old in self.world.provinces and group_id in self.world.province(old).air_groups:
            self.world.province(old).air_groups.remove(group_id)
        g["airfield_province"] = province_id
        if group_id not in self.world.province(province_id).air_groups:
            self.world.province(province_id).air_groups.append(group_id)
        g["readiness"] = clamp(float(g.get("readiness", 0)) - 4)
        self.world.mark_dirty()
        return True, "Авиагруппа перебазирована."

    def set_mission(self, group_id: str, mission: str, target_country: Optional[str], target_province: Optional[int]) -> tuple[bool, str]:
        g = self.world.air_groups.get(group_id)
        if not g:
            return False, "Авиагруппа не найдена."
        if mission not in AIR_TASKS:
            return False, "Неизвестное задание."
        if mission not in {"stop", "standby"}:
            if target_country is None or target_province is None:
                return False, "Нужно выбрать цель."
            if int(target_province) not in self.world.provinces:
                return False, "Провинция не найдена."
            target_owner = self.world.province(int(target_province)).country

            own_target_missions = {"support", "transport", "intercept", "patrol"}
            if mission in own_target_missions:
                if target_owner != g["country"] or target_country != g["country"]:
                    return False, "Для этого задания нужна ваша провинция."
            else:
                if target_country == g["country"]:
                    return False, "Цель должна находиться за пределами вашей страны."
                if target_owner != target_country:
                    return False, "Эта провинция уже не принадлежит выбранной стране."

            if not target_is_reachable(self.world, g, int(target_province)):
                return False, "Цель вне игровой дальности авиагруппы."

            if mission == "strike" and not _at_war(self.world, g["country"], target_country):
                model_key = g.get("model")
                                                                                    
                                                                                                     
                if model_key in UAV_MODELS:
                    return False, "Ударные БПЛА можно применять только во время войны."
                if not g.get("raid_notified"):
                    g["raid"] = True
                    g["raid_notified"] = True
                    attacker = self.world.country(g["country"])
                    defender = self.world.country(target_country)
                    attacker.relations[target_country] = clamp(float(attacker.relations.get(target_country, 0)) - 15, -100, 100)
                    defender.relations[g["country"]] = clamp(float(defender.relations.get(g["country"], 0)) - 15, -100, 100)
                    self.world.add_journal("aviation", "Авиационный рейд", f"{attacker.name} нанёс рейд по провинции {self.world.province(int(target_province)).name} страны {defender.name}.")
            elif mission == "air_superiority" and not _at_war(self.world, g["country"], target_country):
                return False, "Воздушное превосходство против страны доступно только во время войны."
            elif mission == "intercept":
                return False, "Перехват задаётся по своей провинции."
        else:
            target_country = None
            target_province = None
        g["mission"] = mission
        g["target_country"] = target_country
        g["target_province"] = int(target_province) if target_province is not None else None
        g["readiness"] = clamp(float(g.get("readiness", 0)) - 3)
        self.world.mark_dirty()
        self.world.add_log("air_mission", None, {"group": group_id, "mission": mission, "target": target_province})
        return True, f"Задание установлено: {AIR_TASKS[mission]}."

    def damage(self, group_id: str, amount: float) -> tuple[bool, str]:
        g = self.world.air_groups.get(group_id)
        if not g:
            return False, "Авиагруппа не найдена."
        g["condition"] = clamp(float(g.get("condition", 100)) - abs(float(amount)))
        g["readiness"] = clamp(float(g.get("readiness", 100)) - abs(float(amount)) * 0.7)
        self.world.mark_dirty()
        return True, "Авиагруппа получила повреждения."

    def repair(self, group_id: str, amount: float = 8) -> tuple[bool, str]:
        g = self.world.air_groups.get(group_id)
        if not g:
            return False, "Авиагруппа не найдена."
        amount = abs(float(amount))
        g["condition"] = clamp(float(g.get("condition", 100)) + amount)
        g["readiness"] = clamp(float(g.get("readiness", 100)) + amount * 0.8)
        self.world.mark_dirty()
        return True, "Группа восстанавливается."

    def _execute_mission(self, g: dict[str, Any], minutes: float) -> Optional[dict[str, Any]]:
        mission = g.get("mission", "stop")
        if mission == "stop" or int(g.get("quantity", 0)) <= 0:
            return None
        target_pid = g.get("target_province")
        target_country = g.get("target_country")
        if target_pid not in self.world.provinces:
            g["mission"] = "stop"
            return None
        readiness = clamp(float(g.get("readiness", 0))) / 100.0
        condition = clamp(float(g.get("condition", 0))) / 100.0
        model = AIR_MODELS.get(g.get("model")) or UAV_MODELS.get(g.get("model"))
        strength = float(g.get("strength", model.strength if model else 50)) * int(g.get("quantity", 0))
        power = strength * readiness * condition * min(1.0, minutes / 10.0)
        province = self.world.province(int(target_pid))
        result = {"group": g["id"], "mission": mission, "target_country": target_country, "target_province": target_pid, "power": power}
        if mission == "strike":
                                                                                
                                                                                         
            result["raw_strike_power"] = power
        elif mission == "recon":
            result["recon"] = True
        elif mission == "patrol":
            result["pressure"] = power * 0.45
        elif mission == "intercept":
            result["interception"] = power * 0.65
        elif mission == "support":
            result["army_support"] = power * 0.35
        elif mission == "transport":
            result["transport_capacity"] = power * 0.25
        elif mission == "air_superiority":
            result["air_pressure"] = power * 0.40
        g["readiness"] = clamp(float(g.get("readiness", 0)) - minutes * 0.10)
        g["condition"] = clamp(float(g.get("condition", 0)) - minutes * 0.035)
        return result

    def tick(self, minutes: float) -> list[dict[str, Any]]:
        results = []
        for g in self.world.air_groups.values():
            condition = float(g.get("condition", 0))
            readiness = float(g.get("readiness", 0))
            bonus = 0.0
            try:
                for decision in self.world.country(g["country"]).active_decisions.values():
                    if not decision.get("finished"):
                        bonus += float(decision.get("effects", {}).get("air_readiness", 0))
            except Exception:
                pass
            recovery = 0.035 if g.get("mission") == "stop" else 0.008
            recovery += bonus * 0.0005
            g["condition"] = clamp(condition + minutes * (0.015 + bonus * 0.00015))
            g["readiness"] = clamp(readiness + minutes * recovery)
            event = self._execute_mission(g, minutes)
            if event:
                results.append(event)
        if results:
            self.world.add_log("air_tick", None, {"results": results[-20:]})
        self.world.mark_dirty()
        return results

    def validate(self) -> list[str]:
        errors = []
        for gid, g in self.world.air_groups.items():
            if g.get("country") not in PLAYABLE_COUNTRIES:
                errors.append(f"air {gid}: bad country")
            pid = g.get("airfield_province")
            if pid not in self.world.provinces:
                errors.append(f"air {gid}: bad airfield")
            elif not _province_owned(self.world, g["country"], pid):
                errors.append(f"air {gid}: foreign airfield")
            if g.get("model") not in AIR_MODELS and g.get("model") not in UAV_MODELS:
                errors.append(f"air {gid}: bad model")
        return errors


                                                                             
     
                                                                             

class PVO:
    def __init__(self, world: Any, production: Any) -> None:
        self.world = world
        self.production = production
        self._rng = random.Random(729)

    def radars(self, country_code: str) -> list[int]:
        return [pid for pid in self.world.country(country_code).province_ids if self.world.province(pid).building_level("radar") > 0 and self.world.province(pid).condition_of("radar") > 0]

    def units(self, country_code: str) -> list[dict[str, Any]]:
        return [u for u in self.world.pvo_units.values() if u.get("country") == country_code]

    def coverage(self, country_code: str, province_id: int) -> dict[str, Any]:
        province_id = int(province_id)
        candidates = [province_id] + list(self.world.province(province_id).neighbors)
        strength = 0.0
        detection = 0.0
        sources = []
        for unit in self.units(country_code):
            if int(unit.get("province", -1)) in candidates:
                readiness = clamp(float(unit.get("readiness", 0))) / 100.0
                condition = clamp(float(unit.get("condition", 0))) / 100.0
                                                                      
                own = strength / 100.0
                gain = float(unit.get("strength", 0)) * readiness * condition / (1.0 + own * 0.65)
                strength += gain
                sources.append(unit["id"])
        if province_id in self.radars(country_code):
            detection += 65
        for n in self.world.province(province_id).neighbors:
            if n in self.radars(country_code):
                detection += 20
        return {"strength": min(100.0, strength), "detection": min(100.0, detection), "units": sources}

    def deploy(self, country_code: str, model_key: str, quantity: int, province_id: int) -> tuple[bool, str, Optional[str]]:
        quantity = max(1, int(quantity))
        if model_key not in PVO_MODELS:
            return False, "Модель ПВО не найдена.", None
        province_id = int(province_id)
        if not _province_owned(self.world, country_code, province_id):
            return False, "Провинция должна быть вашей.", None
        stock = self.production.stock(country_code, model_key)
        if not self.world.country(country_code).infinite_weapons and stock < quantity:
            return False, f"На складе только {stock} ед.", None
        if model_key == "pvo" and self.world.province(province_id).building_level("radar") <= 0:
                                                                                  
            pass
        if not self.world.country(country_code).infinite_weapons:
            self.production.consume(country_code, model_key, quantity)
        uid = self.world.next_entity_id("pvo")
        model = PVO_MODELS[model_key]
        self.world.pvo_units[uid] = {
            "id": uid,
            "country": country_code,
            "model": model_key,
            "quantity": quantity,
            "province": province_id,
            "readiness": 100.0,
            "condition": 100.0,
            "strength": float(model["strength"]) * quantity,
            "detection": float(model["detection"]),
        }
        self.world.province(province_id).pvo_units.append(uid)
        self.world.mark_dirty()
        self.world.add_log("pvo_deployed", None, {"country": country_code, "unit": uid, "province": province_id})
        return True, f"ПВО размещено: {model['name']} × {quantity}.", uid

    def move(self, unit_id: str, province_id: int) -> tuple[bool, str]:
        u = self.world.pvo_units.get(unit_id)
        if not u:
            return False, "ПВО не найдено."
        province_id = int(province_id)
        if not _province_owned(self.world, u["country"], province_id):
            return False, "Нельзя размещать ПВО за пределами своей страны."
        old = int(u["province"])
        if old in self.world.provinces and unit_id in self.world.province(old).pvo_units:
            self.world.province(old).pvo_units.remove(unit_id)
        u["province"] = province_id
        self.world.province(province_id).pvo_units.append(unit_id)
        u["readiness"] = clamp(float(u.get("readiness", 0)) - 5)
        self.world.mark_dirty()
        return True, "ПВО перемещено."

    def intercept(self, country_code: str, province_id: int, incoming_power: float) -> dict[str, Any]:
        cover = self.coverage(country_code, province_id)
        chance = clamp(cover["detection"] * 0.35 + cover["strength"] * 0.65, 0, 100) / 100.0
        roll = self._rng.random()
        prevented = roll < chance
        effect = min(incoming_power, cover["strength"] * 1.25) if prevented else incoming_power * 0.25
        for uid in cover["units"]:
            if uid in self.world.pvo_units:
                u = self.world.pvo_units[uid]
                u["readiness"] = clamp(float(u.get("readiness", 0)) - 2.5)
                u["condition"] = clamp(float(u.get("condition", 0)) - 0.5)
        self.world.mark_dirty()
        return {"detected": cover["detection"] > 0, "prevented": prevented, "effect": effect, "remaining": max(0.0, incoming_power - effect)}

    def tick(self, minutes: float) -> None:
        for u in self.world.pvo_units.values():
            u["condition"] = clamp(float(u.get("condition", 100)) + minutes * 0.012)
            u["readiness"] = clamp(float(u.get("readiness", 100)) + minutes * 0.03)
        self.world.mark_dirty()

    def validate(self) -> list[str]:
        errors = []
        for uid, u in self.world.pvo_units.items():
            if u.get("country") not in PLAYABLE_COUNTRIES:
                errors.append(f"pvo {uid}: bad country")
            if u.get("province") not in self.world.provinces:
                errors.append(f"pvo {uid}: bad province")
            elif not _province_owned(self.world, u["country"], int(u["province"])):
                errors.append(f"pvo {uid}: foreign province")
        return errors


                                                                             
      
                                                                             

class Navy:
    def __init__(self, world: Any, production: Any) -> None:
        self.world = world
        self.production = production
        self._rng = random.Random(412)

    def naval_bases(self, country_code: str) -> list[int]:
        return [pid for pid in self.world.country(country_code).province_ids if self.world.province(pid).sea_access and self.world.province(pid).is_building_operational("naval_base")]

    def formations(self, country_code: str) -> list[dict[str, Any]]:
        return [f for f in self.world.fleets.values() if f.get("country") == country_code]

    def summary(self, country_code: str) -> dict[str, Any]:
        fleets = self.formations(country_code)
        ships = sum(int(f.get("quantity", 0)) for f in fleets)
        strength = sum(float(f.get("strength", 0)) * int(f.get("quantity", 0)) for f in fleets)
        ready = sum(float(f.get("readiness", 0)) * int(f.get("quantity", 0)) for f in fleets) / max(1, ships)
        return {"formations": len(fleets), "ships": ships, "strength": strength, "bases": len(self.naval_bases(country_code)), "ready": ready}

    def _stock_before_base(self, country_code: str, model_key: str, quantity: int) -> tuple[bool, str]:
        if model_key not in NAVY_MODELS:
            return False, "Модель корабля не найдена."
        stock = self.production.stock(country_code, model_key)
        if self.world.country(country_code).infinite_weapons:
            stock = max(stock, quantity)
        if stock < quantity:
            return False, f"На складе только {stock} ед."
        return True, ""

    def create_fleet(self, country_code: str, model_key: str, quantity: int, province_id: int) -> tuple[bool, str, Optional[str]]:
        quantity = max(1, int(quantity))
        ok, reason = self._stock_before_base(country_code, model_key, quantity)
        if not ok:
            return False, reason, None
        province_id = int(province_id)
        if province_id not in self.naval_bases(country_code):
            return False, "На этой провинции нет рабочей морской базы.", None
        if _naval_capacity(self.world, province_id) < quantity:
            return False, "Морской базе не хватает вместимости.", None
        if not self.world.country(country_code).infinite_weapons:
            self.production.consume(country_code, model_key, quantity)
        model = NAVY_MODELS[model_key]
        fid = self.world.next_entity_id("fleet")
        self.world.fleets[fid] = {
            "id": fid,
            "name": f"Флот {fid}",
            "country": country_code,
            "model": model_key,
            "quantity": quantity,
            "base_province": province_id,
            "sea_zone": None,
            "readiness": 100.0,
            "condition": 100.0,
            "mission": "stop",
            "strength": float(model.strength),
            "created_at": self.world.game_minutes,
        }
        self.world.province(province_id).fleets.append(fid)
        self.world.mark_dirty()
        self.world.add_log("fleet_created", None, {"country": country_code, "fleet": fid, "model": model_key, "quantity": quantity})
        return True, f"Флот сформирован: {model.name} × {quantity}.", fid

    def rebase(self, fleet_id: str, province_id: int) -> tuple[bool, str]:
        f = self.world.fleets.get(fleet_id)
        if not f:
            return False, "Формирование флота не найдено."
        province_id = int(province_id)
        if province_id not in self.naval_bases(f["country"]):
            return False, "Это не ваша морская база."
        if _naval_capacity(self.world, province_id) < int(f.get("quantity", 0)):
            return False, "Недостаточно вместимости."
        old = int(f.get("base_province", 0))
        if old in self.world.provinces and fleet_id in self.world.province(old).fleets:
            self.world.province(old).fleets.remove(fleet_id)
        f["base_province"] = province_id
        self.world.province(province_id).fleets.append(fleet_id)
        f["readiness"] = clamp(float(f.get("readiness", 0)) - 4)
        self.world.mark_dirty()
        return True, "Флот перебазирован."

    def set_mission(self, fleet_id: str, mode: str, sea_zone: Optional[str] = None) -> tuple[bool, str]:
        f = self.world.fleets.get(fleet_id)
        if not f:
            return False, "Флот не найден."
        if mode not in NAVY_MISSIONS:
            return False, "Неизвестное задание."
        if mode != "stop" and not sea_zone:
            return False, "Укажите морскую зону."
        f["mission"] = mode
        f["sea_zone"] = str(sea_zone) if sea_zone else None
        f["readiness"] = clamp(float(f.get("readiness", 0)) - 2)
        self.world.mark_dirty()
        return True, f"Задание флота: {NAVY_MISSIONS[mode]}."

    def damage(self, fleet_id: str, amount: float) -> tuple[bool, str]:
        f = self.world.fleets.get(fleet_id)
        if not f:
            return False, "Флот не найден."
        amount = abs(float(amount))
        f["condition"] = clamp(float(f.get("condition", 100)) - amount)
        f["readiness"] = clamp(float(f.get("readiness", 100)) - amount * 0.7)
        self.world.mark_dirty()
        return True, "Флот повреждён."

    def tick(self, minutes: float) -> list[dict[str, Any]]:
        events: list[dict[str, Any]] = []
                                    
        for f in self.world.fleets.values():
            bonus = 0.0
            try:
                for decision in self.world.country(f["country"]).active_decisions.values():
                    if not decision.get("finished"):
                        bonus += float(decision.get("effects", {}).get("navy_readiness", 0))
            except Exception:
                pass
            f["condition"] = clamp(float(f.get("condition", 100)) + minutes * (0.01 + bonus * 0.0001))
            if f.get("mission") == "stop":
                f["readiness"] = clamp(float(f.get("readiness", 100)) + minutes * (0.045 + bonus * 0.0005))
            else:
                f["readiness"] = clamp(float(f.get("readiness", 100)) + minutes * (0.01 + bonus * 0.0002))
            if f.get("mission") == "patrol":
                events.append({"type": "patrol", "fleet": f["id"], "zone": f.get("sea_zone"), "pressure": navy_group_power(f) * 0.03})
            elif f.get("mission") == "combat":
                events.append({"type": "combat_ready", "fleet": f["id"], "zone": f.get("sea_zone"), "power": navy_group_power(f)})
                f["condition"] = clamp(float(f.get("condition", 0)) - minutes * 0.025)

                                                                                         
        combat_fleets = [f for f in self.world.fleets.values() if f.get("mission") == "combat" and f.get("sea_zone")]
        paired: set[tuple[str, str]] = set()
        for left in combat_fleets:
            for right in combat_fleets:
                if left["id"] == right["id"] or left.get("country") == right.get("country"):
                    continue
                if left.get("sea_zone") != right.get("sea_zone"):
                    continue
                key = tuple(sorted((left["id"], right["id"])))
                if key in paired:
                    continue
                if not _at_war(self.world, left["country"], right["country"]):
                    continue
                paired.add(key)
                lp = navy_group_power(left) * self._rng.uniform(0.94, 1.06)
                rp = navy_group_power(right) * self._rng.uniform(0.94, 1.06)
                if lp >= rp:
                    winner, loser, wp, lpw = left, right, lp, rp
                else:
                    winner, loser, wp, lpw = right, left, rp, lp
                ratio = wp / max(1.0, lpw)
                loser["condition"] = clamp(float(loser.get("condition", 0)) - min(12.0, 4.0 + ratio * 2.5))
                loser["readiness"] = clamp(float(loser.get("readiness", 0)) - min(18.0, 6.0 + ratio * 3.0))
                winner["readiness"] = clamp(float(winner.get("readiness", 0)) - 2.0)
                events.append({"type": "naval_battle", "winner": winner["id"], "loser": loser["id"], "zone": left.get("sea_zone"), "ratio": ratio})
                self.world.add_journal("navy", "Морское сражение", f"Флот {winner['id']} получил преимущество над флотом {loser['id']} в зоне {left.get('sea_zone')}.")

                                                                                
        for fid, fleet in list(self.world.fleets.items()):
            if float(fleet.get("condition", 100)) <= 0 or int(fleet.get("quantity", 0)) <= 0:
                pid = fleet.get("base_province")
                if pid in self.world.provinces and fid in self.world.province(pid).fleets:
                    self.world.province(pid).fleets.remove(fid)
                self.world.fleets.pop(fid, None)
                self.world.add_journal("navy", "Флот потерян", f"Формирование {fid} уничтожено.")
        self.world.mark_dirty()
        if events:
            self.world.add_log("navy_tick", None, {"events": events[-20:]})
        return events

    def validate(self) -> list[str]:
        errors = []
        for fid, f in self.world.fleets.items():
            if f.get("country") not in PLAYABLE_COUNTRIES:
                errors.append(f"fleet {fid}: bad country")
            pid = f.get("base_province")
            if pid not in self.world.provinces:
                errors.append(f"fleet {fid}: bad base")
            elif pid not in self.world.country(f["country"]).province_ids:
                errors.append(f"fleet {fid}: foreign base")
            if f.get("model") not in NAVY_MODELS:
                errors.append(f"fleet {fid}: bad model")
        return errors


__all__ = [
    "AIR_MODELS", "UAV_MODELS", "NAVY_MODELS", "PVO_MODELS", "AIR_TASKS", "NAVY_MISSIONS",
    "Aviation", "PVO", "Navy",
]

                                                                             
                                      
                                                                             

def air_group_power(group: dict[str, Any]) -> float:
    quantity = max(0, int(group.get("quantity", 0)))
    readiness = clamp(float(group.get("readiness", 0))) / 100.0
    condition = clamp(float(group.get("condition", 0))) / 100.0
    strength = float(group.get("strength", 50))
    return strength * quantity * readiness * condition


def air_country_strength(world: Any, country_code: str) -> dict[str, float]:
    groups = [g for g in world.air_groups.values() if g.get("country") == country_code]
    fighters = sum(air_group_power(g) for g in groups if g.get("model") == "fighter")
    bombers = sum(air_group_power(g) for g in groups if g.get("model") == "bomber")
    helicopters = sum(air_group_power(g) for g in groups if g.get("model") == "helicopter")
    uav = sum(air_group_power(g) for g in groups if g.get("model") in UAV_MODELS)
    return {"total": fighters + bombers + helicopters + uav, "fighters": fighters, "bombers": bombers, "helicopters": helicopters, "uav": uav}


def target_is_reachable(world: Any, group: dict[str, Any], target_province: int) -> bool:
    target_province = int(target_province)
    if target_province not in world.provinces:
        return False
    base = int(group.get("airfield_province", -1))
    if base not in world.provinces:
        return False
                                                                                
                                                                              
    level = world.province(base).building_level("airfield")
    radius = min(10, 5 + max(0, level - 1) * 2)
    frontier = [(base, 0)]
    seen = {base}
    while frontier:
        pid, distance = frontier.pop(0)
        if pid == target_province:
            return True
        if distance >= radius:
            continue
        for nxt in world.province(pid).neighbors:
            if nxt not in seen:
                seen.add(nxt)
                frontier.append((nxt, distance + 1))
    return False


def choose_best_airfield(world: Any, country_code: str, quantity: int) -> Optional[int]:
    candidates = []
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        if not p.is_building_operational("airfield"):
            continue
        capacity = _airfield_capacity(world, pid)
        if capacity < quantity:
            continue
        score = p.building_level("airfield") * 10 + (5 if p.capital else 0) + (3 if p.city else 0)
        candidates.append((score, pid))
    return max(candidates, default=(0, None))[1]


def airfield_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    report = []
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        if p.building_level("airfield") <= 0:
            continue
        used = sum(int(world.air_groups[gid].get("quantity", 0)) for gid in p.air_groups if gid in world.air_groups)
        capacity = _airfield_capacity(world, pid)
        report.append({"province": pid, "name": p.name, "level": p.building_level("airfield"), "used": used, "capacity": capacity, "free": max(0, capacity - used), "condition": p.condition_of("airfield")})
    return report


def radar_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        level = p.building_level("radar")
        if level <= 0:
            continue
        rows.append({"province": pid, "name": p.name, "level": level, "condition": p.condition_of("radar"), "detection": min(100, 30 + level * 20)})
    return rows


def pvo_country_strength(world: Any, country_code: str) -> dict[str, float]:
    units = [u for u in world.pvo_units.values() if u.get("country") == country_code]
    power = 0.0
    detection = 0.0
    for u in units:
        power += float(u.get("strength", 0)) * clamp(float(u.get("readiness", 0))) / 100 * clamp(float(u.get("condition", 0))) / 100
        detection += float(u.get("detection", 0)) * clamp(float(u.get("readiness", 0))) / 100
    for row in radar_report(world, country_code):
        detection += row["detection"]
    try:
        for decision in world.country(country_code).active_decisions.values():
            if not decision.get("finished"):
                detection += float(decision.get("effects", {}).get("pvo_detection", 0))
    except Exception:
        pass
    return {"power": power, "detection": min(100.0, detection)}


def navy_group_power(fleet: dict[str, Any]) -> float:
    return float(fleet.get("strength", 50)) * max(0, int(fleet.get("quantity", 0))) * clamp(float(fleet.get("readiness", 0))) / 100 * clamp(float(fleet.get("condition", 0))) / 100


def navy_country_strength(world: Any, country_code: str) -> dict[str, float]:
    fleets = [f for f in world.fleets.values() if f.get("country") == country_code]
    return {"total": sum(navy_group_power(f) for f in fleets), "patrol": sum(navy_group_power(f) for f in fleets if f.get("model") == "patrol_ship"), "frigates": sum(navy_group_power(f) for f in fleets if f.get("model") == "frigate"), "destroyers": sum(navy_group_power(f) for f in fleets if f.get("model") == "destroyer")}


def naval_base_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    for pid in world.country(country_code).province_ids:
        p = world.province(pid)
        if p.building_level("naval_base") <= 0 or not p.sea_access:
            continue
        used = sum(int(world.fleets[fid].get("quantity", 0)) for fid in p.fleets if fid in world.fleets)
        capacity = _naval_capacity(world, pid)
        rows.append({"province": pid, "name": p.name, "level": p.building_level("naval_base"), "used": used, "capacity": capacity, "free": max(0, capacity - used), "condition": p.condition_of("naval_base")})
    return rows


def air_pvo_interaction(world: Any, attacker_country: str, target_country: str, target_province: int, incoming_power: float) -> dict[str, Any]:
    """Resolve one abstract air strike against the defender's local PVO."""
    units = [u for u in world.pvo_units.values() if u.get("country") == target_country]
    candidate_ids = {int(target_province)} | set(world.province(int(target_province)).neighbors)
    local_power = 0.0
    detection = 0.0
    for u in units:
        if int(u.get("province", -1)) not in candidate_ids:
            continue
        local_power += float(u.get("strength", 0)) * clamp(float(u.get("readiness", 0))) / 100 * clamp(float(u.get("condition", 0))) / 100
        detection += float(u.get("detection", 0))
    for row in radar_report(world, target_country):
        if row["province"] in candidate_ids:
            detection += row["detection"]
    chance = max(0.0, min(0.95, detection / 150 + local_power / 700))
    prevented = chance >= 0.55
    prevented_power = incoming_power * (0.70 if prevented else 0.20)
    for u in units:
        if int(u.get("province", -1)) in candidate_ids:
            u["readiness"] = clamp(float(u.get("readiness", 0)) - 2.0)
            u["condition"] = clamp(float(u.get("condition", 0)) - 0.4)
    world.mark_dirty()
    return {"attacker": attacker_country, "defender": target_country, "province": int(target_province), "detection": detection, "pvo_power": local_power, "prevented": prevented, "prevented_power": prevented_power, "remaining_power": max(0.0, incoming_power - prevented_power)}


def service_validate(world: Any) -> list[str]:
    errors = []
    for code in PLAYABLE_COUNTRIES:
        if not any(world.province(pid).sea_access for pid in world.country(code).province_ids):
            errors.append(f"{code}: no sea access")
        if not any(world.province(pid).building_level("airfield") > 0 for pid in world.country(code).province_ids):
            errors.append(f"{code}: no starting airfield")
        if not any(world.province(pid).building_level("naval_base") > 0 for pid in world.country(code).province_ids):
            errors.append(f"{code}: no starting naval base")
    return errors

                                                                             
                                          
                                                                             

def air_mission_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    for g in world.air_groups.values():
        if g.get("country") != country_code:
            continue
        rows.append({"id": g["id"], "name": g.get("name", g["id"]), "model": g.get("model"), "quantity": int(g.get("quantity", 0)), "mission": g.get("mission", "stop"), "target_country": g.get("target_country"), "target_province": g.get("target_province"), "readiness": float(g.get("readiness", 0)), "condition": float(g.get("condition", 0))})
    return rows


def strike_uav_groups(world: Any, country_code: str) -> list[dict[str, Any]]:
    return [g for g in world.air_groups.values() if g.get("country") == country_code and g.get("model") in UAV_MODELS]


def create_strike_uav_group(aviation: Aviation, country_code: str, model_key: str, quantity: int, province_id: int) -> tuple[bool, str, Optional[str]]:
    if model_key not in UAV_MODELS:
        return False, "Это не ударный БПЛА.", None
    return aviation.create_group(country_code, model_key, quantity, province_id)


def strike_uav_status(world: Any, country_code: str) -> dict[str, Any]:
    groups = strike_uav_groups(world, country_code)
    return {"groups": len(groups), "units": sum(int(g.get("quantity", 0)) for g in groups), "ready": sum(float(g.get("readiness", 0)) * int(g.get("quantity", 0)) for g in groups) / max(1, sum(int(g.get("quantity", 0)) for g in groups))}


def choose_target_provinces(world: Any, target_country: str, limit: int = 12) -> list[int]:
    ids = list(world.country(target_country).province_ids)
    ids.sort(key=lambda pid: (not world.province(pid).capital, not world.province(pid).city, -world.province(pid).industrial_level))
    return ids[:max(1, int(limit))]


def pvo_coverage_map(pvo: PVO, country_code: str) -> dict[int, dict[str, Any]]:
    result = {}
    for pid in pvo.world.country(country_code).province_ids:
        result[pid] = pvo.coverage(country_code, pid)
    return result


def strongest_pvo_province(pvo: PVO, country_code: str) -> Optional[int]:
    coverage = pvo_coverage_map(pvo, country_code)
    if not coverage:
        return None
    return max(coverage.items(), key=lambda x: (x[1]["strength"], x[1]["detection"]))[0]


def navy_zone_report(world: Any, country_code: str) -> dict[str, list[dict[str, Any]]]:
    zones: dict[str, list[dict[str, Any]]] = {}
    for fleet in world.fleets.values():
        if fleet.get("country") != country_code:
            continue
        zone = fleet.get("sea_zone") or "база"
        zones.setdefault(zone, []).append(fleet)
    return zones


def navy_zone_strength(world: Any, country_code: str) -> dict[str, float]:
    result = {}
    for zone, fleets in navy_zone_report(world, country_code).items():
        result[zone] = sum(navy_group_power(f) for f in fleets)
    return result


def validate_service_indexes(world: Any) -> list[str]:
    errors = []
    for pid, p in world.provinces.items():
        for gid in p.air_groups:
            if gid not in world.air_groups:
                errors.append(f"province {pid}: missing air group {gid}")
        for uid in p.pvo_units:
            if uid not in world.pvo_units:
                errors.append(f"province {pid}: missing PVO {uid}")
        for fid in p.fleets:
            if fid not in world.fleets:
                errors.append(f"province {pid}: missing fleet {fid}")
    return errors

                                                                             
                                   
                                                                             

class AirPvoNavyManager:
    """Cross-service validator and snapshot helper.

    The class is intentionally independent from Telegram. It can be called from
    diagnostics, tests or the simulation tick without creating network work.
    """

    def __init__(self, world: Any, production: Any) -> None:
        self.world = world
        self.production = production
        self.aviation = Aviation(world, production)
        self.pvo = PVO(world, production)
        self.navy = Navy(world, production)

    def snapshot(self, country_code: str) -> dict[str, Any]:
        return {
            "air": self.aviation.summary(country_code),
            "airfields": airfield_report(self.world, country_code),
            "missions": air_mission_report(self.world, country_code),
            "uav": strike_uav_status(self.world, country_code),
            "pvo": pvo_country_strength(self.world, country_code),
            "radars": radar_report(self.world, country_code),
            "pvo_units": [dict(u) for u in self.pvo.units(country_code)],
            "navy": self.navy.summary(country_code),
            "bases": naval_base_report(self.world, country_code),
            "zones": navy_zone_strength(self.world, country_code),
        }

    def daily_readiness(self, country_code: str) -> dict[str, float]:
        air = self.aviation.summary(country_code)["ready"]
        pvo_units = self.pvo.units(country_code)
        navy = self.navy.summary(country_code)
        pvo_ready = sum(float(x.get("readiness", 0)) * int(x.get("quantity", 0)) for x in pvo_units) / max(1, sum(int(x.get("quantity", 0)) for x in pvo_units))
        return {"air": float(air), "pvo": float(pvo_ready), "navy": float(navy.get("ready", 0))}

    def repair_tick(self, minutes: float) -> dict[str, int]:
        repaired = {"air": 0, "pvo": 0, "navy": 0}
        for g in self.world.air_groups.values():
            old = float(g.get("condition", 100))
            g["condition"] = clamp(old + minutes * 0.018)
            if g["condition"] > old:
                repaired["air"] += 1
        for u in self.world.pvo_units.values():
            old = float(u.get("condition", 100))
            u["condition"] = clamp(old + minutes * 0.015)
            if u["condition"] > old:
                repaired["pvo"] += 1
        for f in self.world.fleets.values():
            old = float(f.get("condition", 100))
            f["condition"] = clamp(old + minutes * 0.012)
            if f["condition"] > old:
                repaired["navy"] += 1
        if any(repaired.values()):
            self.world.mark_dirty()
        return repaired

    def clean_indexes(self) -> None:
        for p in self.world.provinces.values():
            p.air_groups = [gid for gid in p.air_groups if gid in self.world.air_groups and self.world.air_groups[gid].get("airfield_province") == p.id]
            p.pvo_units = [uid for uid in p.pvo_units if uid in self.world.pvo_units and self.world.pvo_units[uid].get("province") == p.id]
            p.fleets = [fid for fid in p.fleets if fid in self.world.fleets and self.world.fleets[fid].get("base_province") == p.id]
        for gid, group in self.world.air_groups.items():
            pid = int(group.get("airfield_province", -1))
            if pid in self.world.provinces and gid not in self.world.province(pid).air_groups:
                self.world.province(pid).air_groups.append(gid)
        for uid, unit in self.world.pvo_units.items():
            pid = int(unit.get("province", -1))
            if pid in self.world.provinces and uid not in self.world.province(pid).pvo_units:
                self.world.province(pid).pvo_units.append(uid)
        for fid, fleet in self.world.fleets.items():
            pid = int(fleet.get("base_province", -1))
            if pid in self.world.provinces and fid not in self.world.province(pid).fleets:
                self.world.province(pid).fleets.append(fid)

    def service_validate(self) -> list[str]:
        errors = []
        errors.extend(service_validate(self.world))
        errors.extend(validate_service_indexes(self.world))
        errors.extend(self.aviation.validate())
        errors.extend(self.pvo.validate())
        errors.extend(self.navy.validate())
        return errors

    def set_all_stop(self, country_code: str) -> None:
        for g in self.aviation.active_groups(country_code):
            g["mission"] = "stop"
            g["target_country"] = None
            g["target_province"] = None
        for f in self.navy.formations(country_code):
            f["mission"] = "stop"
            f["sea_zone"] = None
        self.world.mark_dirty()

    def damage_random_targets(self, country_code: str, amount: float = 5) -> dict[str, int]:
        """Deterministic test helper: damage one of each service when present."""
        amount = abs(float(amount))
        result = {"air": 0, "pvo": 0, "navy": 0}
        for g in self.aviation.active_groups(country_code)[:1]:
            g["condition"] = clamp(float(g.get("condition", 100)) - amount)
            result["air"] += 1
        for u in self.pvo.units(country_code)[:1]:
            u["condition"] = clamp(float(u.get("condition", 100)) - amount)
            result["pvo"] += 1
        for f in self.navy.formations(country_code)[:1]:
            f["condition"] = clamp(float(f.get("condition", 100)) - amount)
            result["navy"] += 1
        if any(result.values()):
            self.world.mark_dirty()
        return result

                                                                                      
