def _clamp(v: float, a: float = 0.0, b: float = 100.0) -> float:
    return max(a, min(b, float(v)))


def _other_countries(country_code: str) -> list[str]:
    return [c for c in PLAYABLE_COUNTRIES if c != country_code]


def treaty_label(key: str) -> str:
    return TREATY_TYPES.get(key, key)


                                                                             
                   
                                                                             

class Diplomacy:
    def __init__(self, world: Any, wars: Any) -> None:
        self.world = world
        self.wars = wars

    def relation(self, country_code: str, other: str) -> int:
        if country_code == other:
            return 100
        c = self.world.country(country_code)
        return int(c.relations.get(other, 0))

    def set_relation(self, country_code: str, other: str, value: int, symmetric: bool = True) -> tuple[bool, str]:
        if country_code == other or country_code not in PLAYABLE_COUNTRIES or other not in PLAYABLE_COUNTRIES:
            return False, "Неверная пара стран."
        value = int(_clamp(value, -100, 100))
        self.world.country(country_code).relations[other] = value
        if symmetric:
            self.world.country(other).relations[country_code] = value
        self.world.mark_dirty()
        return True, "Отношения изменены."

    def change_relation(self, country_code: str, other: str, delta: int, symmetric: bool = True) -> tuple[bool, str]:
        return self.set_relation(country_code, other, self.relation(country_code, other) + int(delta), symmetric)

    def _treaty_exists(self, a: str, b: str, kind: Optional[str] = None) -> bool:
        for treaty in self.world.treaties.values():
            if not treaty.get("active", True):
                continue
            pair = {treaty.get("a"), treaty.get("b")}
            if pair != {a, b}:
                continue
            if kind is None or treaty.get("type") == kind:
                return True
        return False

    def propose_treaty(self, country_code: str, other: str, key: str) -> tuple[bool, str, Optional[str]]:
        if country_code == other or other not in PLAYABLE_COUNTRIES:
            return False, "Неверная страна.", None
        if key not in TREATY_TYPES:
            return False, "Неизвестный договор.", None
        if self._treaty_exists(country_code, other, key):
            return False, "Такой договор уже действует.", None
        tid = self.world.next_entity_id("treaty")
        self.world.treaties[tid] = {
            "id": tid,
            "a": country_code,
            "b": other,
            "type": key,
            "active": True,
            "created_at": self.world.game_minutes,
            "status": "active",
        }
                                                                                    
        relation_delta = 4 if key != "embargo" else -8
        self.change_relation(country_code, other, relation_delta)
        self.world.add_journal("diplomacy", "Договор подписан", f"{country_display(country_code)} и {country_display(other)}: {TREATY_TYPES[key]}.")
        self.world.add_log("treaty_created", None, {"treaty": tid, "a": country_code, "b": other, "type": key})
        return True, f"Договор подписан: {TREATY_TYPES[key]}.", tid

    def terminate_treaty(self, treaty_id: str, country_code: str) -> tuple[bool, str]:
        treaty = self.world.treaties.get(treaty_id)
        if not treaty or not treaty.get("active", False):
            return False, "Договор не найден."
        if country_code not in (treaty.get("a"), treaty.get("b")):
            return False, "Вы не участник договора."
        treaty["active"] = False
        treaty["status"] = "terminated"
        self.world.mark_dirty()
        return True, "Договор прекращён."

    def treaty_list(self, country_code: str) -> list[dict[str, Any]]:
        return [t for t in self.world.treaties.values() if t.get("active", True) and country_code in (t.get("a"), t.get("b"))]

    def send_message(self, sender: str, receiver: str, text: str) -> tuple[bool, str]:
        if sender == receiver or receiver not in PLAYABLE_COUNTRIES:
            return False, "Неверный получатель."
        text = str(text).strip()
        if not text:
            return False, "Сообщение пустое."
        if len(text) > DIPLOMACY_MESSAGE_LIMIT:
            return False, f"Максимум {DIPLOMACY_MESSAGE_LIMIT} символов."
        record = {"time": self.world.game_minutes, "sender": sender, "receiver": receiver, "from": sender, "to": receiver, "text": text}
        self.world.country(sender).message_history.append(record)
        self.world.country(receiver).message_history.append(record)
        self.world.country(sender).message_history = self.world.country(sender).message_history[-100:]
        self.world.country(receiver).message_history = self.world.country(receiver).message_history[-100:]
        self.world.add_journal("diplomacy", "Сообщение", f"Сообщение отправлено стране {country_display(receiver)}.", sender)
        self.world.mark_dirty()
        return True, "Сообщение отправлено."

    def send_warning(self, sender: str, receiver: str, text: str) -> tuple[bool, str]:
        """Отдельное дипломатическое предупреждение без механики ультиматума."""
        if sender == receiver or receiver not in PLAYABLE_COUNTRIES:
            return False, "Неверная страна."
        text = str(text).strip()
        if not text:
            return False, "Предупреждение пустое."
        if len(text) > DIPLOMACY_MESSAGE_LIMIT:
            return False, f"Максимум {DIPLOMACY_MESSAGE_LIMIT} символов."
        record = {"time": self.world.game_minutes, "sender": sender, "receiver": receiver, "from": sender, "to": receiver, "text": text, "kind": "warning"}
        self.world.country(sender).message_history.append(record)
        self.world.country(receiver).message_history.append(record)
        self.world.country(sender).message_history = self.world.country(sender).message_history[-100:]
        self.world.country(receiver).message_history = self.world.country(receiver).message_history[-100:]
        self.change_relation(sender, receiver, -3)
        self.world.add_journal("diplomacy", "Предупреждение", f"{country_display(sender)} направила предупреждение {country_display(receiver)}.", sender)
        self.world.add_log("warning_sent", None, {"sender": sender, "receiver": receiver})
        self.world.mark_dirty()
        return True, "Предупреждение отправлено."

    def ultimatum(self, sender: str, receiver: str, text: str, deadline_hours: float) -> tuple[bool, str, Optional[str]]:
        if sender == receiver or receiver not in PLAYABLE_COUNTRIES:
            return False, "Неверная страна.", None
        deadline_hours = _clamp(deadline_hours, ULTIMATUM_MIN_HOURS, ULTIMATUM_MAX_HOURS)
        uid = self.world.next_entity_id("ultimatum")
        self.world.treaties[uid] = {
            "id": uid,
            "type": "ultimatum",
            "a": sender,
            "b": receiver,
            "text": str(text)[:DIPLOMACY_MESSAGE_LIMIT],
            "deadline": self.world.game_minutes + deadline_hours * 60.0,
            "active": True,
            "status": "pending",
            "created_at": self.world.game_minutes,
        }
        self.world.add_journal("diplomacy", "Ультиматум", f"{country_display(sender)} направила ультиматум {country_display(receiver)}.")
        self.world.mark_dirty()
        return True, "Ультиматум отправлен.", uid

    def respond_ultimatum(self, ultimatum_id: str, receiver: str, accept: bool) -> tuple[bool, str]:
        item = self.world.treaties.get(ultimatum_id)
        if not item or item.get("type") != "ultimatum" or item.get("status") != "pending":
            return False, "Ультиматум не найден."
        if item.get("b") != receiver:
            return False, "Это не ваш ультиматум."
        item["status"] = "accepted" if accept else "rejected"
        item["active"] = False
        self.change_relation(item["b"], item["a"], 5 if accept else -12)
        self.world.mark_dirty()
        return True, "Ответ принят." if accept else "Ультиматум отклонён."

    def create_war_goal(self, creator: str, target: str, goal_type: str) -> tuple[bool, str, Optional[str]]:
        if creator == target or target not in PLAYABLE_COUNTRIES:
            return False, "Неверная цель войны.", None
        if any(g.get("creator") == creator and g.get("target") == target and g.get("status") == "prepared" for g in self.world.war_goals.values()):
            return False, "Цель войны уже подготовлена.", None
        gid = self.world.next_entity_id("goal")
        self.world.war_goals[gid] = {
            "id": gid,
            "creator": creator,
            "target": target,
            "type": goal_type,
            "status": "prepared",
            "created_at": self.world.game_minutes,
        }
        self.world.mark_dirty()
        return True, "Цель войны подготовлена.", gid

    def declare_from_goal(self, goal_id: str) -> tuple[bool, str, Optional[str]]:
        goal = self.world.war_goals.get(goal_id)
        if not goal or goal.get("status") != "prepared":
            return False, "Цель войны не найдена.", None
        allowed, why = can_declare_war(self.world, goal["creator"], goal["target"])
        if not allowed:
            return False, why, None
        reason = f"goalid:{goal_id}:{goal.get('type', 'территориальная цель')}"
        ok, reason_text, wid = self.wars.declare(goal["creator"], goal["target"], reason)
        if ok:
            goal["status"] = "used"
            goal["war"] = wid
            self.world.mark_dirty()
        return ok, reason_text, wid

    def wars_for(self, country_code: str) -> list[Any]:
        return [w for w in self.world.wars.values() if w.active and w.involves(country_code)]

    def can_trade(self, a: str, b: str) -> tuple[bool, str]:
        if a == b or b not in PLAYABLE_COUNTRIES:
            return False, "Неверный партнёр."
        if self._treaty_exists(a, b, "embargo"):
            return False, "Между странами действует эмбарго."
        return True, "Торговля разрешена."

    def tick(self, minutes: float) -> None:
        now = self.world.game_minutes
        for tid, item in list(self.world.treaties.items()):
            if item.get("type") == "ultimatum" and item.get("status") == "pending" and now >= float(item.get("deadline", now + 1)):
                item["status"] = "expired"
                item["active"] = False
                self.change_relation(item.get("a"), item.get("b"), -10)
                self.world.add_journal("diplomacy", "Ультиматум истёк", f"Срок ультиматума {tid} истёк.")
        self.world.mark_dirty()


                                                                             
       
                                                                             

class Trade:
    def __init__(self, world: Any, economy: Any) -> None:
        self.world = world
        self.economy = economy

    def _route_available(self, sender: str, receiver: str, route: str) -> bool:
        if route == "land":
            return self.world.country_share_border(sender, receiver)
        if route == "sea":
            own_sea = any(self.world.province(pid).sea_access for pid in self.world.country(sender).province_ids)
            other_sea = any(self.world.province(pid).sea_access for pid in self.world.country(receiver).province_ids)
            return own_sea and other_sea
        return False

    def _active_deal_count(self, country: str) -> int:
        return sum(1 for t in self.world.trades.values() if t.get("status") in {"active", "in_transit"} and country in (t.get("sender"), t.get("receiver")))

    def create(self, sender: str, receiver: str, resource: str, quantity: int, price: int, route: str) -> tuple[bool, str, Optional[str]]:
        quantity = int(quantity)
        price = int(price)
        if sender == receiver or receiver not in PLAYABLE_COUNTRIES:
            return False, "Неверный торговый партнёр.", None
        if resource not in RESOURCE_KEYS:
            return False, "Ресурс не поддерживается.", None
        if quantity <= 0 or price <= 0:
            return False, "Количество и цена должны быть больше нуля.", None
        if route not in {"land", "sea"} or not self._route_available(sender, receiver, route):
            return False, "Выбранный торговый маршрут недоступен.", None
        if self._active_deal_count(sender) >= 15:
            return False, "У страны слишком много активных сделок.", None
        s = self.world.country(sender)
        r = self.world.country(receiver)
        total_price = quantity * price
        if s.resources.get(resource, 0) < quantity:
            return False, f"Недостаточно {RESOURCE_DISPLAY.get(resource, resource)}.", None
        if r.budget < total_price:
            return False, "У покупателя недостаточно денег.", None
                                                                               
        s.resources[resource] -= quantity
        r.budget -= total_price
        tid = self.world.next_entity_id("trade")
        self.world.trades[tid] = {
            "id": tid,
            "sender": sender,
            "receiver": receiver,
            "resource": resource,
            "quantity": quantity,
            "price": price,
            "total": total_price,
            "route": route,
            "status": "in_transit",
            "created_at": self.world.game_minutes,
            "remaining_minutes": 60.0 if route == "land" else 90.0,
            "delivery_progress": 0.0,
            "route_type": route,
        }
        self.world.add_journal("trade", "Создана торговая сделка", f"{country_display(sender)} → {country_display(receiver)}: {format_number(quantity)} {RESOURCE_DISPLAY.get(resource, resource)}.")
        self.world.mark_dirty()
        return True, f"Сделка создана на {format_money(total_price)}.", tid

    def cancel(self, trade_id: str, country_code: str) -> tuple[bool, str]:
        t = self.world.trades.get(trade_id)
        if not t or t.get("status") not in {"active", "in_transit"}:
            return False, "Сделка не найдена или уже завершена."
        if country_code not in (t.get("sender"), t.get("receiver")):
            return False, "Вы не участник сделки."
        if t.get("cancelled_at") is not None:
            return False, "Сделка уже отменена."
        sender = self.world.country(t["sender"])
        receiver = self.world.country(t["receiver"])
        sender.resources[t["resource"]] = sender.resources.get(t["resource"], 0) + int(t["quantity"])
        receiver.budget += int(t["total"])
        t["status"] = "cancelled"
        t["cancelled_at"] = self.world.game_minutes
        self.world.mark_dirty()
        return True, "Сделка отменена, резервы возвращены."

    def tick(self, minutes: float) -> list[str]:
        completed = []
        for tid, t in list(self.world.trades.items()):
            if t.get("status") not in {"active", "in_transit"}:
                continue
            total_duration = 60.0 if t.get("route") == "land" else 90.0
            t["remaining_minutes"] = max(0.0, float(t.get("remaining_minutes", total_duration)) - float(minutes))
            t["delivery_progress"] = max(0.0, min(1.0, 1.0 - t["remaining_minutes"] / max(1.0, total_duration)))
            if t["remaining_minutes"] <= 0:
                receiver = self.world.country(t["receiver"])
                receiver.resources[t["resource"]] = receiver.resources.get(t["resource"], 0) + int(t["quantity"])
                t["status"] = "completed"
                t["completed_at"] = self.world.game_minutes
                completed.append(tid)
                self.world.add_journal("trade", "Торговая поставка доставлена", f"Сделка {tid} завершена.")
        if completed:
            self.world.mark_dirty()
        return completed

    def active_for(self, country: str) -> list[dict[str, Any]]:
        return [t for t in self.world.trades.values() if t.get("status") in {"active", "in_transit"} and country in (t.get("sender"), t.get("receiver"))]

    def history_for(self, country: str) -> list[dict[str, Any]]:
        return [t for t in self.world.trades.values() if country in (t.get("sender"), t.get("receiver"))]

    def validate(self) -> list[str]:
        errors = []
        for tid, t in self.world.trades.items():
            if t.get("sender") not in PLAYABLE_COUNTRIES or t.get("receiver") not in PLAYABLE_COUNTRIES:
                errors.append(f"trade {tid}: bad country")
            if int(t.get("quantity", 0)) <= 0:
                errors.append(f"trade {tid}: bad quantity")
        return errors


                                                                             
                 
                                                                             

class DecisionEngine:
    def __init__(self, world: Any) -> None:
        self.world = world

    def available(self, country_code: str, category: Optional[str] = None) -> list[DecisionDef]:
        active = self.world.country(country_code).active_decisions
        active_categories = {DECISIONS[k].category for k,v in active.items() if k in DECISIONS and not v.get("finished", False)}
        result = []
        for key, decision in DECISIONS.items():
            if category and decision.category != category:
                continue
            if key in active and not active[key].get("finished", False):
                continue
            if decision.category in active_categories:
                continue
            result.append(decision)
        return result

    def start(self, country_code: str, key: str) -> tuple[bool, str]:
        decision = DECISIONS.get(key)
        if not decision:
            return False, "Решение не найдено."
        c = self.world.country(country_code)
        active = c.active_decisions.get(key)
        if active and not active.get("finished", False):
            return False, "Решение уже действует."
                                                                           
                                                                          
        for other_key, other_data in c.active_decisions.items():
            other_def = DECISIONS.get(other_key)
            if other_def and other_def.category == decision.category and not other_data.get("finished", False):
                return False, f"В категории «{DECISION_CATEGORIES.get(decision.category, decision.category)}» уже есть активное решение."
        if c.budget < decision.cost:
            return False, "Недостаточно денег."
        c.budget -= decision.cost
        data = {
            "key": key,
            "title": decision.title,
            "started_at": self.world.game_minutes,
            "remaining_minutes": decision.duration_days * 1440,
            "finished": False,
            "effects": dict(decision.effects),
            "permanent": decision.permanent,
            "before_income_daily": c.income_daily,
            "before_industry_modifier": c.industry_modifier,
        }
        c.active_decisions[key] = data
        self._apply_start_effect(c, decision)
        if decision.permanent:
            data["remaining_minutes"] = 0
            data["finished"] = True
        self.world.add_journal("decisions", "Решение принято", f"{country_display(country_code)}: {decision.title}.", country_code)
        self.world.mark_dirty()
        return True, f"Решение принято: {decision.title}."

    def _apply_start_effect(self, country: Any, decision: DecisionDef) -> None:
        active = country.active_decisions.get(decision.key, {})
        runtime = []
                                                                              
        pools = {
            "army_readiness": self.world.divisions,
            "air_readiness": self.world.air_groups,
            "pvo_detection": self.world.pvo_units,
            "navy_readiness": self.world.fleets,
        }
        for effect_key, pool in pools.items():
            delta = float(decision.effects.get(effect_key, 0.0))
            if not delta:
                continue
            for obj_id, obj in pool.items():
                if obj.get("country") != country.code:
                    continue
                field = "detection" if effect_key == "pvo_detection" else "readiness"
                old = float(obj.get(field, 0.0))
                cap = 100.0
                obj[field] = min(cap, old + delta)
                runtime.append({"pool": effect_key, "id": obj_id, "field": field, "delta": min(delta, cap-old)})
        active["runtime_adjustments"] = runtime
        for key, value in decision.effects.items():
            if key == "stability":
                country.stability = _clamp(country.stability + value, 0, 100)
            elif key == "industry_modifier":
                country.industry_modifier = max(0.25, country.industry_modifier + value)
            elif key == "income_daily_flat":
                country.income_daily += int(value)
            elif key == "income_daily_pct":
                country.income_daily = int(country.income_daily * (1 + value / 100.0))
            elif key == "manpower_daily_pct":
                                                                              
                pass
            elif key == "relation":
                                                                                                                                    
                for other in PLAYABLE_COUNTRIES:
                    if other != country.code:
                        country.relations[other] = int(_clamp(country.relations.get(other, 0) + value, -100, 100))
                        try:
                            self.world.country(other).relations[country.code] = country.relations[other]
                        except Exception:
                            pass

    def _apply_finish_effect(self, country: Any, decision: DecisionDef, active_data: Optional[dict[str, Any]] = None) -> None:
                                                                                                                 
        if active_data and not decision.permanent:
            if "before_income_daily" in active_data:
                country.income_daily = int(active_data["before_income_daily"])
            if "before_industry_modifier" in active_data:
                country.industry_modifier = float(active_data["before_industry_modifier"])
            for adj in active_data.get("runtime_adjustments", []):
                pool = {
                    "army_readiness": self.world.divisions,
                    "air_readiness": self.world.air_groups,
                    "pvo_detection": self.world.pvo_units,
                    "navy_readiness": self.world.fleets,
                }.get(adj.get("pool"))
                obj = pool.get(adj.get("id")) if pool is not None else None
                if obj is not None:
                    field = adj.get("field", "readiness")
                    obj[field] = max(0.0, float(obj.get(field, 0.0)) - float(adj.get("delta", 0.0)))


    def tick(self, minutes: float) -> list[str]:
        finished = []
        for country_code in PLAYABLE_COUNTRIES:
            c = self.world.country(country_code)
            for key, active in list(c.active_decisions.items()):
                if active.get("finished"):
                    continue
                remaining = max(0.0, float(active.get("remaining_minutes", 0)) - float(minutes))
                active["remaining_minutes"] = remaining
                if remaining <= 0:
                    active["finished"] = True
                    definition = DECISIONS.get(key)
                    if definition:
                        self._apply_finish_effect(c, definition, active)
                    finished.append(key)
                    self.world.add_journal("decisions", "Решение завершено", f"{country_display(country_code)}: {active.get('title', key)}.", country_code)
        if finished:
            self.world.mark_dirty()
        return finished

    def active_text(self, country_code: str) -> str:
        c = self.world.country(country_code)
        active = [v for v in c.active_decisions.values() if not v.get("finished")]
        if not active:
            return "Активных решений нет."
        lines = []
        for d in active:
            lines.append(f"• {d.get('title', d.get('key'))}: осталось {float(d.get('remaining_minutes', 0))/1440:.1f} дн.")
        return "\n".join(lines)

    def validate(self) -> list[str]:
        errors = []
        for code in PLAYABLE_COUNTRIES:
            for key in self.world.country(code).active_decisions:
                if key not in DECISIONS:
                    errors.append(f"decision {code}/{key}: unknown")
        return errors


__all__ = [
    "DECISION_CATEGORIES", "DECISIONS", "TREATY_TYPES", "DecisionDef",
    "DecisionEngine", "Diplomacy", "Trade", "treaty_label",
]

                                                                             
                                       
                                                                             

def diplomatic_status(world: Any, country_code: str) -> dict[str, Any]:
    c = world.country(country_code)
    relations = {other: int(c.relations.get(other, 0)) for other in PLAYABLE_COUNTRIES if other != country_code}
    treaties = [t for t in world.treaties.values() if t.get("active", True) and country_code in (t.get("a"), t.get("b"))]
    wars = [w for w in world.wars.values() if w.active and w.involves(country_code)]
    goals = [g for g in world.war_goals.values() if g.get("creator") == country_code and g.get("status") == "prepared"]
    messages = [m for m in c.message_history[-20:]]
    return {"relations": relations, "treaties": treaties, "wars": wars, "war_goals": goals, "messages": messages}


def relations_table(world: Any, country_code: str) -> list[dict[str, Any]]:
    c = world.country(country_code)
    result = []
    for other in PLAYABLE_COUNTRIES:
        if other == country_code:
            continue
        relation = int(c.relations.get(other, 0))
        trend = "дружественные" if relation >= 50 else "хорошие" if relation >= 20 else "нейтральные" if relation >= -20 else "напряжённые" if relation >= -50 else "враждебные"
        result.append({"country": other, "relation": relation, "status": trend, "border": world.country_share_border(country_code, other)})
    return sorted(result, key=lambda x: x["relation"], reverse=True)


def treaty_matrix(world: Any) -> dict[tuple[str, str], list[str]]:
    result: dict[tuple[str, str], list[str]] = {}
    for treaty in world.treaties.values():
        if not treaty.get("active", True):
            continue
        a, b = treaty.get("a"), treaty.get("b")
        if a not in PLAYABLE_COUNTRIES or b not in PLAYABLE_COUNTRIES:
            continue
        key = tuple(sorted((a, b)))
        result.setdefault(key, []).append(str(treaty.get("type")))
    return result


def can_declare_war(world: Any, attacker: str, defender: str) -> tuple[bool, str]:
    if attacker == defender:
        return False, "Нельзя атаковать себя."
    if attacker not in PLAYABLE_COUNTRIES or defender not in PLAYABLE_COUNTRIES:
        return False, "Недоступная страна."
    if any(w.active and w.involves(attacker) and w.involves(defender) for w in world.wars.values()):
        return False, "Страны уже воюют."
    for treaty in world.treaties.values():
        if not treaty.get("active", True):
            continue
        if treaty.get("type") == "nap" and {treaty.get("a"), treaty.get("b")} == {attacker, defender}:
            return False, "Действует договор о ненападении."
    return True, "Война возможна."


def create_standard_war_goal(diplomacy: Diplomacy, country_code: str, target: str) -> tuple[bool, str, Optional[str]]:
    return diplomacy.create_war_goal(country_code, target, "территориальная цель")


def country_has_embargo(world: Any, a: str, b: str) -> bool:
    return any(
        t.get("active", True) and t.get("type") == "embargo" and {t.get("a"), t.get("b")} == {a, b}
        for t in world.treaties.values()
    )


def trade_route_options(world: Any, sender: str, receiver: str) -> list[str]:
    options = []
    if world.country_share_border(sender, receiver):
        options.append("land")
    own_sea = any(world.province(pid).sea_access for pid in world.country(sender).province_ids)
    other_sea = any(world.province(pid).sea_access for pid in world.country(receiver).province_ids)
    if own_sea and other_sea:
        options.append("sea")
    return options


def recommended_trade_quantity(world: Any, sender: str, receiver: str, resource: str) -> int:
    if resource not in RESOURCE_KEYS:
        return 0
    sender_stock = int(world.country(sender).resources.get(resource, 0))
    if sender_stock <= 0:
        return 0
    return max(0, min(sender_stock // 4, 10_000))


def trade_value(quantity: int, unit_price: int) -> int:
    return max(0, int(quantity)) * max(0, int(unit_price))


def trade_duration_minutes(route: str, quantity: int) -> float:
    base = 60.0 if route == "land" else 90.0
    scale = min(240.0, max(0.0, quantity) / 500.0)
    return base + scale


def completed_trade_report(world: Any, country_code: str) -> list[dict[str, Any]]:
    rows = []
    for trade in world.trades.values():
        if trade.get("status") != "completed" or country_code not in (trade.get("sender"), trade.get("receiver")):
            continue
        rows.append({"id": trade.get("id"), "resource": trade.get("resource"), "quantity": trade.get("quantity"), "route": trade.get("route"), "total": trade.get("total")})
    return rows


def decision_text(decision: DecisionDef) -> str:
    effects = ", ".join(f"{k}: {v:+g}" for k, v in decision.effects.items()) or "нет"
    return f"{decision.title}\n{decision.description}\nСтоимость: {format_money(decision.cost)}\nСрок: {decision.duration_days:g} дн.\nЭффекты: {effects}"


def decision_category_list(category: str) -> list[DecisionDef]:
    return [d for d in DECISIONS.values() if d.category == category]


def active_decision_snapshot(world: Any, country_code: str) -> list[dict[str, Any]]:
    result = []
    for key, active in world.country(country_code).active_decisions.items():
        result.append({"key": key, "title": active.get("title", key), "remaining_days": float(active.get("remaining_minutes", 0)) / 1440.0, "finished": bool(active.get("finished"))})
    return result


def diplomatic_validation(world: Any) -> list[str]:
    errors = []
    for code in PLAYABLE_COUNTRIES:
        for other, relation in world.country(code).relations.items():
            if other not in PLAYABLE_COUNTRIES or other == code:
                errors.append(f"relations {code}: bad key {other}")
            if not -100 <= int(relation) <= 100:
                errors.append(f"relations {code}/{other}: out of range")
    for tid, treaty in world.treaties.items():
        if treaty.get("a") not in PLAYABLE_COUNTRIES or treaty.get("b") not in PLAYABLE_COUNTRIES:
            errors.append(f"treaty {tid}: bad country")
        if treaty.get("a") == treaty.get("b"):
            errors.append(f"treaty {tid}: same countries")
    return errors

                                                                             
                                                   
                                                                             

def diplomacy_text(diplomacy: Diplomacy, country_code: str) -> str:
    status = diplomatic_status(diplomacy.world, country_code)
    relation_lines = []
    for other, value in status["relations"].items():
        relation_lines.append(f"{country_display(other)}: {value:+d}")
    treaty_lines = [f"{treaty_label(t.get('type'))} — {country_display(t.get('b') if t.get('a') == country_code else t.get('a'))}" for t in status["treaties"]]
    war_lines = [f"{country_display(w.opponent(country_code) or '?')} — {w.attacker_score:.0f}:{w.defender_score:.0f}" for w in status["wars"]]
    return (
        f"🤝 <b>Дипломатия {country_display(country_code)}</b>\n\n"
        f"<b>Отношения</b>\n" + ("\n".join(relation_lines) or "нет данных") + "\n\n"
        f"<b>Договоры</b>\n" + ("\n".join(treaty_lines) or "нет") + "\n\n"
        f"<b>Войны</b>\n" + ("\n".join(war_lines) or "нет")
    )


def trade_text(trade: Trade, country_code: str) -> str:
    active = trade.active_for(country_code)
    history = trade.history_for(country_code)
    lines = []
    for item in active:
        partner = item.get("receiver") if item.get("sender") == country_code else item.get("sender")
        role = "продажа" if item.get("sender") == country_code else "покупка"
        lines.append(f"{item.get('id')}: {role} {format_number(item.get('quantity', 0))} {RESOURCE_DISPLAY.get(item.get('resource'), item.get('resource'))} → {country_display(partner)}")
    return (
        f"🚛 <b>Торговля {country_display(country_code)}</b>\n\n"
        f"Активных сделок: {len(active)}\n"
        f"История: {len(history)}\n\n" + ("\n".join(lines) if lines else "Активных сделок нет.")
    )


def decision_catalog_by_category() -> dict[str, list[dict[str, Any]]]:
    result = {key: [] for key in DECISION_CATEGORIES}
    for d in DECISIONS.values():
        result.setdefault(d.category, []).append({"key": d.key, "title": d.title, "cost": d.cost, "days": d.duration_days, "permanent": d.permanent, "description": d.description})
    return result


def relation_effect_from_action(action: str) -> int:
    return {"message": 1, "trade": 3, "cooperation": 5, "ultimatum": -10, "embargo": -15, "war": -30}.get(action, 0)


def apply_diplomatic_action(diplomacy: Diplomacy, sender: str, receiver: str, action: str) -> tuple[bool, str]:
    delta = relation_effect_from_action(action)
    if delta == 0:
        return False, "Действие не определено."
    return diplomacy.change_relation(sender, receiver, delta)


def war_goal_summary(world: Any, country_code: str) -> list[dict[str, Any]]:
    return [g for g in world.war_goals.values() if g.get("creator") == country_code]


def pending_ultimatums(world: Any, receiver: str) -> list[dict[str, Any]]:
    return [t for t in world.treaties.values() if t.get("type") == "ultimatum" and t.get("status") == "pending" and t.get("b") == receiver]


def trade_reserve_preview(world: Any, sender: str, receiver: str, resource: str, quantity: int, price: int, route: str) -> dict[str, Any]:
    errors = []
    if resource not in RESOURCE_KEYS:
        errors.append("unknown resource")
    if route not in trade_route_options(world, sender, receiver):
        errors.append("route unavailable")
    quantity = max(0, int(quantity))
    price = max(0, int(price))
    sender_stock = int(world.country(sender).resources.get(resource, 0)) if resource in RESOURCE_KEYS else 0
    buyer_budget = int(world.country(receiver).budget)
    total = quantity * price
    if sender_stock < quantity:
        errors.append("insufficient seller stock")
    if buyer_budget < total:
        errors.append("insufficient buyer budget")
    return {"ok": not errors, "errors": errors, "seller_stock": sender_stock, "buyer_budget": buyer_budget, "total": total}


def best_trade_route(world: Any, sender: str, receiver: str) -> Optional[str]:
    routes = trade_route_options(world, sender, receiver)
    if "land" in routes:
        return "land"
    if "sea" in routes:
        return "sea"
    return None


def decision_cost_forecast(world: Any, country_code: str, key: str) -> dict[str, Any]:
    d = DECISIONS.get(key)
    if not d:
        return {"ok": False, "reason": "unknown decision"}
    budget = world.country(country_code).budget
    return {"ok": budget >= d.cost, "cost": d.cost, "budget": budget, "after": budget - d.cost}


def diplomacy_validate_full(world: Any) -> list[str]:
    errors = diplomatic_validation(world)
    for goal_id, goal in world.war_goals.items():
        if goal.get("creator") not in PLAYABLE_COUNTRIES or goal.get("target") not in PLAYABLE_COUNTRIES:
            errors.append(f"war goal {goal_id}: bad country")
    for item_id, item in world.treaties.items():
        if item.get("type") == "ultimatum" and float(item.get("deadline", 0)) < float(item.get("created_at", 0)):
            errors.append(f"ultimatum {item_id}: deadline before creation")
    return errors

                                                                             
                                                       
                                                                             

def relation_score(world: Any, country_code: str) -> float:
    values = [int(v) for k, v in world.country(country_code).relations.items() if k in PLAYABLE_COUNTRIES and k != country_code]
    return sum(values) / len(values) if values else 0.0


def international_tension(world: Any) -> float:
    tension = 0.0
    for a in PLAYABLE_COUNTRIES:
        for b in PLAYABLE_COUNTRIES:
            if a >= b:
                continue
            relation = abs(int(world.country(a).relations.get(b, 0)))
            tension += relation * 0.04
            if any(w.active and w.involves(a) and w.involves(b) for w in world.wars.values()):
                tension += 25
            if country_has_embargo(world, a, b):
                tension += 5
    return min(100.0, tension)


def diplomatic_pressure(world: Any, country_code: str) -> float:
    score = 0.0
    for other in PLAYABLE_COUNTRIES:
        if other == country_code:
            continue
        relation = int(world.country(country_code).relations.get(other, 0))
        score += relation * 0.25
        if world.country_share_border(country_code, other):
            score += 4
    score += len([w for w in world.wars.values() if w.active and w.involves(country_code)]) * 8
    return score


def peace_score(world: Any, country_code: str) -> float:
    wars = len([w for w in world.wars.values() if w.active and w.involves(country_code)])
    relation = relation_score(world, country_code)
    treaties = len([t for t in world.treaties.values() if t.get("active") and country_code in (t.get("a"), t.get("b"))])
    return max(0.0, min(100.0, 60 + relation * 0.25 + treaties * 3 - wars * 20))


def country_diplomatic_profile(world: Any, country_code: str) -> dict[str, Any]:
    return {
        "relations": relations_table(world, country_code),
        "relation_average": relation_score(world, country_code),
        "pressure": diplomatic_pressure(world, country_code),
        "peace": peace_score(world, country_code),
        "treaties": [dict(t) for t in world.treaties.values() if t.get("active", True) and country_code in (t.get("a"), t.get("b"))],
        "wars": [w.id for w in world.wars.values() if w.active and w.involves(country_code)],
        "goals": war_goal_summary(world, country_code),
    }


def suggest_diplomatic_action(world: Any, sender: str, receiver: str) -> str:
    relation = int(world.country(sender).relations.get(receiver, 0))
    if country_has_embargo(world, sender, receiver):
        return "end_embargo"
    if relation >= 60:
        return "cooperation"
    if relation >= 20:
        return "trade"
    if relation >= -20:
        return "message"
    if relation >= -50:
        return "warning"
    return "ultimatum"


def balanced_trade_price(resource: str, quantity: int) -> int:
    base = {
        "iron": 120,
        "coal": 110,
        "oil": 180,
        "aluminum": 160,
        "steel": 420,
        "components": 650,
        "fuel": 250,
    }.get(resource, 100)
                                                     
    discount = min(0.18, max(0.0, quantity) / 100_000.0)
    return max(1, int(base * (1 - discount)))


def trade_offer(world: Any, sender: str, receiver: str, resource: str, quantity: int, route: Optional[str] = None) -> dict[str, Any]:
    quantity = max(0, int(quantity))
    route = route or best_trade_route(world, sender, receiver)
    price = balanced_trade_price(resource, quantity)
    preview = trade_reserve_preview(world, sender, receiver, resource, quantity, price, route or "")
    preview.update({"resource": resource, "quantity": quantity, "price": price, "route": route})
    return preview


def decision_rank(world: Any, country_code: str) -> list[tuple[str, float]]:
    c = world.country(country_code)
    ranks = []
    for key, d in DECISIONS.items():
        value = 0.0
        for effect, amount in d.effects.items():
            if effect == "stability":
                value += float(amount) * (1.1 if c.stability < 45 else 0.6)
            elif effect == "industry_modifier":
                value += float(amount) * 30
            elif effect == "income_daily_pct":
                value += float(amount) * 2
            elif effect == "income_daily_flat":
                value += float(amount) / 1_000_000
            elif effect in {"army_readiness", "air_readiness", "pvo_detection", "navy_readiness"}:
                value += float(amount) * 1.8
            elif effect == "energy_bonus":
                value += float(amount) * 30
            elif effect == "relation":
                value += float(amount) * (1 if relation_score(world, country_code) < 0 else 0.5)
        value -= d.cost / 1_000_000_000
        ranks.append((key, value))
    return sorted(ranks, key=lambda x: x[1], reverse=True)

                                                                           
