class AttrDict(dict):
    """Dict that also exposes keys as attributes for legacy UI renderers."""
    def __getattr__(self, name: str) -> Any:
        try:
            return self[name]
        except KeyError as exc:
            raise AttributeError(name) from exc

    def __setattr__(self, name: str, value: Any) -> None:
        self[name] = value


def _wrap_mapping(value: dict[str, Any]) -> AttrDict:
    return value if isinstance(value, AttrDict) else AttrDict(value)

                                                                             
                        
                                                                             

@dataclass(frozen=True)
class ConstructionDef:
    key: str
    title: str
    cost: int
    duration_days: float
    effect: str
