APP_TITLE = "🌍 WORLD STRATEGY"
BOT_TOKEN_ENV_NAMES = ("WORLD_STRATEGY_BOT_TOKEN", "BOT_TOKEN", "TELEGRAM_BOT_TOKEN")
MAX_PAGE = 8
UI_REFRESH_SECONDS = 4.0
AUTOSAVE_REAL_SECONDS = 120.0
LOG_MESSAGE_LIMIT = 3800


def read_token() -> str:
    direct = str(globals().get("BOT_TOKEN", "")).strip()
    if direct:
        return direct
    for name in BOT_TOKEN_ENV_NAMES:
        value = os.getenv(name, "").strip()
        if value:
            return value
    return ""


def esc(value: Any) -> str:
    return html.escape(str(value))


def clamp_page(page: int, total: int, size: int = MAX_PAGE) -> int:
    if total <= 0:
        return 0
    return max(0, min(int(page), max(0, (total - 1) // size)))


def page_slice(items: list[Any], page: int, size: int = MAX_PAGE) -> tuple[list[Any], int, int]:
    page = clamp_page(page, len(items), size)
    start = page * size
    return items[start : start + size], page, max(1, (len(items) + size - 1) // size)


def fmt_pct(value: float) -> str:
    return f"{float(value):.0f}%"


def model_display(key: str) -> str:
    model = PRODUCTION_CATALOG.get(key)
    return model.name if model else key


                                                                               
                    
                                                                               


class SimulationEngine:
    """Неблокирующая игровая симуляция. В ней нет Telegram API-вызовов."""

    def __init__(self, app: "WorldApp") -> None:
        self.app = app
        self._task: Optional[asyncio.Task[Any]] = None
        self._stop = asyncio.Event()
        self.production_accum = 0.0
        self.daily_accum = 0.0
        self.army_accum = 0.0
        self.air_accum = 0.0
        self.trade_accum = 0.0
        self.save_accum_real = 0.0
        self.last_loop_real = time.monotonic()
        self.running = False

    async def start(self) -> None:
        if self._task and not self._task.done():
            return
        self._stop.clear()
        self.running = True
        self.last_loop_real = time.monotonic()
        self._task = asyncio.create_task(self._run(), name="world-simulation")

    async def stop(self) -> None:
        self._stop.set()
        task = self._task
        self._task = None
        if task:
            task.cancel()
            with suppress(asyncio.CancelledError):
                await task
        self.running = False

    async def _run(self) -> None:
        while not self._stop.is_set():
            loop_start = time.monotonic()
            real_delta = max(0.0, min(loop_start - self.last_loop_real, 2.0))
            self.last_loop_real = loop_start
            self.save_accum_real += real_delta
            try:
                async with self.app.world.simulation_lock:
                    if not self.app.world.paused and real_delta > 0:
                        game_delta = real_delta * float(self.app.world.speed)
                        self.advance(game_delta)
                    if self.save_accum_real >= AUTOSAVE_REAL_SECONDS:
                        if self.app.world.settings.get("autosave_enabled", True) and self.app.world.dirty:
                            await asyncio.to_thread(self.app.save_manager.save, self.app.world, True)
                            self.app.world.dirty = False
                        self.save_accum_real = 0.0
            except Exception as exc:
                self.app.world.add_log("simulation_error", None, {"error": repr(exc)})
            await asyncio.sleep(1.0)

    def advance(self, game_minutes: float, force: bool = False) -> None:
        if game_minutes <= 0 or (self.app.world.paused and not force):
            return
                                                                                
        remaining = min(float(game_minutes), 7 * 24 * 60)
        chunk = 60.0
        while remaining > 0:
            step = min(chunk, remaining)
            self.app.world.advance_minutes(step)
            self.production_accum += step
            self.daily_accum += step
            self.army_accum += step
            self.air_accum += step
            self.trade_accum += step

            self.app.construction.tick(step)
            self.app.repair.tick(step)

            while self.production_accum >= WAREHOUSE_UPDATE_MINUTES:
                self.production_accum -= WAREHOUSE_UPDATE_MINUTES
                for code in PLAYABLE_COUNTRIES:
                    self.app.production.tick(code, WAREHOUSE_UPDATE_MINUTES)

            while self.daily_accum >= 1440.0:
                self.daily_accum -= 1440.0
                for code in PLAYABLE_COUNTRIES:
                    self.app.economy.apply_daily_tick(code)

                                                                                                     
            while self.army_accum >= 5.0:
                self.army_accum -= 5.0
                results = self.app.wars.tick(5.0)
                if results:
                    self.app.world.add_log("combat_tick", None, {"battles": len(results)})

                                                                                         
            while self.air_accum >= 10.0:
                self.air_accum -= 10.0
                air_events = self.app.aviation.tick(10.0)
                self.app.pvo.tick(10.0)
                self.app.navy.tick(10.0)
                                                                                             
                for event in air_events[:20]:
                    if event.get("mission") != "strike":
                        continue
                    target_country = event.get("target_country")
                    target_province = event.get("target_province")
                    if target_country in PLAYABLE_COUNTRIES and target_province in self.app.world.provinces:
                        incoming = float(event.get("raw_strike_power", event.get("power", 0)))
                        interception = self.app.pvo.intercept(target_country, int(target_province), incoming)
                        event["pvo"] = interception
                        remaining_power = float(interception.get("remaining", incoming))
                        province = self.app.world.province(int(target_province))
                        province.condition = max(0.0, min(100.0, float(province.condition) - min(5.0, remaining_power / 1000.0)))
                        for building in ("airfield", "radar", "naval_base", "mil_factory"):
                            if province.building_level(building) > 0:
                                province.damage(building, min(4.0, remaining_power / 3000.0))

            while self.trade_accum >= 60.0:
                self.trade_accum -= 60.0
                self.app.trade.tick(60.0)
                self.app.decisions.tick(60.0)
                self.app.diplomacy.tick(60.0)

            remaining -= step

        self._cleanup_expired_inputs()

    def _cleanup_expired_inputs(self) -> None:
        now = time.monotonic()
        for player in self.app.world.players.values():
            expires = player.pending_data.get("expires_at")
            if expires and now > float(expires):
                player.clear_input()

    def warehouse_countdown(self) -> int:
        progress = self.production_accum % float(WAREHOUSE_UPDATE_MINUTES)
        remaining = WAREHOUSE_UPDATE_MINUTES - progress
        return max(1, int(round(remaining)))


                                                                               
            
                                                                               


class Keyboards:
    @staticmethod
    def row(*buttons: types.InlineKeyboardButton) -> list[types.InlineKeyboardButton]:
        return list(buttons)

    @staticmethod
    def btn(text: str, data: str) -> types.InlineKeyboardButton:
        text = str(text)
        data = str(data)
        if not text.strip():
            raise ValueError("Пустой текст кнопки")
        if len(data.encode("utf-8")) > 64:
            raise ValueError(f"Слишком длинный callback_data ({len(data.encode('utf-8'))} bytes): {data[:120]}")
        return types.InlineKeyboardButton(text=text, callback_data=data)

    @classmethod
    def nav(cls, back: str = "home") -> list[list[types.InlineKeyboardButton]]:
        return [
            [cls.btn("⬅️ Назад", back), cls.btn("🏠 Главное", "home")],
        ]

    @classmethod
    def home(cls) -> types.InlineKeyboardMarkup:
        rows = [
            [cls.btn("🏭 Производство", "screen:production"), cls.btn("🗺️ Карта", "screen:map")],
            [cls.btn("🏛️ Страна", "screen:country"), cls.btn("🪖 Армия", "screen:army")],
            [cls.btn("✈️ Авиация", "screen:air"), cls.btn("🛡️ ПВО", "screen:pvo")],
            [cls.btn("⚓ Флот", "screen:navy"), cls.btn("🤝 Дипломатия", "screen:diplomacy")],
            [cls.btn("🚛 Торговля", "screen:trade"), cls.btn("📦 Склад", "screen:warehouse")],
            [cls.btn("📜 Решения", "screen:decisions"), cls.btn("🏗️ Строительство", "screen:construction")],
            [cls.btn("🛠️ Ремонт", "screen:repair"), cls.btn("📜 Журнал", "screen:journal")],
            [cls.btn("📰 Новости", "screen:news"), cls.btn("❓ Объяснения", "screen:help")],
            [cls.btn("🌍 Выбор страны", "country:picker")],
        ]
        return types.InlineKeyboardMarkup(inline_keyboard=rows)

    @classmethod
    def country_picker(cls) -> types.InlineKeyboardMarkup:
        rows = [
            [cls.btn("🟦 Разбагare", "country:643177")],
            [cls.btn("🟩 Педагог", "country:781046")],
            [cls.btn("🟥 Markland", "country:173902")],
            [cls.btn("🧪 ТЕСТ", "country:7771")],
            [cls.btn("🛠️ Администратор", "country:admin")],
        ]
        return types.InlineKeyboardMarkup(inline_keyboard=rows)

    @classmethod
    def pagination(cls, base: str, page: int, total_pages: int) -> list[types.InlineKeyboardButton]:
        result: list[types.InlineKeyboardButton] = []
        if page > 0:
            result.append(cls.btn("◀️", f"{base}:{page-1}"))
        result.append(cls.btn(f"{page+1}/{max(1,total_pages)}", "noop"))
        if page + 1 < total_pages:
            result.append(cls.btn("▶️", f"{base}:{page+1}"))
        return result

    @classmethod
    def simple_nav(cls, back: str) -> types.InlineKeyboardMarkup:
        return types.InlineKeyboardMarkup(inline_keyboard=cls.nav(back))


                                                                               
          
                                                                               

def pending_ultimatums_for_country(world: Any, country: str) -> list[dict[str, Any]]:
    return [x for x in world.treaties.values() if x.get("type") == "ultimatum" and x.get("status") == "pending" and x.get("b") == country]


class WorldApp:
    def __init__(self, save_directory: str | Path = "saves") -> None:
        self.world = WorldState()
        self.save_manager = SaveManager(save_directory)
        load_warnings = self.save_manager.load(self.world)
        if load_warnings:
            self.world.add_log("load_warning", None, {"warnings": load_warnings[:20]})

        self.economy = Economy(self.world)
        self.production = Production(self.world)
        self.army = Army(self.world, self.production)
        self.wars = WarEngine(self.world, self.army)
        self.aviation = Aviation(self.world, self.production)
        self.pvo = PVO(self.world, self.production)
        self.navy = Navy(self.world, self.production)
        self.diplomacy = Diplomacy(self.world, self.wars)
        self.trade = Trade(self.world, self.economy)
        self.decisions = DecisionEngine(self.world)
        self.construction = Construction(self.world, self.economy)
        self.repair = Repair(self.world)
        self.news = NewsService(self.world)
        self.events = EventService(self.world)
        self.admin = AdminService(self.world, self.save_manager)
        self.diagnostics = Diagnostics(self.world, self.production)
        self.simulation = SimulationEngine(self)

        self.router = Router(name="world-strategy")
        self._screen_locks: dict[int, asyncio.Lock] = {}
        self._background_tasks: set[asyncio.Task[Any]] = set()
        self._bind_handlers()

                                                                        
                     
                                                                        

    def player(self, user_id: int, username: str = ""):
        player = self.world.players.get(user_id)
        if player is None:
            player = self.world.register_player(user_id, username)
        else:
            player.touch(username)
                                                                            
                                              
        current = getattr(player, "country", None)
        if current in PLAYABLE_COUNTRIES and getattr(player, "active_country", None) != current:
            player.active_country = current
        return player

    def country_for(self, user_id: int) -> Optional[str]:
        player = self.world.players.get(user_id)
        if not player or player.banned or player.is_admin:
            return None

                      
        if player.country in PLAYABLE_COUNTRIES:
            if getattr(player, "active_country", None) != player.country:
                player.active_country = player.country
            return player.country

                                                                          
                                                                             
                                                                    
        remembered = getattr(player, "active_country", None)
        if remembered not in PLAYABLE_COUNTRIES:
            return None
        owners = [
            other for other in self.world.players.values()
            if other.user_id != player.user_id
            and not other.banned
            and other.role != "admin"
            and other.country == remembered
        ]
        if owners:
            return None
        player.country = remembered
        player.current_screen = player.current_screen or "home"
        self.world.add_log("country_session_restored", user_id, {"country": remembered})
        self.world.mark_dirty()
        return remembered

    def require_country(self, user_id: int) -> tuple[Optional[str], str]:
        player = self.world.players.get(user_id)
        if player and player.banned:
            return None, "⛔ Вы заблокированы."
        country = self.country_for(user_id)
        if not country:
            return None, "🌍 Сначала выберите страну."
        return country, ""

    def is_admin(self, user_id: int) -> bool:
        return self.admin.is_admin(user_id)

    def screen_lock(self, user_id: int) -> asyncio.Lock:
        lock = self._screen_locks.get(user_id)
        if lock is None:
            lock = asyncio.Lock()
            self._screen_locks[user_id] = lock
        return lock

    def spawn(self, coro: Awaitable[Any]) -> None:
        task = asyncio.create_task(coro)
        self._background_tasks.add(task)
        task.add_done_callback(self._background_tasks.discard)

    def save_now(self) -> None:
        self.save_manager.save(self.world, make_backup=True)
        self.world.dirty = False

    async def save_light(self) -> None:
        """Non-blocking lightweight save used after user actions."""
        if not self.world.dirty:
            return
        async with self.world.simulation_lock:
            if not self.world.dirty:
                return
            await asyncio.to_thread(self.save_manager.save, self.world, False)
            self.world.dirty = False

                                                                        
                        
                                                                        

    async def answer_callback(self, callback: types.CallbackQuery) -> None:
        with suppress(Exception):
            await callback.answer(cache_time=0)

    async def show(
        self,
        target: types.Message | types.CallbackQuery,
        text: str,
        markup: Optional[types.InlineKeyboardMarkup] = None,
        *,
        parse_mode: ParseMode = ParseMode.HTML,
    ) -> None:
        if isinstance(target, types.CallbackQuery):
            message = target.message
            user_id = target.from_user.id
        else:
            message = target
            user_id = target.from_user.id
        if message is None:
            return
        text = text[:4096]
        try:
            await message.edit_text(text, reply_markup=markup, parse_mode=parse_mode, disable_web_page_preview=True)
        except TelegramBadRequest as exc:
                                                               
            if "message is not modified" in str(exc).lower():
                return
            try:
                sent = await message.answer(text, reply_markup=markup, parse_mode=parse_mode, disable_web_page_preview=True)
                p = self.player(user_id)
                p.current_message_id = sent.message_id
            except TelegramForbiddenError:
                return
        except TelegramForbiddenError:
            return

    async def show_new(self, message: types.Message, text: str, markup: Optional[types.InlineKeyboardMarkup] = None) -> None:
        sent = await message.answer(text[:4096], reply_markup=markup, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        self.player(message.from_user.id).current_message_id = sent.message_id

    async def render_home(self, target: types.Message | types.CallbackQuery) -> None:
        user_id = target.from_user.id
        player = self.player(user_id, target.from_user.username or "")
        country = self.country_for(user_id)
        if player.is_admin:
            await self.render_admin_home(target)
            return
        if not country:
            text = (
                f"{APP_TITLE}\n\n"
                "Выберите страну для начала игры.\n"
                "🧪 ТЕСТ — техническая страна без территории."
            )
            await self.show(target, text, Keyboards.country_picker())
            return
        country_obj = self.world.country(country)
        text = self.home_text(country)
        player.current_screen = "home"
        await self.show(target, text, Keyboards.home())

    def home_text(self, country_code: str) -> str:
        c = self.world.country(country_code)
        country_wars = [w for w in self.world.wars.values() if w.active and w.involves(country_code)]
        active_builds = len(self.construction.active_for(country_code))
        active_repairs = sum(1 for r in self.world.repairs.values() if r.get("country") == country_code and r.get("status") == "active")
        return (
            f"{c.flag} <b>{esc(c.name)}</b>\n\n"
            f"💰 Бюджет: <b>{format_money(c.budget)}</b>\n"
            f"📈 Доход: {format_money(self.economy.daily_income(country_code))}/день\n"
            f"👥 Население: {format_number(c.population)}\n"
            f"🪖 Резерв: {format_number(c.manpower)}\n"
            f"🏭 ГЗ: {c.civilian_factories} | ВЗ: {c.military_factories}\n"
            f"⚡ Электроэнергия: {self.economy.electricity_ratio(country_code)*100:.0f}%\n"
            f"📊 Стабильность: {c.stability}%\n"
            f"🔥 Военная поддержка: {c.war_support}%\n"
            f"⚔️ Войн: {len(country_wars)}\n"
            f"🏗️ Строек: {active_builds}/{MAX_CONSTRUCTION_QUEUE}\n"
            f"🛠️ Ремонтов: {active_repairs}/{MAX_REPAIR_QUEUE}\n\n"
            f"⏱️ Игровое время: {game_time_text(self.world)}\n"
            f"⚙️ Скорость: x{self.world.speed:g}{' | ⏸️ Пауза' if self.world.paused else ''}"
        )

                                                                        
             
                                                                        

    def _bind_handlers(self) -> None:
        r = self.router

        r.message.register(self.on_start, Command("start"))
        r.message.register(self.on_back, Command("back"))
        r.message.register(self.on_admin_command, Command("admin"))
        r.message.register(self.on_photo, F.photo)
        r.message.register(self.on_text)
        r.callback_query.register(self.on_callback)

                                                                        
                           
                                                                        

    async def on_start(self, message: types.Message) -> None:
        self.player(message.from_user.id, message.from_user.username or "")
        await self.render_home(message)

    async def on_back(self, message: types.Message) -> None:
        player = self.player(message.from_user.id, message.from_user.username or "")
        player.clear_input()
        if player.is_admin:
            await self.render_admin_home(message)
            return
                                                                              
        if player.country in PLAYABLE_COUNTRIES:
            old=player.country
            player.country=None
            self.world.add_log("country_release", message.from_user.id, {"country": old})
            self.world.mark_dirty()
        await self.show_new(message, "🌍 <b>Выбор страны</b>", Keyboards.country_picker())

    async def on_admin_command(self, message: types.Message) -> None:
        player = self.player(message.from_user.id, message.from_user.username or "")
        if self.is_admin(message.from_user.id):
            await self.render_admin_home(message)
            return
        player.pending_input = "admin_code"
        player.pending_data = {"expires_at": time.monotonic() + 180}
        await self.show_new(message, "🛠️ Введите код администратора:")

    async def on_text(self, message: types.Message) -> None:
        if not message.text:
            return
        user_id = message.from_user.id
        player = self.player(user_id, message.from_user.username or "")
        pending = player.pending_input
        if not pending:
            await self.render_home(message)
            return
        value = message.text.strip()
        if not value:
            await self.show_new(message, "❌ Пустой ввод. Нажмите /back и попробуйте ещё раз.")
            return

        if pending == "admin_code":
            if self.admin.authenticate(user_id, value):
                player.clear_input()
                await self.render_admin_home(message)
            else:
                await self.show_new(message, "❌ Неверный код. Повторите ввод или нажмите /back.")
            return

        try:
            async with self.screen_lock(user_id):
                result = await self.process_text_input(player, value)
        except Exception as exc:
            self.world.add_log("ui_input_error", user_id, {"error": repr(exc)})
            result = "❌ Ошибка обработки ввода."
        if player.pending_input == "news_target":
            rows=[[Keyboards.btn("🌍 Всем странам", "admin:newstarget:all")]]
            rows += [[Keyboards.btn(COUNTRY_NAMES[c], f"admin:newstarget:{c}")] for c in PLAYABLE_COUNTRIES]
            rows += Keyboards.nav("admin:section:news")
            await self.show_new(message, result, types.InlineKeyboardMarkup(inline_keyboard=rows))
            return
        if player.pending_input == "event_target":
            rows=[[Keyboards.btn("🌍 Всем", "admin:eventtarget:all")]]
            rows += [[Keyboards.btn(COUNTRY_NAMES[c], f"admin:eventtarget:{c}")] for c in PLAYABLE_COUNTRIES]
            rows += Keyboards.nav("admin:section:events")
            await self.show_new(message, result, types.InlineKeyboardMarkup(inline_keyboard=rows))
            return
        await self.show_new(message, result)

    async def process_text_input(self, player: Any, value: str) -> str:
        action = player.pending_input
        data = dict(player.pending_data)
        player.clear_input()

        if action == "division_name":
            division_id = data.get("division_id")
            if division_id not in self.world.divisions:
                return "❌ Дивизия не найдена."
            ok, reason = self.army.rename(division_id, value)
            if ok:
                awaitable = self.save_light()
                self.spawn(awaitable)
            return ("✅ " if ok else "❌ ") + reason

        if action == "general_name":
            country = data.get("country")
            ok, reason, _ = self.army.create_general(country, value)
            if ok:
                self.spawn(self.save_light())
            return ("✅ " if ok else "❌ ") + reason

        if action == "message_text":
            sender = data.get("sender")
            receiver = data.get("receiver")
            ok, reason = self.diplomacy.send_message(sender, receiver, value)
            return ("✅ " if ok else "❌ ") + reason

        if action == "warning_text":
            sender=data.get("sender"); receiver=data.get("receiver")
            ok, reason = self.diplomacy.send_warning(sender, receiver, value)
            self.spawn(self.save_light())
            return ("✅ " if ok else "❌ ") + reason

        if action == "admin_message_text":
            target_uid = int(data.get("target_user_id", 0))
            if target_uid not in self.world.players:
                return "❌ Игрок не найден."
            text_value = value[:4000]
            async def _send_admin_message() -> None:
                if getattr(self, "bot", None) is not None:
                    with suppress(Exception):
                        await self.bot.send_message(target_uid, "🛠️ Сообщение от администратора:\n\n" + esc(text_value))
            self.spawn(_send_admin_message())
            self.world.add_log("admin_message", player.user_id, {"target": target_uid})
            self.spawn(self.save_light())
            return "✅ Сообщение поставлено в отправку."

        if action == "news_title":
            player.pending_input = "news_text"
            player.pending_data = {**data, "title": value, "expires_at": time.monotonic() + 600}
            return "📰 Теперь введите текст новости."

        if action == "event_title":
            player.pending_input = "event_text"
            player.pending_data = {"title": value, "expires_at": time.monotonic() + 600}
            return "🎉 Теперь введите текст события."

        if action == "event_text":
            player.pending_input = "event_target"
            player.pending_data = {"title": str(data.get("title", "Событие")), "text": value, "expires_at": time.monotonic() + 600}
            return "🎉 Выберите цель события."

        if action == "news_target":
            target = data.get("target_country")
            title = str(data.get("title", "Новая новость"))
            news_id = self.news.create(player.user_id, title, str(data.get("text", "")), target_country=target)
            player.pending_input = "news_image"
            player.pending_data = {"news_id": news_id, "expires_at": time.monotonic() + 600}
            self.spawn(self.save_light())
            return f"✅ Черновик новости <code>{esc(news_id)}</code> создан. Отправьте фотографию для обложки или нажмите /back."
        if action == "news_text":
            player.pending_input = "news_target"
            player.pending_data = {"title": str(data.get("title", "Новая новость")), "text": value, "expires_at": time.monotonic() + 600}
            return "📰 Выберите аудиторию новости."

        return "❌ Неизвестный режим ввода."

    async def on_photo(self, message: types.Message) -> None:
        player = self.player(message.from_user.id, message.from_user.username or "")
        if player.pending_input != "news_image":
            await self.render_home(message)
            return
        news_id = player.pending_data.get("news_id")
        item = self.world.news.get(news_id) if news_id else None
        if not item:
            player.clear_input()
            await self.show_new(message, "❌ Черновик новости не найден.")
            return
        file_id = message.photo[-1].file_id
        self.news.edit(news_id, item.title, item.text, image_file_id=file_id)
        player.clear_input()
        self.spawn(self.save_light())
        await self.show_new(message, f"✅ Изображение прикреплено к новости <code>{esc(news_id)}</code>. Опубликуйте её в админке.")

                                                                                 

                                                                        
                             
                                                                        

    async def on_callback(self, callback: types.CallbackQuery) -> None:
                                                                  
        await self.answer_callback(callback)
        data = callback.data or ""
        user_id = callback.from_user.id
        player = self.player(user_id, callback.from_user.username or "")
        if player.banned:
            await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
            return

        try:
            async with self.screen_lock(user_id):
                if data == "noop":
                    return
                if data == "home":
                    player.clear_input()
                    await self.render_home(callback)
                    return
                if data == "country:picker":
                    player.clear_input()
                    await self.show(callback, "🌍 <b>Выбор страны</b>", Keyboards.country_picker())
                    return
                if data == "admin:home":
                    if not self.is_admin(user_id):
                        player.pending_input = "admin_code"
                        player.pending_data = {"expires_at": time.monotonic() + 180}
                        await self.show(callback, "🛠️ Введите код администратора:")
                        return
                    await self.render_admin_home(callback)
                    return
                if data == "admin:logout":
                    self.world.set_admin(user_id, False)
                    player.clear_input()
                    await self.show(callback, "✅ Вы вышли из режима администратора.", Keyboards.country_picker())
                    return
                if data.startswith("country:"):
                    await self.handle_country(callback, data.split(":", 1)[1])
                    return
                if data.startswith("screen:"):
                    await self.handle_screen(callback, data.split(":", 1)[1])
                    return
                if data.startswith("map:"):
                    await self.handle_map(callback, data)
                    return
                if data.startswith("prov:"):
                    await self.handle_province(callback, data)
                    return
                if data.startswith("provneighbors:"):
                    await self.handle_province_neighbors(callback, data)
                    return
                if data.startswith("prod"):
                    await self.handle_production(callback, data)
                    return
                if data.startswith("warehousecat:"):
                    await self.handle_warehouse(callback, data)
                    return
                if data.startswith("warehouse"):
                    await self.handle_warehouse(callback, data)
                    return
                if data.startswith("army") or data.startswith("gen:") or data.startswith("general"):
                    await self.handle_army(callback, data)
                    return
                if data.startswith("air"):
                    await self.handle_air(callback, data)
                    return
                if data.startswith("pvo"):
                    await self.handle_pvo(callback, data)
                    return
                if data.startswith("navy"):
                    await self.handle_navy(callback, data)
                    return
                if data.startswith("navyrebase:"):
                    await self.handle_navy(callback, data)
                    return
                if data.startswith("diplo") or data.startswith("treaty") or data.startswith("war") or data.startswith("ultimatum") or data.startswith("ultdemand:") or data.startswith("ultdeadline:") or data.startswith("ultsend:") or data.startswith("warningto:"):
                    await self.handle_diplomacy(callback, data)
                    return
                if data.startswith("trade"):
                    await self.handle_trade(callback, data)
                    return
                if data.startswith("decision"):
                    await self.handle_decision(callback, data)
                    return
                if data.startswith("build"):
                    await self.handle_construction(callback, data)
                    return
                if data.startswith("repair"):
                    await self.handle_repair(callback, data)
                    return
                if data.startswith("journal"):
                    await self.handle_journal(callback, data)
                    return
                if data.startswith("news"):
                    await self.handle_news(callback, data)
                    return
                if data.startswith("admin:"):
                    await self.handle_admin(callback, data)
                    return
                await self.show(callback, "🔄 Действие устарело. Обновляю меню.", Keyboards.home())
        except Exception as exc:
            self.world.add_log("callback_error", user_id, {"callback": data[:64], "error": repr(exc)})
            await self.show(callback, "❌ Не удалось обработать действие. Ошибка записана в журнал диагностики.", Keyboards.home())

                                                                        
                            
                                                                        

    async def handle_country(self, callback: types.CallbackQuery, code: str) -> None:
        user_id = callback.from_user.id
        player = self.player(user_id)
        if code == "admin":
            if self.is_admin(user_id):
                await self.render_admin_home(callback)
                return
            player.pending_input = "admin_code"
            player.pending_data = {"expires_at": time.monotonic() + 180}
            await self.show(callback, "🛠️ Введите код администратора:")
            return
        if code == COUNTRY_TEST:
            await self.show(
                callback,
                "🧪 <b>ТЕСТ</b>\n\nТехническая страна без территории. Она используется для проверки функций и не занимает карту.",
                types.InlineKeyboardMarkup(inline_keyboard=[
                    [Keyboards.btn("⬅️ Назад", "country:picker")],
                ]),
            )
            return
        if code not in PLAYABLE_COUNTRIES:
            await self.show(callback, "❌ Такая страна недоступна.", Keyboards.country_picker())
            return
                                                                
        if not self.world.set_country(user_id, code):
            await self.show(callback, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        player.clear_input()
        self.world.add_log("country_switch", user_id, {"country": code})
        await self.render_home(callback)

    async def handle_screen(self, callback: types.CallbackQuery, screen: str) -> None:
        country, error = self.require_country(callback.from_user.id)
        if not country:
            await self.show(callback, error, Keyboards.country_picker())
            return
        player = self.player(callback.from_user.id)
        player.current_screen = screen
        if screen == "production":
            await self.render_production(callback, 0)
        elif screen == "warehouse":
            await self.render_warehouse(callback, None)
        elif screen == "country":
            await self.render_country(callback, country)
        elif screen == "map":
            await self.render_map(callback, 0)
        elif screen == "army":
            await self.render_army(callback)
        elif screen == "air":
            await self.render_air(callback)
        elif screen == "pvo":
            await self.render_pvo(callback)
        elif screen == "navy":
            await self.render_navy(callback)
        elif screen == "diplomacy":
            await self.render_diplomacy(callback)
        elif screen == "trade":
            await self.render_trade(callback)
        elif screen == "decisions":
            await self.render_decisions(callback, 0)
        elif screen == "construction":
            await self.render_construction(callback)
        elif screen == "repair":
            await self.render_repair(callback)
        elif screen == "journal":
            await self.render_journal(callback, "all", 0)
        elif screen == "news":
            await self.render_news(callback, 0)
        elif screen == "help":
            await self.render_help(callback)
        else:
            await self.render_home(callback)

    async def render_country(self, target: types.Message | types.CallbackQuery, country_code: str) -> None:
        text = economy_text(self.economy, country_code)
        keyboard = types.InlineKeyboardMarkup(inline_keyboard=[
            [Keyboards.btn("💰 Экономика", "screen:country"), Keyboards.btn("📊 Производство", "screen:production")],
            [Keyboards.btn("🗺️ Провинции", "screen:map")],
            *Keyboards.nav("home"),
        ])
        await self.show(target, text, keyboard)

