        if data.startswith("pvoplace:"):
            _,key,qtxt,pidtxt=data.split(":",3); ok,reason,_=self.pvo.deploy(country,key,int(qtxt),int(pidtxt)); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("screen:pvo")); return
