        rows += [[Keyboards.btn(f"{COUNTRY_NAMES.get(t['receiver'] if t['sender']==country else t['sender'])} — {t['resource']} ×{t['quantity']} — {t['status']}",f"trade:view:{t['id']}")] for t in trades]
        rows += Keyboards.nav("home")
