    async def handle_trade(self,callback:types.CallbackQuery,data:str)->None:
        country,error=self.require_country(callback.from_user.id)
        if not country: await self.show(callback,error,Keyboards.country_picker()); return
        if data=="trade:new":
            rows=[[Keyboards.btn(COUNTRY_NAMES[x],f"trade:target:{x}")] for x in PLAYABLE_COUNTRIES if x!=country]; rows+=Keyboards.nav("screen:trade"); await self.show(callback,"🚛 Кому отправляем:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:target:"):
            other=data.split(":",2)[2]; rows=[[Keyboards.btn(RESOURCE_DISPLAY[k],f"trade:resource:{other}:{k}")] for k in RESOURCE_KEYS]; rows+=Keyboards.nav("trade:new"); await self.show(callback,"📦 Выберите ресурс:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:resource:"):
            _,_,other,res=data.split(":",3); stock=self.world.country(country).resources.get(res,0); qs=[100,500,1000,5000,min(10000,max(1,stock))]; rows=[[Keyboards.btn(f"{q} ед.",f"trade:q:{other}:{res}:{q}")] for q in dict.fromkeys(qs) if q>0]; rows+=Keyboards.nav("screen:trade"); await self.show(callback,f"Ресурс: {RESOURCE_DISPLAY[res]}\nДоступно: {format_number(stock)}\n\nКоличество:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:q:"):
            _,_,other,res,qtxt=data.split(":",4); q=int(qtxt); prices=[q*20_000,q*50_000,q*100_000]; rows=[[Keyboards.btn(format_money(p),f"trade:price:{other}:{res}:{q}:{p}")] for p in dict.fromkeys(prices)]; rows += Keyboards.nav("screen:trade"); await self.show(callback,"💰 Выберите цену:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:price:"):
            _,_,other,res,qtxt,ptxt=data.split(":",5); q=int(qtxt); price=int(ptxt); routes=[]
            if self.world.countries_share_border(country,other): routes.append("land")
            if any(self.world.province(p).sea_access for p in self.world.country(country).province_ids) and any(self.world.province(p).sea_access for p in self.world.country(other).province_ids): routes.append("sea")
            rows=[]
            if "land" in routes:
                rows.append([Keyboards.btn("🛣️ Сухопутный",f"trade:confirm:{other}:{res}:{q}:{price}:land")])
            if "sea" in routes:
                rows.append([Keyboards.btn("🌊 Морской",f"trade:confirm:{other}:{res}:{q}:{price}:sea")])
            rows+=Keyboards.nav("screen:trade"); await self.show(callback,"🧾 Подтвердите маршрут:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:confirm:"):
            _,_,other,res,qtxt,ptxt,route=data.split(":",6); ok,reason,_=self.trade.create(country,other,res,int(qtxt),int(ptxt),route); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("screen:trade")); return
        if data.startswith("trade:view:"):
            tid=data.split(":",2)[2]; t=self.world.trades.get(tid);
            if not t or country not in {t.get('sender'),t.get('receiver')}: await self.show(callback,"❌ Сделка недоступна."); return
            text=f"🚛 <b>Сделка {esc(tid)}</b>\n\n{COUNTRY_NAMES[t['sender']]} → {COUNTRY_NAMES[t['receiver']]}\nРесурс: {RESOURCE_DISPLAY.get(t['resource'],t['resource'])}\nКоличество: {format_number(t['quantity'])}\nЦена за ед.: {format_money(t['price'])}\nМаршрут: {t.get('route_type', t.get('route','—'))}\nСтатус: {t['status']}\nПрогресс: {float(t.get('delivery_progress',0))*100:.0f}%\nОсталось: {float(t.get('remaining_minutes',0)):.0f} мин."
            rows=[]
            if t.get('status') in {'in_transit','active'}: rows.append([Keyboards.btn("⛔ Отменить",f"trade:cancel:{tid}")])
            rows+=Keyboards.nav("screen:trade"); await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if data.startswith("trade:cancel:"):
            tid=data.split(":",2)[2]; ok,reason=self.trade.cancel(tid,country); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("screen:trade")); return

                                                                        
               
                                                                        

