    async def render_journal(self,target:types.Message|types.CallbackQuery,category:str,page:int)->None:
        country,error=self.require_country(target.from_user.id)
        if not country: await self.show(target,error,Keyboards.country_picker()); return
        entries=[j for j in self.world.journal if not j.country or j.country==country]
        if category!="all": entries=[j for j in entries if j.category==category]
        entries=entries[-100:][::-1]
        chunk,page,total=page_slice(entries,page)
        lines=[f"{esc(e.get('title',''))} — {esc(e.get('text',''))}" for e in chunk]
        cats=[("all","Все"),("news","📰 Новости"),("war","⚔️ Войны"),("army","🪖 Армия"),("aviation","✈️ Авиация"),("pvo","🛡️ ПВО"),("navy","⚓ Флот"),("production","🏭 Производство"),("economy","💰 Экономика"),("diplomacy","🤝 Дипломатия")]
        rows=[[Keyboards.btn(label,f"journalcat:{key}:0")] for key,label in cats]
        rows.append(Keyboards.pagination(f"journalpage:{category}",page,total)); rows+=Keyboards.nav("home")
        await self.show(target,"📖 <b>Журнал</b>\n\n"+("\n\n".join(lines) if lines else "Записей нет."),types.InlineKeyboardMarkup(inline_keyboard=rows))

    async def handle_journal(self,callback:types.CallbackQuery,data:str)->None:
        if data.startswith("journalcat:"):
            _,cat,p=data.split(":",2); await self.render_journal(callback,cat,int(p)); return
        if data.startswith("journalpage:"):
            _,cat,p=data.split(":",2); await self.render_journal(callback,cat,int(p)); return
        await self.render_journal(callback,"all",0)

    async def render_news(self,target:types.Message|types.CallbackQuery,page:int)->None:
        country,error=self.require_country(target.from_user.id)
        if not country: await self.show(target,error,Keyboards.country_picker()); return
        items=self.news.for_country(country,True); chunk,page,total=page_slice(items,page); rows=[]
        for item in chunk:
            rows.append([Keyboards.btn(item.title[:45],f"news:view:{item.id}")])
        rows.append(Keyboards.pagination("newspage",page,total)); rows+=Keyboards.nav("home")
        text="📰 <b>Новости</b>\n\n"+(f"Последних опубликованных: {len(items)}" if items else "Новостей пока нет.")
        await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))

    async def handle_news(self,callback:types.CallbackQuery,data:str)->None:
        country,error=self.require_country(callback.from_user.id)
        if not country: await self.show(callback,error,Keyboards.country_picker()); return
        if data.startswith("newspage:"): await self.render_news(callback,int(data.split(":",1)[1])); return
        if data.startswith("news:view:"):
            nid=data.split(":",2)[2]; item=self.world.news.get(nid)
            if not item or (item.target_country and item.target_country!=country) or not item.published: await self.show(callback,"❌ Новость недоступна."); return
            text=f"📰 <b>{esc(item.title)}</b>\n\n{esc(item.text)}\n\n<i>{esc(item.created_at)}</i>"
            rows=Keyboards.nav("screen:news")
            if item.image_file_id:
                await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows))
                with suppress(Exception):
                    await callback.message.answer_photo(item.image_file_id,caption=text[:1024],reply_markup=types.InlineKeyboardMarkup(inline_keyboard=rows),parse_mode=ParseMode.HTML)
            else:
                await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows))
            return

                                                                        
           
                                                                        

    async def render_admin_home(self,target:types.Message|types.CallbackQuery)->None:
        if not self.is_admin(target.from_user.id):
            await self.show(target,"❌ Нет прав администратора.",Keyboards.country_picker()); return
        result=self.diagnostics.run(); active_wars=result["counts"]["wars"]
        text=("🛠️ <b>Панель администратора</b>\n\n"
              f"Игровое время: {game_time_text(self.world)}\n"
              f"Скорость: x{self.world.speed:g}\n"
              f"Статус: {'⏸️ Пауза' if self.world.paused else '▶️ Игра'}\n"
              f"Провинций: {len(self.world.provinces)}\n"
              f"Игроков: {len(self.world.players)}\n"
              f"Войн: {active_wars}\n"
              f"Диагностика: {'✅ OK' if result['ok'] else '❌ Ошибки'}")
        action_items=list(ADMIN_ACTIONS.items())
        rows=[]
        for i in range(0,len(action_items),2): rows.append([Keyboards.btn(action_items[i][1],f"admin:section:{action_items[i][0]}")] + ([Keyboards.btn(action_items[i+1][1],f"admin:section:{action_items[i+1][0]}")] if i+1<len(action_items) else []))
        rows.append([Keyboards.btn("⏱️ x1", "admin:speed:1"),Keyboards.btn("x2","admin:speed:2"),Keyboards.btn("x5","admin:speed:5"),Keyboards.btn("x10","admin:speed:10")])
        rows.append([Keyboards.btn("⏸️ Пауза", "admin:pause:1"),Keyboards.btn("▶️ Продолжить","admin:pause:0")])
        rows.append([Keyboards.btn("💾 Сохранить","admin:save"),Keyboards.btn("🩺 Диагностика","admin:diag")])
        rows.append([Keyboards.btn("🚪 Выйти из админки","admin:logout")])
        await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))

    async def handle_admin(self,callback:types.CallbackQuery,data:str)->None:
        if not self.is_admin(callback.from_user.id):
            await self.show(callback,"❌ Нет прав администратора.",Keyboards.country_picker()); return
        parts=data.split(":")
        action=parts[1] if len(parts)>1 else ""
        uid=callback.from_user.id
        if action=="newstarget":
            target = None if parts[2]=="all" else parts[2]
            player=self.player(uid); pd=dict(player.pending_data); title=str(pd.get("title","Новая новость")); body=str(pd.get("text",""))
            nid=self.news.create(uid,title,body,target_country=target); player.pending_input="news_image"; player.pending_data={"news_id":nid,"expires_at":time.monotonic()+600}; self.spawn(self.save_light())
            await self.show(callback,f"✅ Черновик новости <code>{esc(nid)}</code> создан. Можно прикрепить фото или опубликовать без него.",types.InlineKeyboardMarkup(inline_keyboard=[[Keyboards.btn("Без фото","admin:news:skipimage")],Keyboards.nav("admin:section:news")[0]])); return
        if action=="eventtarget":
            target = None if parts[2]=="all" else parts[2]
            player=self.player(uid); pd=dict(player.pending_data); title=str(pd.get("title","Событие")); body=str(pd.get("text",""))
            player.pending_input="event_effect"; player.pending_data={**pd,"target_country":target,"expires_at":time.monotonic()+600}
            rows=[[Keyboards.btn("📈 Стабильность +5","admin:event:effect:stability")],[Keyboards.btn("💰 Бюджет +500 млн","admin:event:effect:budget")],[Keyboards.btn("➖ Без эффекта","admin:event:effect:none")]]; rows+=Keyboards.nav("admin:section:events")
            await self.show(callback,"🎉 Выберите эффект события:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if action=="section":
            section=parts[2] if len(parts)>2 else "world"
            await self.render_admin_section(callback,section); return
        if action=="speed":
            speed=float(parts[2]); self.admin.set_speed(uid,speed); await self.render_admin_home(callback); return
        if action=="pause":
            paused=parts[2]=="1"; self.admin.pause(uid,paused); await self.render_admin_home(callback); return
        if action=="save":
            async with self.world.simulation_lock:
                ok,reason=await asyncio.to_thread(self.admin.save, uid)
            await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:home")); return
        if action=="backup":
            async with self.world.simulation_lock:
                ok,reason=await asyncio.to_thread(self.admin.create_backup, uid)
            await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:home")); return
        if action=="restore":
            self.world.paused=True
            async with self.world.simulation_lock:
                ok,reason=await asyncio.to_thread(self.admin.restore, uid)
            await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:home")); return
        if action=="diag":
            await self.show(callback,self.diagnostics.text(),Keyboards.simple_nav("admin:home")); return
        if action=="fill":
            code=parts[2]; ok,reason=self.admin.fill_warehouse(uid,code,self.production,1000); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:warehouse")); return
        if action=="infinite":
            code=parts[2]; enabled=parts[3]=="1"; ok,reason=self.admin.toggle_infinite_weapons(uid,code,enabled); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:warehouse")); return
        if action=="prodset":
            code,key,fac=parts[2],parts[3],int(parts[4]); ok,reason=self.production.set_line(code,key,fac); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"admin:prod:{code}")); return
        if action=="newsdelete":
            nid=parts[2]; ok,reason=self.news.delete(nid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:news")); return
        if action=="grantmoney":
            code=parts[2]; amount=int(parts[3]); ok,reason=self.admin.grant_money(uid,code,amount); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:economy")); return
        if action=="grantresource":
            code,res,amt=parts[2],parts[3],int(parts[4]); ok,reason=self.admin.grant_resource(uid,code,res,amt); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:economy")); return
        if action=="granteq":
            code,key,amt=parts[2],parts[3],int(parts[4]); ok,reason=self.admin.grant_equipment(uid,code,key,amt,self.production); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:production")); return
        if action=="factories":
            code,civ,mil=parts[2],int(parts[3]),int(parts[4]); ok,reason=self.admin.add_factories(uid,code,civ,mil); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:economy")); return
        if action=="time":
            minutes=max(0.0,float(parts[2]))
            async with self.world.simulation_lock:
                if self.world.paused:
                    await self.show(callback,"⏸️ Сначала нажмите ▶️ Продолжить.",Keyboards.simple_nav("admin:section:time")); return
                                                                                     
                for chunk in range(0, int(minutes), 120):
                    step=min(120, int(minutes)-chunk)
                    await asyncio.to_thread(self.simulation.advance, step, True)
                    await asyncio.sleep(0)
                self.world.dirty=True
                await asyncio.to_thread(self.save_manager.save, self.world, False)
                self.world.dirty=False
            await self.show(callback,"✅ Игровое время продвинуто.",Keyboards.simple_nav("admin:section:time")); return
        if action=="reset":
            ok,reason=self.admin.reset(uid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:home")); return
        if action=="broadcast_news":
            nid=parts[2]; item=self.world.news.get(nid)
            if item:
                ok,reason=self.news.publish(nid,uid); self.spawn(self.broadcast_news(nid)); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:news")); return
        if action=="event_apply":
            eid=parts[2]; ok,reason=self.events.apply(eid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:events")); return
        if action=="country":
            code=parts[2]; await self.render_admin_country(callback,code); return
        if action=="warehouse":
            code=parts[2]; await self.render_admin_warehouse(callback,code,0); return
        if action=="warehouse_page":
            code,page=parts[2],int(parts[3]); await self.render_admin_warehouse(callback,code,page); return
        if action=="prod":
            code=parts[2]; await self.render_admin_production(callback,code,0); return
        if action=="prod_page":
            code,page=parts[2],int(parts[3]); await self.render_admin_production(callback,code,page); return
        if action=="player":
            await self.render_admin_player(callback,int(parts[2])); return
        if action=="message":
            target_uid=int(parts[2])
            if target_uid not in self.world.players:
                await self.show(callback,"❌ Игрок не найден.",Keyboards.simple_nav("admin:section:players")); return
            player=self.player(uid)
            player.pending_input="admin_message_text"
            player.pending_data={"target_user_id":target_uid,"expires_at":time.monotonic()+600}
            await self.show(callback,"💬 Введите сообщение игроку. Только текст, без команд:")
            return
        if action=="assign":
            target=int(parts[2]); code=None if parts[3]=="none" else parts[3]; ok,reason=self.admin.assign_player(uid,target,code)
            if ok:
                if code in PLAYABLE_COUNTRIES:
                    self._session_country[target] = code
                else:
                    self._session_country.pop(target, None)
            self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"admin:player:{target}")); return
        if action=="kick":
            target=int(parts[2]); ok,reason=self.admin.kick(uid,target)
            if ok:
                self._session_country.pop(target, None)
            self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:players")); return
        if action=="ban":
            target=int(parts[2]); enabled=parts[3]=="1"; ok,reason=self.admin.ban(uid,target,enabled)
            if ok:
                self._session_country.pop(target, None)
            self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:players")); return
        if action=="news":
            sub=parts[2]
            if sub=="create":
                player=self.player(uid); player.pending_input="news_title"; player.pending_data={"expires_at":time.monotonic()+600}
                await self.show(callback,"📰 Введите заголовок новости:"); return
            if sub=="target":
                target=None if parts[3]=="all" else parts[3]
                player=self.player(uid); data2=dict(player.pending_data); data2["target_country"]=target; title=str(data2.get("title","Новая новость")); body=str(data2.get("text",""))
                nid=self.news.create(uid,title,body,target_country=target); player.pending_input="news_image"; player.pending_data={"news_id":nid,"expires_at":time.monotonic()+600}; self.spawn(self.save_light())
                await self.show(callback,f"✅ Черновик <code>{esc(nid)}</code> создан. Отправьте фото или нажмите «Без фото».",types.InlineKeyboardMarkup(inline_keyboard=[[Keyboards.btn("Без фото","admin:news:skipimage")],Keyboards.nav("admin:section:news")[0]])); return
            if sub=="skipimage":
                self.player(uid).clear_input(); await self.show(callback,"✅ Новость оставлена без изображения.",Keyboards.simple_nav("admin:section:news")); return
            if sub=="view":
                await self.render_admin_news_view(callback,parts[3]); return
        if action=="event":
            sub=parts[2]
            if sub=="create":
                player=self.player(uid); player.pending_input="event_title"; player.pending_data={"expires_at":time.monotonic()+600}; await self.show(callback,"🎉 Введите заголовок события:"); return
            if sub=="target":
                target=None if parts[3]=="all" else parts[3]; player=self.player(uid); pd=dict(player.pending_data); pd["target_country"]=target; player.pending_input="event_effect"; player.pending_data=pd
                rows=[[Keyboards.btn("📈 Стабильность +5","admin:event:effect:stability")],[Keyboards.btn("💰 Бюджет +500 млн","admin:event:effect:budget")],[Keyboards.btn("➖ Без эффекта","admin:event:effect:none")]]; rows+=Keyboards.nav("admin:section:events"); await self.show(callback,"🎉 Выберите эффект:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
            if sub=="effect":
                effect=parts[3]; player=self.player(uid); pd=dict(player.pending_data); target=pd.get("target_country"); effects={"stability":5} if effect=="stability" else ({"budget":500_000_000} if effect=="budget" else {}); eid=self.events.create(str(pd.get("title","Событие")),str(pd.get("text","")),target,effects); player.clear_input(); self.spawn(self.save_light()); await self.show(callback,f"✅ Событие <code>{esc(eid)}</code> создано.",Keyboards.simple_nav("admin:section:events")); return
            if sub=="view":
                eid=parts[3]; item=self.world.events.get(eid);
                if not item: await self.show(callback,"❌ Событие не найдено.",Keyboards.simple_nav("admin:section:events")); return
                text=f"🎉 <b>{esc(item.title)}</b>\n\n{esc(item.text)}\n\nЭффекты: {esc(item.effects)}\nПрименено: {item.applied}"; rows=[]
                if not item.applied: rows.append([Keyboards.btn("✅ Применить","admin:event_apply:"+eid)])
                rows+=Keyboards.nav("admin:section:events"); await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if action=="warnew":
            attacker,defender=parts[2],parts[3]; ok,reason,_=self.wars.declare(attacker,defender,"тестовая война"); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:section:wars")); return

        await self.render_admin_home(callback)

    async def render_admin_section(self,target:types.Message|types.CallbackQuery,section:str)->None:
        if not self.is_admin(target.from_user.id): await self.show(target,"❌ Нет прав."); return
        if section=="world":
            text=f"📊 <b>Мир</b>\n\n{game_time_text(self.world)}\nСкорость x{self.world.speed:g}\nПауза: {self.world.paused}\nПровинций: {len(self.world.provinces)}\nИгроков: {len(self.world.players)}"
            await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="countries" or section=="economy":
            rows=[]
            for code in PLAYABLE_COUNTRIES:
                c=self.world.country(code); rows.append([Keyboards.btn(f"{c.flag} {c.name}",f"admin:country:{code}")])
            rows += Keyboards.nav("admin:home"); await self.show(target,"🌍 Выберите страну:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="warehouse":
            rows=[]
            for code in PLAYABLE_COUNTRIES:
                c=self.world.country(code); rows.append([Keyboards.btn(f"{c.name} | ♾️ {'ON' if c.infinite_weapons else 'OFF'}",f"admin:warehouse:{code}")])
            rows+=Keyboards.nav("admin:home"); await self.show(target,"📦 <b>Склады / вооружение</b>",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="production":
            rows=[[Keyboards.btn(c.name,f"admin:prod:{code}")] for code,c in self.world.countries.items() if code in PLAYABLE_COUNTRIES]; rows+=Keyboards.nav("admin:home"); await self.show(target,"🏭 Выберите страну для производства:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="army":
            text=f"🪖 Дивизии: {len(self.world.divisions)}\n👤 Генералы: {len(self.world.generals)}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="aviation":
            text=f"✈️ Авиагрупп: {len(self.world.air_groups)}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="pvo":
            text=f"🛡️ ПВО: {len(self.world.pvo_units)}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="navy":
            text=f"⚓ Флотских соединений: {len(self.world.fleets)}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="wars":
            text="⚔️ <b>Войны</b>\n\n"+"\n".join(f"{w.id}: {COUNTRY_NAMES[w.attacker]} vs {COUNTRY_NAMES[w.defender]} — {'активна' if w.active else 'завершена'}" for w in self.world.wars.values())
            await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="diplomacy":
            text=f"🤝 Договоров: {len(self.world.treaties)}\n🎯 Целей войны: {len(self.world.war_goals)}\nСообщений: {sum(len(c.message_history) for c in self.world.countries.values())}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="trade":
            text=f"🚛 Сделок: {len(self.world.trades)}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="decisions":
            text=f"📜 Активных решений: {sum(1 for c in self.world.countries.values() for x in c.active_decisions.values() if not x.get('finished'))}"; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="news":
            rows=[[Keyboards.btn("➕ Создать новость","admin:news:create")]]
            for item in list(self.world.news.values())[-20:][::-1]:
                status="✅" if item.published else "📝"; rows.append([Keyboards.btn(f"{status} {item.title[:40]}",f"admin:news:view:{item.id}")])
            rows+=Keyboards.nav("admin:home"); await self.show(target,"📰 <b>Админ-новости</b>",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="events":
            rows=[[Keyboards.btn("➕ Создать событие","admin:event:create")]]
            for item in list(self.world.events.values())[-20:][::-1]: rows.append([Keyboards.btn(f"{'✅' if item.applied else '🎉'} {item.title[:40]}",f"admin:event:view:{item.id}")])
            rows+=Keyboards.nav("admin:home"); await self.show(target,"🎉 <b>События</b>",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="construction":
            await self.show(target,f"🏗️ Активных строек: {sum(1 for p in self.world.construction_projects.values() if p.get('status')=='active')}",Keyboards.simple_nav("admin:home")); return
        if section=="repair":
            await self.show(target,f"🛠️ Активных ремонтов: {sum(1 for p in self.world.repairs.values() if p.get('status')=='active')}",Keyboards.simple_nav("admin:home")); return
        if section=="time":
            rows=[[Keyboards.btn("+1 мин","admin:time:1"),Keyboards.btn("+10 мин","admin:time:10")],[Keyboards.btn("+1 час","admin:time:60"),Keyboards.btn("+1 день","admin:time:1440")],[Keyboards.btn("⏸️ Пауза","admin:pause:1"),Keyboards.btn("▶️ Продолжить","admin:pause:0")],*Keyboards.nav("admin:home")]; await self.show(target,"⏱️ Управление временем",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if section=="tests":
            await self.show(target,self.test_summary(),types.InlineKeyboardMarkup(inline_keyboard=[[Keyboards.btn("🧪 Запустить проверки","admin:diag")],Keyboards.nav("admin:home")[0]])); return
        if section=="logs":
            lines=[f"{x.get('kind')} — user={x.get('user_id')} — {x.get('data', {})}" for x in self.world.logs[-30:]][::-1]; await self.show(target,"📋 <b>Последние логи</b>\n\n"+"\n".join(esc(x) for x in lines),Keyboards.simple_nav("admin:home")); return
        if section=="diagnostics": await self.show(target,self.diagnostics.text(),Keyboards.simple_nav("admin:home")); return
        if section=="settings":
            s=self.world.settings; text=f"⚙️ <b>Настройки</b>\n\nАвтосохранение: {s.get('autosave_enabled')}\nИнтервал автосохранения: {s.get('autosave_minutes')} мин.\nОбновление склада: {s.get('warehouse_update_minutes')} игровых мин."; await self.show(target,text,Keyboards.simple_nav("admin:home")); return
        if section=="saves":
            await self.show(target,"💾 <b>Сохранения</b>\n\n",types.InlineKeyboardMarkup(inline_keyboard=[[Keyboards.btn("💾 Сохранить","admin:save")],[Keyboards.btn("🗂️ Backup","admin:backup")],[Keyboards.btn("♻️ Восстановить","admin:restore")],Keyboards.nav("admin:home")[0]])); return
        if section=="players":
            player_rows=[]
            for p in self.world.players.values():
                if p.role == "admin":
                    continue
                ban_mark = "🔨 " if p.banned else ""
                player_rows.append([Keyboards.btn(f"{ban_mark}{p.username or p.user_id} — {COUNTRY_NAMES.get(p.country,'—')}",f"admin:player:{p.user_id}")])
            rows=player_rows[-60:]
            rows+=Keyboards.nav("admin:home")
            await self.show(target,"👥 <b>Игроки</b>\n\nЗаблокированные игроки тоже отображаются, чтобы их можно было разблокировать.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        await self.show(target,"ℹ️ Раздел пока только информационный.",Keyboards.simple_nav("admin:home"))

    async def render_admin_country(self,target:types.Message|types.CallbackQuery,code:str)->None:
        if code not in PLAYABLE_COUNTRIES:
            await self.show(target,"❌ Страна не найдена.",Keyboards.simple_nav("admin:home")); return
        c=self.world.country(code)
        text=(f"🌍 <b>{esc(c.name)}</b>\n\nБюджет: {format_money(c.budget)}\nДоход: {format_money(self.economy.daily_income(code))}/день\n"f"Население: {format_number(c.population)}\nРезерв: {format_number(c.manpower)}\nГЗ: {c.civilian_factories} | ВЗ: {c.military_factories}\n"f"Стабильность: {c.stability}% | Поддержка: {c.war_support}%")
        rows=[[Keyboards.btn("+100 млн",f"admin:grantmoney:{code}:100000000"),Keyboards.btn("+1 млрд",f"admin:grantmoney:{code}:1000000000")],[Keyboards.btn("+10 ГЗ / +10 ВЗ",f"admin:factories:{code}:10:10")],[Keyboards.btn("📦 Склад","admin:warehouse:"+code)],[Keyboards.btn("🏭 Производство","admin:prod:"+code)],*Keyboards.nav("admin:home")]
        await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))

    async def render_admin_warehouse(self,target:types.Message|types.CallbackQuery,code:str,page:int)->None:
        c=self.world.country(code); models=sorted(self.production.models(),key=lambda m:m.name); chunk,page,total=page_slice(models,page,12)
        rows=[[Keyboards.btn(f"♾️ {'ON' if c.infinite_weapons else 'OFF'}",f"admin:infinite:{code}:{0 if c.infinite_weapons else 1}"),Keyboards.btn("📦 Заполнить +1000","admin:fill:"+code)]]
