def _v11_make_map(self: "WorldState") -> None:
    names = list(EXACT_MAP_NAMES)
    if len(names) != MAX_PROVINCES or len(set(names)) != MAX_PROVINCES:
        raise RuntimeError("Точная карта: список имён должен содержать 100 уникальных провинций")
                                     
    flat = [int(pid) for row in EXACT_MAP_GRID for pid in row]
    missing = sorted(set(range(1, 101)) - set(flat))
    dupes = sorted({x for x in flat if flat.count(x) > 1})
    if missing or dupes or len(flat) != 100:
        raise RuntimeError(f"Точная карта: неверная сетка; missing={missing}, duplicates={dupes}")

    positions = {}
    for r, row in enumerate(EXACT_MAP_GRID):
        for c, pid in enumerate(row):
            positions[int(pid)] = (r, c)

    for pid in range(1, MAX_PROVINCES + 1):
        r, c = positions[pid]
        neighbors = []
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < 10 and 0 <= cc < 10:
                neighbors.append(EXACT_MAP_GRID[rr][cc])
        owner = EXACT_COUNTRY_BY_ID[pid]
        city = pid in {x for values in EXACT_CITY_IDS.values() for x in values}
        capital = pid in set(EXACT_CAPITAL_IDS.values())
                                                                          
                                                                             
        sea = r in (0, 9) or c in (0, 9)
        terrain = "urban" if city or capital else (
            "forest" if pid % 9 in (1, 4) else "hill" if pid % 11 in (0, 5) else "plain"
        )
        p = Province(
            id=pid,
            name=names[pid - 1],
            country=owner,
            neighbors=[int(x) for x in neighbors],
            city=city,
            capital=capital,
            sea_access=sea,
            terrain=terrain,
            river=(pid % 7 == 0),
            bridge=(pid % 11 == 0),
            road_level=2 + (pid % 3),
            rail_level=1 + ((pid + 1) % 3),
            industrial_level=1,
        )
        p.buildings = {k: 0 for k in (
            "civ_factory", "mil_factory", "mine", "npz", "metallurgy", "oilwell",
            "oil_processing", "components", "power", "substation", "airfield",
            "naval_base", "fort", "radar", "business"
        )}
        p.building_condition = {k: 100.0 for k in p.buildings}
        self.provinces[pid] = p
        self.countries[owner].province_ids.append(pid)

    counts = {code: len(self.countries[code].province_ids) for code in PLAYABLE_COUNTRIES}
    expected = {COUNTRY_RAZBAGARE: 34, COUNTRY_PEDAGOG: 33, COUNTRY_MARKLAND: 33}
    if counts != expected:
        raise RuntimeError(f"Точная карта: неверные размеры стран {counts}")
    for a in PLAYABLE_COUNTRIES:
        for b in PLAYABLE_COUNTRIES:
            if a < b and not self.country_share_border(a, b):
                raise RuntimeError(f"Точная карта: страны не граничат {a}/{b}")

                                                                                    
    for code in PLAYABLE_COUNTRIES:
        capital_pid = EXACT_CAPITAL_IDS[code]
        self.provinces[capital_pid].add_building("airfield", 1)
        border_candidates = [
            pid for pid in self.countries[code].province_ids
            if any(self.provinces[n].country != code for n in self.provinces[pid].neighbors)
            and pid != capital_pid
        ]
        if border_candidates:
            self.provinces[border_candidates[0]].add_building("airfield", 1)
        sea_candidates = [pid for pid in self.countries[code].province_ids if self.provinces[pid].sea_access]
        if sea_candidates:
            self.provinces[sea_candidates[0]].add_building("naval_base", 1)


WorldState._make_map = _v11_make_map


def _v11_map_integrity(world: "WorldState") -> dict[str, Any]:
    errors = []
    if len(world.provinces) != 100:
        errors.append("Не 100 провинций")
    if [world.province(i).name for i in range(1, 101)] != EXACT_MAP_NAMES:
        errors.append("Имена провинций не соответствуют карте")
    for code, pid in EXACT_CAPITAL_IDS.items():
        if world.province(pid).country != code or not world.province(pid).capital:
            errors.append(f"Неверная столица {code}")
    if not all(world.country_share_border(a, b) for a in PLAYABLE_COUNTRIES for b in PLAYABLE_COUNTRIES if a < b):
        errors.append("Не все страны граничат друг с другом")
    if not all(any(world.province(pid).sea_access for pid in world.country(code).province_ids) for code in PLAYABLE_COUNTRIES):
        errors.append("Не у всех стран есть море")
    return {"ok": not errors, "errors": errors}

map_integrity = _v11_map_integrity


                                                 
_old_production_summary = Production.summary


def _v11_production_summary(self: Production, country_code: str) -> dict[str, Any]:
    data = _old_production_summary(self, country_code)
    data["used_factories"] = sum(int(v.get("factories", 0)) for v in data.get("lines", {}).values())
    data["free_factories"] = max(0, int(data.get("military_factories", 0)) - int(data["used_factories"]))
    return data


