def _v11_create_division(self: Army, country_code: str, template: str, province_id: int, name: Optional[str] = None):
    if template not in DIVISION_TEMPLATES:
        return False, "Шаблон дивизии не найден.", None
    try:
        province_id = int(province_id)
    except (TypeError, ValueError):
        return False, "Неверная провинция.", None
    if province_id not in self.world.provinces:
        return False, "Провинция не найдена.", None
    province = self.world.province(province_id)
    if province.country != country_code:
        return False, "Дивизию можно создавать только на своей территории.", None
    country = self.world.country(country_code)
    template_data = DIVISION_TEMPLATES[template]
    equipment = _equipment_total(template_data)
    missing = {k: amount - int(country.warehouse.get(k, 0)) for k, amount in equipment.items() if not country.infinite_weapons and int(country.warehouse.get(k, 0)) < amount}
    if missing:
        short = ", ".join(f"{model_display(k)}: не хватает {format_number(v)}" for k, v in missing.items())
        return False, "Недостаточно снаряжения: " + short, None
    manpower_need = int(template_data.get("manpower", 0))
    if not country.infinite_weapons and int(country.manpower) < manpower_need:
        return False, f"Недостаточно людского резерва: нужно {format_number(manpower_need)}, есть {format_number(country.manpower)}.", None
                                                     
    if not country.infinite_weapons:
        for key, amount in equipment.items():
            country.warehouse[key] = int(country.warehouse.get(key, 0)) - amount
        country.manpower -= manpower_need
    did = self.world.next_entity_id("div")
    d = {
        "id": did,
        "country": country_code,
        "name": name or f"Дивизия {len(self.country_divisions(country_code)) + 1}",
        "template": template,
        "province": province_id,
        "general": None,
        "manpower": manpower_need,
        "organization": float(template_data["organization"]),
        "readiness": float(template_data["readiness"]),
        "condition": float(template_data["condition"]),
        "experience": 0.0,
        "combat": float(template_data["combat"]),
        "base_combat": float(template_data["combat"]),
        "base_attack": float(template_data["attack"]),
        "base_defense": float(template_data["defense"]),
        "order": "hold",
        "target_province": None,
        "selected_cells": [province_id],
        "upgrades": {},
        "movement": None,
        "path": [],
        "created_at": self.world.game_minutes,
    }
    self.world.divisions[did] = d
    province.armies.append(did)
    self.world.add_log("division_created", None, {"country": country_code, "division": did, "template": template})
    self.world.mark_dirty()
    return True, f"Дивизия создана: {d['name']}.", did


Army.create_division = _v11_create_division


                                                                                  
def _v11_create_group(self: Aviation, country_code: str, model_key: str, quantity: int, province_id: int):
    quantity = int(quantity)
    if quantity <= 0:
        return False, "Количество должно быть больше нуля.", None
    if model_key not in AIR_MODELS and model_key not in UAV_MODELS:
        return False, "Модель авиации не найдена.", None
    stock = int(self.world.country(country_code).warehouse.get(model_key, 0))
    if not self.world.country(country_code).infinite_weapons and stock < quantity:
        return False, f"На складе только {stock} единиц.", None
    province_id = int(province_id)
    if province_id not in self.airfields(country_code):
        return False, "На этой провинции нет рабочего аэродрома.", None
    if not self.world.country(country_code).infinite_weapons:
        self.world.country(country_code).warehouse[model_key] = stock - quantity
    model = AIR_MODELS.get(model_key) or UAV_MODELS.get(model_key)
    gid = self.world.next_entity_id("air")
    self.world.air_groups[gid] = {
        "id": gid, "name": f"Авиагруппа {gid}", "country": country_code,
        "model": model_key, "quantity": quantity, "airfield_province": province_id,
        "readiness": 100.0, "condition": 100.0, "mission": "stop",
        "target_country": None, "target_province": None, "manual": True,
        "route": [], "route_index": 0, "created_at": self.world.game_minutes,
        "strength": float(model.strength),
    }
    if gid not in self.world.province(province_id).air_groups:
        self.world.province(province_id).air_groups.append(gid)
    self.world.mark_dirty()
    return True, f"Создана авиагруппа: {model.name} × {quantity}.", gid


Aviation.create_group = _v11_create_group


def _v11_rebase(self: Aviation, group_id: str, province_id: int):
    g = self.world.air_groups.get(group_id)
    if not g:
        return False, "Авиагруппа не найдена."
    province_id = int(province_id)
    if province_id not in self.airfields(g["country"]):
        return False, "Это не ваш рабочий аэродром."
    old = int(g.get("airfield_province", 0))
    if old in self.world.provinces and group_id in self.world.province(old).air_groups:
        self.world.province(old).air_groups.remove(group_id)
    g["airfield_province"] = province_id
    if group_id not in self.world.province(province_id).air_groups:
        self.world.province(province_id).air_groups.append(group_id)
    g["readiness"] = _clamp(float(g.get("readiness", 100.0)) - 2.0, 0, 100)
    self.world.mark_dirty()
    return True, "Авиагруппа перебазирована."


Aviation.rebase = _v11_rebase


def _v11_set_mission(self: Aviation, group_id: str, mission: str, target_country: Optional[str], target_province: Optional[int]):
    g = self.world.air_groups.get(group_id)
    if not g:
        return False, "Авиагруппа не найдена."
    if mission not in AIR_TASKS:
        return False, "Неизвестное задание."
    if mission in {"stop", "standby"}:
        target_country = None
        target_province = None
    else:
        if target_country is None or target_province is None:
            return False, "Нужно выбрать цель."
        target_province = int(target_province)
        if target_province not in self.world.provinces:
            return False, "Провинция не найдена."
        owner = self.world.province(target_province).country
        own_target_missions = {"support", "transport", "intercept", "patrol", "recon"}
        if mission in own_target_missions:
            if owner != g["country"] or target_country != g["country"]:
                return False, "Для этого задания нужна ваша провинция."
        elif target_country == g["country"] or owner != target_country:
            return False, "Цель должна находиться на выбранной чужой территории."
        if mission in {"air_superiority"} and not _at_war(self.world, g["country"], target_country):
            return False, "Воздушное превосходство против страны доступно только во время войны."
        if mission == "strike" and g.get("model") in UAV_MODELS and not _at_war(self.world, g["country"], target_country):
            return False, "Ударные БПЛА можно применять только во время войны."
    g["mission"] = mission
    g["target_country"] = target_country
    g["target_province"] = target_province
    g["readiness"] = _clamp(float(g.get("readiness", 100.0)) - 2.0, 0, 100)
    self.world.mark_dirty()
    self.world.add_log("air_mission", None, {"group": group_id, "mission": mission, "target": target_province})
    return True, f"Задание установлено: {AIR_TASKS[mission]}."


Aviation.set_mission = _v11_set_mission


def _v11_set_route(self: Aviation, group_id: str, province_ids: list[int]):
    g = self.world.air_groups.get(group_id)
    if not g:
        return False, "Авиагруппа не найдена."
    cleaned = []
    for pid in province_ids:
        pid = int(pid)
        if pid in self.world.provinces and pid not in cleaned:
            if not cleaned or pid in self.world.province(cleaned[-1]).neighbors or pid == int(g.get("airfield_province", -1)):
                cleaned.append(pid)
            else:
                return False, f"Провинция {pid} не соседствует с предыдущей точкой маршрута."
    g["route"] = cleaned[:30]
    g["route_index"] = 0
    g["manual"] = True
    self.world.mark_dirty()
    return True, f"Маршрут сохранён: {len(g['route'])} точек."


def _v11_clear_route(self: Aviation, group_id: str):
    g = self.world.air_groups.get(group_id)
    if not g:
        return False, "Авиагруппа не найдена."
    g["route"] = []
    g["route_index"] = 0
    self.world.mark_dirty()
    return True, "Маршрут очищен."


Aviation.set_route = _v11_set_route
Aviation.clear_route = _v11_clear_route


                                               
def _v11_pvo_deploy(self: PVO, country_code: str, model_key: str, quantity: int, province_id: int):
    quantity = max(1, int(quantity))
    if model_key not in PVO_MODELS:
        return False, "Модель ПВО не найдена.", None
    province_id = int(province_id)
    if not _province_owned(self.world, country_code, province_id):
        return False, "Провинция должна быть вашей.", None
    stock = int(self.world.country(country_code).warehouse.get(model_key, 0))
    if not self.world.country(country_code).infinite_weapons and stock < quantity:
        return False, f"На складе только {stock} ед.", None
    if not self.world.country(country_code).infinite_weapons:
        self.world.country(country_code).warehouse[model_key] = stock - quantity
    uid = self.world.next_entity_id("pvo")
    model = PVO_MODELS[model_key]
    self.world.pvo_units[uid] = {
        "id": uid, "country": country_code, "model": model_key, "quantity": quantity,
        "province": province_id, "readiness": 100.0, "condition": 100.0,
        "strength": float(model["strength"]) * quantity, "detection": float(model["detection"]),
        "mode": "wide", "priority": "normal", "active": True,
    }
    self.world.province(province_id).pvo_units.append(uid)
    self.world.mark_dirty()
    return True, f"ПВО размещено: {model['name']} × {quantity}.", uid


PVO.deploy = _v11_pvo_deploy


def _v11_pvo_coverage(self: PVO, country_code: str, province_id: int) -> dict[str, Any]:
    province_id = int(province_id)
    if province_id not in self.world.provinces:
        return {"strength": 0.0, "detection": 0.0, "units": []}
    strength = 0.0
    detection = 0.0
    sources = []
    for unit in self.units(country_code):
        if not unit.get("active", True):
            continue
        mode = unit.get("mode", "wide")
        covered = province_id == int(unit.get("province", -1))
        if mode == "wide":
            covered = covered or province_id in self.world.province(int(unit.get("province", -1))).neighbors
        elif mode == "sector":
            covered = covered and True
        elif mode == "priority":
            covered = covered or province_id in self.world.province(int(unit.get("province", -1))).neighbors
        if not covered:
            continue
        readiness = _clamp(float(unit.get("readiness", 0))) / 100.0
        condition = _clamp(float(unit.get("condition", 0))) / 100.0
        priority_mod = {"high": 1.18, "normal": 1.0, "low": 0.82}.get(unit.get("priority", "normal"), 1.0)
        mode_mod = {"wide": 0.95, "sector": 1.18, "priority": 1.05}.get(mode, 1.0)
        own = strength / 100.0
        gain = float(unit.get("strength", 0)) * readiness * condition * priority_mod * mode_mod / (1.0 + own * 0.65)
        strength += gain
        detection += float(unit.get("detection", 0)) * readiness * condition
        sources.append(unit["id"])
    if province_id in self.radars(country_code):
        detection += 65
    for n in self.world.province(province_id).neighbors:
        if n in self.radars(country_code):
            detection += 20
    return {"strength": min(100.0, strength), "detection": min(100.0, detection), "units": sources}


PVO.coverage = _v11_pvo_coverage


                                                          
def parse_compact_number(value: str, allow_negative: bool = False) -> Optional[int]:
    raw = str(value).strip().lower().replace(" ", "").replace("_", "").replace("$", "")
    raw = raw.replace(",", ".")
    multipliers = (("ккк", 1_000_000_000), ("kkk", 1_000_000_000), ("кк", 1_000_000), ("kk", 1_000_000), ("млрд", 1_000_000_000), ("млн", 1_000_000), ("к", 1_000), ("k", 1_000))
    mult = 1
    for suffix, factor in multipliers:
        if raw.endswith(suffix):
            raw = raw[:-len(suffix)]
            mult = factor
            break
    try:
        number = float(raw)
    except ValueError:
        return None
    if not allow_negative:
        number = max(0.0, number)
    number *= mult
    if number > 10_000_000_000_000:
        return None
    return int(number)


                                                   
def _v11_warehouse_text(self, country: str) -> str:
    c = self.world.country(country)
    lines = [f"📦 <b>Склад — {esc(c.name)}</b>", ""]
    section_order = [
        ("🔫 Вооружение", WEAPON_CATEGORIES["infantry"]),
        ("🚙 Бронетехника", WEAPON_CATEGORIES["vehicles"]),
        ("🛡️ Танки", WEAPON_CATEGORIES["tanks"]),
        ("💥 Артиллерия", WEAPON_CATEGORIES["artillery"]),
        ("🛡️ ПВО", WEAPON_CATEGORIES["pvo"]),
        ("✈️ Авиация", WEAPON_CATEGORIES["air"]),
        ("🛰️ Ударные БПЛА", WEAPON_CATEGORIES["uav"]),
        ("🚛 Транспорт", {"truck"}),
        ("⚓ Флот", WEAPON_CATEGORIES["navy"]),
    ]
    for title, keys in section_order:
        lines.append(f"<b>{title}</b>")
        for key in keys:
            lines.append(f"• {esc(model_display(key))}: {format_number(c.warehouse.get(key, 0))}")
        lines.append("")
    lines.append("<b>⛏️ Ресурсы</b>")
    for key in RESOURCE_KEYS:
        lines.append(f"• {RESOURCE_DISPLAY[key]}: {format_number(c.resources.get(key, 0))}")
    lines.append("")
    lines.append(f"⏱️ Следующее обновление склада: <b>{self.simulation.warehouse_countdown():02d} мин.</b>")
    return "\n".join(lines)


