async def _v11_render_journal(self: WorldApp, target: types.Message | types.CallbackQuery, category: str, page: int) -> None:
    country, error = self.require_country(target.from_user.id)
    if not country:
        await self.show(target, error, Keyboards.country_picker())
        return
    raw_entries = []
    for item in self.world.journal:
        if isinstance(item, dict):
            getter = item.get
        else:
            getter = lambda key, default=None: getattr(item, key, default)
        item_country = getter("country")
        item_category = getter("category", "all")
        if item_country and item_country != country:
            continue
        if category != "all" and item_category != category:
            continue
        raw_entries.append((getter("time", 0), getter("title", ""), getter("text", ""), item_category))
    raw_entries = raw_entries[-100:][::-1]
    chunk, page, total = page_slice(raw_entries, page)
    lines = []
    for when, title, body, cat in chunk:
        lines.append(f"<b>{esc(title)}</b>\n{esc(body)}")
    cats = [("all", "Все"), ("news", "📰 Новости"), ("wars", "⚔️ Войны"), ("army", "🪖 Армия"), ("aviation", "✈️ Авиация"), ("pvo", "🛡️ ПВО"), ("navy", "⚓ Флот"), ("production", "🏭 Производство"), ("economy", "💰 Экономика"), ("diplomacy", "🤝 Дипломатия"), ("trade", "🚛 Торговля"), ("decisions", "📜 Решения")]
    rows = [[Keyboards.btn(label, f"journalcat:{key}:0")] for key, label in cats]
    rows.append(Keyboards.pagination(f"journalpage:{category}", page, total))
    rows += Keyboards.nav("home")
    await self.show(target, "📖 <b>Журнал</b>\n\n" + ("\n\n".join(lines) if lines else "Записей нет."), types.InlineKeyboardMarkup(inline_keyboard=rows))


