def _v11_admin_log_line(entry: dict[str, Any]) -> str:
    kind = str(entry.get("kind", "event"))
    label = ADMIN_LOG_RU.get(kind, kind.replace("_", " ").capitalize())
    user_id = entry.get("user_id")
    data = entry.get("data") or {}
    if not isinstance(data, dict):
        data = {"детали": str(data)}
    parts = []
    for key, value in data.items():
        ru_key = {
            "country": "страна", "amount": "сумма", "resource": "ресурс", "equipment": "техника",
            "division": "дивизия", "group": "группа", "mission": "задание", "target": "цель",
            "war": "война", "template": "шаблон", "country_code": "страна",
        }.get(str(key), str(key))
        if str(key) == "country":
            value = COUNTRY_NAMES.get(str(value), value)
        parts.append(f"{ru_key}={value}")
    actor = f"игрок {user_id}" if user_id is not None else "система"
    return f"{label} — {actor}" + (" — " + ", ".join(parts) if parts else "")


