async def _v11_handle_pvo(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    country, error = self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback, error, Keyboards.country_picker())
        return
    if data.startswith("pvounit:"):
        uid = data.split(":", 1)[1]; u = self.world.pvo_units.get(uid)
        if not u or u.get("country") != country:
            await self.show(callback, "❌ Комплекс ПВО не найден.", Keyboards.simple_nav("screen:pvo")); return
        mode = {"wide":"Широкое покрытие", "sector":"Локальный сектор", "priority":"Приоритетный сектор"}.get(u.get("mode","wide"), u.get("mode"))
        priority = {"high":"Высокий", "normal":"Обычный", "low":"Низкий"}.get(u.get("priority","normal"), u.get("priority"))
        text=(f"🛡️ <b>{esc(PVO_MODELS[u['model']]['name'])}</b> ×{u['quantity']}\n\n"
              f"Провинция: {self.world.province(u['province']).name}\n"
              f"Готовность: {u['readiness']:.0f}%\nСостояние: {u['condition']:.0f}%\n"
              f"Режим: {mode}\nПриоритет: {priority}\nСтатус: {'🟢 включено' if u.get('active', True) else '🔴 выключено'}")
        rows=[[Keyboards.btn("📍 Переместить", f"pvomove:{uid}")],[Keyboards.btn("🎛️ Режим", f"pvomode:{uid}"), Keyboards.btn("⭐ Приоритет", f"pvopriority:{uid}")],[Keyboards.btn("🔌 Вкл/выкл", f"pvoactive:{uid}"), Keyboards.btn("🗺️ Покрытие", f"pvocover:{uid}")],*Keyboards.nav("screen:pvo")]
        await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvomove:"):
        uid=data.split(":",1)[1]; u=self.world.pvo_units.get(uid)
        if not u or u.get("country")!=country: await self.show(callback,"❌ Комплекс не найден."); return
        rows=[[Keyboards.btn(self.world.province(pid).name,f"pvomoveto:{uid}:{pid}")] for pid in self.world.country(country).province_ids[:70]]; rows+=Keyboards.nav(f"pvounit:{uid}")
        await self.show(callback,"📍 Выберите новую провинцию:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvomoveto:"):
        _,uid,pidtxt=data.split(":",2); u=self.world.pvo_units.get(uid); pid=int(pidtxt)
        if not u or u.get("country")!=country or pid not in self.world.country(country).province_ids:
            await self.show(callback,"❌ Недопустимое перемещение.",Keyboards.simple_nav("screen:pvo")); return
        old=int(u["province"])
        if uid in self.world.province(old).pvo_units: self.world.province(old).pvo_units.remove(uid)
        u["province"]=pid
        if uid not in self.world.province(pid).pvo_units: self.world.province(pid).pvo_units.append(uid)
        u["readiness"]=_clamp(float(u.get("readiness",100))-2,0,100)
        self.world.mark_dirty(); self.spawn(self.save_light()); await self.show(callback,"✅ ПВО перемещено.",Keyboards.simple_nav(f"pvounit:{uid}")); return
    if data.startswith("pvomode:"):
        uid=data.split(":",1)[1]; rows=[[Keyboards.btn("🌐 Широкое покрытие","pvomodeset:%s:wide"%uid)],[Keyboards.btn("📍 Локальный сектор","pvomodeset:%s:sector"%uid)],[Keyboards.btn("⭐ Приоритетный сектор","pvomodeset:%s:priority"%uid)],*Keyboards.nav(f"pvounit:{uid}")]; await self.show(callback,"🎛️ Выберите режим ПВО:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvomodeset:"):
        _,uid,mode=data.split(":",2); u=self.world.pvo_units.get(uid)
        if not u or u.get("country")!=country or mode not in {"wide","sector","priority"}: await self.show(callback,"❌ Недопустимый режим."); return
        u["mode"]=mode; self.world.mark_dirty(); self.spawn(self.save_light()); await self.show(callback,"✅ Режим ПВО изменён.",Keyboards.simple_nav(f"pvounit:{uid}")); return
    if data.startswith("pvopriority:"):
        uid=data.split(":",1)[1]; rows=[[Keyboards.btn("⬆️ Высокий","pvopriorityset:%s:high"%uid)],[Keyboards.btn("🟰 Обычный","pvopriorityset:%s:normal"%uid)],[Keyboards.btn("⬇️ Низкий","pvopriorityset:%s:low"%uid)],*Keyboards.nav(f"pvounit:{uid}")]; await self.show(callback,"⭐ Выберите приоритет:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvopriorityset:"):
        _,uid,priority=data.split(":",2); u=self.world.pvo_units.get(uid)
        if not u or u.get("country")!=country or priority not in {"high","normal","low"}: await self.show(callback,"❌ Недопустимый приоритет."); return
        u["priority"]=priority; self.world.mark_dirty(); self.spawn(self.save_light()); await self.show(callback,"✅ Приоритет ПВО изменён.",Keyboards.simple_nav(f"pvounit:{uid}")); return
    if data.startswith("pvoactive:"):
        uid=data.split(":",1)[1]; u=self.world.pvo_units.get(uid)
        if not u or u.get("country")!=country: await self.show(callback,"❌ Комплекс не найден."); return
        u["active"]=not u.get("active",True); self.world.mark_dirty(); self.spawn(self.save_light()); await self.show(callback,"✅ " + ("ПВО включено." if u["active"] else "ПВО выключено."),Keyboards.simple_nav(f"pvounit:{uid}")); return
    if data.startswith("pvocover:"):
        uid=data.split(":",1)[1]; u=self.world.pvo_units.get(uid)
        if not u or u.get("country")!=country: await self.show(callback,"❌ Комплекс не найден."); return
        base=int(u["province"]); cov=self.pvo.coverage(country,base)
        names=[self.world.province(pid).name for pid in [base]+self.world.province(base).neighbors]
        await self.show(callback,f"🗺️ <b>Покрытие</b>\n\nКомплекс: {esc(PVO_MODELS[u['model']]['name'])}\nСила: {cov['strength']:.0f}%\nОбнаружение: {cov['detection']:.0f}%\n\nЗона рядом с: {esc(', '.join(names))}",Keyboards.simple_nav(f"pvounit:{uid}")); return
    if data == "pvo:coverage":
        rows=[[Keyboards.btn(self.world.province(pid).name,f"pvocountry:{pid}")] for pid in self.world.country(country).province_ids[:70]]; rows+=Keyboards.nav("screen:pvo"); await self.show(callback,"🗺️ Выберите провинцию для просмотра покрытия:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvocountry:"):
        pid=int(data.split(":",1)[1]); cov=self.pvo.coverage(country,pid); await self.show(callback,f"🗺️ <b>Покрытие {esc(self.world.province(pid).name)}</b>\n\nСила: {cov['strength']:.0f}%\nОбнаружение: {cov['detection']:.0f}%\nКомплексы: {len(cov['units'])}",Keyboards.simple_nav("screen:pvo")); return
    await _old_handle_pvo(self, callback, data)


