async def _v11_handle_air(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    country, error = self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback, error, Keyboards.country_picker()); return
    if data.startswith("airroute:"):
        gid = data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if not g or g.get("country") != country: await self.show(callback,"❌ Группа не найдена."); return
        rows=[[Keyboards.btn(COUNTRY_NAMES[x], f"airroutecountry:{gid}:{x}")] for x in PLAYABLE_COUNTRIES]
        rows += [[Keyboards.btn("🧹 Очистить маршрут", f"airrouteclear:{gid}")], *Keyboards.nav(f"airgroup:{gid}")]
        route = [self.world.province(pid).name for pid in g.get("route", []) if pid in self.world.provinces]
        current = ", ".join(route) if route else "нет"
        await self.show(callback, f"🛣️ <b>Маршрут авиагруппы</b>\n\nТочки: {esc(current)}\n\nДобавьте следующую точку маршрута.", types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airroutecountry:"):
        _,gid,target = data.split(":",2); g=self.world.air_groups.get(gid)
        if not g or g.get("country") != country: await self.show(callback,"❌ Группа не найдена."); return
        if target != country and not _at_war(self.world, country, target):
            await self.show(callback,"❌ Чужие провинции в маршрут можно добавлять только во время войны.",Keyboards.simple_nav(f"airgroup:{gid}")); return
        pids = self.world.country(target).province_ids
        rows=[[Keyboards.btn(self.world.province(pid).name, f"airrouteprov:{gid}:{pid}")] for pid in pids[:70]]; rows+=Keyboards.nav(f"airroute:{gid}")
        await self.show(callback,"📍 Выберите следующую точку маршрута:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airrouteprov:"):
        _,gid,pidtxt=data.split(":",2); pid=int(pidtxt); g=self.world.air_groups.get(gid)
        if not g or g.get("country") != country: await self.show(callback,"❌ Группа не найдена."); return
        route=list(g.get("route") or [])
        start=int(g.get("airfield_province", -1)) if not route else int(route[-1])
        if pid != start and pid not in self.world.province(start).neighbors:
            await self.show(callback,"❌ Для удобного маршрута сначала выберите соседнюю провинцию.",Keyboards.simple_nav(f"airroute:{gid}")); return
        ok,reason=self.aviation.set_route(gid, route+[pid]); self.spawn(self.save_light()); await self.show(callback,"✅ "+reason,Keyboards.simple_nav(f"airroute:{gid}")); return
    if data.startswith("airrouteclear:"):
        gid=data.split(":",1)[1]; ok,reason=self.aviation.clear_route(gid); self.spawn(self.save_light()); await self.show(callback,"✅ "+reason,Keyboards.simple_nav(f"airgroup:{gid}")); return
    if data.startswith("airgroup:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if g and g.get("country")==country:
            route = [self.world.province(pid).name for pid in g.get("route", []) if pid in self.world.provinces]
            model=AIR_MODELS.get(g.get("model")) or UAV_MODELS.get(g.get("model"))
            text=(f"✈️ <b>{esc(g.get('name',''))}</b>\n\nМодель: {esc(model.name if model else g.get('model'))}\n"
                  f"Количество: {g.get('quantity',0)}\nАэродром: {self.world.province(g['airfield_province']).name}\n"
                  f"Готовность: {g.get('readiness',0):.0f}%\nСостояние: {g.get('condition',0):.0f}%\n"
                  f"Задание: {AIR_TASKS.get(g.get('mission'),g.get('mission'))}\nМаршрут: {esc(' → '.join(route) if route else 'нет')}")
            rows=[[Keyboards.btn("🎯 Задание",f"airmission:{gid}"), Keyboards.btn("🛣️ Маршрут",f"airroute:{gid}")],[Keyboards.btn("🛫 Перебазировать",f"airrebase:{gid}")],*Keyboards.nav("air:groups")]
            await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    await _old_handle_air(self, callback, data)


WorldApp.handle_air = _v11_handle_air


                                                           
