async def _v11_handle_admin(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    parts = data.split(":")
    if len(parts) >= 4 and parts[1] == "news" and parts[2] == "publish":
        if not self.is_admin(callback.from_user.id):
            await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker()); return
        nid = parts[3]
        ok, reason = self.news.publish(nid, callback.from_user.id)
        self.spawn(self.broadcast_news(nid))
        self.spawn(self.save_light())
        await self.show(callback, ("✅ " if ok else "❌ ") + reason, Keyboards.simple_nav("admin:section:news"))
        return
    await _old_handle_admin(self, callback, data)


WorldApp.handle_admin = _v11_handle_admin


                                                                                   
MAP_IMAGE_FILENAME = "world_map.png"


async def _v11_send_map_image(self: WorldApp, target: types.Message | types.CallbackQuery) -> bool:
    _file = globals().get("__file__")
    _base_dir = Path(_file).resolve().parent if _file else Path.cwd()
    path = _base_dir / MAP_IMAGE_FILENAME
    if not path.exists() or not getattr(self, "bot", None):
        return False
    try:
                                                     
        from aiogram.types import FSInputFile
        caption = "🗺️ <b>WORLD STRATEGY — Политическая карта</b>\n100 провинций\n⭐ столицы • 🏙️ города"
        if isinstance(target, types.CallbackQuery):
            await target.message.answer_photo(FSInputFile(str(path)), caption=caption, parse_mode=ParseMode.HTML)
        else:
            await target.answer_photo(FSInputFile(str(path)), caption=caption, parse_mode=ParseMode.HTML)
        return True
    except Exception:
        return False


WorldApp.send_map_image = _v11_send_map_image


                                                 
_old_validate = WorldState.validate


def _v11_validate(self: WorldState) -> list[str]:
    errors = list(_old_validate(self))
    mi = _v11_map_integrity(self)
    errors.extend(mi.get("errors", []))
                                             
    for code in PLAYABLE_COUNTRIES:
        c = self.country(code)
        for key, value in c.warehouse.items():
            if int(value) < 0:
                errors.append(f"negative warehouse {code}/{key}")
                                                                       
    for uid, u in self.pvo_units.items():
        pid = int(u.get("province", -1))
        if pid not in self.provinces:
            errors.append(f"pvo {uid}: bad province")
        elif uid not in self.province(pid).pvo_units:
            errors.append(f"pvo {uid}: missing province link")
    for gid, g in self.air_groups.items():
        pid = int(g.get("airfield_province", -1))
        if pid not in self.provinces:
            errors.append(f"air {gid}: bad airfield")
        elif gid not in self.province(pid).air_groups:
            errors.append(f"air {gid}: missing airfield link")
        for rpid in g.get("route", []) or []:
            if int(rpid) not in self.provinces:
                errors.append(f"air {gid}: bad route province {rpid}")
    return list(dict.fromkeys(errors))


WorldState.validate = _v11_validate

                                                                   


def _v12_air_path(world: "WorldState", start: int, target: int, country: str) -> list[int]:
    start, target = int(start), int(target)
    if start == target:
        return [start]
    queue = [start]
    parent = {start: None}
    while queue:
        current = queue.pop(0)
        for nxt in world.province(current).neighbors:
            if nxt in parent:
                continue
            owner = world.province(nxt).country
            if owner != country and not _at_war(world, country, owner):
                continue
            parent[nxt] = current
            if nxt == target:
                path = [target]
                while parent[path[-1]] is not None:
                    path.append(parent[path[-1]])
                path.reverse()
                return path
            queue.append(nxt)
    return []


_old_v11_handle_air = WorldApp.handle_air


async def _v12_handle_air(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    country, error = self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback, error, Keyboards.country_picker()); return
    if data.startswith("airrouteprov:"):
        _, gid, pidtxt = data.split(":", 2)
        pid = int(pidtxt)
        g = self.world.air_groups.get(gid)
        if not g or g.get("country") != country or pid not in self.world.provinces:
            await self.show(callback, "❌ Группа или провинция не найдена.", Keyboards.simple_nav("screen:air")); return
        route = list(g.get("route") or [])
        start = int(route[-1]) if route else int(g.get("airfield_province", -1))
        path = _v12_air_path(self.world, start, pid, country)
        if not path:
            await self.show(callback, "❌ Автоматический маршрут до этой провинции не найден.", Keyboards.simple_nav(f"airroute:{gid}")); return
                                                                          
        full_route = route + path[1:]
        ok, reason = self.aviation.set_route(gid, full_route)
        self.spawn(self.save_light())
        pretty = " → ".join(self.world.province(x).name for x in full_route)
        await self.show(callback, ("✅ " if ok else "❌ ") + reason + f"\n\nМаршрут: {esc(pretty)}", Keyboards.simple_nav(f"airroute:{gid}")); return
    if data.startswith("airroutecountry:"):
        _, gid, target = data.split(":", 2)
        g = self.world.air_groups.get(gid)
        if not g or g.get("country") != country:
            await self.show(callback, "❌ Группа не найдена.", Keyboards.simple_nav("screen:air")); return
        if target != country and not _at_war(self.world, country, target):
            await self.show(callback, "❌ Маршрут по чужой территории доступен только во время войны.", Keyboards.simple_nav(f"airroute:{gid}")); return
        rows = [[Keyboards.btn(self.world.province(pid).name, f"airrouteprov:{gid}:{pid}")] for pid in self.world.country(target).province_ids[:70]]
        rows += Keyboards.nav(f"airroute:{gid}")
        await self.show(callback, "📍 Выберите конечную точку. Маршрут до неё построится автоматически.", types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    await _old_v11_handle_air(self, callback, data)


WorldApp.handle_air = _v12_handle_air


                                                                              
                                                                     
                                                                              

