def _v12_server_default_state() -> dict[str, Any]:
    return {
        "time_running": True,
        "work_enabled": True,
        "maintenance": False,
        "server_started_at": now_iso(),
        "last_clock_real": 0.0,
        "last_clock_game": 0.0,
        "clock_entries": 0,
        "admin_ids": [],
    }


def _v12_is_server_admin(self: WorldState, user_id: int) -> bool:
    state = getattr(self, "server_state", {}) or {}
    return int(user_id) in {int(x) for x in state.get("admin_ids", [])}


def _v12_set_server_admin(self: WorldState, user_id: int, enabled: bool) -> None:
    state = getattr(self, "server_state", None)
    if state is None:
        self.server_state = _v12_server_default_state()
        state = self.server_state
    ids = {int(x) for x in state.get("admin_ids", [])}
    if enabled:
        ids.add(int(user_id))
    else:
        ids.discard(int(user_id))
    state["admin_ids"] = sorted(ids)


                                                                              
_v12_world_init_base = WorldState.__init__

def _v12_world_init(self: WorldState, *args: Any, **kwargs: Any) -> None:
    _v12_world_init_base(self, *args, **kwargs)
    self.server_state = _v12_server_default_state()
    self.notifications: list[dict[str, Any]] = []
    self.server_state["time_running"] = not bool(self.paused)

WorldState.__init__ = _v12_world_init
WorldState.is_server_admin = _v12_is_server_admin
WorldState.set_server_admin = _v12_set_server_admin

_v12_world_to_dict_base = WorldState.to_dict
_v12_world_from_dict_base = WorldState.from_dict

def _v12_world_to_dict(self: WorldState) -> dict[str, Any]:
    data = _v12_world_to_dict_base(self)
    data["server_state"] = copy.deepcopy(getattr(self, "server_state", _v12_server_default_state()))
    data["notifications"] = copy.deepcopy(getattr(self, "notifications", []))
    return data


def _v12_world_from_dict(self: WorldState, data: dict[str, Any]) -> None:
    _v12_world_from_dict_base(self, data)
    state = _v12_server_default_state()
    loaded_state = data.get("server_state")
    if isinstance(loaded_state, dict):
        state.update(loaded_state)
    state["admin_ids"] = sorted({int(x) for x in state.get("admin_ids", []) if str(x).lstrip("-").isdigit()})
    state["time_running"] = bool(state.get("time_running", not bool(self.paused)))
    state["work_enabled"] = bool(state.get("work_enabled", True))
    state["maintenance"] = bool(state.get("maintenance", False))
    self.server_state = state
    raw_notifications = data.get("notifications", [])
    self.notifications = list(raw_notifications) if isinstance(raw_notifications, list) else []

WorldState.to_dict = _v12_world_to_dict
WorldState.from_dict = _v12_world_from_dict


def _v12_server_working(world: WorldState) -> bool:
    state = getattr(world, "server_state", {}) or {}
    return bool(state.get("work_enabled", True)) and not bool(state.get("maintenance", False))


def _v12_server_status(world: WorldState) -> str:
    state = getattr(world, "server_state", {}) or {}
    if state.get("maintenance"):
        return SERVER_MAINTENANCE
    if not state.get("work_enabled", True):
        return SERVER_STOPPED
    return SERVER_WORKING


def _v12_queue_notification(world: WorldState, country: Optional[str], section: str, detail: str = "") -> None:
    section_name = SERVER_SECTION_RU.get(section, section)
    recipients: list[int] = []
    for uid, player in world.players.items():
        if player.banned or player.role == "admin":
            continue
        if country is not None and player.country != country:
            continue
        if country is None and player.country not in PLAYABLE_COUNTRIES:
            continue
        recipients.append(int(uid))
    if not recipients:
        return
    nid = world.next_entity_id("notification")
    world.notifications.append({
        "id": nid,
        "time": world.game_minutes,
        "section": section,
        "section_name": section_name,
        "detail": str(detail)[:240],
        "recipients": recipients,
    })
    world.notifications = world.notifications[-200:]
    world.mark_dirty()


                                                                                
def _v12_server_clock_path(self: WorldApp) -> Path:
    return Path(self.save_manager.directory) / SERVER_CLOCK_FILENAME


def _v12_server_clock_line(self: WorldApp) -> str:
    real_now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    status = _v12_server_status(self.world)
    return f"{real_now} {SERVER_TIMEZONE_LABEL} | Игровое время: {game_time_text(self.world)} | Статус: {status}\n"


def _v12_write_server_clock(self: WorldApp) -> None:
    path = _v12_server_clock_path(self)
    path.parent.mkdir(parents=True, exist_ok=True)
    line = _v12_server_clock_line(self)
    with path.open("a", encoding="utf-8") as f:
        f.write(line)
        f.flush()
        os.fsync(f.fileno())
                                                                          
    try:
        if path.stat().st_size > 2_000_000:
            lines = path.read_text(encoding="utf-8").splitlines()[-10_000:]
            path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    except OSError:
        pass
    self.world.server_state["last_clock_real"] = time.time()
    self.world.server_state["last_clock_game"] = float(self.world.game_minutes)
    self.world.server_state["clock_entries"] = int(self.world.server_state.get("clock_entries", 0)) + 1


def _v12_read_server_clock_tail(self: WorldApp, limit: int = 18) -> list[str]:
    path = _v12_server_clock_path(self)
    if not path.exists():
        return []
    try:
        return path.read_text(encoding="utf-8").splitlines()[-max(1, int(limit)):]
    except OSError:
        return []


async def _v12_server_clock_loop(self: WorldApp) -> None:
                                                                                  
                                                 
    try:
        _v12_write_server_clock(self)
    except Exception as exc:
        self.world.add_log("server_clock_error", None, {"error": repr(exc)})
    last = time.monotonic()
    while True:
        await asyncio.sleep(1.0)
        now = time.monotonic()
        if now - last < SERVER_CLOCK_INTERVAL:
            continue
        periods = int((now - last) // SERVER_CLOCK_INTERVAL)
                                                                                   
                                                                         
        last += max(1, periods) * SERVER_CLOCK_INTERVAL
        try:
            _v12_write_server_clock(self)
            print(f"[SERVER CLOCK] Игровое время: {game_time_text(self.world)} | {_v12_server_status(self.world)}", flush=True)
        except Exception as exc:
            self.world.add_log("server_clock_error", None, {"error": repr(exc)})


                                                                              
async def _v12_dispatch_notifications(self: WorldApp) -> None:
    if not getattr(self, "bot", None):
        return
    if not _v12_server_working(self.world):
        return
    pending = list(getattr(self.world, "notifications", []))[:10]
    if not pending:
        return
    processed_ids: set[str] = set()
    for item in pending:
        recipients = list(item.get("recipients", []))
        section = str(item.get("section_name") or SERVER_SECTION_RU.get(item.get("section", ""), item.get("section", "Сообщения")))
        detail = str(item.get("detail", "")).strip()
        text_msg = f"🔔 <b>Новое сообщение в разделе «{esc(section)}».</b>"
        if detail:
            text_msg += f"\n\n{esc(detail)}"
        remaining_recipients: list[int] = []
        for uid in recipients:
            try:
                await self.bot.send_message(int(uid), text_msg, parse_mode=ParseMode.HTML)
            except (TelegramForbiddenError, TelegramBadRequest):
                                                                                    
                continue
            except Exception:
                                                                                  
                remaining_recipients.append(int(uid))
        item["recipients"] = remaining_recipients
        if not remaining_recipients:
            processed_ids.add(str(item.get("id")))
    if processed_ids:
        self.world.notifications = [x for x in self.world.notifications if str(x.get("id")) not in processed_ids]
        self.world.mark_dirty()


async def _v12_notification_loop(self: WorldApp) -> None:
    while True:
        await asyncio.sleep(SERVER_NOTIFICATION_INTERVAL)
        try:
            await _v12_dispatch_notifications(self)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.world.add_log("notification_error", None, {"error": repr(exc)})


                                                                                
_v12_simulation_run_base = SimulationEngine._run

async def _v12_simulation_run(self: SimulationEngine) -> None:
    while not self._stop.is_set():
        loop_start = time.monotonic()
        real_delta = max(0.0, min(loop_start - self.last_loop_real, 2.0))
        self.last_loop_real = loop_start
        self.save_accum_real += real_delta
        try:
            async with self.app.world.simulation_lock:
                                                                                
                                                                                
                if REALTIME_GAME_TIME and _v12_server_working(self.app.world) and not self.app.world.paused and real_delta > 0:
                    game_delta = real_delta / 60.0
                    self.advance(game_delta)
                elif (not REALTIME_GAME_TIME) and _v12_server_working(self.app.world) and not self.app.world.paused and real_delta > 0:
                    game_delta = real_delta * float(self.app.world.speed)
                    self.advance(game_delta)
                if self.save_accum_real >= AUTOSAVE_REAL_SECONDS:
                    if self.app.world.settings.get("autosave_enabled", True) and self.app.world.dirty:
                        await asyncio.to_thread(self.app.save_manager.save, self.app.world, True)
                        self.app.world.dirty = False
                    self.save_accum_real = 0.0
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.app.world.add_log("simulation_error", None, {"error": repr(exc)})
        await asyncio.sleep(1.0)

SimulationEngine._run = _v12_simulation_run


                                                                                
_v12_army_create_base = Army.create_division


def _v12_army_create_division(self: Army, country_code: str, template: str, province_id: int, name: Optional[str] = None):
                                                                            
    c = self.world.country(country_code)
    if template not in DIVISION_TEMPLATES:
        return False, "Неизвестный шаблон дивизии.", None
    required_manpower = int(DIVISION_TEMPLATES.get(template, {}).get("manpower", 0))
    if required_manpower <= 0:
        required_manpower = 1
    if int(c.manpower) < required_manpower:
        return False, "Недостаточно людского резерва.", None
    before = int(c.manpower)
    result = _v12_army_create_base(self, country_code, template, province_id, name)
    if result[0] and int(c.manpower) != before - required_manpower:
                                                                
        c.manpower = max(0, before - required_manpower)
    return result

Army.create_division = _v12_army_create_division


def _v12_army_validate(self: Army) -> list[str]:
    errors = list(self.validate_army())
    province_seen: dict[str, int] = {}
    for pid, province in self.world.provinces.items():
        for did in province.armies:
            province_seen[did] = province_seen.get(did, 0) + 1
    for did, d in self.world.divisions.items():
        if province_seen.get(did, 0) != 1:
            errors.append(f"division {did}: должно быть ровно одно размещение")
        if d.get("country") not in PLAYABLE_COUNTRIES:
            errors.append(f"division {did}: неверная страна")
        if d.get("target_province") is not None and int(d.get("target_province")) not in self.world.provinces:
            errors.append(f"division {did}: неверная цель")
        movement = d.get("movement")
        if movement:
            a = int(movement.get("from", -1)); b = int(movement.get("to", -1))
            if a not in self.world.provinces or b not in self.world.provinces:
                errors.append(f"division {did}: неверный маршрут")
            elif b not in self.world.province(a).neighbors:
                errors.append(f"division {did}: шаг не является соседним")
            elif self.world.province(b).country != d.get("country") and not _war_exists(self.world, d.get("country"), self.world.province(b).country):
                errors.append(f"division {did}: движение на чужую территорию без войны")
    for gid, g in self.world.generals.items():
        divs = list(g.get("divisions", []))
        if len(divs) > MAX_DIVISIONS_PER_GENERAL:
            errors.append(f"general {gid}: более 24 дивизий")
        for did in divs:
            if did not in self.world.divisions:
                errors.append(f"general {gid}: неизвестная дивизия {did}")
            elif self.world.divisions[did].get("general") != gid:
                errors.append(f"general {gid}: разрыв связи с {did}")
        hq = int(g.get("hq_province", -1))
        if hq not in self.world.provinces:
            errors.append(f"general {gid}: неверный штаб")
        elif self.world.province(hq).country != g.get("country"):
            errors.append(f"general {gid}: штаб вне своей страны")
    return list(dict.fromkeys(errors))

Army.validate = _v12_army_validate


                                                                                
_v12_war_declare_base = WarEngine.declare
_v12_war_end_base = WarEngine.end_war
_v12_war_resolve_base = WarEngine.resolve_battle
_v12_war_outcomes_base = WarEngine.update_war_outcomes


def _v12_war_declare(self: WarEngine, attacker: str, defender: str, reason: str = ""):
                                              
    if attacker == defender:
        return False, "Нельзя объявить войну самому себе.", None
    if _war_exists(self.world, attacker, defender):
        return False, "Эти страны уже находятся в войне.", None
                                                                 
    system_call = str(reason).lower().startswith(("admin", "test", "system"))
    if not system_call:
        allowed, why = can_declare_war(self.world, attacker, defender)
        if not allowed:
            return False, why, None
        gid = re_match_goal_id(str(reason))
        if not gid:
            return False, "Сначала подготовьте цель войны.", None
        goal = self.world.war_goals.get(gid)
        if not goal or goal.get("status") != "prepared" or goal.get("creator") != attacker or goal.get("target") != defender:
            return False, "Подготовленная цель войны не найдена.", None
    result = _v12_war_declare_base(self, attacker, defender, reason)
    if result[0]:
        wid = result[2]
        _v12_queue_notification(self.world, attacker, "wars", "Война началась.")
        _v12_queue_notification(self.world, defender, "wars", f"{country_display(attacker)} объявила войну.")
        self.world.mark_dirty()
    return result

WarEngine.declare = _v12_war_declare


def _v12_war_end(self: WarEngine, war_id: str, winner: Optional[str] = None, reason: str = ""):
    war = self.world.wars.get(war_id)
    if not war or not war.active:
        return False, "Война не найдена или уже завершена."
    if winner is not None and winner not in (war.attacker, war.defender):
        return False, "Победитель не является участником войны."
    a, d = war.attacker, war.defender
    result = _v12_war_end_base(self, war_id, winner, reason)
    if result[0]:
        text = f"Война завершена. {('Победитель: ' + country_display(winner) + '. ') if winner else ''}{reason or ''}".strip()
        _v12_queue_notification(self.world, a, "wars", text)
        _v12_queue_notification(self.world, d, "wars", text)
        self.world.mark_dirty()
    return result

WarEngine.end_war = _v12_war_end


def _v12_war_resolve(self: WarEngine, province_id: int, attacker_country: str, defender_country: str) -> dict[str, Any]:
    if not _war_exists(self.world, attacker_country, defender_country):
        return {"result": "invalid", "reason": "Между сторонами нет активной войны.", "captured": False, "province": int(province_id)}
    province = self.world.province(int(province_id))
    if province.country not in {attacker_country, defender_country}:
        return {"result": "invalid", "reason": "Провинция не принадлежит одной из сторон войны.", "captured": False, "province": int(province_id)}
    return _v12_war_resolve_base(self, province_id, attacker_country, defender_country)

WarEngine.resolve_battle = _v12_war_resolve


def _v12_war_outcomes(self: WarEngine) -> list[str]:
    ended: list[str] = []
    for war in list(self.active_wars()):
        attacker_owned = set(self.world.country(war.attacker).province_ids)
        defender_owned = set(self.world.country(war.defender).province_ids)
        attacker_capital = int(SPECIAL_CAPITAL_IDS[war.attacker])
        defender_capital = int(SPECIAL_CAPITAL_IDS[war.defender])
        a_capital_lost = attacker_capital not in attacker_owned
        d_capital_lost = defender_capital not in defender_owned
        if len(defender_owned) <= 4 or (d_capital_lost and len(defender_owned) <= 10):
            ok, _ = self.end_war(war.id, war.attacker, "Капитуляция обороняющейся стороны.")
            if ok:
                ended.append(war.id)
        elif len(attacker_owned) <= 4 or (a_capital_lost and len(attacker_owned) <= 10):
            ok, _ = self.end_war(war.id, war.defender, "Капитуляция атакующей стороны.")
            if ok:
                ended.append(war.id)
    return ended

WarEngine.update_war_outcomes = _v12_war_outcomes


                                                                               
def _v12_wrap_notification_method(cls: Any, method_name: str, callback_builder: Any) -> None:
    base = getattr(cls, method_name, None)
    if base is None:
        return
    marker_name = f"_v12_base_{method_name}"
    if getattr(cls, marker_name, None) is not None:
        return
    setattr(cls, marker_name, base)
    def wrapper(self, *args: Any, **kwargs: Any):
        result = getattr(cls, marker_name)(self, *args, **kwargs)
        try:
            callback_builder(self, result, *args, **kwargs)
        except Exception as exc:
            self.world.add_log("notification_hook_error", None, {"method": method_name, "error": repr(exc)})
        return result
    setattr(cls, method_name, wrapper)


