def _v12_after_news(service: NewsService, result: Any, news_id: str, user_id: int):
    if result and result[0]:
        item = service.world.news.get(news_id, {})
        target = item.get("target_country")
        if target in PLAYABLE_COUNTRIES:
            _v12_queue_notification(service.world, target, "news")
        else:
            _v12_queue_notification(service.world, None, "news")

_v12_wrap_notification_method(NewsService, "publish", _v12_after_news)


def _v12_after_event(service: EventService, result: Any, event_id: str):
    if result and result[0]:
        item = service.world.events.get(event_id, {})
        target = item.get("target")
        if target in PLAYABLE_COUNTRIES:
            _v12_queue_notification(service.world, target, "events")
        else:
            _v12_queue_notification(service.world, None, "events")

_v12_wrap_notification_method(EventService, "apply", _v12_after_event)


                                                                               
