def _v12_game_time_from_minutes(value: float) -> str:
    minutes = max(0, int(float(value)))
    days, rem = divmod(minutes, 1440)
    hours, mins = divmod(rem, 60)
    return f"День {days + 1}, {hours:02d}:{mins:02d}"


def _v12_server_panel_text(self: WorldApp) -> str:
    state = self.world.server_state
    status = _v12_server_status(self.world)
    time_status = "▶️ идёт" if state.get("time_running", True) and not self.world.paused else "⏸️ остановлено"
    lines = [
        "🖥️ <b>ПАНЕЛЬ СЕРВЕРА</b>",
        "",
        f"Статус сервера: <b>{'🟢 работает' if status == SERVER_WORKING else '🔴 остановлен' if status == SERVER_STOPPED else '🟠 техработы'}</b>",
        f"Игровое время: <b>{game_time_text(self.world)}</b>",
        f"Состояние времени: <b>{time_status}</b>",
        f"Режим: <b>{'1 реальная минута = 1 игровая минута' if REALTIME_GAME_TIME else 'ускоренный'}</b>",
        f"Последняя отметка часов: <b>{_v12_game_time_from_minutes(state.get('last_clock_game', self.world.game_minutes))}</b>",
        f"Записей серверных часов: <b>{state.get('clock_entries', 0)}</b>",
        f"Уведомлений в очереди: <b>{len(getattr(self.world, 'notifications', []))}</b>",
    ]
    return "\n".join(lines)


