        [Keyboards.btn("🕐 Время / часы", "server:clock"), Keyboards.btn("📋 Просмотр логов", "server:logs")],
        [Keyboards.btn("🧹 Очистить логи", "server:clear_logs"), Keyboards.btn("🩺 Диагностика", "server:diagnostics")],
