async def _v12_server_panel(self: WorldApp, target: types.Message | types.CallbackQuery) -> None:
    if not self.world.is_server_admin(target.from_user.id):
        await self.show(target, "❌ Нет доступа к серверной панели.")
        return
    await self.show(target, _v12_server_panel_text(self), _v12_server_panel_keyboard())


async def _v12_server_clock_screen(self: WorldApp, target: types.CallbackQuery) -> None:
    lines = _v12_read_server_clock_tail(self, 18)
    text = (
        "🕐 <b>Серверные часы</b>\n\n"
        f"Текущее игровое время: <b>{game_time_text(self.world)}</b>\n"
        f"Последняя запись: <b>{_v12_game_time_from_minutes(self.world.server_state.get('last_clock_game', self.world.game_minutes))}</b>\n\n"
        + ("\n".join(esc(x) for x in lines) if lines else "Записей пока нет.")
    )
    await self.show(target, text, types.InlineKeyboardMarkup(inline_keyboard=[Keyboards.nav("server:panel")]))


async def _v12_server_logs_screen(self: WorldApp, target: types.CallbackQuery) -> None:
    entries = list(self.world.logs[-50:])[::-1]
    lines = [_v11_admin_log_line(x) if isinstance(x, dict) else str(x) for x in entries]
    text = "📋 <b>Логи администратора</b>\n\n" + ("\n".join(esc(x) for x in lines) if lines else "Логов пока нет.")
    await self.show(target, text, types.InlineKeyboardMarkup(inline_keyboard=[Keyboards.nav("server:panel")]))


async def _v12_server_handle(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    uid = callback.from_user.id
    if not self.world.is_server_admin(uid):
        await self.show(callback, "❌ Нет доступа к серверной панели.")
        return True
    if data == "server:panel":
        await _v12_server_panel(self, callback); return True
    if data == "server:time_pause":
        self.world.paused = True
        self.world.server_state["time_running"] = False
        self.world.mark_dirty()
        self.world.add_log("server_time_pause", uid, {})
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:time_resume":
        if self.world.server_state.get("maintenance") or not self.world.server_state.get("work_enabled", True):
            await self.show(callback, "❌ Сначала возобновите работу сервера/завершите техработы.", _v12_server_panel_keyboard()); return True
        self.world.paused = False
        self.world.server_state["time_running"] = True
        self.world.mark_dirty()
        self.world.add_log("server_time_resume", uid, {})
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:stop":
        self.world.server_state["work_enabled"] = False
        self.world.paused = True
        self.world.server_state["time_running"] = False
        self.world.mark_dirty()
        self.world.add_log("server_stop", uid, {})
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:resume":
        self.world.server_state["work_enabled"] = True
        if not self.world.server_state.get("maintenance"):
            self.world.paused = False
            self.world.server_state["time_running"] = True
        self.world.mark_dirty()
        self.world.add_log("server_resume", uid, {})
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:maintenance_on":
        self.world.server_state["maintenance"] = True
        self.world.server_state["work_enabled"] = False
        self.world.paused = True
        self.world.server_state["time_running"] = False
        self.world.mark_dirty()
        self.world.add_log("server_maintenance_on", uid, {})
        self.spawn(self._broadcast_server_maintenance(True))
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:maintenance_off":
        self.world.server_state["maintenance"] = False
        self.world.server_state["work_enabled"] = True
        self.world.paused = False
        self.world.server_state["time_running"] = True
        self.world.mark_dirty()
        self.world.add_log("server_maintenance_off", uid, {})
        self.spawn(self._broadcast_server_maintenance(False))
        await self.show(callback, _v12_server_panel_text(self), _v12_server_panel_keyboard()); return True
    if data == "server:clock":
        await _v12_server_clock_screen(self, callback); return True
    if data == "server:logs":
        await _v12_server_logs_screen(self, callback); return True
    if data == "server:clear_logs":
        self.world.logs.clear()
        self.world.mark_dirty()
        await self.show(callback, "✅ Логи администратора очищены.", _v12_server_panel_keyboard())
        return True
    if data == "server:diagnostics":
        await self.show(callback, self.test_summary(), types.InlineKeyboardMarkup(inline_keyboard=[Keyboards.nav("server:panel")]))
        return True
    if data == "server:save":
        await asyncio.to_thread(self.save_manager.save, self.world, False)
        self.world.dirty = False
        await self.show(callback, "✅ Состояние сервера сохранено.", _v12_server_panel_keyboard()); return True
    if data == "server:backup":
        await asyncio.to_thread(self.save_manager.create_backup)
        await self.show(callback, "✅ Резервная копия создана.", _v12_server_panel_keyboard()); return True
    if data == "server:restore":
        ok = await asyncio.to_thread(self.save_manager.restore)
        if ok:
            warnings = await asyncio.to_thread(self.save_manager.load, self.world)
                                                                             
            self.news.__init__(self.world)
            self.events.__init__(self.world)
            self.world.mark_dirty()
            text = "✅ Backup восстановлен." + (f"\nПредупреждения: {len(warnings)}" if warnings else "")
        else:
            text = "❌ Backup не найден."
        await self.show(callback, text, _v12_server_panel_keyboard()); return True
    if data == "server:clear_notifications":
        self.world.notifications.clear(); self.world.mark_dirty()
        self.world.add_log("server_notification_clear", uid, {})
        await self.show(callback, "✅ Очередь уведомлений очищена.", _v12_server_panel_keyboard()); return True
    if data == "server:country_message":
        rows = [[Keyboards.btn(COUNTRY_NAMES[c], f"admin:countrymsgto:{c}")] for c in PLAYABLE_COUNTRIES]
        rows += Keyboards.nav("server:panel")
        await self.show(callback, "📨 Выберите страну, которой отправить сообщение от администрации.", types.InlineKeyboardMarkup(inline_keyboard=rows)); return True
    if data == "server:logout":
        self.world.set_server_admin(uid, False)
        self.world.mark_dirty()
        await self.show(callback, "✅ Вы вышли из серверной панели.", Keyboards.home()); return True
    return False


async def _v12_broadcast_server_maintenance(self: WorldApp, enabled: bool) -> None:
    if not getattr(self, "bot", None):
        return
    text = "⚠️ Сервер временно на технических работах" if enabled else "✅ Технические работы завершены. Сервер возобновил работу."
    for uid, player in list(self.world.players.items()):
        if player.banned or player.role == "admin":
            continue
        if player.country not in PLAYABLE_COUNTRIES:
            continue
        try:
            await self.bot.send_message(int(uid), text)
        except Exception:
            continue

WorldApp._broadcast_server_maintenance = _v12_broadcast_server_maintenance


                                                                              
async def _v12_admin_country_message_text(self: WorldApp, player: Any, value: str) -> str:
    target = str(player.pending_data.get("country", ""))
    if target not in PLAYABLE_COUNTRIES:
        player.clear_input()
        return "❌ Страна не найдена."
    text_value = str(value).strip()[:4000]
    recipients = [p for p in self.world.player_for_country(target) if not p.banned]
    if not recipients:
        player.clear_input()
        return "❌ У этой страны пока нет игроков."
    recipient_ids = [int(p.user_id) for p in recipients]
    player.clear_input()
    self.world.add_log("server_country_message", player.user_id, {"country": target, "recipients": len(recipient_ids)})
    self.world.mark_dirty()
    async def send_all() -> None:
        sent = 0
        if not getattr(self, "bot", None):
            return
        for recipient_id in recipient_ids:
            try:
                await self.bot.send_message(recipient_id, "📨 <b>Сообщение от администрации</b>:\n\n" + esc(text_value), parse_mode=ParseMode.HTML)
                sent += 1
            except Exception:
                continue
    self.spawn(send_all())
    return f"✅ Сообщение поставлено в отправку игрокам страны {COUNTRY_NAMES[target]}: {len(recipient_ids)}."


                                                                               
_v12_on_text_base = WorldApp.on_text
_v12_process_text_base = WorldApp.process_text_input


async def _v12_process_text(self: WorldApp, player: Any, value: str) -> str:
    if player.pending_input == "server_code":
        expected = SERVER_CONTROL_CODE
        entered = str(value).strip()
        if entered != expected:
            self.world.add_log("server_auth_failed", player.user_id, {})
            return "❌ Неверный код серверной панели. Попробуйте ещё раз."
        self.world.set_server_admin(player.user_id, True)
        player.clear_input()
        self.world.add_log("server_auth_success", player.user_id, {})
        self.world.mark_dirty()
        return "✅ Доступ к серверной панели разрешён."
    if player.pending_input == "admin_country_message":
        return await _v12_admin_country_message_text(self, player, value)
    return await _v12_process_text_base(self, player, value)

WorldApp.process_text_input = _v12_process_text


async def _v12_on_text(self: WorldApp, message: types.Message) -> None:
    if not message.text:
        return
    user_id = message.from_user.id
    player = self.player(user_id, message.from_user.username or "")
    if player.pending_input == "server_code":
        pending = dict(player.pending_data)
        chat_id = pending.get("chat_id")
        prompt_id = pending.get("prompt_message_id")
        is_group = getattr(message.chat, "type", "private") in {"group", "supergroup"}
        if is_group:
            reply = getattr(message, "reply_to_message", None)
            if int(getattr(message.chat, "id", 0)) != int(chat_id or 0) or not reply or int(getattr(reply, "message_id", 0)) != int(prompt_id or 0):
                return
        result = await self.process_text_input(player, message.text.strip())
        if self.world.is_server_admin(user_id):
            await _v12_server_panel(self, message)
        else:
            await self.show_new(message, result)
        return
    if not _v12_server_working(self.world) and not self.world.is_server_admin(user_id):
        return
    if player.pending_input == "admin_country_message":
        try:
            async with self.screen_lock(user_id):
                result = await self.process_text_input(player, message.text.strip())
        except Exception as exc:
            self.world.add_log("ui_input_error", user_id, {"error": repr(exc)})
            result = "❌ Ошибка отправки сообщения стране."
        await self.show_new(message, result, Keyboards.simple_nav("admin:home"))
        return
    await _v12_on_text_base(self, message)

WorldApp.on_text = _v12_on_text


                                                                               
async def _v12_on_server_command(self: WorldApp, message: types.Message) -> None:
    user_id = message.from_user.id
    player = self.player(user_id, message.from_user.username or "")
    if self.world.is_server_admin(user_id):
        await _v12_server_panel(self, message)
        return
    player.pending_input = "server_code"
    player.pending_data = {
        "expires_at": time.monotonic() + 300,
        "chat_id": getattr(message.chat, "id", None),
    }
    is_group = getattr(message.chat, "type", "private") in {"group", "supergroup"}
    if is_group:
        try:
            sent = await message.answer(
                "🖥️ <b>Серверная панель</b>\n\nВведите код ответом на это сообщение:",
                reply_markup=types.ForceReply(selective=True),
                parse_mode=ParseMode.HTML,
            )
            player.pending_data["prompt_message_id"] = sent.message_id
            return
        except Exception:
            pass
    await self.show_new(message, "🖥️ <b>Серверная панель</b>\n\nВведите код доступа:")

WorldApp.on_server_command = _v12_on_server_command


                                                                             
async def _v12_admin_countrymsg(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    if not self.is_admin(callback.from_user.id):
        return False
    if data == "admin:countrymsg":
        rows = [[Keyboards.btn(COUNTRY_NAMES[c], f"admin:countrymsgto:{c}")] for c in PLAYABLE_COUNTRIES]
        rows += Keyboards.nav("admin:home")
        await self.show(callback, "📨 Выберите страну для сообщения от администрации.", types.InlineKeyboardMarkup(inline_keyboard=rows))
        return True
    if data.startswith("admin:countrymsgto:"):
        country = data.split(":", 2)[2]
        if country not in PLAYABLE_COUNTRIES:
            await self.show(callback, "❌ Страна не найдена.", Keyboards.simple_nav("admin:home")); return True
        p = self.player(callback.from_user.id)
        p.pending_input = "admin_country_message"
        p.pending_data = {"country": country, "expires_at": time.monotonic() + 600}
        await self.show(callback, f"📨 Введите сообщение для страны <b>{esc(COUNTRY_NAMES[country])}</b> одним сообщением:")
        return True
    return False


                                                                               
_v12_on_callback_base = WorldApp.on_callback


async def _v12_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    data = callback.data or ""
    uid = callback.from_user.id
                                                                                 
    if data.startswith("server:"):
        await self.answer_callback(callback)
        try:
            if await _v12_server_handle(self, callback, data):
                return
        except Exception as exc:
            self.world.add_log("callback_error", uid, {"error": repr(exc), "data": data})
            with suppress(Exception):
                await self.show(callback, "❌ Ошибка серверной панели. Ошибка записана в журнал диагностики.")
        return
                                                                                 
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid):
        await self.answer_callback(callback)
        return
                                                           
    if data.startswith("admin:countrymsg"):
        await self.answer_callback(callback)
        if await _v12_admin_countrymsg(self, callback, data):
            return
                                                                                 
    try:
        await _v12_on_callback_base(self, callback)
    except Exception as exc:
        self.world.add_log("callback_error", uid, {"error": repr(exc), "data": data})
        with suppress(Exception):
            await self.show(callback, "❌ Не удалось обработать действие. Ошибка записана в журнал диагностики.")



                                                                                
_v12_bind_base = WorldApp._bind_handlers

def _v12_bind_handlers(self: WorldApp) -> None:
                                                                 
    self.router.message.register(self.on_server_command, Command("server"))
    _v12_bind_base(self)

WorldApp._bind_handlers = _v12_bind_handlers

_v12_start_base = WorldApp.start

async def _v12_start(self: WorldApp, bot: Bot) -> None:
    self.bot = bot
    self._server_clock_task = asyncio.create_task(_v12_server_clock_loop(self), name="server-clock")
    self._notification_task = asyncio.create_task(_v12_notification_loop(self), name="world-notifications")
    try:
        await _v12_start_base(self, bot)
    finally:
        for attr in ("_server_clock_task", "_notification_task"):
            task = getattr(self, attr, None)
            if task:
                task.cancel()
                with suppress(asyncio.CancelledError):
                    await task

WorldApp.start = _v12_start


                                                                              
