_v12_army_tick_movement_base = Army.tick_movement

def _v12_army_tick_movement(self: Army, minutes: float) -> list[str]:
                                                                            
                                                                                
    for d in self.world.divisions.values():
        movement = d.get("movement")
        if not movement:
            continue
        to_pid = int(movement.get("to", -1))
        if to_pid not in self.world.provinces:
            d["movement"] = None; d["path"] = []; d["order"] = "hold"; d["target_province"] = None
            continue
        owner = self.world.province(to_pid).country
        if owner != d.get("country") and not _war_exists(self.world, d.get("country"), owner):
            d["movement"] = None; d["path"] = []; d["order"] = "hold"; d["target_province"] = None
            self.world.mark_dirty()
    return _v12_army_tick_movement_base(self, minutes)

Army.tick_movement = _v12_army_tick_movement

                                                                                
_v12_war_end_base2 = WarEngine.end_war

def _v12_war_end2(self: WarEngine, war_id: str, winner: Optional[str] = None, reason: str = ""):
    result = _v12_war_end_base2(self, war_id, winner, reason)
    if result[0]:
        war = self.world.wars.get(war_id)
        if war:
            for d in self.world.divisions.values():
                if d.get("country") not in (war.attacker, war.defender):
                    continue
                target = d.get("target_province")
                movement = d.get("movement")
                target_pid = target if target is not None else (movement or {}).get("to") if isinstance(movement, dict) else None
                if target_pid is not None and int(target_pid) in self.world.provinces:
                    owner = self.world.province(int(target_pid)).country
                    if owner != d.get("country") and not _war_exists(self.world, d.get("country"), owner):
                        d["movement"] = None; d["path"] = []; d["target_province"] = None; d["order"] = "hold"
            self.world.mark_dirty()
    return result

WarEngine.end_war = _v12_war_end2

                                                                               
