_v12_world_validate_base = WorldState.validate

def _v12_world_validate(self: WorldState) -> list[str]:
    errors = list(_v12_world_validate_base(self))
                                                                               
                                                                           
    errors = [e for e in errors if not e.startswith("capital count ")]
    for code in PLAYABLE_COUNTRIES:
        capital_id = int(SPECIAL_CAPITAL_IDS[code])
        p = self.provinces.get(capital_id)
        if p is None:
            errors.append(f"capital missing {code}")
    for did, d in self.divisions.items():
        if d.get("country") not in PLAYABLE_COUNTRIES:
            errors.append(f"division {did}: bad country")
    for wid, war in self.wars.items():
        if war.attacker not in PLAYABLE_COUNTRIES or war.defender not in PLAYABLE_COUNTRIES or war.attacker == war.defender:
            errors.append(f"war {wid}: invalid participants")
        if war.active and any(t.get("active", True) and t.get("type") == "nap" and {t.get("a"), t.get("b")} == {war.attacker, war.defender} for t in self.treaties.values()):
            errors.append(f"war {wid}: active non-aggression treaty conflict")
    return list(dict.fromkeys(errors))

WorldState.validate = _v12_world_validate

                                                                               
                                                                     
                                                                               
                                                                                
                                                                               
EXACT_MAP_GRID = [
    [1, 2, 3, 4, 5, 35, 36, 37, 68, 69],
    [6, 7, 8, 9, 10, 38, 39, 40, 70, 71],
    [11, 12, 13, 14, 15, 41, 42, 43, 72, 73],
    [16, 17, 18, 19, 20, 44, 45, 46, 74, 75],
    [21, 22, 23, 24, 25, 47, 48, 49, 76, 77],
    [26, 27, 28, 29, 30, 50, 51, 52, 78, 79],
    [31, 32, 33, 34, 80, 53, 54, 55, 81, 82],
    [56, 57, 58, 59, 60, 61, 62, 83, 84, 85],
    [63, 64, 65, 66, 67, 86, 87, 88, 89, 90],
    [91, 92, 93, 94, 95, 96, 97, 98, 99, 100],
]


def _v13_expected_neighbors() -> dict[int, list[int]]:
                                                            
    coord_to_pid: dict[tuple[int, int], int] = {}
    for r, row in enumerate(EXACT_MAP_GRID):
        for c, pid in enumerate(row):
            coord_to_pid[(r, c)] = int(pid)
    out: dict[int, list[int]] = {}
    for (r, c), pid in coord_to_pid.items():
        items: list[int] = []
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            neighbor_pid = coord_to_pid.get((r + dr, c + dc))
            if neighbor_pid is not None:
                items.append(int(neighbor_pid))
        out[pid] = sorted(items)
    return out


_V13_NEIGHBORS = _v13_expected_neighbors()


def _v13_rebuild_map_indexes(world: "WorldState") -> None:
    """Apply authoritative names/owners/city flags and the corrected graph."""
    if len(world.provinces) != MAX_PROVINCES:
        return
    for pid in range(1, MAX_PROVINCES + 1):
        p = world.provinces[pid]
        p.name = EXACT_MAP_NAMES[pid - 1]
        p.country = EXACT_COUNTRY_BY_ID[pid]
        p.neighbors = list(_V13_NEIGHBORS[pid])
        p.city = any(pid in ids for ids in EXACT_CITY_IDS.values())
        p.capital = pid in set(EXACT_CAPITAL_IDS.values())
                                                                    
        p.sea_access = False
        for row_index, row in enumerate(EXACT_MAP_GRID):
            if pid not in row:
                continue
            col_index = row.index(pid)
            p.sea_access = row_index in (0, 9) or col_index in (0, 9)
            break
    for code in PLAYABLE_COUNTRIES:
        c = world.country(code)
        c.province_ids = [pid for pid in range(1, MAX_PROVINCES + 1) if world.provinces[pid].country == code]
    world.mark_dirty()


                                                  
def _v13_make_map(self: "WorldState") -> None:
    missing = sorted(set(range(1, MAX_PROVINCES + 1)) - set(_V13_NEIGHBORS))
    if missing:
        raise RuntimeError(f"Карта: отсутствуют провинции {missing}")
    names = list(EXACT_MAP_NAMES)
    if len(names) != MAX_PROVINCES or len(set(names)) != MAX_PROVINCES:
        raise RuntimeError("Карта: нужны ровно 100 уникальных названий")
    for pid in range(1, MAX_PROVINCES + 1):
        owner = EXACT_COUNTRY_BY_ID[pid]
        p = Province(
            id=pid,
            name=names[pid - 1],
            country=owner,
            neighbors=list(_V13_NEIGHBORS[pid]),
            city=any(pid in ids for ids in EXACT_CITY_IDS.values()),
            capital=pid in set(EXACT_CAPITAL_IDS.values()),
            sea_access=any(pid in row and (r == 0 or r == 9 or row.index(pid) in (0, 9)) for r, row in enumerate(EXACT_MAP_GRID)),
            terrain="urban" if pid in set(EXACT_CAPITAL_IDS.values()) or pid in {x for ids in EXACT_CITY_IDS.values() for x in ids} else MAP_TERRAIN_BY_ROW[0],
            river=(pid % 7 == 0),
            bridge=(pid % 11 == 0),
            road_level=2 + (pid % 3),
            rail_level=2 + ((pid + 1) % 2),
        )
                                                                                    
        p.add_building("airfield", 1)
        if p.sea_access:
            p.add_building("naval_base", 1)
        self.provinces[pid] = p
        self.countries[owner].province_ids.append(pid)


WorldState._make_map = _v13_make_map

                                                                        
