_v13_production_summary_base = Production.summary


def _v13_production_summary(self: Production, country_code: str) -> dict[str, Any]:
    result = dict(_v13_production_summary_base(self, country_code))
    lines = result.get("lines", {})
    used = sum(int(v.get("factories", 0)) for v in lines.values() if isinstance(v, dict))
    result["used_factories"] = used
    result["free_factories"] = max(0, int(result.get("military_factories", 0)) - used)
    result.setdefault("military_factories", int(self.world.country(country_code).military_factories))
    result.setdefault("daily_output", {})
    result.setdefault("electricity", 1.0)
    return result


Production.summary = _v13_production_summary


                                                                               
                                                             
                                                                               
async def _v13_handle_province(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    try:
        pid = int(data.split(":", 1)[1])
    except Exception:
        await self.show(callback, "❌ Неверный номер провинции.", Keyboards.simple_nav("screen:map"))
        return
    p = self.world.provinces.get(pid)
    if p is None:
        await self.show(callback, "❌ Провинция не найдена.", Keyboards.simple_nav("screen:map"))
        return
    country, _ = self.require_country(callback.from_user.id)
    building_lines = []
    for key, level in p.buildings.items():
        lvl = int(level)
        if lvl <= 0:
            continue
        building_lines.append(
            f"{BUILDING_DISPLAY.get(key, key)} — {lvl} ур. ({p.condition_of(key):.0f}%)"
        )
    capital_label = "⭐ Столица\n" if p.capital else ""
    city_label = "🏙️ Город\n" if p.city else ""
    sea_label = "🌊 Выход к морю\n" if p.sea_access else ""
    text = (
        f"🗺️ <b>{esc(p.name)}</b> [{p.id}]\n\n"
        f"Владелец: {esc(p.owner_name())}\n"
        f"{capital_label}"
        f"{city_label}"
        f"{sea_label}"
        f"⛰️ Местность: {esc(p.terrain)}\n"
        f"🛣️ Дороги: {p.road_level} ур. ({p.road_condition:.0f}%)\n"
        f"🚆 ЖД: {p.rail_level} ур. ({p.rail_condition:.0f}%)\n"
        f"🌊 Река: {'да' if p.river else 'нет'} | 🌉 Мост: {'да' if p.bridge else 'нет'}\n"
        f"🔧 Состояние провинции: {p.condition:.0f}%\n"
        f"👷 Промышленный уровень: {p.industrial_level}\n\n"
        f"🏗️ <b>Здания</b>\n{chr(10).join(building_lines) if building_lines else 'нет'}\n\n"
        f"🪖 Дивизий: {len(p.armies)} | ✈️ Авиагрупп: {len(p.air_groups)} | "
        f"🛡️ ПВО: {len(p.pvo_units)} | ⚓ Флот: {len(p.fleets)}"
    )
    rows = []
    if country == p.country:
        rows.append([Keyboards.btn("🏗️ Строить здесь", f"build:province:{pid}")])
        rows.append([Keyboards.btn("🛠️ Ремонт здесь", f"repair:province:{pid}")])
    rows.append([Keyboards.btn("📍 Соседи", f"provneighbors:{pid}")])
    rows += Keyboards.nav("screen:map")
    await self.show(callback, text, types.InlineKeyboardMarkup(inline_keyboard=rows))


