def _v13_move_division(self: Army, division_id: str, target_pid: int, war: bool = False) -> tuple[bool, str]:
    d = self.world.divisions.get(division_id)
    if not d:
        return False, "Дивизия не найдена."
    target_pid = int(target_pid)
    if target_pid not in self.world.provinces:
        return False, "Провинция не найдена."
    target_owner = self.world.province(target_pid).country
    allow_hostile = bool(war) or _war_exists(self.world, d.get("country"), target_owner)
    return self.request_move(division_id, target_pid, allow_hostile=allow_hostile)


Army.move_division = _v13_move_division


def _v13_set_order(self: Army, division_id: str, order: str, target_pid: Optional[int] = None) -> tuple[bool, str]:
    d = self.world.divisions.get(division_id)
    if not d:
        return False, "Дивизия не найдена."
    if order not in {"attack", "advance", "hold", "stop", "defense"}:
        return False, "Неизвестный приказ."
    if target_pid is not None:
        target_pid = int(target_pid)
        if target_pid not in self.world.provinces:
            return False, "Целевая провинция не найдена."
        owner = self.world.province(target_pid).country
        if owner != d.get("country") and not _war_exists(self.world, d.get("country"), owner):
            return False, "⛔ Вход на чужую территорию возможен только во время войны."
    d["order"] = order
    d["target_province"] = target_pid
    if order in {"stop", "hold", "defense"}:
        d["movement"] = None
        d["path"] = []
    elif target_pid is not None:
        current = int(d.get("province", 0))
        if current == target_pid:
            d["movement"] = None
            d["path"] = []
        else:
            d["movement"] = None
            d["path"] = []
            if not self._start_next_step(d):
                return False, "Маршрут до цели не найден."
    self.world.mark_dirty()
    return True, f"Приказ: {ORDER_LABELS[order]}."


Army.set_order = _v13_set_order


                                                                               
                                                          
                                                                               

def _v13_active_fronts(self: WarEngine, country_code: str) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    for war in self.wars_for(country_code):
        enemy = war.opponent(country_code)
        if not enemy:
            continue
        for pid in self.world.country(country_code).province_ids:
            p = self.world.province(pid)
            enemy_provinces = [n for n in p.neighbors if self.world.province(n).country == enemy]
            if enemy_provinces:
                result.append({"province": pid, "enemy": enemy, "enemy_provinces": enemy_provinces, "war": war.id})
    return result


WarEngine.active_fronts = _v13_active_fronts

_v13_resolve_battle_base = WarEngine.resolve_battle


def _v13_resolve_battle(self: WarEngine, province_id: int, attacker_country: str, defender_country: str) -> dict[str, Any]:
    if not _war_exists(self.world, attacker_country, defender_country):
        return {"result": "no_war", "attacker": 0, "defender": 0, "captured": False, "province": int(province_id)}
    p = self.world.province(int(province_id))
    if p.country not in {attacker_country, defender_country}:
        return {"result": "invalid_front", "attacker": 0, "defender": 0, "captured": False, "province": int(province_id)}
    return _v13_resolve_battle_base(self, province_id, attacker_country, defender_country)


WarEngine.resolve_battle = _v13_resolve_battle


                                                                               
                                                                   
                                                                               
