async def _v13_handle_admin(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    parts = data.split(":")
    if data == "admin:news:skipimage":
        uid = callback.from_user.id
        if not self.is_admin(uid):
            await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker())
            return
        p = self.player(uid)
        nid = str(p.pending_data.get("news_id", ""))
        p.clear_input()
        if not self.world.news.get(nid):
            await self.show(callback, "❌ Черновик новости не найден.", Keyboards.simple_nav("admin:section:news"))
            return
        await self.render_admin_news_view(callback, nid)
        return
    if len(parts) >= 4 and parts[1] == "news" and parts[2] == "publish":
        if not self.is_admin(callback.from_user.id):
            await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker())
            return
        nid = parts[3]
        ok, reason = self.news.publish(nid, callback.from_user.id)
        if ok:
            self.spawn(self.broadcast_news(nid))
            self.spawn(self.save_light())
        await self.show(callback, ("✅ " if ok else "❌ ") + reason, Keyboards.simple_nav("admin:section:news"))
        return
    await _v13_handle_admin_base(self, callback, data)


WorldApp.handle_admin = _v13_handle_admin


                                                                               
                                                                   
                                                                               
async def _v13_render_admin_news_view(self: WorldApp, target: types.Message | types.CallbackQuery, nid: str) -> None:
    item = self.world.news.get(nid)
    if not item:
        await self.show(target, "❌ Новость не найдена.", Keyboards.simple_nav("admin:section:news"))
        return
    def get(field: str, default: Any = None) -> Any:
        return item.get(field, default) if isinstance(item, dict) else getattr(item, field, default)
    title = str(get("title", "Без названия"))
    body = str(get("text", ""))
    target_country = get("target_country")
    published = bool(get("published", False))
    image_id = get("image_file_id")
    lines = [
        f"📰 <b>{esc(title)}</b>", "", esc(body), "",
        f"Цель: {esc(COUNTRY_NAMES.get(target_country, 'Все'))}",
        f"Статус: {'✅ опубликована' if published else '📝 черновик'}",
        f"Изображение: {'есть' if image_id else 'нет'}",
    ]
    rows = []
