    rows.append([Keyboards.btn("🗑️ Удалить", f"admin:newsdelete:{nid}")])
    rows += Keyboards.nav("admin:section:news")
    await self.show(target, "\n".join(lines), types.InlineKeyboardMarkup(inline_keyboard=rows))


