async def _v13_answer_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    cache = getattr(self, "_answered_callback_ids", None)
    if cache is None:
        cache = set()
        self._answered_callback_ids = cache
    callback_id = str(getattr(callback, "id", id(callback)))
    if callback_id in cache:
        return
    cache.add(callback_id)
    if len(cache) > 1024:
                                              
        self._answered_callback_ids = set(list(cache)[-512:])
    with suppress(Exception):
        await callback.answer(cache_time=0)


WorldApp.answer_callback = _v13_answer_callback


                                                                               
                                                                    
                                                                               
