def read_token() -> str:
    direct = str(globals().get("BOT_TOKEN", "")).strip()
    if direct:
        return direct
    for name in BOT_TOKEN_ENV_NAMES:
        value = os.getenv(name, "").strip()
        if value:
            return value
    return ""


                                                                               
                                                 
                                                                               
async def _v13_pvo_bulk(self: WorldApp, callback: types.CallbackQuery, enabled: bool) -> None:
    country, error = self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback, error, Keyboards.country_picker())
        return
    changed = 0
    for unit in self.world.pvo_units.values():
        if unit.get("country") != country:
            continue
        unit["active"] = bool(enabled)
        changed += 1
    self.world.mark_dirty()
    self.spawn(self.save_light())
    await self.show(callback, "✅ Все комплексы ПВО включены." if enabled else "⏸️ Все комплексы ПВО отключены.", Keyboards.simple_nav("screen:pvo"))


