def _v13_contract_diagnostics(world: WorldState) -> dict[str, Any]:
    errors: list[str] = []
    if len(world.provinces) != 100:
        errors.append(f"Неверное число провинций: {len(world.provinces)}")
    all_ids = set(world.provinces)
    if all_ids != set(range(1, 101)):
        errors.append("ID провинций должны быть 1–100 без пропусков")
    for pid, expected in _V13_NEIGHBORS.items():
        p = world.provinces.get(pid)
        if not p or set(p.neighbors) != set(expected):
            errors.append(f"Неверные соседи провинции {pid}")
                                                 
    border_pairs = set()
    for p in world.provinces.values():
        for n in p.neighbors:
            if p.country != world.provinces[n].country:
                border_pairs.add(tuple(sorted((p.country, world.provinces[n].country))))
    expected_pairs = {
        tuple(sorted((COUNTRY_RAZBAGARE, COUNTRY_PEDAGOG))),
        tuple(sorted((COUNTRY_RAZBAGARE, COUNTRY_MARKLAND))),
        tuple(sorted((COUNTRY_PEDAGOG, COUNTRY_MARKLAND))),
    }
    for pair in expected_pairs:
        if pair not in border_pairs:
            errors.append(f"Нет общей границы: {pair}")
    for code, capital_id in EXACT_CAPITAL_IDS.items():
        if world.provinces.get(capital_id, None) is None:
            errors.append(f"Отсутствует столица {code}")
    for did, d in world.divisions.items():
        pid = int(d.get("province", -1))
        if pid not in all_ids:
            errors.append(f"Дивизия {did}: неверная провинция")
        elif did not in world.provinces[pid].armies:
            errors.append(f"Дивизия {did}: отсутствует обратная ссылка провинции")
    for wid, war in world.wars.items():
        if war.attacker == war.defender:
            errors.append(f"Война {wid}: сторона сама против себя")
        if war.active and any(
            t.get("active", True) and t.get("type") == "nap"
            and {t.get("a"), t.get("b")} == {war.attacker, war.defender}
            for t in world.treaties.values()
        ):
            errors.append(f"Война {wid}: конфликт с договором о ненападении")
    return {"ok": not errors, "errors": errors}


_v13_world_validate_base = WorldState.validate


def _v13_world_validate(self: WorldState) -> list[str]:
    errors = list(_v13_world_validate_base(self))
    extra = _v13_contract_diagnostics(self)
    errors.extend(extra.get("errors", []))
    return list(dict.fromkeys(errors))


WorldState.validate = _v13_world_validate


                                                                               
                                                  
                                                                               
                                                                            
                                                                            
                                    
