def _v13_run_contract_tests() -> list[str]:
    temp = WorldState()
    _v13_rebuild_map_indexes(temp)
    errors = temp.validate()
    result = ["V13 contract test: OK" if not errors else "V13 contract test: FAILED"]
    if errors:
        result.extend(errors[:20])
                           
    for value, expected in (("500", 500), ("10к", 10000), ("2кк", 2000000), ("1,5ккк", 1500000000)):
        got = parse_compact_number(value)
        if got != expected:
            result.append(f"number parser failed: {value} => {got}")
                                                                           
    army = Army(temp, Production(temp))
    wars = WarEngine(temp, army)
    if wars.active_wars():
        result.append("fresh world unexpectedly contains active wars")
    return result

                                                                             
                                                                     
                                                                       
                                                                              
                                                                            
                                         
                                                                             
V16_MAP_GRID = [
    [1,2,3,4,35,36,37,68,69,70],
    [5,6,7,8,38,39,40,71,72,73],
    [9,10,11,12,13,41,42,43,74,75],
    [14,15,16,17,47,44,45,46,76,77],
    [18,19,20,21,48,49,50,51,78,79],
    [22,23,24,25,52,53,54,55,80,81],
    [26,27,28,29,56,57,58,59,82,83],
    [30,31,32,33,60,61,62,63,84,85],
    [34,64,65,66,67,86,87,88,89,90],
    [91,92,93,94,95,96,97,98,99,100],
]

def _v16_neighbors_from_grid():
    pos={int(pid):(r,c) for r,row in enumerate(V16_MAP_GRID) for c,pid in enumerate(row)}
    out={int(pid):set() for pid in pos}
    for pid,(r,c) in pos.items():
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            q=pos.get((r+dr,c+dc))
            if q is not None:
                out[pid].add(q)
    return {pid:sorted(vals) for pid,vals in out.items()}

V16_NEIGHBORS=_v16_neighbors_from_grid()

                                                                             
def _v16_border_pairs_from_graph():
    pairs=set()
    for pid,p in ((int(pid),p) for pid,p in getattr(WorldState,'__dict__',{}).items() if False):
        pass
    for pid, owner in EXACT_COUNTRY_BY_ID.items():
        for n in V16_NEIGHBORS.get(pid,[]):
            o2=EXACT_COUNTRY_BY_ID.get(n)
            if o2 and o2!=owner and owner in PLAYABLE_COUNTRIES and o2 in PLAYABLE_COUNTRIES:
                pairs.add(tuple(sorted((owner,o2))))
    return pairs

V16_BORDER_PAIRS=_v16_border_pairs_from_graph()

def _v16_rebuild_map(world:WorldState):
    if set(V16_NEIGHBORS)!=set(range(1,101)):
        raise RuntimeError("V16: граф карты должен содержать все 100 провинций")
    for pid in range(1,101):
        if pid not in world.provinces:
            world.provinces[pid]=Province(id=pid,name=EXACT_MAP_NAMES[pid-1],country=EXACT_COUNTRY_BY_ID[pid])
        p=world.province(pid)
        p.id=pid
        p.name=EXACT_MAP_NAMES[pid-1]
        p.country=EXACT_COUNTRY_BY_ID[pid]
        p.neighbors=list(V16_NEIGHBORS[pid])
        p.capital=pid in EXACT_CAPITAL_IDS.values()
        p.city=any(pid in ids for ids in EXACT_CITY_IDS.values())
                                                                             
                                                
        if p.capital or p.city:
            p.terrain="urban"
        else:
                                                                          
                                       
            row=next(r for r,rowdata in enumerate(V16_MAP_GRID) if pid in rowdata)
            p.terrain=MAP_TERRAIN_BY_ROW[row]
        p.sea_access=pid in EXACT_COAST.get(p.country,set())
        p.armies=list(dict.fromkeys(p.armies))
        p.air_groups=list(dict.fromkeys(p.air_groups))
        p.pvo_units=list(dict.fromkeys(p.pvo_units))
        p.fleets=list(dict.fromkeys(getattr(p,'fleets',[])))
    for code,c in world.countries.items():
        c.province_ids=sorted(pid for pid,p in world.provinces.items() if p.country==code)
                            
    for pid,p in world.provinces.items():
        for n in p.neighbors:
            if pid not in world.province(n).neighbors:
                raise RuntimeError(f"V16: граф несимметричен {pid}<->{n}")
    if V16_BORDER_PAIRS != set(tuple(sorted(x)) for x in PLAYABLE_COUNTRIES for x in PLAYABLE_COUNTRIES if False):
        pass

_v16_world_make_map_prev=WorldState._make_map
def _v16_make_map(self:WorldState):
    _v16_world_make_map_prev(self)
    _v16_rebuild_map(self)
WorldState._make_map=_v16_make_map

