def _v16_move_duration(self:Army, division:dict[str,Any], from_pid:int, to_pid:int)->float:
                                                                      
    src=self.world.province(int(from_pid)); dst=self.world.province(int(to_pid))
    own=(src.country==division.get('country') and dst.country==division.get('country'))
    base=1440.0/90.0 if own else 1440.0/59.4
    if own:
        network_ok=(src.road_level>0 and src.road_condition>0) or (src.rail_level>0 and src.rail_condition>0)
        if not network_ok:
            return base*2.2
                                                                                        
        return base
    terrain_penalty={"plain":1.0,"forest":1.10,"hill":1.18,"urban":1.05}.get(dst.terrain,1.0)
    river_penalty=1.25 if dst.river and not dst.bridge else 1.0
    return base*terrain_penalty*river_penalty
Army._move_duration=_v16_move_duration

def _v16_request_move(self:Army,division_id:str,target_pid:int,allow_hostile:bool=False)->tuple[bool,str]:
    d=self.world.divisions.get(division_id)
    if not d: return False,"Дивизия не найдена."
    target_pid=int(target_pid)
    if target_pid not in self.world.provinces: return False,"Провинция не найдена."
    if d.get('movement'): return False,"Дивизия уже перемещается."
    start=int(d.get('province',0))
    if start==target_pid: return False,"Дивизия уже находится в этой провинции."
    owner=self.world.province(target_pid).country
    hostile=owner!=d.get('country')
    if hostile and not _war_exists(self.world,d.get('country'),owner):
        return False,"⛔ Чужая территория доступна только во время войны."
    path=_shortest_path(self.world,start,target_pid,d.get('country'),allow_hostile or hostile)
    if len(path)<2: return False,"❌ Маршрут до цели не найден."
    d['path']=list(path[1:])
    d['target_province']=target_pid
    d['order']='advance'
    if not self._start_next_step(d):
        d['path']=[]
        return False,"❌ Не удалось начать первый участок маршрута."
    self.world.mark_dirty()
    return True,f"Маршрут построен: {len(path)-1} клеток. Первое перемещение начато."
Army.request_move=_v16_request_move

def _v16_move_division(self:Army,division_id:str,target_pid:int,war:bool=False)->tuple[bool,str]:
                                                                             
    return self.request_move(division_id,int(target_pid),allow_hostile=bool(war))
Army.move_division=_v16_move_division

def _v16_set_order(self:Army,division_id:str,order:str,target:Optional[int]=None)->tuple[bool,str]:
    if division_id not in self.world.divisions: return False,"Дивизия не найдена."
    if order not in ORDER_LABELS: return False,"Неизвестный приказ."
    d=self.world.divisions[division_id]
    if order in {"stop","hold","defense"}:
        d['order']=order
        if order!='attack': d['target_province']=None
        d['movement']=None
        d['path']=[]
        self.world.mark_dirty()
        return True,f"Приказ: {ORDER_LABELS[order]}."
    if target is None:
        return False,"Для этого приказа нужна цель."
    target=int(target)
    if target not in self.world.provinces: return False,"Целевая провинция не найдена."
    hostile=self.world.province(target).country!=d['country']
    if hostile and not _war_exists(self.world,d['country'],self.world.province(target).country):
        return False,"⛔ В мирное время нельзя задавать приказ на чужую территорию."
    ok,reason=self.request_move(division_id,target,allow_hostile=hostile)
    if not ok: return False,reason
    d['order']=order
    self.world.mark_dirty()
    return True,f"Приказ: {ORDER_LABELS[order]}. {reason}"
Army.set_order=_v16_set_order

def _v16_start_next_step(self:Army,d:dict[str,Any])->bool:
    if d.get('order') not in {'attack','advance'}: return False
    target=d.get('target_province')
    if target is None or int(target) not in self.world.provinces: return False
    current=int(d.get('province',0))
    if current==int(target): return False
    path=list(d.get('path') or [])
    if not path:
        allow_hostile=_war_exists(self.world,d['country'],self.world.province(int(target)).country)
        built=_shortest_path(self.world,current,int(target),d['country'],allow_hostile)
        if len(built)<2: return False
        path=list(built[1:])
    nxt=int(path[0])
    if nxt not in self.world.province(current).neighbors: return False
    owner=self.world.province(nxt).country
    if owner!=d['country'] and not _war_exists(self.world,d['country'],owner): return False
    d['path']=path[1:]
    duration=self._move_duration(d,current,nxt)
    d['movement']={'from':current,'to':nxt,'remaining':duration,'total':duration}
    return True
Army._start_next_step=_v16_start_next_step

def _v16_tick_movement(self:Army,minutes:float)->list[str]:
    finished=[]
    self._execute_deployment_plans()
    for d in list(self.world.divisions.values()):
        remaining_minutes=max(0.0,float(minutes))
        safety=0
        while remaining_minutes>0 and safety<96:
            safety+=1
            if d.get('movement') is None:
                if not self._start_next_step(d): break
            movement=d.get('movement')
            if not movement: break
            rem=float(movement.get('remaining',0.0))
            if rem>remaining_minutes:
                movement['remaining']=rem-remaining_minutes
                remaining_minutes=0.0
                break
            remaining_minutes-=max(0.0,rem)
            target_pid=int(movement['to'])
            self._move_finish(d,target_pid)
                                                                                             
            enemy_units=[x for x in self.world.province(target_pid).armies if self.world.divisions.get(x,{}).get('country') not in (None,d.get('country'))]
            if enemy_units:
                d['movement']=None
                d['order']='attack'
                break
            if target_pid==int(d.get('target_province',-1)):
                d['movement']=None
                d['path']=[]
                d['order']='hold'
                break
            d['movement']=None
            if not self._start_next_step(d):
                d['order']='hold'
                d['target_province']=None
                d['path']=[]
                break
            if d['id'] not in finished: finished.append(d['id'])
    if finished: self.world.mark_dirty()
    return finished
Army.tick_movement=_v16_tick_movement

                                                                             
                                                                            
                                                                             
_v16_war_declare_prev=WarEngine.declare
def _v16_war_declare(self:WarEngine,attacker:str,defender:str,reason:str=""):
                                                              
    if attacker==defender: return False,"Нельзя объявить войну самому себе.",None
    if attacker not in PLAYABLE_COUNTRIES or defender not in PLAYABLE_COUNTRIES: return False,"Страна не участвует в игре.",None
    if _war_exists(self.world,attacker,defender): return False,"Эти страны уже находятся в войне.",None
    if str(reason).lower().startswith(("admin","test","system","goalid:")):
        pass
    else:
        if not _war_exists(self.world,attacker,defender):
            allowed,why=can_declare_war(self.world,attacker,defender)
            if not allowed: return False,why,None
    result=_v16_war_declare_prev(self,attacker,defender,reason)
    if result[0] and not str(reason).lower().startswith(("admin","test","system")):
        gid=re_match_goal_id(str(reason))
        if gid and gid in self.world.war_goals:
            self.world.war_goals[gid]['status']='used'
            self.world.war_goals[gid]['war_id']=result[2]
    return result
WarEngine.declare=_v16_war_declare

_v15_resolve_battle_base=WarEngine.resolve_battle

def _v16_resolve_battle(self:WarEngine,province_id:int,attacker_country:str,defender_country:str):
    if not _war_exists(self.world,attacker_country,defender_country):
        return {"result":"no_war","attacker":0,"defender":0,"captured":False,"province":int(province_id)}
    p=self.world.province(int(province_id))
                                                                                    
                                         
    if p.country!=defender_country:
        return {"result":"invalid_front","attacker":0,"defender":0,"captured":False,"province":int(province_id)}
    attackers=self.units_in_province(province_id,attacker_country)
    defenders=self.units_in_province(province_id,defender_country)
    if not attackers or not defenders:
        return {"result":"no_battle","attacker":0,"defender":0,"captured":False,"province":int(province_id)}
    return _v15_resolve_battle_base(self,province_id,attacker_country,defender_country)
WarEngine.resolve_battle=_v16_resolve_battle

                                                                             
                                                       
                                                                             
def _v16_pvo_move(self:PVO,unit_id:str,target_pid:int)->tuple[bool,str]:
    u=self.world.pvo_units.get(unit_id)
    if not u: return False,"Комплекс ПВО не найден."
    target_pid=int(target_pid)
    country=u.get('country')
    if target_pid not in self.world.provinces or self.world.province(target_pid).country!=country:
        return False,"ПВО можно перемещать только по своей территории."
    old=int(u.get('province',target_pid))
    if old in self.world.provinces and unit_id in self.world.province(old).pvo_units:
        self.world.province(old).pvo_units.remove(unit_id)
    self.world.province(target_pid).pvo_units.append(unit_id)
    u['province']=target_pid
    u['readiness']=clamp(float(u.get('readiness',100))-3)
    self.world.mark_dirty()
    return True,"Комплекс ПВО перемещён."
PVO.move_unit=_v16_pvo_move

                                                                             
                                                       
                                                                             
def _v16_air_set_route(self:Aviation,group_id:str,waypoints:list[int])->tuple[bool,str]:
    g=self.world.air_groups.get(group_id)
    if not g: return False,"Авиагруппа не найдена."
    points=[]
    for x in waypoints:
        pid=int(x)
        if pid not in self.world.provinces: return False,f"Провинция {pid} не найдена."
        if not points or points[-1]!=pid: points.append(pid)
    if not points: return False,"Маршрут пустой."
    origin=int(g.get('airfield_province',0))
    if points[0]!=origin: points.insert(0,origin)
    expanded=[points[0]]; current=points[0]; country=g.get('country')
    for waypoint in points[1:]:
        owner=self.world.province(waypoint).country
        if owner!=country and not _at_war(self.world,country,owner):
            return False,"Маршрут не может проходить через чужую территорию без войны."
        path=_shortest_path(self.world,current,waypoint,country,owner!=country)
        if len(path)<2: return False,f"Не удалось построить маршрут до {self.world.province(waypoint).name}."
        expanded.extend(path[1:]); current=waypoint
                                                     
    clean=[]
    for pid in expanded:
        if not clean or clean[-1]!=pid: clean.append(pid)
    if len(clean)>100: return False,"Маршрут слишком длинный. Выберите более близкие точки."
    g['route']=clean; g['route_index']=0; g['manual']=True
    self.world.mark_dirty()
    return True,f"Маршрут сохранён: {len(clean)} точек."
Aviation.set_route=_v16_air_set_route

                                                                             
                                                                              
                                          
                                                                             
                                                                                
                                           
_v16_answer_prev=WorldApp.answer_callback
async def _v16_answer_callback(self:WorldApp,callback:types.CallbackQuery)->None:
    key=str(getattr(callback,'id',id(callback)))
    seen=getattr(self,'_answered_callback_ids',None)
    if seen is None:
        seen=set(); self._answered_callback_ids=seen
    if key in seen: return
    seen.add(key)
    if len(seen)>5000:
                                                                         
        self._answered_callback_ids=set(list(seen)[-2500:])
    await _v16_answer_prev(self,callback)
WorldApp.answer_callback=_v16_answer_callback

async def _v16_on_callback(self:WorldApp,callback:types.CallbackQuery)->None:
    uid=callback.from_user.id
    data=callback.data or ""
    player=self.player(uid,callback.from_user.username or "")
    await self.answer_callback(callback)
    if player.banned:
        await self.show(callback,"⛔ Вы заблокированы.",Keyboards.country_picker()); return
                                                                                   
                                                                                    
                         
    if data.startswith("server:"):
        try:
            if data=="server:panel":
                await _v15_server_panel(self,callback); return
            if await _v14_server_handle(self,callback,data): return
            if await _v12_server_handle(self,callback,data): return
        except Exception as exc:
            self.world.add_log("server_callback_error",uid,{"data":data[:80],"error":repr(exc)})
            await self.show(callback,"❌ Ошибка серверной панели. Запись добавлена в журнал диагностики.",_v15_server_keyboard()); return
        await self.show(callback,"❌ Неизвестная команда серверной панели.",_v15_server_keyboard()); return
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid):
        await self.show(callback,"⛔ Сервер сейчас остановлен. Используйте /server.")
        return
    try:
                                                                          
        await _v12_on_callback_base(self,callback)
    except Exception as exc:
        self.world.add_log("callback_error",uid,{"callback":data[:80],"error":repr(exc)})
