async def _v16_broadcast_news(self:WorldApp,news_id:str)->None:
    if not getattr(self,'bot',None): return
    item=self.world.news.get(news_id)
    if not item or not item.published: return
    recipients=[]
    for uid,p in self.world.players.items():
        if p.banned or p.role=='admin': continue
        if item.target_country and p.country!=item.target_country: continue
        recipients.append(int(uid))
    for uid in recipients:
        try:
            if item.image_file_id:
                await self.bot.send_photo(uid,item.image_file_id,caption=f"📰 <b>{esc(item.title)}</b>\n\n{esc(item.text)}"[:1024],parse_mode=ParseMode.HTML)
            else:
                await self.bot.send_message(uid,f"📰 <b>{esc(item.title)}</b>\n\n{esc(item.text)}",parse_mode=ParseMode.HTML)
        except Exception:
            continue
