def _v161_rebuild_map(world:WorldState):
    _v16_rebuild_map(world)
                                                                              
                                                             
    borders=set()
    for pid,p in world.provinces.items():
        for n in p.neighbors:
            q=world.province(n)
            if p.country!=q.country and p.country in PLAYABLE_COUNTRIES and q.country in PLAYABLE_COUNTRIES:
                borders.add(tuple(sorted((p.country,q.country))))
    wanted=set(tuple(sorted((a,b))) for i,a in enumerate(PLAYABLE_COUNTRIES) for b in PLAYABLE_COUNTRIES[i+1:])
    if not wanted.issubset(borders):
        raise RuntimeError(f"V16: карта не даёт все межгосударственные границы: {wanted-borders}")

WorldState._make_map_prev_v161 = WorldState._make_map
def _v161_make_map(self:WorldState):
    WorldState._make_map_prev_v161(self)
    _v161_rebuild_map(self)
