async def _v161_on_text(self:WorldApp,message:types.Message)->None:
    if not getattr(message,"text",None): return
    uid=message.from_user.id
    p=self.player(uid,message.from_user.username or "")
    if p.pending_input=="server_code":
        pending=dict(p.pending_data or {})
        if pending.get("owner_user_id") not in (None,uid): return
        if pending.get("expires_at",0)<time.monotonic():
            p.clear_input(); await self.show_new(message,"❌ Код доступа просрочен. Введите /server снова."); return
        chat_type=getattr(getattr(message,"chat",None),"type","private")
        if chat_type in {"group","supergroup"}:
            if int(getattr(message.chat,"id",0))!=int(pending.get("chat_id",0) or 0): return
            reply=getattr(message,"reply_to_message",None)
            if not reply or int(getattr(reply,"message_id",0))!=int(pending.get("prompt_message_id",0) or 0): return
        result=await self.process_text_input(p,message.text.strip())
        if self.world.is_server_admin(uid):
            await _v15_server_panel(self,message)
        else:
            await self.show_new(message,result)
        return
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid):
        await self.show_new(message,"⛔ Сервер сейчас остановлен. Используйте /server для управления сервером."); return
    await _v161_on_text_prev(self,message)
