def _v161_start_next_step(self:Army,d:dict[str,Any])->bool:
    if d.get('order') not in {'attack','advance'}: return False
    target=d.get('target_province')
    if target is None or int(target) not in self.world.provinces: return False
    current=int(d.get('province',0))
    if current==int(target): return False
    path=list(d.get('path') or [])
    if not path:
        owner=self.world.province(int(target)).country
        allow=_war_exists(self.world,d['country'],owner)
        full=_shortest_path(self.world,current,int(target),d['country'],allow)
        if len(full)<2: return False
        path=list(full[1:])
    nxt=int(path[0])
    if nxt not in self.world.province(current).neighbors: return False
    owner=self.world.province(nxt).country
    if owner!=d['country'] and not _war_exists(self.world,d['country'],owner): return False
    d['path']=path[1:]
    duration=self._move_duration(d,current,nxt)
    d['movement']={'from':current,'to':nxt,'remaining':duration,'total':duration}
    return True
Army._start_next_step=_v161_start_next_step

def _v161_tick_movement(self:Army,minutes:float)->list[str]:
    finished=[]; self._execute_deployment_plans()
    for d in list(self.world.divisions.values()):
        budget=max(0.0,float(minutes)); guard=0
        while budget>0 and guard<100:
            guard+=1
            if d.get('movement') is None and not self._start_next_step(d): break
            m=d.get('movement')
            if not m: break
            rem=float(m.get('remaining',0.0))
            if rem>budget:
                m['remaining']=rem-budget; budget=0; break
            budget-=max(rem,0.0)
            target_pid=int(m['to']); self._move_finish(d,target_pid)
            enemy=[x for x in self.world.province(target_pid).armies if self.world.divisions.get(x,{}).get('country') not in (None,d.get('country'))]
            if enemy:
                d['movement']=None; d['order']='attack'; break
            if target_pid==int(d.get('target_province',-1)):
                d['movement']=None; d['path']=[]; d['order']='hold'; break
            d['movement']=None
            if not self._start_next_step(d):
                d['path']=[]; d['target_province']=None; d['order']='hold'; break
            if d['id'] not in finished: finished.append(d['id'])
    if finished: self.world.mark_dirty()
    return finished
Army.tick_movement=_v161_tick_movement

