Army.move_division=_v161_move_division

                                                                             
                                                                               
                                                                             
_v161_resolve_war_prev=WarEngine.resolve_battle
def _v161_resolve_battle(self:WarEngine,province_id:int,attacker_country:str,defender_country:str):
    if not _war_exists(self.world,attacker_country,defender_country):
        return {"result":"no_war","attacker":0,"defender":0,"captured":False,"province":int(province_id)}
    p=self.world.province(int(province_id))
    if p.country!=defender_country:
        return {"result":"invalid_front","attacker":0,"defender":0,"captured":False,"province":int(province_id)}
    attackers=self.units_in_province(p.id,attacker_country); defenders=self.units_in_province(p.id,defender_country)
    if not attackers or not defenders:
        return {"result":"no_battle","attacker":0,"defender":0,"captured":False,"province":p.id}
                                                                                   
                                                                   
    valid=False
    for d in attackers:
        lf=d.get('last_from_province')
        if lf in p.neighbors and self.world.province(int(lf)).country==attacker_country:
            valid=True; break
                                                                                  
                                                                            
        if any(self.world.province(n).country==attacker_country for n in p.neighbors):
            valid=True; break
    if not valid:
        return {"result":"invalid_front","attacker":0,"defender":0,"captured":False,"province":p.id}
    return _v161_resolve_war_prev(self,p.id,attacker_country,defender_country)
WarEngine.resolve_battle=_v161_resolve_battle

                                                                                
