Army._move_finish=_v161_move_finish

                                                                             
                                                            
                                                                             
def _v161_move_pvo(self:PVO,unit_id:str,target_pid:int)->tuple[bool,str]:
    u=self.world.pvo_units.get(unit_id)
    if not u: return False,"Комплекс ПВО не найден."
    target_pid=int(target_pid); country=u.get('country')
    if target_pid not in self.world.provinces or self.world.province(target_pid).country!=country:
        return False,"ПВО можно перемещать только по своей территории."
    old=int(u.get('province',target_pid))
    if old in self.world.provinces and unit_id in self.world.province(old).pvo_units:
        self.world.province(old).pvo_units.remove(unit_id)
    if unit_id not in self.world.province(target_pid).pvo_units:
        self.world.province(target_pid).pvo_units.append(unit_id)
    u['province']=target_pid; u['readiness']=clamp(float(u.get('readiness',100))-2)
    self.world.mark_dirty(); return True,"Комплекс ПВО перемещён."
PVO.move_unit=_v161_move_pvo
PVO.move=_v161_move_pvo

                                                                             
                                                                                  
                                                                             
_v161_sim_prev=SimulationEngine._run
async def _v161_sim_run(self:SimulationEngine)->None:
    while not self._stop.is_set():
        loop_start=time.monotonic(); real_delta=max(0.0,min(loop_start-self.last_loop_real,2.0)); self.last_loop_real=loop_start
        self.save_accum_real+=real_delta
        try:
            async with self.app.world.simulation_lock:
                self.app.world.speed=1.0
                state=getattr(self.app.world,'server_state',{})
                can_run=bool(state.get('work_enabled',True)) and not bool(state.get('maintenance',False))
                if can_run and not self.app.world.paused and REALTIME_GAME_TIME and real_delta>0:
                    self.advance(real_delta/60.0)
                if self.save_accum_real>=AUTOSAVE_REAL_SECONDS and self.app.world.settings.get('autosave_enabled',True) and self.app.world.dirty:
                    await asyncio.to_thread(self.app.save_manager.save,self.app.world,True); self.app.world.dirty=False; self.save_accum_real=0.0
        except asyncio.CancelledError: raise
        except Exception as exc: self.app.world.add_log('simulation_error',None,{'error':repr(exc)})
        await asyncio.sleep(1.0)
SimulationEngine._run=_v161_sim_run

                                                                             
                                                                           
                                                                             
