def v16_regression_test()->list[str]:
    errors=[]
    w=WorldState(); _v161_rebuild_map(w)
    if len(w.provinces)!=100: errors.append('100 провинций')
    if [w.province(x).name for x in (19,51,81)]!=['Йцукен','шышка','StarkIndustrialist']: errors.append('названия столиц')
    expected_cities={COUNTRY_RAZBAGARE:{4,9,14},COUNTRY_PEDAGOG:{39,44,50,59},COUNTRY_MARKLAND:{70,75,79,89}}
    for c,ids in expected_cities.items():
        got={p.id for p in w.provinces.values() if p.country==c and p.city}
        if got!=ids: errors.append(f'города {c}: {got} != {ids}')
    for pid,p in w.provinces.items():
        for n in p.neighbors:
            if pid not in w.province(n).neighbors: errors.append(f'граф {pid}<->{n}')
    prod=Production(w); army=Army(w,prod); wars=WarEngine(w,army); c=w.country(COUNTRY_RAZBAGARE)
    c.warehouse={k:0 for k in EQUIPMENT_KEYS}; mp0=c.manpower
    ok,_,did=army.create_division(COUNTRY_RAZBAGARE,'infantry',19)
    if ok or did or c.manpower!=mp0: errors.append('дивизия без техники')
    c.infinite_weapons=True
    ok,_,did=army.create_division(COUNTRY_RAZBAGARE,'infantry',19)
    if not ok: errors.append('создание дивизии с infinite')
    else:
        target=20
        ok,_=army.move_division(did,target,war=True)
        if not ok or int(w.divisions[did]['province'])!=19: errors.append('телепорт армии')
        army.tick_movement(16.0)
        if int(w.divisions[did]['province'])!=20: errors.append('армия не завершила перемещение')
    if wars.declare(COUNTRY_RAZBAGARE,COUNTRY_PEDAGOG,'direct')[0]: errors.append('война без цели')
    gid=w.next_entity_id('goal'); w.war_goals[gid]={'id':gid,'creator':COUNTRY_RAZBAGARE,'target':COUNTRY_PEDAGOG,'status':'prepared'}
    ok,_,wid=wars.declare(COUNTRY_RAZBAGARE,COUNTRY_PEDAGOG,f'goalid:{gid}')
    if not ok or wid is None or w.war_goals[gid].get('status')!='used': errors.append('цель войны')
         
    c.warehouse['pvo_medium']=5; pvo=PVO(w,prod); ok,_,puid=pvo.deploy(COUNTRY_RAZBAGARE,'pvo_medium',1,19)
    if not ok or not pvo.move_unit(puid,20)[0] or not pvo.set_mode(puid,'priority')[0] or not pvo.set_priority(puid,'high')[0] or not pvo.set_active(puid,False)[0]: errors.append('ПВО controls')
               
    c.warehouse['fighter']=500; av=Aviation(w,prod); ok,_,aid=av.create_group(COUNTRY_RAZBAGARE,'fighter',500,19)
    if not ok or not av.set_route(aid,[20,22])[0]: errors.append('авиа маршрут')
    return ['V16 REGRESSION: OK'] if not errors else ['V16 REGRESSION: FAILED',*sorted(set(errors))]

                                                                                       
