async def _v17_answer_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    answered = getattr(callback, "_ws_answered", False)
    if answered:
        return
    try:
        await callback.answer(cache_time=0)
    except Exception:
        pass
    try:
        setattr(callback, "_ws_answered", True)
    except Exception:
        pass
WorldApp.answer_callback = _v17_answer_callback

                                                                                                           
async def _v17_show(self: WorldApp, target, text: str, markup=None, *, parse_mode=ParseMode.HTML) -> None:
    if isinstance(target, types.CallbackQuery):
        message = target.message
        uid = target.from_user.id
    else:
        message = target
        uid = target.from_user.id
    if message is None:
        return
    text = text[:4096]
    async def _edit_or_send():
        try:
            await message.edit_text(text, reply_markup=markup, parse_mode=parse_mode, disable_web_page_preview=True)
            return
        except TelegramBadRequest as exc:
            if "message is not modified" in str(exc).lower():
                return
            sent = await message.answer(text, reply_markup=markup, parse_mode=parse_mode, disable_web_page_preview=True)
            self.player(uid).current_message_id = getattr(sent, "message_id", 0)
        except TelegramForbiddenError:
            return
    try:
        await asyncio.wait_for(_edit_or_send(), timeout=6.0)
    except (asyncio.TimeoutError, TelegramForbiddenError):
        self.world.add_log("ui_timeout", uid, {"screen": self.player(uid).current_screen})
    except Exception as exc:
        self.world.add_log("ui_error", uid, {"error": repr(exc)[:300]})

                                                                                 
async def _v17_process_time_skip(self: WorldApp, minutes: float) -> None:
    remaining = max(0.0, float(minutes))
    if remaining <= 0:
        return
    was_paused = self.world.paused
    self.world.paused = False
    try:
        while remaining > 0:
            step = min(30.0, remaining)
            async with self.world.simulation_lock:
                self.simulation.advance(step, True)
            remaining -= step
            await asyncio.sleep(0)
    finally:
        self.world.paused = was_paused
    await self.save_light()
WorldApp.process_time_skip = _v17_process_time_skip

                                                                                             
def _v17_air_create_group(self: Aviation, country_code: str, model_key: str, quantity: int, province_id: int):
    quantity=int(quantity)
    ok, reason = self._stock_before_airfield(country_code, model_key, quantity)
    if not ok:
        return False, reason, None
    province_id=int(province_id)
    if province_id not in self.airfields(country_code):
        return False, "На этой провинции нет рабочего аэродрома.", None
    if not self.world.country(country_code).infinite_weapons:
        self.production.consume(country_code, model_key, quantity)
    model=AIR_MODELS.get(model_key) or UAV_MODELS.get(model_key)
    gid=self.world.next_entity_id("air")
    self.world.air_groups[gid]={"id":gid,"name":f"Авиагруппа {gid}","country":country_code,"model":model_key,"quantity":quantity,"airfield_province":province_id,"readiness":100.0,"condition":100.0,"mission":"stop","target_country":None,"target_province":None,"manual":False,"route":[],"route_index":0,"created_at":self.world.game_minutes,"strength":float(model.strength)}
    self.world.province(province_id).air_groups.append(gid)
    self.world.mark_dirty(); self.world.add_log("air_group_created",None,{"country":country_code,"group":gid,"model":model_key,"quantity":quantity})
    return True, f"Создана авиагруппа: {model.name} × {quantity}.", gid
Aviation.create_group = _v17_air_create_group

def _v17_air_rebase(self: Aviation, group_id: str, province_id: int):
    g=self.world.air_groups.get(group_id)
    if not g: return False,"Авиагруппа не найдена."
    province_id=int(province_id)
    if province_id not in self.airfields(g["country"]): return False,"Это не ваш рабочий аэродром."
    old=int(g.get("airfield_province",province_id))
    if old in self.world.provinces and group_id in self.world.province(old).air_groups:
        self.world.province(old).air_groups.remove(group_id)
    g["airfield_province"]=province_id
    if group_id not in self.world.province(province_id).air_groups: self.world.province(province_id).air_groups.append(group_id)
    g["readiness"]=clamp(float(g.get("readiness",100))-2)
    self.world.mark_dirty(); return True,"Авиагруппа перебазирована."
Aviation.rebase = _v17_air_rebase

                                     

