def _v17_rebuild_map(world: WorldState):
    pos={int(pid):(r,c) for r,row in enumerate(EXACT_MAP_GRID) for c,pid in enumerate(row)}
    by_pos={(r,c):int(pid) for pid,(r,c) in pos.items()}
    if set(pos)!=set(range(1,101)): raise RuntimeError("Карта должна содержать ровно 100 провинций")
    for pid in range(1,101):
        p=world.province(pid)
        p.name=EXACT_MAP_NAMES[pid-1]
        p.country=EXACT_COUNTRY_BY_ID[pid]
        r,c=pos[pid]
        p.neighbors=[by_pos[(r+dr,c+dc)] for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)) if (r+dr,c+dc) in by_pos]
        p.capital=pid in set(EXACT_CAPITAL_IDS.values())
        p.city=pid in {x for v in EXACT_CITY_IDS.values() for x in v}
        p.terrain="urban" if p.capital or p.city else ("forest" if (r+c)%5==0 else "hill" if (r*3+c)%7==0 else "plain")
        p.sea_access=pid in EXACT_COAST.get(p.country,set())
    for code in PLAYABLE_COUNTRIES:
        world.country(code).province_ids=sorted(pid for pid,p in world.provinces.items() if p.country==code)
def _v17_make_map_final(self: WorldState):
    self.provinces = {}
    for code in PLAYABLE_COUNTRIES:
        self.countries[code].province_ids = []
    positions = {int(pid):(r,c) for r,row in enumerate(EXACT_MAP_GRID) for c,pid in enumerate(row)}
    by_pos = {(r,c): int(pid) for pid,(r,c) in positions.items()}
    for pid in range(1,101):
        r,c=positions[pid]
        owner=EXACT_COUNTRY_BY_ID[pid]
        p=Province(
            id=pid, name=EXACT_MAP_NAMES[pid-1], country=owner,
            neighbors=[], city=pid in {x for ids in EXACT_CITY_IDS.values() for x in ids},
            capital=pid in set(EXACT_CAPITAL_IDS.values()),
            sea_access=pid in EXACT_COAST.get(owner,set()),
            terrain="urban" if pid in set(EXACT_CAPITAL_IDS.values()) or pid in {x for ids in EXACT_CITY_IDS.values() for x in ids} else ("forest" if (r+c)%5==0 else "hill" if (r*3+c)%7==0 else "plain"),
            river=(pid%7==0), bridge=(pid%11==0), road_level=2+(pid%3), rail_level=1+((pid+1)%3), industrial_level=1,
        )
        p.neighbors=[by_pos[(rr,cc)] for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if (rr,cc) in by_pos]
        p.buildings={k:0 for k in ("civ_factory","mil_factory","mine","npz","metallurgy","oilwell","oil_processing","components","power","substation","airfield","naval_base","fort","radar","business")}
        p.building_condition={k:100.0 for k in p.buildings}
        self.provinces[pid]=p
        self.countries[owner].province_ids.append(pid)
                                                                                              
    for code in PLAYABLE_COUNTRIES:
        cap=EXACT_CAPITAL_IDS[code]
        self.provinces[cap].add_building("airfield",1)
        border=next((pid for pid in self.countries[code].province_ids if pid!=cap and any(self.provinces[n].country!=code for n in self.provinces[pid].neighbors)),None)
        if border is not None: self.provinces[border].add_building("airfield",1)
        coast=next((pid for pid in self.countries[code].province_ids if self.provinces[pid].sea_access),None)
        if coast is not None: self.provinces[coast].add_building("naval_base",1)


                                                                                   
                                                                         
def _v17_tick_movement(self: Army, minutes: float) -> list[str]:
    finished=[]
    for d in list(self.world.divisions.values()):
        budget=max(0.0,float(minutes)); guard=0
        while budget>0 and guard<128:
            guard+=1
            if d.get("movement") is None:
                if not self._start_next_step(d): break
            m=d.get("movement")
            if not m: break
            rem=float(m.get("remaining",0.0))
            if rem>budget:
                m["remaining"]=rem-budget; budget=0.0; break
            budget-=max(rem,0.0)
            target=int(m["to"])
            self._move_finish(d,target)
            enemies=[x for x in self.world.province(target).armies if self.world.divisions.get(x,{}).get("country") not in (None,d.get("country"))]
            d["movement"]=None
            if enemies:
                d["order"]="attack"
                break
            if target==int(d.get("target_province",-1)):
                d["path"]=[]; d["target_province"]=None; d["order"]="hold"
                break
            if not self._start_next_step(d):
                d["path"]=[]; d["target_province"]=None; d["order"]="hold"
                break
            if d["id"] not in finished: finished.append(d["id"])
    if finished: self.world.mark_dirty()
    return finished
Army.tick_movement=_v17_tick_movement

WorldState._make_map = _v17_make_map_final

