def v17_regression_test():
    errors=[]; w=WorldState(); _v17_rebuild_map(w)
    if len(w.provinces)!=100: errors.append("100 провинций")
    if len({p.name for p in w.provinces.values()})!=100: errors.append("уникальные названия")
    for code,pid in EXACT_CAPITAL_IDS.items():
        if w.province(pid).country!=code or not w.province(pid).capital: errors.append(f"столица {code}")
    for code,city_ids in EXACT_CITY_IDS.items():
        if {p.id for p in w.provinces.values() if p.city and p.country==code}!=set(city_ids): errors.append(f"города {code}")
    for pid,p in w.provinces.items():
        for n in p.neighbors:
            if pid not in w.province(n).neighbors: errors.append(f"граф {pid}<->{n}")
    for a,b in ((PLAYABLE_COUNTRIES[i],PLAYABLE_COUNTRIES[j]) for i in range(3) for j in range(i+1,3)):
        if not w.country_share_border(a,b): errors.append(f"граница {a}-{b}")
    prod=Production(w); army=Army(w,prod); wars=WarEngine(w,army); c=w.country(COUNTRY_RAZBAGARE)
    c.warehouse={k:0 for k in EQUIPMENT_KEYS}; mp=c.manpower
    ok,_,did=army.create_division(COUNTRY_RAZBAGARE,'infantry',EXACT_CAPITAL_IDS[COUNTRY_RAZBAGARE])
    if ok or did or c.manpower!=mp: errors.append("дивизия без техники")
    c.infinite_weapons=True
    ok,_,did=army.create_division(COUNTRY_RAZBAGARE,'infantry',EXACT_CAPITAL_IDS[COUNTRY_RAZBAGARE])
    if not ok: errors.append("дивизия infinite")
    if did:
        target=20; old=int(w.divisions[did]["province"])
        ok,_=army.move_division(did,target,war=True)
        if not ok or int(w.divisions[did]["province"])!=old: errors.append("телепорт армии")
        army.tick_movement(1000)
        if int(w.divisions[did]["province"])==old: errors.append("движение")
    ok,_,wid=wars.declare(COUNTRY_RAZBAGARE,COUNTRY_PEDAGOG,"system test")
    if not ok or not wid: errors.append("системная война")
    av=Aviation(w,prod); c.warehouse["fighter"]=1000
    ok,_,gid=av.create_group(COUNTRY_RAZBAGARE,"fighter",500,EXACT_CAPITAL_IDS[COUNTRY_RAZBAGARE])
    if not ok or not gid: errors.append("авиа без лимита")
    elif not av.rebase(gid,EXACT_CAPITAL_IDS[COUNTRY_RAZBAGARE])[0]: errors.append("авиа перебазирование")
    pvo=PVO(w,prod); c.warehouse["pvo"]=10
    ok,_,uid=pvo.deploy(COUNTRY_RAZBAGARE,"pvo",1,EXACT_CAPITAL_IDS[COUNTRY_RAZBAGARE])
    if not ok or not uid or not pvo.set_mode(uid,"priority")[0] or not pvo.set_priority(uid,"high")[0] or not pvo.set_active(uid,False)[0]: errors.append("ПВО управление")
    return ["V18 CORE REGRESSION: OK"] if not errors else ["V18 CORE REGRESSION: FAILED",*sorted(set(errors))]

v16_regression_test = v17_regression_test

def v18_balance_regression_test():
    errors=[]; w=WorldState()
    for code in PLAYABLE_COUNTRIES:
        c=w.country(code)
        expected={"civilian_factories":102,"military_factories":408,"income_daily":38_000_000,"stability":60.0,"budget":13_000_000_000,"power_plants":4,"substation_capacity":204}
        for field,value in expected.items():
            if getattr(c,field)!=value: errors.append(f"{code}: {field}={getattr(c,field)}")
        for key,value in (("mine",6),("npz",4),("metallurgy",2),("oil_processing",1),("oilwell",4),("components",2),("power",4),("substation",204),("civ_factory",102),("mil_factory",408)):
            got=building_count(w,code,key)
            if got!=value: errors.append(f"{code}: {key}={got}, expected {value}")
    errors.extend(Production(w).validate_catalog())
    required=("sp_artillery","mlrs","modern_tank","recon_uav","aa_gun","corvette","submarine")
    for key in required:
        if key not in EQUIPMENT_KEYS or key not in PRODUCTION_CATALOG: errors.append(f"missing equipment {key}")
    return ["V18 BALANCE: OK"] if not errors else ["V18 BALANCE: FAILED",*sorted(set(errors))]

                                                                             
                        
                                                                             
                                                                                    
                                                                           
                                                                             

