def _v18_seed_balanced_industry(self: WorldState) -> None:
    for code in PLAYABLE_COUNTRIES:
        ids = list(self.country(code).province_ids)
        special = [pid for pid in ids if self.province(pid).capital or self.province(pid).city]
                                                                               
        for pid in ids:
            p = self.province(pid)
            for key in ("civ_factory", "mil_factory", "power", "substation", "mine", "npz", "metallurgy", "oilwell", "oil_processing", "components", "business"):
                p.buildings[key] = 0
                p.building_condition[key] = 100.0
                                                                 
        target_civ = int(self.country(code).civilian_factories)
        target_mil = int(self.country(code).military_factories)
        target_power = int(self.country(code).power_plants)
        target_sub = int(self.country(code).substation_capacity)

                                                                                          
        for pid in ids:
            self.province(pid).add_building("civ_factory", 2)
            self.province(pid).add_building("mil_factory", 8)
        civ_now = 2 * len(ids)
        mil_now = 8 * len(ids)
                                                                 
        for pid in special:
            if civ_now < target_civ:
                self.province(pid).add_building("civ_factory", 1); civ_now += 1
            if civ_now < target_civ:
                self.province(pid).add_building("civ_factory", 1); civ_now += 1
            if mil_now < target_mil:
                self.province(pid).add_building("mil_factory", 2); mil_now += 2
            if mil_now < target_mil:
                self.province(pid).add_building("mil_factory", 2); mil_now += 2
                                                                                   
        cursor = 0
        while civ_now < target_civ:
            pid = ids[cursor % len(ids)]; self.province(pid).add_building("civ_factory", 1); civ_now += 1; cursor += 1
        cursor = 0
        while mil_now < target_mil:
            pid = ids[cursor % len(ids)]; self.province(pid).add_building("mil_factory", 1); mil_now += 1; cursor += 1

                                                                   
        for key, count in (("mine", 6), ("npz", 4), ("metallurgy", 2), ("oilwell", 4), ("oil_processing", 1), ("components", 2)):
            for pid in ids[:count]: self.province(pid).add_building(key, 1)
                                                                               
        for pid in ids[:target_power]: self.province(pid).add_building("power", 1)
        for i in range(target_sub): self.province(ids[i % len(ids)]).add_building("substation", 1)

        self.country(code).business_centers = 0
        self.country(code).power_plants = target_power
        self.country(code).power_capacity = target_power
        self.country(code).substations = target_sub
        self.country(code).substation_capacity = target_sub

