async def _v18_render_decisions(self: WorldApp, target: types.Message | types.CallbackQuery, page: int = 0) -> None:
    country, error = self.require_country(target.from_user.id)
    if not country:
        await self.show(target, error, Keyboards.country_picker()); return
    c = self.world.country(country)
    active = [x for x in c.active_decisions.values() if not x.get("finished")]
    available = self.decisions.available(country)
    grouped = []
    for cat_key, cat_name in DECISION_CATEGORIES.items():
        count = sum(1 for d in available if d.category == cat_key)
        active_count = sum(1 for x in active if DECISIONS.get(x.get("key"), DecisionDef("","","","",0,0,{})).category == cat_key)
        grouped.append((cat_key, cat_name, count, active_count))
    rows=[]
    for key,label,count,active_count in grouped:
        rows.append([Keyboards.btn(f"{label}  [{count}/{active_count}]", f"decisioncat:{key}")])
    rows.append([Keyboards.btn("✅ Активные решения", "decision:active")])
    rows += Keyboards.nav("home")
    text=("📜 <b>РЕШЕНИЯ</b>\n\n"
          f"💰 Бюджет: <b>{format_money(c.budget)}</b>\n"
          f"📌 Активно: <b>{len(active)}</b>\n"
          "\nВыберите направление. Решения стоят денег и имеют срок действия.")
    await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))

async def _v18_handle_decision(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    country,error=self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback,error,Keyboards.country_picker()); return
    if data.startswith("decisioncat:"):
        cat=data.split(":",1)[1]
        items=[d for d in DECISIONS.values() if d.category==cat]
        rows=[[Keyboards.btn(f"{d.title} — {format_money(d.cost)}",f"decision:view:{d.key}")] for d in items]
        rows += Keyboards.nav("screen:decisions")
        await self.show(callback,f"📜 <b>{esc(DECISION_CATEGORIES.get(cat,cat))}</b>\n\nВыберите решение:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data=="decision:active":
        c=self.world.country(country); active=[x for x in c.active_decisions.values() if not x.get("finished")]
        if not active:
            text="📜 <b>АКТИВНЫЕ РЕШЕНИЯ</b>\n\nНет активных решений."
        else:
            lines=[]
            for x in active:
                mins=float(x.get("remaining_minutes",0)); days=mins/1440.0
                lines.append(f"• <b>{esc(x.get('title',x.get('key','—')))}</b> — осталось {days:.1f} дн.")
            text="📜 <b>АКТИВНЫЕ РЕШЕНИЯ</b>\n\n"+"\n".join(lines)
        await self.show(callback,text,Keyboards.simple_nav("screen:decisions")); return
    if data.startswith("decision:view:"):
        key=data.split(":",2)[2]; d=DECISIONS.get(key)
        if not d: await self.show(callback,"❌ Решение не найдено.",Keyboards.simple_nav("screen:decisions")); return
        c=self.world.country(country); active=c.active_decisions.get(key); can=c.budget>=d.cost and not (active and not active.get("finished"))
        effect_lines=[]
        for k,v in d.effects.items(): effect_lines.append(f"• {k}: {v:+g}")
        text=(f"📜 <b>{esc(d.title)}</b>\n\n"
              f"{esc(d.description)}\n\n"
              f"💰 Стоимость: <b>{format_money(d.cost)}</b>\n"
              f"⏱️ Длительность: <b>{d.duration_days:g} дн.</b>\n"
              f"📊 Эффекты:\n"+"\n".join(effect_lines)+"\n\n"
              f"{'🟢 Можно принять' if can else '🔴 Сейчас недоступно'}")
        rows=[]
        if can: rows.append([Keyboards.btn("✅ Принять решение",f"decision:take:{key}")])
        rows += Keyboards.nav("screen:decisions")
        await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("decision:take:"):
        key=data.split(":",2)[2]; ok,reason=self.decisions.start(country,key); self.spawn(self.save_light())
        await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("screen:decisions")); return
    await self.render_decisions(callback,0)

WorldApp.render_decisions = _v18_render_decisions
WorldApp.handle_decision = _v18_handle_decision

                                                                                 
async def _v18_render_journal(self: WorldApp, target: types.Message | types.CallbackQuery, category: str, page: int) -> None:
    country,error=self.require_country(target.from_user.id)
    if not country:
        await self.show(target,error,Keyboards.country_picker()); return
    entries=[]
    for item in self.world.journal:
        if item.get("country") not in (None,country): continue
        cat=item.get("category","all")
        if category!="all" and cat!=category: continue
        entries.append(item)
    entries=entries[-150:][::-1]
    chunk,page,total=page_slice(entries,page)
    icons={"news":"📰","wars":"⚔️","army":"🪖","aviation":"✈️","pvo":"🛡️","navy":"⚓","production":"🏭","economy":"💰","diplomacy":"🤝","trade":"🚛","decisions":"📜","construction":"🏗️","repair":"🛠️","events":"🎉"}
    lines=[]
    for e in chunk:
        cat=e.get("category","event"); icon=icons.get(cat,"📌"); mins=float(e.get("time",0)); day=int(mins//1440)+1; hh=int((mins%1440)//60); mm=int(mins%60)
        lines.append(f"{icon} <b>{esc(e.get('title','Событие'))}</b>  <i>День {day}, {hh:02d}:{mm:02d}</i>\n{esc(e.get('text',''))}")
    cats=[("all","📚 Все"),("wars","⚔️ Войны"),("army","🪖 Армия"),("production","🏭 Производство"),("construction","🏗️ Стройки"),("economy","💰 Экономика"),("decisions","📜 Решения"),("diplomacy","🤝 Дипломатия"),("trade","🚛 Торговля"),("aviation","✈️ Авиация"),("pvo","🛡️ ПВО"),("navy","⚓ Флот"),("news","📰 Новости"),("events","🎉 События"),("repair","🛠️ Ремонт")]
    rows=[]
    for i in range(0,len(cats),2): rows.append([Keyboards.btn(cats[i][1],f"journalcat:{cats[i][0]}:0")]+([Keyboards.btn(cats[i+1][1],f"journalcat:{cats[i+1][0]}:0")] if i+1<len(cats) else []))
    rows.append(Keyboards.pagination(f"journalpage:{category}",page,total)); rows += Keyboards.nav("home")
    counts={k:0 for k,_ in cats}
    for e in self.world.journal:
        if e.get("country") in (None,country): counts[e.get("category","all")]=counts.get(e.get("category","all"),0)+1
    text=("📖 <b>ЖУРНАЛ</b>\n\n"
          f"Записей: <b>{counts.get('all',0) if counts.get('all',0) else sum(1 for e in self.world.journal if e.get('country') in (None,country))}</b>\n"
          f"Текущий фильтр: <b>{dict(cats).get(category,'Все')}</b>\n\n"+ ("\n\n".join(lines) if lines else "Записей по этому фильтру пока нет."))
    await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))

