async def _v18_render_production(self: WorldApp, target: types.Message | types.CallbackQuery, page: int = 0) -> None:
    country,error=self.require_country(target.from_user.id)
    if not country:
        await self.show(target,error,Keyboards.country_picker()); return
    summary=self.production.summary(country)
    c=self.world.country(country)
    rows=[]
    categories=list(PRODUCTION_CATEGORIES.items())
    chunk,page,total=page_slice(categories,page)
    for key,label in chunk: rows.append([Keyboards.btn(label,f"prodcat:{key}")])
    rows.append(Keyboards.pagination("prodpage",page,total)); rows += Keyboards.nav("home")
    text=("🏭 <b>ПРОИЗВОДСТВО</b>\n\n"
          f"ВЗ: <b>{c.military_factories}</b> | Занято: <b>{summary['used_factories']}</b> | Свободно: <b>{summary['free_factories']}</b>\n"
          f"Эффективность промышленности: <b>{operational_industry(self.world,country)*100:.0f}%</b>\n"
          f"Топливо: <b>{format_number(c.resources.get('fuel',0))}</b>\n\nВыберите категорию техники:")
    await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))
