async def main() -> None:
    """Create the Telegram bot, initialize the app and start polling.

    This function is intentionally kept separate from ``WorldApp.start`` so
    the file works both as a normal Python script and when executed from a
    Google Colab/Jupyter cell that already has a running asyncio loop.
    """
    token = read_token()
    if not token:
        raise RuntimeError(
            "Не найден токен бота. Укажите BOT_TOKEN или переменную "
            "WORLD_STRATEGY_BOT_TOKEN / TELEGRAM_BOT_TOKEN."
        )

    bot = Bot(
        token=token,
        default=DefaultBotProperties(parse_mode=ParseMode.HTML),
    )
    app = WorldApp()
    try:
        await app.start(bot)
    finally:
        await bot.session.close()


async def _world_strategy_managed_main() -> None:
    """Run the bot as a single managed Colab/Jupyter task.

    Re-running a cell used to leave an older polling task alive, which could
    make Telegram callbacks appear to be handled by an older bot version.
    Before starting the new instance, cancel all previous WORLD STRATEGY tasks
    created by this entrypoint and wait for them to finish.
    """
    loop = asyncio.get_running_loop()
    current = asyncio.current_task(loop=loop)
    old_tasks = []
    for task in asyncio.all_tasks(loop):
        if task is current or task.done():
            continue
        name = str(task.get_name() or '')
        if name in {
            'world-strategy-main',
            'world-strategy-runner',
            'world-simulation',
            'server-clock',
            'world-notifications',
        }:
            task.cancel()
            old_tasks.append(task)
    if old_tasks:
        await asyncio.gather(*old_tasks, return_exceptions=True)
    await main()


def _v18_run_entrypoint():
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None
    if loop is not None and loop.is_running():
        task = loop.create_task(_world_strategy_managed_main(), name='world-strategy-main')
        globals()['_WORLD_STRATEGY_MAIN_TASK'] = task
        return task
    return asyncio.run(main())
                                                                            
                                                                          
                                                                              

                                                       
