async def _v18_final_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "")
    player = self.player(uid, callback.from_user.username or "")

    await self.answer_callback(callback)

    if player.banned:
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

                                                                            
                                                                             
    if data.startswith("server:"):
        try:
            if self.is_admin(uid) and not self.world.is_server_admin(uid):
                self.world.set_server_admin(uid, True)
            if not self.world.is_server_admin(uid):
                await self.show(callback, "❌ Нет доступа к серверной панели.", _v15_server_keyboard())
                return
            await _v12_server_handle(self, callback, data)
        except Exception as exc:
            self.world.add_log("server_callback_error", uid, {"data": data[:80], "error": repr(exc)})
            await self.show(callback, "❌ Ошибка серверной панели. Запись добавлена в диагностику.", _v15_server_keyboard())
        return

                                                                             
                                                                               
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid) and not self.is_admin(uid):
        await self.show(callback, "⛔ Сервер сейчас остановлен. Используйте /server.")
        return

    try:
        if data == "noop":
            return
        if data == "home":
            player.clear_input()
            await self.render_home(callback)
            return
        if data == "country:picker":
            player.clear_input()
            await self.show(callback, "🌍 <b>Выбор страны</b>", Keyboards.country_picker())
            return
        if data == "country:economy":
            await self.render_country_economy(callback)
            return
        if data.startswith("country:"):
            await self.handle_country(callback, data.split(":", 1)[1])
            return
        if data == "admin:home":
            if not self.is_admin(uid):
                player.pending_input = "admin_code"
                player.pending_data = {"expires_at": time.monotonic() + 180}
                await self.show(callback, "🛠️ Введите код администратора:")
            else:
                await self.render_admin_home(callback)
            return
        if data == "admin:logout":
            self.world.set_admin(uid, False)
            player.clear_input()
            await self.show(callback, "✅ Вы вышли из режима администратора.", Keyboards.country_picker())
            return
        if data.startswith("admin:countrymsg"):
            if await _v12_admin_countrymsg(self, callback, data):
                return
        if data.startswith("screen:"):
            await self.handle_screen(callback, data.split(":", 1)[1])
            return
        if data.startswith("map:"):
            await self.handle_map(callback, data)
            return
        if data.startswith("provneighbors:"):
            await self.handle_province_neighbors(callback, data)
            return
        if data.startswith("prov:"):
            await self.handle_province(callback, data)
            return
        if data.startswith("prod"):
            await self.handle_production(callback, data)
            return
        if data.startswith("warehousecat:") or data.startswith("warehouse"):
            await self.handle_warehouse(callback, data)
            return
        if data.startswith("army") or data.startswith("gen:") or data.startswith("general"):
            await self.handle_army(callback, data)
            return
        if data.startswith("air"):
            await self.handle_air(callback, data)
            return
        if data.startswith("pvo"):
            await self.handle_pvo(callback, data)
            return
        if data.startswith("navy") or data.startswith("navyrebase:"):
            await self.handle_navy(callback, data)
            return
        if (data.startswith("diplo") or data.startswith("treaty") or
                data.startswith("war") or data.startswith("ultimatum") or
                data.startswith("ultdemand:") or data.startswith("ultdeadline:") or
                data.startswith("ultsend:") or data.startswith("warningto:")):
            await self.handle_diplomacy(callback, data)
            return
        if data.startswith("trade"):
            await self.handle_trade(callback, data)
            return
        if data.startswith("decision"):
            await self.handle_decision(callback, data)
            return
        if data.startswith("build"):
            await self.handle_construction(callback, data)
            return
        if data.startswith("repair"):
            await self.handle_repair(callback, data)
            return
        if data.startswith("journal"):
            await self.handle_journal(callback, data)
            return
        if data.startswith("news"):
            await self.handle_news(callback, data)
            return
        if data.startswith("admin:"):
            await self.handle_admin(callback, data)
            return
        await self.show(callback, "🔄 Действие устарело. Обновляю меню.", Keyboards.home())
    except Exception as exc:
        self.world.add_log("callback_error", uid, {"callback": data[:64], "error": repr(exc)})
        await self.show(callback, "❌ Не удалось обработать действие. Ошибка записана в журнал диагностики.", Keyboards.home())



async def _v18_final_on_text(self: WorldApp, message: types.Message) -> None:
    if not message.text:
        return

    uid = int(message.from_user.id)
    player = self.player(uid, message.from_user.username or "")
    value = message.text.strip()
    pending = str(player.pending_input or "")

                                    
    if pending == "server_code":
        pdata = dict(player.pending_data or {})
        if int(pdata.get("owner_user_id", uid)) != uid:
            return
        if pdata.get("expires_at", 0) and time.monotonic() > float(pdata["expires_at"]):
            player.clear_input()
            await self.show_new(message, "❌ Код доступа просрочен. Введите /server снова.")
            return
        if getattr(getattr(message, "chat", None), "type", "private") in {"group", "supergroup"}:
            if int(getattr(message.chat, "id", 0)) != int(pdata.get("chat_id", 0) or 0):
                return
            reply = getattr(message, "reply_to_message", None)
            if not reply or int(getattr(reply, "message_id", 0)) != int(pdata.get("prompt_message_id", 0) or 0):
                return
        ok = value == SERVER_CONTROL_CODE
        if ok:
            self.world.set_server_admin(uid, True)
            player.clear_input()
            self.world.add_log("server_auth_success", uid, {})
            self.world.mark_dirty()
            await _v12_server_panel(self, message)
        else:
            self.world.add_log("server_auth_failed", uid, {})
            await self.show_new(message, "❌ Неверный код серверной панели. Попробуйте ещё раз.")
        return

                                   
    if pending == "admin_code":
        expires = float((player.pending_data or {}).get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            player.clear_input()
            await self.show_new(message, "❌ Код администратора просрочен. Введите /admin снова.")
            return
        if self.admin.authenticate(uid, value):
            player.clear_input()
                                                                              
            await self.render_admin_home(message)
        else:
            await self.show_new(message, "❌ Неверный код администратора. Повторите ввод или нажмите /back.")
        return

                                 
    if pending == "country_code":
        pdata = dict(player.pending_data or {})
        code = str(pdata.get("country", ""))
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            player.clear_input()
            await self.show_new(message, "❌ Код страны просрочен. Нажмите /start и выберите страну снова.", Keyboards.country_picker())
            return
        expected = str(COUNTRY_ACCESS_CODES.get(code, code))
        if value != expected:
            await self.show_new(message, f"❌ Неверный код страны.\n\nВведите код страны {esc(COUNTRY_NAMES.get(code, code))}:", Keyboards.simple_nav("country:picker"))
            return
        if code == COUNTRY_TEST:
            player.clear_input()
            player.current_screen = "test"
            await self.show_new(message, "✅ Доступ к техническому режиму ТЕСТ разрешён.")
            return
        if code not in PLAYABLE_COUNTRIES:
            player.clear_input()
            await self.show_new(message, "❌ Такая страна недоступна.", Keyboards.country_picker())
            return
        if not self.world.set_country(uid, code):
            await self.show_new(message, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        player.clear_input()
        self.world.add_log("country_switch", uid, {"country": code})
        self.world.mark_dirty()
        await self.render_home(message)
        return

                                                                         
                                     
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid) and not self.is_admin(uid):
        await self.show_new(message, "⛔ Сервер сейчас остановлен. Используйте /server для управления сервером.")
        return

                                                                          
    if player.pending_input:
        try:
            async with self.screen_lock(uid):
                result = await self.process_text_input(player, value)
        except Exception as exc:
            self.world.add_log("ui_input_error", uid, {"input": pending, "error": repr(exc)})
            result = "❌ Ошибка обработки ввода."
        await self.show_new(message, result)
        return

    await self.render_home(message)

WorldApp.on_text = _v18_final_on_text

                                                                             
                                                                               
                                                                                 


                                                                              
                                                                          
                                                                              
                                                                          
                                                                              

