_v19_apply_daily_prev = Economy.apply_daily_tick

def _v19_apply_daily_tick(self, country_code: str) -> None:
                                                                         
                                                                         
    _v19_apply_daily_prev(self, country_code)
    c = self.world.country(country_code)
    flat_bonus = 0
    for active in c.active_decisions.values():
        if active.get("finished"):
            continue
        effects = active.get("effects") or {}
        flat_bonus += max(0, int(effects.get("manpower_daily_flat", 0)))
    if flat_bonus:
        c.manpower = min(c.population // 5, c.manpower + flat_bonus)
        self.world.mark_dirty()

Economy.apply_daily_tick = _v19_apply_daily_tick

                                                          
