def _v19_clean_reset_world(self: WorldState) -> None:
    with self.state_lock:
        old_server_state = copy.deepcopy(getattr(self, "server_state", {}))
        settings = getattr(self, "settings", None)
        self.countries = {code: Country.new(code) for code in PLAYABLE_COUNTRIES}
        self.provinces = {}
        self.players = {}
        self.divisions = {}
        self.generals = {}
        self.air_groups = {}
        self.pvo_units = {}
        self.fleets = {}
        self.wars = {}
        self.war_goals = {}
        self.treaties = {}
        self.trades = {}
        self.decisions = {}
        self.construction_projects = {}
        self.repairs = {}
        self.news = {}
        self.events = {}
        self.journal = []
        self.logs = []
        self._ids = {}
        self.game_minutes = 0.0
        self.dirty = False
        self.paused = False
        self.speed = 1.0
        self._make_map()
        if settings is not None:
            self.settings = settings
        if old_server_state:
            old_server_state["work_enabled"] = True
            old_server_state["maintenance"] = False
            old_server_state["time_running"] = True
            self.server_state = old_server_state
WorldState._reset_world = _v19_clean_reset_world

                                                                      
