def _v19_set_admin(self: WorldState, user_id: int, enabled: bool) -> None:
    player = self.register_player(user_id)
    if enabled:
                                                                           
                                                               
        if player.country in PLAYABLE_COUNTRIES:
            player.active_country = player.country
        player.role = "admin"
        player.country = None
    else:
        player.role = "player"
        self.set_server_admin(user_id, False)
        if getattr(player, "active_country", None) in PLAYABLE_COUNTRIES:
            player.country = player.active_country
    player.clear_input()
    self.dirty = True
