def _v19_air_set_route(self: Aviation, group_id: str, waypoints: list[int]) -> tuple[bool, str]:
    g = self.world.air_groups.get(group_id)
    if not g:
        return False, "Авиагруппа не найдена."
    points=[]
    for x in waypoints:
        pid=int(x)
        if pid not in self.world.provinces:
            return False, f"Провинция {pid} не найдена."
        if not points or points[-1]!=pid:
            points.append(pid)
    if not points:
        return False, "Маршрут пустой."
    origin=int(g.get("airfield_province",0))
    if points[0]!=origin:
        points.insert(0,origin)
    expanded=[points[0]]
    current=points[0]
                                                                               
                                                                
    for waypoint in points[1:]:
        queue=[current]
        parent={current:None}
        while queue and waypoint not in parent:
            cur=queue.pop(0)
            for nxt in self.world.province(cur).neighbors:
                if nxt in parent: continue
                parent[nxt]=cur; queue.append(nxt)
        if waypoint not in parent:
            return False, f"Не удалось построить воздушный маршрут до {self.world.province(waypoint).name}."
        path=[waypoint]
        while parent[path[-1]] is not None:
            path.append(parent[path[-1]])
        path.reverse()
        expanded.extend(path[1:])
        current=waypoint
    clean=[]
    for pid in expanded:
        if not clean or clean[-1]!=pid: clean.append(pid)
    if len(clean)>100:
        return False, "Маршрут слишком длинный."
    g["route"]=clean; g["route_index"]=0; g["manual"]=True
    self.world.mark_dirty()
    return True, f"Маршрут сохранён: {len(clean)} точек."
Aviation.set_route = _v19_air_set_route

