def _v19_auto_deploy_pvo(self: PVO, country_code: str) -> tuple[bool, str, int]:
    c=self.world.country(country_code)
    own=list(c.province_ids)
    if not own: return False,"У страны нет провинций.",0
    def score(pid:int)->float:
        p=self.world.province(pid)
        return (100 if p.capital else 0)+(60 if p.city else 0)+(35 if any(self.world.province(n).country!=country_code for n in p.neighbors) else 0)+p.industrial_level*5
    targets=sorted(own,key=score,reverse=True)[:min(8,len(own))]
    deployed=0
    leftovers=[]
    for model in ("pvo_long","pvo","radar_station","aa_gun"):
        stock=int(c.warehouse.get(model,0))
        if stock<=0: continue
        if model not in PVO_MODELS: continue
        base,rem=divmod(stock,len(targets))
        for i,pid in enumerate(targets):
            q=base+(1 if i<rem else 0)
            if q<=0: continue
            ok,reason,_=self.deploy(country_code,model,q,pid)
            if ok:
                deployed += q
            else:
                leftovers.append(f"{model}: {reason}")
    if deployed:
        self.world.add_journal("pvo","Авторасстановка ПВО",f"Размещено автоматикой: {deployed} единиц.",country_code)
        self.world.mark_dirty()
        return True,f"Авторасстановка завершена: {deployed} единиц ПВО распределены по {len(targets)} ключевым провинциям.",deployed
    return False,"На складе нет доступных систем ПВО для автоматического размещения.",0
PVO.auto_deploy = _v19_auto_deploy_pvo

