def _v19_trade_type_text(t:dict[str,Any])->str:
    if t.get("cargo_type") == "equipment":
        return f"🔫 {model_display(t.get('equipment',''))} ×{format_number(t.get('quantity',0))}"
    return f"📦 {RESOURCE_DISPLAY.get(t.get('resource'),t.get('resource'))} ×{format_number(t.get('quantity',0))}"

_v19_trade_create_prev = Trade.create
def _v19_trade_create_equipment(self:Trade,sender:str,receiver:str,equipment:str,quantity:int,price:int,route:str)->tuple[bool,str,Optional[str]]:
    quantity=int(quantity); price=int(price)
    if sender==receiver or receiver not in PLAYABLE_COUNTRIES: return False,"Неверный торговый партнёр.",None
    if equipment not in EQUIPMENT_KEYS: return False,"Техника не поддерживается.",None
    if quantity<=0 or price<=0: return False,"Количество и цена должны быть больше нуля.",None
    if route not in {"land","sea"} or not self._route_available(sender,receiver,route): return False,"Выбранный торговый маршрут недоступен.",None
    if self._active_deal_count(sender)>=15: return False,"У страны слишком много активных сделок.",None
    s=self.world.country(sender); r=self.world.country(receiver); total=quantity*price
    if not s.infinite_weapons and s.warehouse.get(equipment,0)<quantity:
        return False,f"Недостаточно на складе: {model_display(equipment)}.",None
    if r.budget<total: return False,"У покупателя недостаточно денег.",None
    if not s.infinite_weapons: s.warehouse[equipment]-=quantity
    r.budget-=total
    tid=self.world.next_entity_id("trade")
    duration=60.0 if route=="land" else 90.0
    self.world.trades[tid]={"id":tid,"sender":sender,"receiver":receiver,"cargo_type":"equipment","equipment":equipment,"quantity":quantity,"price":price,"total":total,"created_at":self.world.game_minutes,"remaining_minutes":duration,"delivery_progress":0.0,"route":route,"route_type":route,"status":"in_transit"}
    self.world.add_journal("trade","Продажа техники",f"{country_display(sender)} → {country_display(receiver)}: {_v19_trade_type_text(self.world.trades[tid])}.")
    self.world.mark_dirty()
    return True,f"Сделка с техникой создана на {format_money(total)}.",tid
Trade.create_equipment = _v19_trade_create_equipment

_v19_trade_cancel_prev = Trade.cancel
def _v19_trade_cancel(self:Trade,trade_id:str,country_code:str)->tuple[bool,str]:
    t=self.world.trades.get(trade_id)
    if not t or t.get("status") not in {"active","in_transit"}: return False,"Сделка не найдена или уже завершена."
    if country_code not in (t.get("sender"),t.get("receiver")): return False,"Вы не участник сделки."
    sender=self.world.country(t["sender"]); receiver=self.world.country(t["receiver"])
    if t.get("cargo_type")=="equipment":
        if not sender.infinite_weapons: sender.warehouse[t["equipment"]]=sender.warehouse.get(t["equipment"],0)+int(t["quantity"])
    else:
        sender.resources[t["resource"]]=sender.resources.get(t["resource"],0)+int(t["quantity"])
    receiver.budget+=int(t["total"])
    t["status"]="cancelled"; t["cancelled_at"]=self.world.game_minutes
    self.world.mark_dirty(); return True,"Сделка отменена, резервы возвращены."
Trade.cancel = _v19_trade_cancel

_v19_trade_tick_prev = Trade.tick
def _v19_trade_tick(self:Trade,minutes:float)->list[str]:
    completed=[]
    for tid,t in list(self.world.trades.items()):
        if t.get("status") not in {"active","in_transit"}: continue
        total_duration=60.0 if t.get("route")=="land" else 90.0
        t["remaining_minutes"]=max(0.0,float(t.get("remaining_minutes",total_duration))-float(minutes))
        t["delivery_progress"]=max(0.0,min(1.0,1.0-t["remaining_minutes"]/max(1.0,total_duration)))
        if t["remaining_minutes"]>0: continue
        receiver=self.world.country(t["receiver"])
        if t.get("cargo_type")=="equipment":
            receiver.warehouse[t["equipment"]]=receiver.warehouse.get(t["equipment"],0)+int(t["quantity"])
        else:
            receiver.resources[t["resource"]]=receiver.resources.get(t["resource"],0)+int(t["quantity"])
        t["status"]="completed"; t["completed_at"]=self.world.game_minutes; completed.append(tid)
        self.world.add_journal("trade","Торговая поставка доставлена",f"Сделка {tid} завершена.")
    if completed: self.world.mark_dirty()
    return completed
Trade.tick = _v19_trade_tick

