async def _v19_handle_construction(self,callback,data):
    if data=="build:new":
        country,error=self.require_country(callback.from_user.id)
        if not country: await self.show(callback,error,Keyboards.country_picker()); return
        rows=[]
        for k,d in CONSTRUCTION_DEFS.items():
            rows.append([Keyboards.btn(f"{d.title} — {format_money(d.cost)} / {d.duration_days:g} дн.",f"build:type:{k}")])
        rows+=Keyboards.nav("screen:construction")
        await self.show(callback,"🏗️ <b>Выберите объект</b>\n\nНиже сразу указано, сколько стоит и сколько строится объект.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("build:type:"):
        key=data.split(":",2)[2]; d=CONSTRUCTION_DEFS.get(key)
        if not d: await self.show(callback,"❌ Объект не найден.",Keyboards.simple_nav("screen:construction")); return
        country,_=self.require_country(callback.from_user.id)
        own=sorted(self.world.country(country).province_ids)
        rows=[[Keyboards.btn(self.world.province(pid).name,f"build:place:{key}:{pid}")] for pid in own[:70]]; rows+=Keyboards.nav("screen:construction")
        text=(f"🏗️ <b>{esc(d.title)}</b>\n\n"
              f"💰 Стоимость: <b>{format_money(d.cost)}</b>\n"
              f"⏱️ Срок: <b>{d.duration_days:g} игровых дней</b>\n"
              f"📈 Что даёт: <b>{esc(d.effect)}</b>\n\n"
              "Выберите свою провинцию:")
        await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("build:view:"):
        pid=data.split(":",2)[2]; p=self.world.construction_projects.get(pid)
        if not p:
            await self.show(callback,"❌ Проект не найден.",Keyboards.simple_nav("screen:construction")); return
        d=CONSTRUCTION_DEFS.get(p.get("building")); effect=d.effect if d else "—"
        text=(f"🏗️ <b>{esc(d.title if d else p.get('building','Стройка'))}</b>\n\n"
              f"Провинция: {esc(self.world.province(int(p['province'])).name)}\n"
              f"💰 Стоимость: {format_money(p.get('cost',0))}\n"
              f"📈 Эффект: {esc(effect)}\n"
              f"⏱️ Осталось: {float(p.get('remaining_minutes',0)):.0f} мин.")
        rows=[[Keyboards.btn("⛔ Отменить",f"build:cancel:{pid}")],*Keyboards.nav("build:list")]
        await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    await _v19_handle_construction_prev(self,callback,data)
WorldApp.handle_construction = _v19_handle_construction

                                                                             
                        
                                                                             
