def _v19_reset_country(self:WorldApp, code:str)->tuple[bool,str]:
    if code not in PLAYABLE_COUNTRIES: return False,"Страна не найдена."
    baseline=WorldState()
                                                  
    for did,d in list(self.world.divisions.items()):
        if d.get("country")==code:
            pid=int(d.get("province",0))
            if pid in self.world.provinces and did in self.world.province(pid).armies: self.world.province(pid).armies.remove(did)
            del self.world.divisions[did]
    for collection in ("generals","air_groups","pvo_units","fleets"):
        for eid,obj in list(getattr(self.world,collection).items()):
            if obj.get("country")==code:
                pid=int(obj.get("province",obj.get("airfield_province",obj.get("base_province",-1))))
                if pid in self.world.provinces:
                    p=self.world.province(pid)
                    for field in ("air_groups","pvo_units","fleets"):
                        if eid in getattr(p,field,[]): getattr(p,field).remove(eid)
                del getattr(self.world,collection)[eid]
    for wid,w in list(self.world.wars.items()):
        if w.attacker==code or w.defender==code: del self.world.wars[wid]
    for gid,g in list(self.world.war_goals.items()):
        if g.get("creator")==code or g.get("target")==code: del self.world.war_goals[gid]
    for tid,t in list(self.world.treaties.items()):
        if code in (t.get("a"),t.get("b")): del self.world.treaties[tid]
    for tid,t in list(self.world.trades.items()):
        if code in (t.get("sender"),t.get("receiver")):
            other=t.get("receiver") if t.get("sender")==code else t.get("sender")
            if other in PLAYABLE_COUNTRIES and t.get("status") in {"active","in_transit"}:
                other_c=self.world.country(other)
                if t.get("receiver")==code:
                    if t.get("cargo_type")=="equipment":
                        other_c.warehouse[t.get("equipment")]=other_c.warehouse.get(t.get("equipment"),0)+int(t.get("quantity",0))
                    else:
                        other_c.resources[t.get("resource")]=other_c.resources.get(t.get("resource"),0)+int(t.get("quantity",0))
                else:
                    other_c.budget += int(t.get("total",0))
            del self.world.trades[tid]
    old_player_data={p.user_id:copy.deepcopy(p) for p in self.world.players.values() if p.country==code}
    self.world.countries[code]=copy.deepcopy(baseline.country(code))
    for pid in list(self.world.countries[code].province_ids):
        if pid in baseline.provinces:
            self.world.provinces[pid]=copy.deepcopy(baseline.province(pid))
    for other in PLAYABLE_COUNTRIES:
        if other!=code:
            self.world.country(other).relations[code]=0
            self.world.country(code).relations[other]=0
    for p in old_player_data.values():
        self.world.players[p.user_id]=p
    self.world.mark_dirty()
    return True,f"{COUNTRY_NAMES[code]} сброшена к стартовому состоянию."
WorldApp._v19_reset_country = _v19_reset_country

async def _v19_handle_admin(self,callback,data):
    uid=callback.from_user.id
    if not self.is_admin(uid):
        await self.show(callback,"❌ Нет прав администратора.",Keyboards.country_picker()); return
    if data=="admin:server":
        self.world.set_server_admin(uid,True); self.world.mark_dirty(); await _v12_server_panel(self,callback); return
    if data=="admin:section:reset":
        p=self.player(uid); p.pending_input="admin_reset_code"; p.pending_data={"expires_at":time.monotonic()+300}
        await self.show(callback,"♻️ <b>Сброс мира</b>\n\nВведите специальный код подтверждения.",Keyboards.simple_nav("admin:home")); return
    if data.startswith("admin:reset_country:"):
        code=data.split(":",2)[2]; ok,reason=self._v19_reset_country(code); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("admin:home")); return
    if data=="admin:reset_world":
        current_admins=[p.user_id for p in self.world.players.values() if p.is_admin]
        server_admins=[int(x) for x in getattr(self.world,"server_state",{}).get("admin_ids",[])]
        self.world._reset_world()
        for auid in current_admins:
            self.world.set_admin(auid,True)
        for suid in server_admins:
            self.world.set_server_admin(suid,True)
        self.world.set_server_admin(uid,True)
        self.world.mark_dirty()
        self.spawn(self.save_light())
        await self.show(callback,"✅ Весь мир сброшен к самому старту.",Keyboards.simple_nav("admin:home")); return
    if data.startswith("admin:eventtarget:"):
                                             
        await _v19_handle_admin_prev(self,callback,data); return
    await _v19_handle_admin_prev(self,callback,data)
_v19_handle_admin_prev = WorldApp.handle_admin
WorldApp.handle_admin = _v19_handle_admin

                                                                       
async def _v19_server_handle(self:WorldApp,callback:types.CallbackQuery,data:str)->bool:
    uid=int(callback.from_user.id)
    if not self.world.is_server_admin(uid):
        await self.show(callback,"❌ Нет доступа к серверной панели.",_v15_server_keyboard()); return True
    state=self.world.server_state
    if data=="server:panel": await _v12_server_panel(self,callback); return True
    if data=="server:time_pause":
        state["time_running"]=False; state["paused_before_time_pause"]=True; self.world.paused=True; self.world.mark_dirty(); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:time_resume":
        if state.get("maintenance") or not state.get("work_enabled",True): await self.show(callback,"❌ Сначала возобновите работу сервера/завершите техработы.",_v12_server_panel_keyboard()); return True
        self.world.paused=False; state["time_running"]=True; self.world.mark_dirty(); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:stop":
        state["paused_before_server_stop"]=bool(self.world.paused); state["work_enabled"]=False; state["time_running"]=False; self.world.paused=True; self.world.mark_dirty(); self.world.add_log("server_stop",uid,{}); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:resume":
        state["work_enabled"]=True
        restore_paused=bool(state.pop("paused_before_server_stop",False))
        if not state.get("maintenance"):
            self.world.paused=restore_paused; state["time_running"]=not restore_paused
        self.world.mark_dirty(); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:maintenance_on":
        state["paused_before_maintenance"]=bool(self.world.paused); state["maintenance"]=True; state["work_enabled"]=False; state["time_running"]=False; self.world.paused=True; self.world.mark_dirty(); self.spawn(self._broadcast_server_maintenance(True)); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:maintenance_off":
        was_paused=bool(state.pop("paused_before_maintenance",False)); state["maintenance"]=False; state["work_enabled"]=True; self.world.paused=was_paused; state["time_running"]=not was_paused; self.world.mark_dirty(); self.spawn(self._broadcast_server_maintenance(False)); await self.show(callback,_v12_server_panel_text(self),_v12_server_panel_keyboard()); return True
    if data=="server:clock": await _v12_server_clock_screen(self,callback); return True
    if data=="server:logs": await _v12_server_logs_screen(self,callback); return True
    if data=="server:clear_logs":
        self.world.logs.clear(); self.world.mark_dirty(); await self.show(callback,"✅ Логи очищены.",_v12_server_panel_keyboard()); return True
    if data=="server:diagnostics": await self.show(callback,self.test_summary(),types.InlineKeyboardMarkup(inline_keyboard=[Keyboards.nav("server:panel")])); return True
    if data=="server:save":
        async with self.world.simulation_lock:
            await asyncio.to_thread(self.save_manager.save,self.world,False); self.world.dirty=False
        await self.show(callback,"✅ Состояние сервера сохранено.",_v12_server_panel_keyboard()); return True
    if data=="server:backup":
        async with self.world.simulation_lock:
            await asyncio.to_thread(self.save_manager.create_backup)
        await self.show(callback,"✅ Резервная копия создана.",_v12_server_panel_keyboard()); return True
    if data=="server:restore":
        was_server_admin=True
        async with self.world.simulation_lock:
            ok=await asyncio.to_thread(self.save_manager.restore)
            if ok:
                warnings=await asyncio.to_thread(self.save_manager.load,self.world)
                self.world.set_server_admin(uid,was_server_admin)
                self.simulation.production_accum=0.0; self.simulation.daily_accum=0.0; self.simulation.army_accum=0.0; self.simulation.air_accum=0.0; self.simulation.trade_accum=0.0; self.simulation.last_loop_real=time.monotonic()
                self.world.mark_dirty()
        await self.show(callback,"✅ Backup восстановлен."+(f" Предупреждений: {len(warnings)}" if ok and warnings else ""),_v12_server_panel_keyboard()); return True
    if data=="server:clear_notifications": self.world.notifications.clear(); self.world.mark_dirty(); await self.show(callback,"✅ Очередь уведомлений очищена.",_v12_server_panel_keyboard()); return True
    if data=="server:country_message":
        rows=[[Keyboards.btn(COUNTRY_NAMES[c],f"admin:countrymsgto:{c}")] for c in PLAYABLE_COUNTRIES]; rows+=Keyboards.nav("server:panel"); await self.show(callback,"📨 Выберите страну, которой отправить сообщение от администрации.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return True
    if data=="server:logout":
        self.world.set_server_admin(uid,False); self.world.mark_dirty()
        if self.is_admin(uid): await self.render_admin_home(callback)
        else: await self.show(callback,"✅ Вы вышли из серверной панели.",Keyboards.country_picker())
        return True
    return False

                                                        
async def _v19_on_server_command(self:WorldApp,message:types.Message)->None:
    uid=message.from_user.id; p=self.player(uid,message.from_user.username or "")
    p.pending_input="server_code"
    p.pending_data={"expires_at":time.monotonic()+300,"owner_user_id":uid,"chat_id":getattr(message.chat,"id",None)}
    if getattr(message.chat,"type","private") in {"group","supergroup"}:
        try:
            sent=await message.answer("🖥️ <b>Серверная панель</b>\n\nВведите код ответом на это сообщение:",reply_markup=types.ForceReply(selective=True),parse_mode=ParseMode.HTML)
            p.pending_data["prompt_message_id"]=getattr(sent,"message_id",0); return
        except Exception: pass
    await self.show_new(message,"🖥️ <b>Серверная панель</b>\n\nВведите код доступа:")
WorldApp.on_server_command = _v19_on_server_command

                                                    
