_v19_process_prev = WorldApp.process_text_input
async def _v19_process_text_input(self:WorldApp,player:Any,value:str)->str:
    action=str(player.pending_input or "")
    pdata=dict(player.pending_data or {})
    if action=="division_quantity":
        try: qty=int(value)
        except Exception: return "❌ Введите целое число от 1 до 50."
        if qty<1 or qty>50: return "❌ Количество должно быть от 1 до 50."
        country=str(pdata.get("country","")); template=str(pdata.get("template","")); province=int(pdata.get("province",0))
        created=[]
        for i in range(qty):
            number=len(self.army.country_divisions(country))+1
            ok,reason,did=self.army.create_division(country,template,province,f"{TEMPLATE_LABELS.get(template,template)} №{number}")
            if not ok:
                break
            created.append(did)
        player.clear_input()
        if not created:
            return "❌ Не удалось создать ни одной дивизии. Проверьте резерв и технику на складе."
        self.world.add_journal("army","Пакетное создание дивизий",f"Создано дивизий: {len(created)}.",country)
        self.spawn(self.save_light())
        setattr(player,"_v19_post_route","screen:army")
        return f"✅ Создано дивизий: <b>{len(created)}</b> из {qty}."
    if action=="production_factories":
        key=str(pdata.get("model","")); country=str(pdata.get("country",""))
        try: count=int(value)
        except Exception: return "❌ Введите целое количество заводов."
        maximum=int(pdata.get("max",0))
        if count<0 or count>maximum: return f"❌ Можно указать от 0 до {maximum} ВЗ."
        ok,reason=self.production.set_line(country,key,count); player.clear_input()
        self.spawn(self.save_light())
        setattr(player,"_v19_post_route",f"prodmodel:{key}")
        return ("✅ " if ok else "❌ ")+reason
    if action=="division_name":
        did=str(pdata.get("division_id","")); player.clear_input()
        ok,reason=self.army.rename(did,value)
        self.spawn(self.save_light())
        setattr(player,"_v19_post_route",f"armydiv:{did}" if ok else "screen:army")
        return ("✅ " if ok else "❌ ")+reason
    if action=="general_name":
        country=str(pdata.get("country","")); player.clear_input(); ok,reason,gid=self.army.create_general(country,value)
        self.spawn(self.save_light())
        setattr(player,"_v19_post_route",f"gen:view:{gid}" if ok and gid else "army:generals")
        return ("✅ " if ok else "❌ ")+reason
    result=await _v19_process_prev(self,player,value)
    if action in {"message_text","warning_text"}:
        setattr(player,"_v19_post_route","screen:diplomacy")
    elif action=="admin_message_text":
        setattr(player,"_v19_post_route","admin:home")
    return result
WorldApp.process_text_input = _v19_process_text_input

async def _v19_on_text(self:WorldApp,message:types.Message)->None:
    if not message.text: return
    uid=int(message.from_user.id); p=self.player(uid,message.from_user.username or ""); value=message.text.strip(); pending=str(p.pending_input or ""); pdata=dict(p.pending_data or {})
                 
    if pending=="server_code":
        if int(pdata.get("owner_user_id",uid))!=uid: return
        if pdata.get("expires_at",0) and time.monotonic()>float(pdata["expires_at"]):
            p.clear_input(); await self.show_new(message,"❌ Код доступа просрочен. Введите /server снова."); return
        if getattr(message.chat,"type","private") in {"group","supergroup"}:
            reply=getattr(message,"reply_to_message",None)
            if int(getattr(message.chat,"id",0))!=int(pdata.get("chat_id",0) or 0) or not reply or int(getattr(reply,"message_id",0))!=int(pdata.get("prompt_message_id",0) or 0): return
        if value!=SERVER_CONTROL_CODE:
            await self.show_new(message,"❌ Неверный код серверной панели. Попробуйте ещё раз."); return
        self.world.set_server_admin(uid,True); p.clear_input(); self.world.mark_dirty(); await _v12_server_panel(self,message); return
                
    if pending=="admin_code":
        expires=float(pdata.get("expires_at",0) or 0)
        if expires and time.monotonic()>expires: p.clear_input(); await self.show_new(message,"❌ Код администратора просрочен. Введите /admin снова."); return
        if self.admin.authenticate(uid,value): p.clear_input(); await self.render_admin_home(message)
        else: await self.show_new(message,"❌ Неверный код администратора. Повторите ввод или нажмите /back.")
        return
                      
    if pending=="admin_reset_code":
        expires=float(pdata.get("expires_at",0) or 0)
        if expires and time.monotonic()>expires: p.clear_input(); await self.show_new(message,"❌ Код сброса просрочен.",Keyboards.simple_nav("admin:home")); return
        if value!=V19_ADMIN_RESET_CODE:
            await self.show_new(message,"❌ Неверный код сброса. Попробуйте ещё раз.",Keyboards.simple_nav("admin:home")); return
        p.clear_input()
        rows=[
            [Keyboards.btn(f"🟦 {COUNTRY_NAMES[COUNTRY_RAZBAGARE]}",f"admin:reset_country:{COUNTRY_RAZBAGARE}")],
            [Keyboards.btn(f"🟩 {COUNTRY_NAMES[COUNTRY_PEDAGOG]}",f"admin:reset_country:{COUNTRY_PEDAGOG}")],
            [Keyboards.btn(f"🟥 {COUNTRY_NAMES[COUNTRY_MARKLAND]}",f"admin:reset_country:{COUNTRY_MARKLAND}")],
            [Keyboards.btn("🌍 Весь мир", "admin:reset_world")]
        ]
        rows += Keyboards.nav("admin:home")
        await self.show_new(message,"♻️ <b>Выберите, что сбросить:</b>\n\nСброс страны возвращает её экономику, склады, технику, решения, армии и инфраструктуру к старту. Сброс мира возвращает весь мир к самому началу.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
                  
    if pending=="country_code":
        code=str(pdata.get("country","")); expires=float(pdata.get("expires_at",0) or 0)
        if expires and time.monotonic()>expires: p.clear_input(); await self.show_new(message,"❌ Код страны просрочен. Нажмите /start.",Keyboards.country_picker()); return
        if value!=str(COUNTRY_ACCESS_CODES.get(code,code)):
            await self.show_new(message,f"❌ Неверный код страны.\n\nВведите код страны {esc(COUNTRY_NAMES.get(code,code))}:",Keyboards.simple_nav("country:picker")); return
        if code==COUNTRY_TEST:
            p.clear_input(); p.current_screen="test"; await self.show_new(message,"✅ Доступ к техническому режиму ТЕСТ разрешён."); return
        if code not in PLAYABLE_COUNTRIES:
            p.clear_input(); await self.show_new(message,"❌ Такая страна недоступна.",Keyboards.country_picker()); return
        if not self.world.set_country(uid,code): await self.show_new(message,"❌ Эта страна уже занята другим игроком.",Keyboards.country_picker()); return
        p.clear_input(); self.world.mark_dirty(); await self.render_home(message); return
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid) and not self.is_admin(uid):
        await self.show_new(message,"⛔ Сервер сейчас остановлен. Используйте /server для управления сервером."); return
    if p.pending_input:
        try:
            async with self.screen_lock(uid):
                result=await self.process_text_input(p,value)
        except Exception as exc:
            self.world.add_log("ui_input_error",uid,{"input":pending,"error":repr(exc)}); result="❌ Ошибка обработки ввода."
        route=getattr(p,"_v19_post_route",None); setattr(p,"_v19_post_route",None)
        if pending=="news_text" and p.pending_input=="news_target":
            rows=[[Keyboards.btn("🌍 Всем странам","admin:newstarget:all")]]+[[Keyboards.btn(COUNTRY_NAMES[c],f"admin:newstarget:{c}")] for c in PLAYABLE_COUNTRIES]
            rows+=Keyboards.nav("admin:section:news"); await self.show_new(message,result,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if pending=="event_text" and p.pending_input=="event_target":
            rows=[[Keyboards.btn("🌍 Всем","admin:eventtarget:all")]]+[[Keyboards.btn(COUNTRY_NAMES[c],f"admin:eventtarget:{c}")] for c in PLAYABLE_COUNTRIES]
            rows+=Keyboards.nav("admin:section:events"); await self.show_new(message,result,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
        if route=="screen:diplomacy" or pending in {"message_text","warning_text"}:
            await self.show_new(message,result,Keyboards.simple_nav("screen:diplomacy")); return
        if route=="admin:home" or pending=="admin_message_text":
            await self.show_new(message,result,Keyboards.simple_nav("admin:home")); return
        if route:
            await self.show_new(message,result,Keyboards.simple_nav(route)); return
        await self.show_new(message,result); return
    await self.render_home(message)
WorldApp.on_text = _v19_on_text

                                                                                             
                                                                                    


                                                                              
                                  
                                                                              
                                                                            
                                                                               
                        

                                            
_v191_handle_army_prev = WorldApp.handle_army
async def _v191_handle_army(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    country, error = self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback, error, Keyboards.country_picker())
        return
    if data == "general:create":
        p = self.player(callback.from_user.id)
        p.pending_input = "general_name"
        p.pending_data = {"country": country, "expires_at": time.monotonic() + 600}
        await self.show(
            callback,
            "👤 <b>Создание генерала</b>\n\nВведите имя генерала.",
            Keyboards.simple_nav("army:generals"),
        )
        return
    if data.startswith("armyrename:"):
        did = data.split(":", 1)[1]
        d = self.world.divisions.get(did)
        if not d or d.get("country") != country:
            await self.show(callback, "❌ Дивизия не найдена.", Keyboards.simple_nav("army:divisions"))
            return
        p = self.player(callback.from_user.id)
        p.pending_input = "division_name"
        p.pending_data = {"division_id": did, "expires_at": time.monotonic() + 600}
        await self.show(
            callback,
            f"✏️ Введите новое название дивизии <b>{esc(d.get('name',''))}</b>.",
            Keyboards.simple_nav(f"armydiv:{did}"),
        )
        return
    await _v191_handle_army_prev(self, callback, data)
WorldApp.handle_army = _v191_handle_army

                                                                                 
