    if data == "trade:weapons":
        rows = [[Keyboards.btn(COUNTRY_NAMES[x], f"trade:equipto:{x}")] for x in PLAYABLE_COUNTRIES if x != country]
        rows += Keyboards.nav("screen:trade")
