def _v191_test_summary_final(self: WorldApp) -> str:
    try:
        result = self.diagnostics.run()
    except Exception as exc:
        self.world.add_log("diagnostics_error", None, {"error": repr(exc)})
        return "🧪 <b>Диагностика</b>\n\n❌ Ошибка диагностики: " + esc(repr(exc))
    counts = result.get("counts", {}) if isinstance(result, dict) else {}
    errors = result.get("errors", []) if isinstance(result, dict) else []
    return (
        "🧪 <b>Диагностика</b>\n\n"
        f"Статус: {'✅ OK' if not errors else '❌ Ошибки'}\n"
        f"Провинции: {counts.get('provinces', len(self.world.provinces))}\n"
        f"Страны: {counts.get('countries', len(self.world.countries))}\n"
        f"Игроки: {counts.get('players', len(self.world.players))}\n"
        f"Дивизии: {counts.get('divisions', len(self.world.divisions))}\n"
        f"Генералы: {counts.get('generals', len(self.world.generals))}\n"
        f"Авиагруппы: {counts.get('air_groups', len(self.world.air_groups))}\n"
        f"ПВО: {counts.get('pvo_units', len(self.world.pvo_units))}\n"
        f"Флоты: {counts.get('fleets', len(self.world.fleets))}\n"
        f"Войны: {counts.get('wars', len(self.world.wars))}\n"
        f"Торговля: {counts.get('trades', len(self.world.trades))}\n"
        f"Стройки: {counts.get('construction', len(self.world.construction_projects))}\n"
        f"Ремонты: {counts.get('repair', len(self.world.repairs))}\n"
        f"События: {counts.get('events', len(self.world.events))}\n"
        f"Ошибок: {len(errors)}"
        + ("\n\n" + "\n".join("• " + esc(str(x)) for x in errors[:20]) if errors else "")
    )
WorldApp.test_summary = _v191_test_summary_final

                                                                     
