def _v20_set_line_exact(self: Production, country_code: str, model_key: str, factories: int) -> tuple[bool, str]:
    if model_key not in PRODUCTION_CATALOG:
        return False, "Модель не найдена."
    c = self.world.country(country_code)
    requested = int(factories)
    if requested < 0 or requested > int(c.military_factories):
        return False, f"Можно указать от 0 до {int(c.military_factories)} ВЗ."
    line = self.line(country_code, model_key)
    old = int(line.get("factories", 0))
    available_without_old = self.free_factories(country_code) + old
    reallocated = 0
    if requested > available_without_old:
        need = requested - available_without_old
                                                                              
                                                                           
        others = sorted(
            ((key, value) for key, value in c.production_lines.items() if key != model_key and int(value.get("factories", 0)) > 0),
            key=lambda kv: int(kv[1].get("factories", 0)), reverse=True,
        )
        for other_key, other_line in others:
            cut = min(need, int(other_line.get("factories", 0)))
            if cut <= 0:
                continue
            other_line["factories"] = int(other_line.get("factories", 0)) - cut
            other_line["enabled"] = other_line["factories"] > 0
            need -= cut
            reallocated += cut
            if need <= 0:
                break
        if need > 0:
            return False, "Не удалось перераспределить нужное количество ВЗ."
    line["factories"] = requested
    line.setdefault("accumulator", 0.0)
    line["enabled"] = requested > 0
    self.world.mark_dirty()
    self.world.add_log("production_line", None, {"country": country_code, "model": model_key, "factories": requested, "reallocated": reallocated})
    if reallocated:
        return True, f"Линия установлена на {requested} ВЗ. Перераспределено с других линий: {reallocated} ВЗ."
    return True, f"Линия установлена на {requested} ВЗ."
Production.set_line = _v20_set_line_exact

                                                                           
                                                                        
