async def _v20_handle_production(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    if data.startswith("prodinput:"):
        key = data.split(":", 1)[1]
        country, error = self.require_country(callback.from_user.id)
        if not country or key not in PRODUCTION_CATALOG:
            await self.show(callback, error or "❌ Модель не найдена.", Keyboards.simple_nav("screen:production")); return
        c = self.world.country(country)
        current = int(c.production_lines.get(key, {}).get("factories", 0))
        p = self.player(callback.from_user.id)
        p.pending_input = "production_factories"
        p.pending_data = {
            "country": country, "model": key, "current": current,
            "max": int(c.military_factories), "expires_at": time.monotonic() + 600,
        }
        await self.show(
            callback,
            f"✏️ <b>{esc(PRODUCTION_CATALOG[key].name)}</b>\n\n"
            f"Сейчас: <b>{current}</b> ВЗ\n"
            f"Введите точное количество от <b>0</b> до <b>{int(c.military_factories)}</b>.\n\n"
            "При необходимости недостающие ВЗ будут автоматически сняты с других производственных линий.",
            Keyboards.simple_nav(f"prodmodel:{key}"),
        ); return
    await _v20_handle_production_prev(self, callback, data)
