def _v20_max_affordable_divisions(country: Country, template_key: str) -> int:
    template = DIVISION_TEMPLATES.get(template_key)
    if not template:
        return 0
    max_count = int(country.manpower // max(1, int(template.get("manpower", 1))))
    for item, amount in template.get("equipment", {}).items():
        if country.infinite_weapons:
            continue
        max_count = min(max_count, int(country.warehouse.get(item, 0)) // max(1, int(amount)))
    return max(0, min(50, max_count))

