async def _v20_handle_army(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    if data.startswith("armyplace:"):
        country, error = self.require_country(callback.from_user.id)
        if not country:
            await self.show(callback, error, Keyboards.country_picker()); return
        _, template, pidtxt = data.split(":", 2)
        pid = int(pidtxt)
        if template not in DIVISION_TEMPLATES or pid not in self.world.country(country).province_ids:
            await self.show(callback, "❌ Недопустимое формирование дивизии.", Keyboards.simple_nav("army:create")); return
        p = self.player(callback.from_user.id)
        possible = _v20_max_affordable_divisions(self.world.country(country), template)
        p.pending_input = "division_quantity"
        p.pending_data = {"country": country, "template": template, "province": pid, "max_possible": possible, "expires_at": time.monotonic() + 600}
        await self.show(
            callback,
            f"🪖 <b>{esc(TEMPLATE_LABELS.get(template, template))}</b>\n\n"
            f"Введите количество дивизий от <b>1</b> до <b>50</b>.\n"
            f"С текущим резервом и складом можно создать: <b>{possible}</b> шт.\n\n"
            "Названия создаются автоматически.",
            Keyboards.simple_nav("army:create"),
        ); return
    await _v20_handle_army_prev(self, callback, data)
