async def _v20_process_text_input(self: WorldApp, player: Any, value: str) -> str:
    action = str(player.pending_input or "")
    pdata = dict(player.pending_data or {})
    result = await _v20_process_prev(self, player, value)
    if action == "general_name":
        setattr(player, "_v19_post_route", "army:generals")
    elif action == "division_quantity" and not getattr(player, "_v19_post_route", None):
        setattr(player, "_v19_post_route", "screen:army")
    elif action == "production_factories" and not getattr(player, "_v19_post_route", None):
        key = str(pdata.get("model", ""))
        setattr(player, "_v19_post_route", f"prodmodel:{key}" if key else "screen:production")
    return result
WorldApp.process_text_input = _v20_process_text_input

                                                                          
                                                          
