async def _v20_handle_construction(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    if data == "build:new":
        country, error = self.require_country(callback.from_user.id)
        if not country:
            await self.show(callback, error, Keyboards.country_picker()); return
        rows = [[Keyboards.btn(f"🏗️ {d.title}", f"build:type:{k}")] for k, d in CONSTRUCTION_DEFS.items()]
        rows += Keyboards.nav("screen:construction")
        descriptions = [f"• <b>{esc(d.title)}</b> — {esc(d.effect)} · {format_money(d.cost)} · {d.duration_days:g} дн." for d in CONSTRUCTION_DEFS.values()]
        text = "🏗️ <b>Строительство</b>\n\n" + "\n".join(descriptions) + "\n\nВыберите объект:"
        await self.show(callback, text, types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("build:type:"):
        key = data.split(":", 2)[2]; d = CONSTRUCTION_DEFS.get(key)
        country, error = self.require_country(callback.from_user.id)
        if not country:
            await self.show(callback, error, Keyboards.country_picker()); return
        if not d:
            await self.show(callback, "❌ Объект не найден.", Keyboards.simple_nav("screen:construction")); return
        own = sorted(self.world.country(country).province_ids)
        rows = [[Keyboards.btn(self.world.province(pid).name, f"build:place:{key}:{pid}")] for pid in own[:70]]
        rows += Keyboards.nav("screen:construction")
        text = (
            f"🏗️ <b>{esc(d.title)}</b>\n\n"
            f"💰 Стоимость: <b>{format_money(d.cost)}</b>\n"
            f"⏱️ Срок: <b>{d.duration_days:g} игровых дней</b>\n"
            f"📈 Что даёт: <b>{esc(d.effect)}</b>\n\n"
            "Выберите свою провинцию:"
        )
        await self.show(callback, text, types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    await _v19_handle_construction_prev(self, callback, data)
WorldApp.handle_construction = _v20_handle_construction

                                                              
