async def _v20_simulation_run(self: SimulationEngine) -> None:
    while not self._stop.is_set():
        loop_start = time.monotonic()
        real_delta = max(0.0, loop_start - self.last_loop_real)
        self.last_loop_real = loop_start
        self.save_accum_real += real_delta
        try:
            async with self.app.world.simulation_lock:
                self.app.world.speed = 1.0
                state = getattr(self.app.world, "server_state", {}) or {}
                can_run = bool(state.get("work_enabled", True)) and not bool(state.get("maintenance", False))
                if can_run and not self.app.world.paused and REALTIME_GAME_TIME and real_delta > 0:
                    self.advance(real_delta / 60.0)
                if self.save_accum_real >= AUTOSAVE_REAL_SECONDS and self.app.world.settings.get("autosave_enabled", True) and self.app.world.dirty:
                    await asyncio.to_thread(self.app.save_manager.save, self.app.world, True)
                    self.app.world.dirty = False
                    self.save_accum_real = 0.0
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.app.world.add_log("simulation_error", None, {"error": repr(exc)})
        await asyncio.sleep(1.0)
SimulationEngine._run = _v20_simulation_run

                                                                             
                                                                          
                                                           
async def _v20_server_handle_country_message(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    uid = int(callback.from_user.id)
    if not self.world.is_server_admin(uid):
        await self.show(callback, "❌ Нет доступа к серверной панели.", _v15_server_keyboard())
        return True
    if data == "server:country_message":
        rows = [[Keyboards.btn(COUNTRY_NAMES[c], f"server:countrymsgto:{c}")] for c in PLAYABLE_COUNTRIES]
        rows += Keyboards.nav("server:panel")
        await self.show(callback, "📨 Выберите страну для сообщения от администрации.", types.InlineKeyboardMarkup(inline_keyboard=rows))
        return True
    if data.startswith("server:countrymsgto:"):
        country = data.split(":", 2)[2]
        if country not in PLAYABLE_COUNTRIES:
            await self.show(callback, "❌ Страна не найдена.", _v12_server_panel_keyboard()); return True
        p = self.player(uid)
        p.pending_input = "admin_country_message"
        p.pending_data = {"country": country, "expires_at": time.monotonic() + 600}
        await self.show(callback, f"📨 Введите сообщение для страны <b>{esc(COUNTRY_NAMES[country])}</b>:", Keyboards.simple_nav("server:panel"))
        return True
    return False

_v20_server_handle_prev = _v19_server_handle
