def _v22_player(self: WorldApp, user_id: int, username: str = "") -> Any:
    player = self.world.players.get(int(user_id))
    if player is None:
        player = self.world.register_player(int(user_id), username)
    else:
        player.touch(username)
                                                                             
    if not hasattr(player, "active_country"):
        player.active_country = player.country if player.country in PLAYABLE_COUNTRIES else None
    if not hasattr(player, "admin_mode"):
        player.admin_mode = bool(player.role == "admin" and player.country is None and player.active_country is None)
    if player.country in PLAYABLE_COUNTRIES and not player.admin_mode:
        player.active_country = player.country
    return player

WorldApp.player = _v22_player


def _v22_country_for(self: WorldApp, user_id: int) -> Optional[str]:
    player = self.world.players.get(int(user_id))
    if not player or player.banned:
        return None
                                                                             
    if bool(getattr(player, "admin_mode", False)):
        return None
    current = getattr(player, "country", None)
    if current in PLAYABLE_COUNTRIES:
        player.active_country = current
        return current
    remembered = getattr(player, "active_country", None)
    if remembered not in PLAYABLE_COUNTRIES:
        return None
    owners = [
        other for other in self.world.players.values()
        if other.user_id != player.user_id
        and not other.banned
        and other.role != "admin"
        and other.country == remembered
        and not getattr(other, "admin_mode", False)
    ]
                                                                            
                                                                
    if owners:
        return None
    player.country = remembered
    player.active_country = remembered
    self.world.mark_dirty()
    self.world.add_log("country_session_restored", int(user_id), {"country": remembered})
    return remembered

WorldApp.country_for = _v22_country_for


def _v22_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    player = self.world.players.get(int(user_id))
    if player and player.banned:
        return None, "⛔ Вы заблокированы."
    country = self.country_for(int(user_id))
    if not country:
        return None, "🌍 Сначала выберите страну."
    return country, ""

WorldApp.require_country = _v22_require_country

                                                                              
def _v22_set_admin(self: WorldState, user_id: int, enabled: bool) -> None:
    player = self.register_player(int(user_id))
    if enabled:
        if player.country in PLAYABLE_COUNTRIES:
            player.active_country = player.country
        elif getattr(player, "active_country", None) not in PLAYABLE_COUNTRIES:
            player.active_country = None
        player.role = "admin"
        player.admin_mode = True
        player.country = None
    else:
        player.role = "player"
        player.admin_mode = False
        self.set_server_admin(int(user_id), False)
        remembered = getattr(player, "active_country", None)
        if remembered in PLAYABLE_COUNTRIES:
            player.country = remembered
    player.clear_input()
    self.dirty = True

WorldState.set_admin = _v22_set_admin


def _v22_set_country(self: WorldState, user_id: int, code: Optional[str]) -> bool:
    player = self.register_player(int(user_id))
    if code is not None and code not in PLAYABLE_COUNTRIES:
        return False
    if code is not None and player.role != "admin":
        for other in self.players.values():
            if (other.user_id != player.user_id and not other.banned
                    and other.role != "admin" and not getattr(other, "admin_mode", False)
                    and other.country == code):
                return False
    old = player.country
    if code in PLAYABLE_COUNTRIES:
        player.country = code
        player.active_country = code
                                                                    
        player.admin_mode = False
    else:
        player.country = None
        player.active_country = None
        player.admin_mode = False
    player.clear_input()
    self.dirty = True
    self.add_log("country_switch", int(user_id), {"old": old, "new": code})
    return True

WorldState.set_country = _v22_set_country


