async def _v22_handle_country(self: WorldApp, callback: types.CallbackQuery, code: str) -> None:
    uid = int(callback.from_user.id)
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")
    p.clear_input()                                                                   
    if code == "admin":
        if self.is_admin(uid):
            p.admin_mode = True
            await self.render_admin_home(callback)
            return
        p.pending_input = "admin_code"
        p.pending_data = {"expires_at": time.monotonic() + 180}
        await self.show(callback, "🛠️ <b>Вход администратора</b>\n\nВведите код администратора:",
                        Keyboards.simple_nav("country:picker"))
        return
    if code not in PLAYABLE_COUNTRIES and code != COUNTRY_TEST:
        await self.show(callback, "❌ Такая страна недоступна.", Keyboards.country_picker())
        return
    p.pending_input = "country_code"
    p.pending_data = {
        "country": code,
        "expires_at": time.monotonic() + 180,
        "source": "country_picker",
    }
    await self.show(callback,
                    f"🔐 <b>{esc(COUNTRY_NAMES.get(code, code))}</b>\n\nВведите код страны:",
                    Keyboards.simple_nav("country:picker"))

WorldApp.handle_country = _v22_handle_country

                                                                              
async def _v22_on_back(self: WorldApp, message: types.Message) -> None:
    uid = int(message.from_user.id)
    p = self.player(uid, getattr(message.from_user, "username", "") or "")
    p.clear_input()
    if bool(getattr(p, "admin_mode", False)) and self.is_admin(uid):
        await self.render_admin_home(message)
        return
    if p.country in PLAYABLE_COUNTRIES:
        old = p.country
        p.country = None
        p.active_country = None
        p.admin_mode = False
        self.world.add_log("country_release", uid, {"country": old})
        self.world.mark_dirty()
    await self.show_new(message, "🌍 <b>Выбор страны</b>", Keyboards.country_picker())

WorldApp.on_back = _v22_on_back

                                                                               
_v22_text_prev = WorldApp.on_text
async def _v22_on_text(self: WorldApp, message: types.Message) -> None:
    if not getattr(message, "text", None):
        return
    uid = int(message.from_user.id)
    p = self.player(uid, getattr(message.from_user, "username", "") or "")
    pending = str(p.pending_input or "")
    value = str(message.text).strip()

                  
    if pending == "server_code":
        pdata = dict(p.pending_data or {})
        if int(pdata.get("owner_user_id", uid)) != uid:
            return
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код доступа просрочен. Введите /server снова.")
            return
        if value != SERVER_CONTROL_CODE:
            await self.show_new(message, "❌ Неверный код серверной панели. Попробуйте ещё раз.")
            return
        self.world.set_server_admin(uid, True)
        p.clear_input()
        self.world.mark_dirty()
        await _v12_server_panel(self, message)
        return

                 
    if pending == "admin_code":
        expires = float((p.pending_data or {}).get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код администратора просрочен. Введите /admin снова.")
            return
        if self.admin.authenticate(uid, value):
            p.admin_mode = True
            p.clear_input()
            await self.render_admin_home(message)
        else:
            await self.show_new(message, "❌ Неверный код администратора. Повторите ввод или нажмите /back.")
        return

                                                                          
                                                        
    if pending == "country_code":
        pdata = dict(p.pending_data or {})
        code = str(pdata.get("country", ""))
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код страны просрочен. Нажмите /start и выберите страну снова.", Keyboards.country_picker())
            return
        expected = str(COUNTRY_ACCESS_CODES.get(code, ""))
        if code not in PLAYABLE_COUNTRIES and code != COUNTRY_TEST:
            p.clear_input()
            await self.show_new(message, "❌ Такая страна недоступна.", Keyboards.country_picker())
            return
        if value != expected:
            await self.show_new(message,
                                f"❌ Неверный код страны.\n\nВведите код страны {esc(COUNTRY_NAMES.get(code, code))}:",
                                Keyboards.simple_nav("country:picker"))
            return
        if code == COUNTRY_TEST:
            p.clear_input()
            p.current_screen = "test"
            await self.show_new(message, "✅ Доступ к техническому режиму ТЕСТ разрешён.", Keyboards.simple_nav("country:picker"))
            return
        if not self.world.set_country(uid, code):
            await self.show_new(message, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        p.clear_input()
        self.world.add_log("country_login_success", uid, {"country": code})
        self.world.mark_dirty()
        await self.render_home(message)
        return

                                                                 
    await _v22_text_prev(self, message)

WorldApp.on_text = _v22_on_text

                                                                               
def _v22_server_keyboard() -> types.InlineKeyboardMarkup:
    return _v12_server_panel_keyboard()


async def _v22_server_handler(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    uid = int(callback.from_user.id)
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")

                                                                           
    if data == "server:logout":
        self.world.set_server_admin(uid, False)
        p.clear_input()
        self.world.mark_dirty()
        if self.is_admin(uid):
                                                                  
            p.admin_mode = True
            await self.render_admin_home(callback)
            return True
        p.admin_mode = False
        country = self.country_for(uid)
        if country:
            await self.show(callback, "✅ Вы вышли из серверной панели.", Keyboards.home())
            return True
        await self.show(callback, "✅ Вы вышли из серверной панели.", Keyboards.country_picker())
        return True

                                                                             
                                                                         
    if not self.world.is_server_admin(uid):
        if self.is_admin(uid):
            self.world.set_server_admin(uid, True)
        else:
            await self.show(callback, "❌ Нет доступа к серверной панели.", _v22_server_keyboard())
            return True

    state = getattr(self.world, "server_state", None) or _v12_server_default_state()
    self.world.server_state = state

    try:
        if data == "server:panel":
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:time_pause":
            state["time_running"] = False
            state["paused_before_time_pause"] = bool(self.world.paused)
            self.world.paused = True
            self.world.mark_dirty()
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:time_resume":
            if state.get("maintenance") or not state.get("work_enabled", True):
                await self.show(callback, "❌ Сначала возобновите работу сервера и завершите техработы.", _v22_server_keyboard())
                return True
            self.world.paused = False
            state["time_running"] = True
            self.world.mark_dirty()
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:stop":
            state["paused_before_server_stop"] = bool(self.world.paused)
            state["work_enabled"] = False
            state["time_running"] = False
            self.world.paused = True
            self.world.mark_dirty()
            self.world.add_log("server_stop", uid, {})
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:resume":
            state["work_enabled"] = True
            restore_paused = bool(state.pop("paused_before_server_stop", False))
            if not state.get("maintenance"):
                self.world.paused = restore_paused
                state["time_running"] = not restore_paused
            self.world.mark_dirty()
            self.world.add_log("server_resume", uid, {})
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:maintenance_on":
            state["paused_before_maintenance"] = bool(self.world.paused)
            state["maintenance"] = True
            state["work_enabled"] = False
            state["time_running"] = False
            self.world.paused = True
            self.world.mark_dirty()
            self.spawn(self._broadcast_server_maintenance(True))
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:maintenance_off":
            was_paused = bool(state.pop("paused_before_maintenance", False))
            state["maintenance"] = False
            state["work_enabled"] = True
            self.world.paused = was_paused
            state["time_running"] = not was_paused
            self.world.mark_dirty()
            self.spawn(self._broadcast_server_maintenance(False))
            await self.show(callback, _v12_server_panel_text(self), _v22_server_keyboard())
            return True
        if data == "server:clock":
            await _v12_server_clock_screen(self, callback)
            return True
        if data == "server:logs":
            await _v12_server_logs_screen(self, callback)
            return True
        if data == "server:clear_logs":
            self.world.logs.clear()
            self.world.mark_dirty()
            self.world.add_log("server_logs_clear", uid, {})
            await self.show(callback, "✅ Логи очищены.", _v22_server_keyboard())
            return True
        if data == "server:diagnostics":
            diagnostic = self.test_summary()
            await self.show(callback, diagnostic, Keyboards.simple_nav("server:panel"))
            return True
        if data == "server:save":
            async with self.world.simulation_lock:
                await asyncio.to_thread(self.save_manager.save, self.world, False)
                self.world.dirty = False
            self.world.add_log("server_save", uid, {})
            await self.show(callback, "✅ Состояние сервера сохранено.", _v22_server_keyboard())
            return True
        if data == "server:backup":
            primary = Path(self.save_manager.primary)
            if not primary.exists():
                await self.show(callback, "❌ Нечего копировать: основное сохранение ещё не создано.", _v22_server_keyboard())
                return True
            await asyncio.to_thread(self.save_manager.create_backup)
            self.world.add_log("server_backup", uid, {})
            await self.show(callback, "✅ Резервная копия создана.", _v22_server_keyboard())
            return True
        if data == "server:restore":
            admin_before = self.is_admin(uid)
                                                                               
                                                                               
                                                                            
            current_session = copy.deepcopy(self.world.players.get(uid))
            async with self.world.simulation_lock:
                ok = await asyncio.to_thread(self.save_manager.restore)
                warnings: list[Any] = []
                if ok:
                    warnings = await asyncio.to_thread(self.save_manager.load, self.world)
                    if current_session is not None:
                        restored_player = self.world.players.get(uid)
                        if restored_player is None:
                            self.world.players[uid] = current_session
                            restored_player = current_session
                        else:
                            restored_player.username = current_session.username
                            restored_player.country = current_session.country
                            restored_player.active_country = current_session.active_country
                            restored_player.admin_mode = getattr(current_session, "admin_mode", False)
                            restored_player.role = current_session.role
                            restored_player.banned = current_session.banned
                            restored_player.current_screen = current_session.current_screen
                            restored_player.current_message_id = current_session.current_message_id
                        restored_player.clear_input()
                    self.world.set_server_admin(uid, True)
                    if admin_before:
                        self.world.set_admin(uid, True)
                        restored_after = self.world.players.get(uid)
                        if restored_after is not None:
                            restored_after.admin_mode = getattr(current_session, "admin_mode", True) if current_session is not None else True
                    self.simulation.production_accum = 0.0
                    self.simulation.daily_accum = 0.0
                    self.simulation.army_accum = 0.0
                    self.simulation.air_accum = 0.0
                    self.simulation.trade_accum = 0.0
                    self.simulation.last_loop_real = time.monotonic()
                    self.world.mark_dirty()
            msg = "✅ Backup восстановлен." if ok else "❌ Backup не найден."
            if ok and warnings:
                msg += f"\nПредупреждений: {len(warnings)}"
            await self.show(callback, msg, _v22_server_keyboard())
            return True
        if data == "server:clear_notifications":
            self.world.notifications.clear()
            self.world.add_log("server_notification_clear", uid, {})
            self.world.mark_dirty()
            await self.show(callback, "✅ Очередь уведомлений очищена.", _v22_server_keyboard())
            return True
        if data == "server:country_message":
            rows = [[Keyboards.btn(COUNTRY_NAMES[c], f"server:countrymsgto:{c}")] for c in PLAYABLE_COUNTRIES]
            rows += Keyboards.nav("server:panel")
            await self.show(callback, "📨 Выберите страну для сообщения от администрации.",
                            types.InlineKeyboardMarkup(inline_keyboard=rows))
            return True
        if data.startswith("server:countrymsgto:"):
            country = data.split(":", 2)[2]
            if country not in PLAYABLE_COUNTRIES:
                await self.show(callback, "❌ Страна не найдена.", _v22_server_keyboard())
                return True
            p.pending_input = "admin_country_message"
            p.pending_data = {"country": country, "expires_at": time.monotonic() + 600}
            await self.show(callback,
                            f"📨 Введите сообщение для страны <b>{esc(COUNTRY_NAMES[country])}</b>:",
                            Keyboards.simple_nav("server:panel"))
            return True
        return False
    except Exception as exc:
        self.world.add_log("server_callback_error", uid, {"data": data[:80], "error": repr(exc)})
        await self.show(callback,
                        "❌ Ошибка серверной панели. Запись добавлена в диагностику.",
                        _v22_server_keyboard())
        return True

                                                                          
                                                                     
_v22_callback_prev = WorldApp.on_callback
