_V23_REAL_DELTA_MAX = 2.0

async def _v23_simulation_run(self: SimulationEngine) -> None:
    while not self._stop.is_set():
        loop_start = time.monotonic()
        raw_delta = max(0.0, loop_start - self.last_loop_real)
        self.last_loop_real = loop_start
        real_delta = min(raw_delta, _V23_REAL_DELTA_MAX)
        self.save_accum_real += real_delta
        try:
            async with self.app.world.simulation_lock:
                self.app.world.speed = 1.0
                state = getattr(self.app.world, "server_state", {}) or {}
                can_run = bool(state.get("work_enabled", True)) and not bool(state.get("maintenance", False))
                if can_run and not self.app.world.paused and REALTIME_GAME_TIME and real_delta > 0:
                    self.advance(real_delta / 60.0)
                if self.save_accum_real >= AUTOSAVE_REAL_SECONDS:
                    if self.app.world.settings.get("autosave_enabled", True) and self.app.world.dirty:
                        await asyncio.to_thread(self.app.save_manager.save, self.app.world, True)
                        self.app.world.dirty = False
                                                                              
                                                                            
                    self.save_accum_real = 0.0
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.app.world.add_log("simulation_error", None, {"error": repr(exc)})
        await asyncio.sleep(1.0)

SimulationEngine._run = _v23_simulation_run


                                                                              
                                                    
                                                                              
                                                                        
                                                                               
                                                            

async def _v24_repair_player_session(self: WorldApp, user_id: int, username: str = "") -> Any:
    p = self.world.players.get(int(user_id))
    if p is None:
        p = self.world.register_player(int(user_id), username)
    else:
        p.touch(username)
    if not hasattr(p, "active_country"):
        p.active_country = p.country if getattr(p, "country", None) in PLAYABLE_COUNTRIES else None
    if not hasattr(p, "admin_mode"):
        p.admin_mode = False
                                                        
    if getattr(p, "country", None) in PLAYABLE_COUNTRIES:
        p.active_country = p.country
                                                                       
        return p
                                                                             
                                             
    remembered = getattr(p, "active_country", None)
    if remembered in PLAYABLE_COUNTRIES and not bool(getattr(p, "admin_mode", False)):
        p.country = remembered
        self.world.mark_dirty()
        self.world.add_log("country_session_repaired", int(user_id), {"country": remembered})
    return p

WorldApp.repair_player_session = _v24_repair_player_session


def _v24_country_for(self: WorldApp, user_id: int) -> Optional[str]:
    p = self.world.players.get(int(user_id))
    if p is None or p.banned:
        return None
                                                                             
                                                           
    if bool(getattr(p, "admin_mode", False)):
        return None
    current = getattr(p, "country", None)
    if current in PLAYABLE_COUNTRIES:
        p.active_country = current
        return current
    remembered = getattr(p, "active_country", None)
    if remembered in PLAYABLE_COUNTRIES:
        p.country = remembered
        self.world.mark_dirty()
        return remembered
    return None

WorldApp.country_for = _v24_country_for


def _v24_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    p = self.world.players.get(int(user_id))
    if p and p.banned:
        return None, "⛔ Вы заблокированы."
    country = self.country_for(int(user_id))
    if country:
        return country, ""
    return None, "🌍 Сначала выберите страну."

WorldApp.require_country = _v24_require_country

async def _v24_render_home(self: WorldApp, target: types.Message | types.CallbackQuery) -> None:
    uid = int(target.from_user.id)
    p = await self.repair_player_session(uid, getattr(target.from_user, "username", "") or "")
    if bool(getattr(p, "admin_mode", False)) and self.is_admin(uid):
        await self.render_admin_home(target)
        return
    country = self.country_for(uid)
    if not country:
        await self.show(target,
                        f"{APP_TITLE}\n\nВыберите страну для начала игры.\n🧪 ТЕСТ — техническая страна без территории.",
                        Keyboards.country_picker())
        return
    p.current_screen = "home"
    await self.show(target, self.home_text(country), Keyboards.home())

WorldApp.render_home = _v24_render_home

