WorldApp._session_country = {}


def _v25_session_country(self: WorldApp, user_id: int) -> Optional[str]:
    uid = int(user_id)
    p = self.world.players.get(uid)
    if p is None or p.banned or bool(getattr(p, "admin_mode", False)):
        return None
    current = getattr(self, "_session_country", {}).get(uid)
    if current in PLAYABLE_COUNTRIES:
                                                                            
        if getattr(p, "country", None) != current:
            p.country = current
        p.active_country = current
        return current
    saved = getattr(p, "country", None)
    if saved in PLAYABLE_COUNTRIES:
        self._session_country[uid] = saved
        p.active_country = saved
        return saved
    saved = getattr(p, "active_country", None)
    if saved in PLAYABLE_COUNTRIES:
        self._session_country[uid] = saved
        p.country = saved
        return saved
    return None


def _v25_set_session_country(self: WorldApp, user_id: int, country: str) -> bool:
    uid = int(user_id)
    if country not in PLAYABLE_COUNTRIES:
        return False
    p = self.player(uid)
    self._session_country[uid] = country
    p.country = country
    p.active_country = country
    p.admin_mode = False
    p.current_screen = "home"
    p.clear_input()
    self.world.mark_dirty()
    return True


def _v25_clear_session_country(self: WorldApp, user_id: int) -> None:
    uid = int(user_id)
    self._session_country.pop(uid, None)
    p = self.world.players.get(uid)
    if p is not None:
        p.country = None
        p.active_country = None
        p.current_screen = "home"
        p.clear_input()
    self.world.mark_dirty()


_v25_init_prev = WorldApp.__init__
def _v25_init(self: WorldApp, *args: Any, **kwargs: Any) -> None:
    _v25_init_prev(self, *args, **kwargs)
                                                                                     
    self._session_country = {}

WorldApp.__init__ = _v25_init

WorldApp.session_country = _v25_session_country
WorldApp.set_session_country = _v25_set_session_country
WorldApp.clear_session_country = _v25_clear_session_country


def _v25_country_for(self: WorldApp, user_id: int) -> Optional[str]:
    return self.session_country(int(user_id))

WorldApp.country_for = _v25_country_for


def _v25_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    p = self.world.players.get(int(user_id))
    if p is not None and p.banned:
        return None, "⛔ Вы заблокированы."
    country = self.session_country(int(user_id))
    if country:
        return country, ""
    return None, "🌍 Сначала выберите страну."

WorldApp.require_country = _v25_require_country

                                                                                 
_v25_handle_country_prev = WorldApp.handle_country
async def _v25_handle_country(self: WorldApp, callback: types.CallbackQuery, code: str) -> None:
    if code in PLAYABLE_COUNTRIES:
        uid = int(callback.from_user.id)
        p = self.player(uid, getattr(callback.from_user, "username", "") or "")
                                                                           
        p.clear_input()
        if not self.world.set_country(uid, code):
            await self.show(callback, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        self.set_session_country(uid, code)
        self.world.add_log("authoritative_country_login", uid, {"country": code})
        await self.render_home(callback)
        return
