async def _v25_process_text_input(self: WorldApp, player: Any, value: str) -> str:
    action = str(player.pending_input or "")
    pdata = dict(player.pending_data or {})
    if action == "country_code":
        code = str(pdata.get("country", ""))
        if code not in PLAYABLE_COUNTRIES:
            return "❌ Такая страна недоступна."
        expected = str(COUNTRY_ACCESS_CODES.get(code, code))
        if value != expected:
            return f"❌ Неверный код страны.\n\nВведите код страны {esc(COUNTRY_NAMES.get(code, code))}:"
        if not self.world.set_country(player.user_id, code):
            return "❌ Эта страна уже занята другим игроком."
        self.set_session_country(player.user_id, code)
        player.clear_input()
        self.world.add_log("authoritative_country_login", player.user_id, {"country": code})
        return f"✅ Вход выполнен. Вы играете за {COUNTRY_NAMES[code]}."
    return await _v25_process_text_prev(self, player, value)

