async def _v27_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "")
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")

    if p.banned:
        await self.answer_callback(callback)
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

                                                                                 
    free_routes = (
        data in {"noop", "country:picker", "admin:home", "admin:logout", "home"}
        or data.startswith("country:")
        or data.startswith("admin:")
        or data.startswith("server:")
    )

                                                                           
                                                                            
                                                                   
    if not free_routes:
        country = self._v27_game_country(uid)
        if not country:
            await self.answer_callback(callback)
            await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
            return

    await _v27_on_callback_prev(self, callback)



                                                                            
                                                         
