def _v28_country_menu_keyboard(country: str) -> types.InlineKeyboardMarkup:
    rows = [
        [Keyboards.btn("🏭 Производство", f"croute:{country}:production"), Keyboards.btn("🗺️ Карта", f"croute:{country}:map")],
        [Keyboards.btn("🏛️ Страна", f"croute:{country}:country"), Keyboards.btn("🪖 Армия", f"croute:{country}:army")],
        [Keyboards.btn("✈️ Авиация", f"croute:{country}:air"), Keyboards.btn("🛡️ ПВО", f"croute:{country}:pvo")],
        [Keyboards.btn("⚓ Флот", f"croute:{country}:navy"), Keyboards.btn("🤝 Дипломатия", f"croute:{country}:diplomacy")],
        [Keyboards.btn("🚛 Торговля", f"croute:{country}:trade"), Keyboards.btn("📦 Склад", f"croute:{country}:warehouse")],
        [Keyboards.btn("📜 Решения", f"croute:{country}:decisions"), Keyboards.btn("🏗️ Строительство", f"croute:{country}:construction")],
        [Keyboards.btn("🛠️ Ремонт", f"croute:{country}:repair"), Keyboards.btn("📜 Журнал", f"croute:{country}:journal")],
        [Keyboards.btn("📰 Новости", f"croute:{country}:news"), Keyboards.btn("❓ Объяснения", f"croute:{country}:help")],
        [Keyboards.btn("🌍 Выбор страны", "country:picker")],
    ]
    return types.InlineKeyboardMarkup(inline_keyboard=rows)


def _v28_country_route_data(country: str, target: str) -> str:
    if target == "home":
        return f"croute:{country}:home"
    if target == "country:economy":
        return f"croute:{country}:country"
    if target.startswith("screen:"):
        return f"croute:{country}:{target.split(':', 1)[1]}"
    return target


def _v28_rewrite_markup_for_country(
    markup: Optional[types.InlineKeyboardMarkup],
    country: Optional[str],
) -> Optional[types.InlineKeyboardMarkup]:
    if markup is None or country not in PLAYABLE_COUNTRIES:
        return markup
    changed = False
    new_rows = []
    for row in markup.inline_keyboard:
        new_row = []
        for button in row:
            data = getattr(button, "callback_data", None)
            if data in {"home", "country:economy"} or (isinstance(data, str) and data.startswith("screen:")):
                new_data = _v28_country_route_data(country, data)
                try:
                    button = button.model_copy(update={"callback_data": new_data})
                except Exception:
                    button = types.InlineKeyboardButton(text=button.text, callback_data=new_data)
                changed = True
            new_row.append(button)
        new_rows.append(new_row)
    if not changed:
        return markup
    try:
        return markup.model_copy(update={"inline_keyboard": new_rows})
    except Exception:
        return types.InlineKeyboardMarkup(inline_keyboard=new_rows)


                                                                           
                                                                             
                                                                  
