_v28_on_callback_prev = WorldApp.on_callback
async def _v28_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "")

    if data.startswith("croute:"):
        parts = data.split(":", 2)
        if len(parts) != 3:
            await self.answer_callback(callback)
            await self.show(callback, "❌ Некорректный маршрут.", _v28_country_menu_keyboard(self.country_for(uid) or COUNTRY_RAZBAGARE))
            return
        route_country, target = parts[1], parts[2]
        current = self.country_for(uid)
        await self.answer_callback(callback)
        if current not in PLAYABLE_COUNTRIES:
            await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
            return
        if route_country != current:
            await self.show(callback, "⚠️ Это меню относится к другой стране. Открыто меню вашей текущей страны.", _v28_country_menu_keyboard(current))
            return
        if target == "home":
            await self.render_home(callback)
            return
        await self.handle_screen(callback, target)
        return

                                                                            
                                                                           
                                                               
    if data == "home" or data == "country:economy" or data.startswith("screen:"):
        current = self.country_for(uid)
        await self.answer_callback(callback)
        if current not in PLAYABLE_COUNTRIES:
            await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
            return
        if data == "home":
            await self.render_home(callback)
        elif data == "country:economy":
            await self.handle_screen(callback, "country")
        else:
            await self.handle_screen(callback, data.split(":", 1)[1])
        return

    await _v28_on_callback_prev(self, callback)



