V29_AUTHENTICATED_PENDING = {"admin_code", "server_code"}


def _v29_is_playable_country(value: Any) -> bool:
    return str(value) in PLAYABLE_COUNTRIES


def _v29_bootstrap_auth(self: WorldApp) -> None:
    if not hasattr(self, "_session_country"):
        self._session_country = {}
    for p in self.world.players.values():
        country = getattr(p, "country", None)
        active = getattr(p, "active_country", None)
        if _v29_is_playable_country(country):
            p.active_country = country
            self._session_country[int(p.user_id)] = country
                                                                            
                                             
            if p.pending_input in {"admin_code", "server_code"}:
                p.clear_input()
        elif _v29_is_playable_country(active):
                                                                              
                                       
            owners = [
                other for other in self.world.players.values()
                if int(other.user_id) != int(p.user_id)
                and not getattr(other, "banned", False)
                and getattr(other, "role", "player") != "admin"
                and getattr(other, "country", None) == active
            ]
            if not owners:
                p.country = active
                self._session_country[int(p.user_id)] = active
                if p.pending_input in {"admin_code", "server_code"}:
                    p.clear_input()
    self.world.dirty = bool(getattr(self.world, "dirty", False))

_v29_init_prev = WorldApp.__init__
def _v29_init(self: WorldApp, *args: Any, **kwargs: Any) -> None:
    _v29_init_prev(self, *args, **kwargs)
    _v29_bootstrap_auth(self)

WorldApp.__init__ = _v29_init


def _v29_game_country(self: WorldApp, user_id: int) -> Optional[str]:
    uid = int(user_id)
    p = self.world.players.get(uid)
    if p is None or bool(getattr(p, "banned", False)):
        return None
    session = getattr(self, "_session_country", {})

    direct = getattr(p, "country", None)
    if _v29_is_playable_country(direct):
        p.active_country = direct
        session[uid] = direct
        return direct

    runtime = session.get(uid)
    if _v29_is_playable_country(runtime):
        p.country = runtime
        p.active_country = runtime
        return runtime

    saved = getattr(p, "active_country", None)
    if _v29_is_playable_country(saved):
        owners = [
            other for other in self.world.players.values()
            if int(other.user_id) != uid
            and not getattr(other, "banned", False)
            and getattr(other, "role", "player") != "admin"
            and getattr(other, "country", None) == saved
        ]
        if not owners:
            p.country = saved
            p.active_country = saved
            session[uid] = saved
            self.world.mark_dirty()
            return saved
    return None

WorldApp._v29_game_country = _v29_game_country
WorldApp.country_for = _v29_game_country


def _v29_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    p = self.world.players.get(int(user_id))
    if p is not None and bool(getattr(p, "banned", False)):
        return None, "⛔ Вы заблокированы."
    country = self._v29_game_country(int(user_id))
    if country:
        return country, ""
    return None, "🌍 Сначала выберите страну."

WorldApp.require_country = _v29_require_country


