async def _v29_on_text(self: WorldApp, message: types.Message) -> None:
    if not getattr(message, "text", None):
        return
    uid = int(message.from_user.id)
    p = self.player(uid, getattr(message.from_user, "username", "") or "")
    value = str(message.text).strip()
    pending = str(getattr(p, "pending_input", "") or "")
    pdata = dict(getattr(p, "pending_data", {}) or {})
    current = self._v29_game_country(uid)

                                                                               
                                                                              
                                                                          
    if pending == "country_code":
        code = str(pdata.get("country", ""))
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код страны просрочен. Выберите страну снова.", Keyboards.country_picker())
            return
        expected = str(COUNTRY_ACCESS_CODES.get(code, ""))
        if code not in PLAYABLE_COUNTRIES and code != COUNTRY_TEST:
            p.clear_input()
            await self.show_new(message, "❌ Такая страна недоступна.", Keyboards.country_picker())
            return
        if value != expected:
            await self.show_new(
                message,
                f"❌ Неверный код страны {esc(COUNTRY_NAMES.get(code, code))}.\n\nВведите код страны ещё раз:",
                Keyboards.simple_nav("country:picker"),
            )
            return
        if code == COUNTRY_TEST:
            p.clear_input()
            p.current_screen = "test"
            await self.show_new(message, "✅ Доступ к техническому режиму ТЕСТ разрешён.")
            return
                                                                              
                                                   
        if not self.world.set_country(uid, code):
            await self.show_new(message, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        if not hasattr(self, "_session_country"):
            self._session_country = {}
        self._session_country[uid] = code
        p.admin_mode = False
        p.clear_input()
        p.current_screen = "home"
        self.world.mark_dirty()
        await self.render_home(message)
        return

                                                                               
                                                                                
    if current and pending == "admin_code" and pdata.get("context") != "admin_login":
        p.clear_input()
        pending = ""
    if current and pending == "server_code" and pdata.get("context") != "server_login":
        p.clear_input()
        pending = ""

    await _v29_on_text_prev(self, message)

WorldApp.on_text = _v29_on_text


                                                                  
