_v29_on_callback_prev = WorldApp.on_callback
async def _v29_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "")
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")

    if getattr(p, "banned", False):
        await self.answer_callback(callback)
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

    current = self._v29_game_country(uid)

                                           
    if data == "country:picker":
        p.clear_input()
        await self.answer_callback(callback)
        await self.show(callback, "🌍 <b>Выбор страны</b>", Keyboards.country_picker())
        return
    if data.startswith("country:"):
        await self.answer_callback(callback)
        await self.handle_country(callback, data.split(":", 1)[1])
        return

                                   
    if data.startswith("croute:"):
        parts = data.split(":", 2)
        await self.answer_callback(callback)
        if len(parts) != 3:
            if current:
                await self.show(callback, "❌ Некорректный маршрут.", _v28_country_menu_keyboard(current))
            else:
                await self.show(callback, "🌍 Выберите страну.", Keyboards.country_picker())
            return
        route_country, target = parts[1], parts[2]
        if not current:
            await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
            return
        if route_country != current:
            await self.show(callback, "⚠️ Это меню другой страны. Открыто меню вашей текущей страны.", _v28_country_menu_keyboard(current))
            return
        p.clear_input()
        if target == "home":
            await self.render_home(callback)
        else:
            await self.handle_screen(callback, target)
        return

                                                                       
                                                                             
    free = data == "noop" or data.startswith("admin:") or data.startswith("server:")
    if current and not free:
        if p.pending_input in {"admin_code", "server_code"}:
            p.clear_input()
                                                                         
                                                     
        if p.pending_input == "country_code" and not data.startswith("country:"):
            p.clear_input()

    await _v29_on_callback_prev(self, callback)


