_old_country_from_dict_v31 = Country.from_dict.__func__ if isinstance(Country.from_dict, classmethod) else Country.from_dict

@classmethod
def _v31_country_from_dict(cls, d: dict[str, Any]) -> "Country":
    raw = dict(d or {})
    defaults = {
        "resources": copy.deepcopy(INITIAL_RESOURCES),
        "warehouse": copy.deepcopy(INITIAL_WAREHOUSE),
        "province_ids": [],
        "production_lines": {},
        "active_decisions": {},
        "message_history": [],
        "relations": {},
        "infinite_weapons": False,
        "industry_modifier": 1.0,
        "construction_modifier": 1.0,
        "repair_modifier": 1.0,
        "business_centers": 0,
        "war_exhaustion": 0.0,
    }
    for key, default in defaults.items():
        if key not in raw or raw.get(key) is None:
            raw[key] = copy.deepcopy(default)
    for k in RESOURCE_KEYS:
        raw["resources"].setdefault(k, 0)
    for k in EQUIPMENT_KEYS:
        raw["warehouse"].setdefault(k, 0)
    scalar_defaults = {
        "code": "", "name": "", "flag": "🌍", "population": 0, "manpower": 0,
        "budget": 0, "income_daily": 0, "civilian_factories": 0,
        "military_factories": 0, "power_plants": 0, "power_capacity": 0,
        "substations": 0, "substation_capacity": 0, "stability": 60.0,
        "war_support": 20.0,
    }
    for key, default in scalar_defaults.items():
        raw.setdefault(key, default)
    payload = {name: raw.get(name) for name in cls.__dataclass_fields__}
    obj = cls(**payload)
    obj.ensure_resources()
    obj.ensure_warehouse()
    return obj

Country.from_dict = _v31_country_from_dict

                                                       
def _v31_game_country(self: WorldApp, user_id: int) -> Optional[str]:
    uid = int(user_id)
    p = self.world.players.get(uid)
    if p is None or bool(getattr(p, "banned", False)):
        return None

                                                                        
    direct = getattr(p, "country", None)
    if direct in PLAYABLE_COUNTRIES:
        p.active_country = direct
        if hasattr(self, "_session_country"):
            self._session_country[uid] = direct
        return direct

                                                                           
    remembered = getattr(p, "active_country", None)
    if remembered in PLAYABLE_COUNTRIES:
                                                                             
                                                                      
        occupied_by_other = any(
            int(o.user_id) != uid
            and not bool(getattr(o, "banned", False))
            and getattr(o, "country", None) == remembered
            and getattr(o, "role", "player") != "admin"
            for o in self.world.players.values()
        )
        if not occupied_by_other:
            p.country = remembered
            if hasattr(self, "_session_country"):
                self._session_country[uid] = remembered
            self.world.mark_dirty()
            return remembered

                                                                                  
    runtime = getattr(self, "_session_country", {}).get(uid)
    if runtime in PLAYABLE_COUNTRIES:
        p.country = runtime
        p.active_country = runtime
        return runtime
    return None

WorldApp.v31_game_country = _v31_game_country
WorldApp.country_for = _v31_game_country

def _v31_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    p = self.world.players.get(int(user_id))
    if p is not None and bool(getattr(p, "banned", False)):
        return None, "⛔ Вы заблокированы."
    country = _v31_game_country(self, int(user_id))
    if country:
        return country, ""
    return None, "🌍 Сначала выберите страну."

WorldApp.require_country = _v31_require_country

                                                                                
_v31_init_prev = WorldApp.__init__
def _v31_init(self: WorldApp, *args: Any, **kwargs: Any) -> None:
    _v31_init_prev(self, *args, **kwargs)
    self._session_country = getattr(self, "_session_country", {})
    for p in self.world.players.values():
        active = getattr(p, "active_country", None)
        country = getattr(p, "country", None)
        if country in PLAYABLE_COUNTRIES:
            p.active_country = country
            self._session_country[int(p.user_id)] = country
        elif active in PLAYABLE_COUNTRIES:
            p.country = active
            self._session_country[int(p.user_id)] = active
                                                                                      
        if _v31_game_country(self, int(p.user_id)):
            if getattr(p, "pending_input", None) in {"admin_code", "server_code"}:
                p.clear_input()
