def _v31_auth_prompt_allowed(p: Any, normalized: str) -> bool:
    pending = str(getattr(p, "pending_input", "") or "")
    data = dict(getattr(p, "pending_data", {}) or {})
    if pending == "admin_code" and data.get("context") == "admin_login":
        return True
    if pending == "server_code" and data.get("context") == "server_login":
        return True
    if pending == "country_code" and data.get("context") == "country_login":
        return True
    return False

