async def _v32_show(self: WorldApp, target: types.Message | types.CallbackQuery, text: str,
                    markup: Optional[types.InlineKeyboardMarkup] = None,
                    *, parse_mode: ParseMode = ParseMode.HTML) -> None:
    uid = int(target.from_user.id)
    p = self.player(uid)
    country = _v31_game_country(self, uid)
    normalized = str(text or "").lower()
    registration_prompt = "сначала выберите страну" in normalized or "выберите страну для начала игры" in normalized
    bad_admin_prompt = "введите код администратора" in normalized or "вход администратора" in normalized
    bad_server_prompt = "введите код доступа" in normalized
    if country and not _v32_auth_prompt_allowed(p, normalized) and (registration_prompt or bad_admin_prompt or bad_server_prompt):
        p.clear_input()
        text = self.home_text(country)
        markup = _v28_country_menu_keyboard(country)
    await _v32_show_prev(self, target, text, markup, parse_mode=parse_mode)


