async def _v36_handle_country(self: WorldApp, callback: types.CallbackQuery, code: str) -> None:
    uid = int(callback.from_user.id)
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")
    code = str(code)

    if code == "picker":
        p.clear_input()
        await self.show(callback, "🌍 <b>Выбор страны</b>\n\nВыберите страну, затем введите её код доступа.", Keyboards.country_picker())
        return

    if code == "admin":
        if self.is_admin(uid):
            p.admin_mode = True
            p.clear_input()
            await self.render_admin_home(callback)
            return
        p.clear_input()
        p.pending_input = "admin_code"
        p.pending_data = {
            "expires_at": time.monotonic() + 180,
            "context": "admin_login",
            "owner_user_id": uid,
        }
        await self.show(callback, "🛠️ <b>Вход администратора</b>\n\nВведите код администратора:", Keyboards.simple_nav("country:picker"))
        return

    if code not in PLAYABLE_COUNTRIES and code != COUNTRY_TEST:
        await self.show(callback, "❌ Такая страна недоступна.", Keyboards.country_picker())
        return

    p.clear_input()
    p.admin_mode = False
    p.pending_input = "country_login"
    p.pending_data = {
        "country": code,
        "expires_at": time.monotonic() + 180,
        "context": "country_login",
        "owner_user_id": uid,
    }
    await self.show(
        callback,
        f"🔐 <b>{esc(COUNTRY_NAMES.get(code, code))}</b>\n\nВведите код страны:",
        Keyboards.simple_nav("country:picker"),
    )

WorldApp.handle_country = _v36_handle_country

_v36_on_text_prev = WorldApp.on_text
async def _v36_on_text(self: WorldApp, message: types.Message) -> None:
    if not getattr(message, "text", None):
        return
    uid = int(message.from_user.id)
    p = self.player(uid, getattr(message.from_user, "username", "") or "")
    value = str(message.text).strip()
    pending = str(getattr(p, "pending_input", "") or "")
    pdata = dict(getattr(p, "pending_data", {}) or {})

    # Normalize both historical state names so old saved players cannot fall into a legacy handler.
    if pending == "country_code" and pdata.get("context") == "country_login":
        pending = "country_login"
        p.pending_input = "country_login"

    if pending == "country_login" and pdata.get("context") == "country_login":
        code = str(pdata.get("country", ""))
        owner = int(pdata.get("owner_user_id", uid) or uid)
        expires = float(pdata.get("expires_at", 0) or 0)
        if owner != uid:
            return
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код страны просрочен. Нажмите /start и выберите страну снова.", Keyboards.country_picker())
            return
        if code not in PLAYABLE_COUNTRIES and code != COUNTRY_TEST:
            p.clear_input()
            await self.show_new(message, "❌ Такая страна недоступна.", Keyboards.country_picker())
            return
        expected = str(COUNTRY_ACCESS_CODES.get(code, ""))
        if value != expected:
            await self.show_new(
                message,
                f"❌ Неверный код страны.\n\nВведите код страны {esc(COUNTRY_NAMES.get(code, code))} ещё раз:",
                Keyboards.simple_nav("country:picker"),
            )
            return
        if code == COUNTRY_TEST:
            p.clear_input()
            p.current_screen = "test"
            await self.show_new(message, "✅ Доступ к техническому режиму ТЕСТ разрешён.", Keyboards.simple_nav("country:picker"))
            return
        if not self.world.set_country(uid, code):
            await self.show_new(message, "❌ Эта страна уже занята другим игроком.", Keyboards.country_picker())
            return
        p = self.player(uid, getattr(message.from_user, "username", "") or "")
        p.country = code
        p.active_country = code
        p.admin_mode = False
        p.current_screen = "home"
        p.clear_input()
        if hasattr(self, "_session_country"):
            self._session_country[uid] = code
        self.world.mark_dirty()
        await self.render_home(message)
        return

    if pending == "admin_code" and pdata.get("context") == "admin_login":
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код администратора просрочен. Введите /admin снова.")
            return
        if self.admin.authenticate(uid, value):
            p.admin_mode = True
            p.clear_input()
            await self.render_admin_home(message)
        else:
            await self.show_new(message, "❌ Неверный код администратора. Повторите ввод или нажмите /back.")
        return

    if pending == "server_code" and pdata.get("context") == "server_login":
        expires = float(pdata.get("expires_at", 0) or 0)
        if expires and time.monotonic() > expires:
            p.clear_input()
            await self.show_new(message, "❌ Код серверной панели просрочен. Введите /server снова.")
            return
        if value != SERVER_CONTROL_CODE:
            await self.show_new(message, "❌ Неверный код серверной панели. Попробуйте ещё раз.")
            return
        self.world.set_server_admin(uid, True)
        p.clear_input()
        self.world.mark_dirty()
        await _v12_server_panel(self, message)
        return

    current = _v31_game_country(self, uid)
    if current and pending in {"country_code", "admin_code", "server_code"}:
        p.clear_input()

    await _v36_on_text_prev(self, message)

WorldApp.on_text = _v36_on_text


# ==================== V36.6 — FINAL CALLBACK ROUTER ====================
# No new game message is allowed to contain w:<token> callbacks.
# Legacy w:<token> callbacks are supported only when their old in-memory
# route table is still available. After a restart, the exact old action cannot
# be recovered from an opaque token, so the bot refreshes the current screen.

async def _v36_6_render_current_screen(self: WorldApp, target: types.Message | types.CallbackQuery, p: Any) -> None:
    screen = str(getattr(p, "current_screen", "home") or "home")
    aliases = {
        "home": "home", "production": "production", "map": "map", "country": "country",
        "army": "army", "air": "air", "pvo": "pvo", "navy": "navy",
        "diplomacy": "diplomacy", "trade": "trade", "warehouse": "warehouse",
        "decisions": "decisions", "construction": "construction", "repair": "repair",
        "journal": "journal", "news": "news", "help": "help",
    }
    target_screen = aliases.get(screen, "home")
    try:
        if target_screen == "home":
            await self.render_home(target)
        else:
            await self.handle_screen(target, target_screen)
    except Exception as exc:
        uid = int(target.from_user.id)
        self.world.add_log("screen_refresh_error", uid, {"screen": target_screen, "error": repr(exc)})
        await self.render_home(target)

async def _v36_6_sanitize_markup(self: WorldApp, target: types.Message | types.CallbackQuery,
                                 markup: Optional[types.InlineKeyboardMarkup]) -> Optional[types.InlineKeyboardMarkup]:
    if markup is None:
        return None
    uid = int(target.from_user.id)
    country = _v31_game_country(self, uid)
    p = self.player(uid)
    if country not in PLAYABLE_COUNTRIES or bool(getattr(p, "admin_mode", False)):
        return markup
    screen = str(getattr(p, "current_screen", "home") or "home")
    rows = []
    changed = False
    for row in markup.inline_keyboard:
        new_row = []
        for button in row:
            data = getattr(button, "callback_data", None)
            new_data = data
            if isinstance(data, str) and data.startswith("w:"):
                # Never send an obsolete token back to Telegram.
                new_data = "home" if screen == "home" else f"screen:{screen}"
                changed = True
            try:
                if new_data != data:
                    button = button.model_copy(update={"callback_data": new_data})
            except Exception:
                if new_data != data:
                    button = types.InlineKeyboardButton(
                        text=getattr(button, "text", ""), callback_data=new_data
                    )
            new_row.append(button)
        rows.append(new_row)
    if not changed:
        return markup
    try:
        return markup.model_copy(update={"inline_keyboard": rows})
    except Exception:
        return types.InlineKeyboardMarkup(inline_keyboard=rows)

_v36_6_show_prev = WorldApp.show
async def _v36_6_show(self: WorldApp, target: types.Message | types.CallbackQuery, text: str,
                      markup: Optional[types.InlineKeyboardMarkup] = None,
                      *, parse_mode: ParseMode = ParseMode.HTML) -> None:
    markup = await _v36_6_sanitize_markup(self, target, markup)
    await _v36_6_show_prev(self, target, text, markup, parse_mode=parse_mode)

_v36_6_show_new_prev = WorldApp.show_new
async def _v36_6_show_new(self: WorldApp, message: types.Message,
                          text: str, markup: Optional[types.InlineKeyboardMarkup] = None) -> None:
    markup = await _v36_6_sanitize_markup(self, message, markup)
    await _v36_6_show_new_prev(self, message, text, markup)

_v36_6_on_callback_prev = WorldApp.on_callback
async def _v36_6_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "")
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")
    await self.answer_callback(callback)

    if getattr(p, "banned", False):
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

    # Legacy V34/V36.1/V36.2 callback compatibility.
    # If an old route table is still alive in this process, execute the exact
    # original callback. Otherwise the token is unrecoverable and we refresh
    # the current screen without showing an error.
    if data.startswith("w:"):
        token = data.split(":", 1)[1]
        route_table = getattr(self, "_button_routes", {})
        route = route_table.get(uid, {}).get(token) if isinstance(route_table, dict) else None
        if route:
            original = str(route.get("data", ""))
            route_country = route.get("country")
            current = _v31_game_country(self, uid)
            if current and route_country == current and original and not original.startswith("w:"):
                callback.data = original
                await _v36_6_on_callback(self, callback)
                return
        await _v36_6_render_current_screen(self, callback, p)
        return

    # Authentication / free routes.
    if data == "noop":
        return
    if data == "country:picker":
        p.clear_input()
        await self.show(callback, "🌍 <b>Выбор страны</b>\n\nВыберите страну, затем введите её код доступа.", Keyboards.country_picker())
        return
    if data.startswith("country:") and data != "country:economy":
        await self.handle_country(callback, data.split(":", 1)[1])
        return
    if data in PLAYABLE_COUNTRIES or data == COUNTRY_TEST or data == "admin":
        await self.handle_country(callback, data)
        return
    if data == "country:economy":
        await self.handle_screen(callback, "country")
        return

    if data == "home" or data == "main" or data == "menu":
        p.clear_input()
        await self.render_home(callback)
        return
    if data.startswith("screen:"):
        p.clear_input()
        await self.handle_screen(callback, data.split(":", 1)[1])
        return

    # Admin/server callbacks are isolated from normal game callbacks.
    if data == "admin:home":
        p.clear_input()
        if self.is_admin(uid):
            p.admin_mode = True
            await self.render_admin_home(callback)
        else:
            p.pending_input = "admin_code"
            p.pending_data = {"expires_at": time.monotonic() + 180, "context": "admin_login", "owner_user_id": uid}
            await self.show(callback, "🛠️ <b>Вход администратора</b>\n\nВведите код администратора:", Keyboards.simple_nav("home"))
        return
    if data == "admin:logout":
        p.admin_mode = False
        p.clear_input()
        country = _v31_game_country(self, uid)
        if country:
            await self.render_home(callback)
        else:
            await self.render_admin_home(callback)
        return
    if data.startswith("admin:"):
        try:
            await self.handle_admin(callback, data)
        except Exception as exc:
            self.world.add_log("admin_callback_error", uid, {"callback": data[:80], "error": repr(exc)})
            await self.show(callback, "❌ Ошибка административной панели. Запись добавлена в диагностику.", Keyboards.simple_nav("admin:home"))
        return
    if data.startswith("server:"):
        if data == "server:logout":
            self.world.set_server_admin(uid, False)
            self.world.mark_dirty()
            p.clear_input()
            if self.is_admin(uid):
                p.admin_mode = True
                await self.render_admin_home(callback)
            else:
                country = _v31_game_country(self, uid)
                if country:
                    await self.render_home(callback)
                else:
                    await self.show(callback, "✅ Вы вышли из серверной панели.", Keyboards.country_picker())
            return
        try:
            if await _v20_server_handle(self, callback, data):
                return
        except Exception as exc:
            self.world.add_log("server_callback_error", uid, {"data": data[:80], "error": repr(exc)})
        return

    country = _v31_game_country(self, uid)
    if not country:
        await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
        return

    # Country-bound top-level navigation.
    if data.startswith("croute:"):
        parts = data.split(":", 2)
        if len(parts) == 3 and parts[1] == country:
            p.clear_input()
            if parts[2] == "home":
                await self.render_home(callback)
            else:
                await self.handle_screen(callback, parts[2])
            return
        await self.show(callback, "⚠️ Это меню другой страны.", _v28_country_menu_keyboard(country))
        return

    # Every game callback family is dispatched by its stable prefix.
    try:
        async with self.screen_lock(uid):
            if data.startswith("map:") or data.startswith("prov:") or data.startswith("provneighbors:"):
                if data.startswith("map:"):
                    await self.handle_map(callback, data)
                elif data.startswith("provneighbors:"):
                    await self.handle_province_neighbors(callback, data)
                else:
                    await self.handle_province(callback, data)
                return
            if data.startswith("prod"):
                await self.handle_production(callback, data); return
            if data.startswith("warehouse"):
                await self.handle_warehouse(callback, data); return
            if data.startswith("army") or data.startswith("gen") or data.startswith("general"):
                await self.handle_army(callback, data); return
            if data.startswith("air"):
                await self.handle_air(callback, data); return
            if data.startswith("pvo"):
                await self.handle_pvo(callback, data); return
            if data.startswith("navy"):
                await self.handle_navy(callback, data); return
            if (data.startswith("diplo") or data.startswith("treaty") or data.startswith("war")
                    or data.startswith("ultimatum") or data.startswith("ultdemand:")
                    or data.startswith("ultdeadline:") or data.startswith("ultsend:")
                    or data.startswith("warningto:")):
                await self.handle_diplomacy(callback, data); return
            if data.startswith("trade"):
                await self.handle_trade(callback, data); return
            if data.startswith("decision"):
                await self.handle_decision(callback, data); return
            if data.startswith("build"):
                await self.handle_construction(callback, data); return
            if data.startswith("repair"):
                await self.handle_repair(callback, data); return
            if data.startswith("journal"):
                await self.handle_journal(callback, data); return
            if data.startswith("news"):
                await self.handle_news(callback, data); return

            # Unknown game callback: never show a technical error. Refresh the
            # current screen so the user gets fresh, valid buttons.
            self.world.add_log("unknown_callback_refresh", uid, {
                "callback": data[:100],
                "screen": str(getattr(p, "current_screen", "home") or "home"),
                "country": country,
            })
            await _v36_6_render_current_screen(self, callback, p)
    except Exception as exc:
        self.world.add_log("callback_error", uid, {"callback": data[:100], "error": repr(exc)})
        await _v36_6_render_current_screen(self, callback, p)


GAME_VERSION = "36.6.0-final-direct-callback-routing"
SAVE_VERSION = 33



# ============================================================================
# V37 — SINGLE AUTHORITATIVE UI ROUTER
# All historical on_callback/show/show_new assignments are intentionally
# removed. One callback handler and one rendering pair are installed here.
# ============================================================================

async def _v37_show(self: WorldApp, target: types.Message | types.CallbackQuery,
                    text: str, markup: Optional[types.InlineKeyboardMarkup] = None,
                    *, parse_mode: ParseMode = ParseMode.HTML) -> None:
    # Use the last stable implementation before the old token-routing layers.
    # V32 retains the authentication quarantine without creating w:<token>.
    await _v32_show(self, target, text, markup, parse_mode=parse_mode)

async def _v37_show_new(self: WorldApp, message: types.Message,
                        text: str, markup: Optional[types.InlineKeyboardMarkup] = None) -> None:
    await _v32_show_new(self, message, text, markup)

async def _v37_render_current_screen(self: WorldApp, target: types.Message | types.CallbackQuery, p: Any) -> None:
    screen = str(getattr(p, "current_screen", "home") or "home")
    allowed = {"home","production","map","country","army","air","pvo","navy",
               "diplomacy","trade","warehouse","decisions","construction","repair",
               "journal","news","help"}
    if screen not in allowed:
        screen = "home"
    try:
        if screen == "home":
            await self.render_home(target)
        else:
            await self.handle_screen(target, screen)
    except Exception as exc:
        uid = int(target.from_user.id)
        self.world.add_log("screen_refresh_error", uid, {"screen": screen, "error": repr(exc)[:300]})
        await self.render_home(target)

async def _v37_dispatch_game(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    """Return True when the callback family was recognized and dispatched."""
    if data.startswith("map:"):
        await self.handle_map(callback, data); return True
    if data.startswith("provneighbors:"):
        await self.handle_province_neighbors(callback, data); return True
    if data.startswith("prov:"):
        await self.handle_province(callback, data); return True
    if data.startswith("prod"):
        await self.handle_production(callback, data); return True
    if data.startswith("warehouse"):
        await self.handle_warehouse(callback, data); return True
    if data.startswith("army") or data.startswith("gen") or data.startswith("general"):
        await self.handle_army(callback, data); return True
    if data.startswith("air"):
        await self.handle_air(callback, data); return True
    if data.startswith("pvo"):
        await self.handle_pvo(callback, data); return True
    if data.startswith("navy"):
        await self.handle_navy(callback, data); return True
    if (data.startswith("diplo") or data.startswith("treaty") or data.startswith("war")
        or data.startswith("ultimatum") or data.startswith("ultdemand:")
        or data.startswith("ultdeadline:") or data.startswith("ultsend:")
        or data.startswith("warningto:")):
        await self.handle_diplomacy(callback, data); return True
    if data.startswith("trade"):
        await self.handle_trade(callback, data); return True
    if data.startswith("decision"):
        await self.handle_decision(callback, data); return True
    if data.startswith("build"):
        await self.handle_construction(callback, data); return True
    if data.startswith("repair"):
        await self.handle_repair(callback, data); return True
    if data.startswith("journal"):
        await self.handle_journal(callback, data); return True
    if data.startswith("news"):
        await self.handle_news(callback, data); return True
    return False

async def _v37_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "").strip()
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")
    await self.answer_callback(callback)

    if getattr(p, "banned", False):
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

    # Legacy opaque tokens: use them only if their route is still available.
    # New buttons can never be created with this format because the historical
    # show/show_new assignment layers are no longer registered.
    if data.startswith("w:"):
        token = data.split(":", 1)[1]
        table = getattr(self, "_button_routes", {})
        route = table.get(uid, {}).get(token) if isinstance(table, dict) else None
        current = _v31_game_country(self, uid)
        original = str(route.get("data", "")) if route else ""
        if route and current and route.get("country") == current and original and not original.startswith("w:"):
            callback.data = original
            await _v37_on_callback(self, callback)
            return
        await _v37_render_current_screen(self, callback, p)
        return

    # Free/auth/navigation callbacks.
    if data in {"", "noop"}:
        return
    if data in {"home", "main", "menu"}:
        p.clear_input(); await self.render_home(callback); return
    if data == "country:picker":
        p.clear_input()
        await self.show(callback, "🌍 <b>Выбор страны</b>\n\nВыберите страну, затем введите её код доступа.", Keyboards.country_picker())
        return
    if data.startswith("country:") and data != "country:economy":
        await self.handle_country(callback, data.split(":", 1)[1]); return
    if data in PLAYABLE_COUNTRIES or data == COUNTRY_TEST or data == "admin":
        await self.handle_country(callback, data); return
    if data == "country:economy":
        await self.handle_screen(callback, "country"); return
    if data.startswith("screen:"):
        p.clear_input(); await self.handle_screen(callback, data.split(":", 1)[1]); return
    if data.startswith("croute:"):
        parts = data.split(":", 2)
        country = _v31_game_country(self, uid)
        if len(parts) != 3 or not country or parts[1] != country:
            if country:
                await self.show(callback, "⚠️ Это меню другой страны.", _v28_country_menu_keyboard(country))
            else:
                await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
            return
        p.clear_input()
        if parts[2] == "home": await self.render_home(callback)
        else: await self.handle_screen(callback, parts[2])
        return

    # Admin/server callbacks.
    if data == "admin:home":
        p.clear_input()
        if self.is_admin(uid):
            p.admin_mode = True; await self.render_admin_home(callback)
        else:
            p.pending_input = "admin_code"
            p.pending_data = {"expires_at": time.monotonic()+180, "context":"admin_login", "owner_user_id":uid}
            await self.show(callback, "🛠️ <b>Вход администратора</b>\n\nВведите код администратора:", Keyboards.simple_nav("home"))
        return
    if data == "admin:logout":
        p.admin_mode = False; p.clear_input()
        country = _v31_game_country(self, uid)
        await (self.render_home(callback) if country else self.render_admin_home(callback))
        return
    if data.startswith("admin:"):
        try: await self.handle_admin(callback, data)
        except Exception as exc:
            self.world.add_log("admin_callback_error", uid, {"callback":data[:100],"error":repr(exc)[:300]})
            await self.show(callback, "❌ Ошибка административной панели.", Keyboards.simple_nav("admin:home"))
        return
    if data.startswith("server:"):
        try:
            if await _v20_server_handle(self, callback, data): return
        except Exception as exc:
            self.world.add_log("server_callback_error", uid, {"data":data[:100],"error":repr(exc)[:300]})
        return

    country = _v31_game_country(self, uid)
    if not country:
        await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker()); return

    try:
        async with self.screen_lock(uid):
            if await _v37_dispatch_game(self, callback, data):
                return

            # Last-resort recovery: use the current screen instead of ever
            # exposing a technical "unknown button" state to the player.
            self.world.add_log("unknown_callback_recovery", uid, {
                "callback": data[:100], "screen": getattr(p, "current_screen", "home"), "country": country
            })
            await _v37_render_current_screen(self, callback, p)
    except Exception as exc:
        self.world.add_log("callback_error", uid, {"callback":data[:100], "error":repr(exc)[:300]})
        await _v37_render_current_screen(self, callback, p)

# These are the ONLY registrations of the three hot-path UI methods.
WorldApp.show = _v37_show
WorldApp.show_new = _v37_show_new
WorldApp.on_callback = _v37_on_callback

GAME_VERSION = "37.1.0-ui-audited-single-router"
SAVE_VERSION = 33

def _ui_static_contract_audit() -> None:
    # Static top-level keyboards must always contain valid labels/callbacks.
    for markup in (Keyboards.home(), Keyboards.country_picker()):
        for row in markup.inline_keyboard:
            for button in row:
                if not str(button.text or '').strip():
                    raise RuntimeError('UI audit: empty button text')
                data = str(button.callback_data or '')
                if not data:
                    raise RuntimeError('UI audit: empty callback_data')
                if len(data.encode('utf-8')) > 64:
                    raise RuntimeError(f'UI audit: callback_data >64 bytes: {data}')

_ui_static_contract_audit()



# =============================================================================
# WORLD STRATEGY V38 — CLEAN BUTTON SYSTEM
# =============================================================================
# This layer replaces the active Telegram UI routing completely.
# No w:<token> generation, no croute rewriting, and no legacy UI wrappers are
# used for newly rendered buttons. Existing gameplay handlers are preserved.

V38_VERSION = "38.0.0-clean-button-system"

async def _v38_show(self: WorldApp, target: types.Message | types.CallbackQuery,
                    text: str,
                    markup: Optional[types.InlineKeyboardMarkup] = None,
                    *, parse_mode: ParseMode = ParseMode.HTML) -> None:
    """One clean message editor. It never rewrites callback_data."""
    if isinstance(target, types.CallbackQuery):
        message = target.message
        user_id = int(target.from_user.id)
    else:
        message = target
        user_id = int(target.from_user.id)
    if message is None:
        return
    text = str(text or "")[:4096]
    try:
        await message.edit_text(
            text,
            reply_markup=markup,
            parse_mode=parse_mode,
            disable_web_page_preview=True,
        )
    except TelegramBadRequest as exc:
        if "message is not modified" in str(exc).lower():
            return
        try:
            sent = await message.answer(
                text,
                reply_markup=markup,
                parse_mode=parse_mode,
                disable_web_page_preview=True,
            )
            self.player(user_id).current_message_id = sent.message_id
        except TelegramForbiddenError:
            return
    except TelegramForbiddenError:
        return


async def _v38_show_new(self: WorldApp, message: types.Message,
                        text: str,
                        markup: Optional[types.InlineKeyboardMarkup] = None) -> None:
    sent = await message.answer(
        str(text or "")[:4096],
        reply_markup=markup,
        parse_mode=ParseMode.HTML,
        disable_web_page_preview=True,
    )
    self.player(int(message.from_user.id)).current_message_id = sent.message_id


async def _v38_render_home(self: WorldApp, target: types.Message | types.CallbackQuery) -> None:
    uid = int(target.from_user.id)
    p = self.player(uid, getattr(target.from_user, "username", "") or "")
    if bool(getattr(p, "admin_mode", False)) and self.is_admin(uid):
        await self.render_admin_home(target)
        return
    country = self.country_for(uid)
    if not country:
        await self.show(
            target,
            f"{APP_TITLE}\n\nВыберите страну для начала игры.\n🧪 ТЕСТ — техническая страна без территории.",
            Keyboards.country_picker(),
        )
        return
    p.current_screen = "home"
    await self.show(target, self.home_text(country), Keyboards.home())


async def _v38_on_start(self: WorldApp, message: types.Message) -> None:
    uid = int(message.from_user.id)
    p = self.player(uid, getattr(message.from_user, "username", "") or "")
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid):
        await self.show_new(message, "⛔ Сервер сейчас остановлен. Дождитесь возобновления работы.")
        return
    p.clear_input()
    p.admin_mode = False
    # /start intentionally resets only the UI position, not the saved country.
    await self.show_new(
        message,
        "🌍 <b>Выбор страны</b>\n\nВыберите страну, затем введите её код доступа.",
        Keyboards.country_picker(),
    )


def _v38_screen_alias(screen: str) -> str:
    aliases = {
        "main": "home", "menu": "home", "country:economy": "country",
    }
    return aliases.get(str(screen), str(screen))


async def _v38_dispatch_game(self: WorldApp, callback: types.CallbackQuery, data: str) -> bool:
    """Every gameplay callback goes directly to its existing gameplay handler."""
    if data.startswith("map:"):
        await self.handle_map(callback, data); return True
    if data.startswith("provneighbors:"):
        await self.handle_province_neighbors(callback, data); return True
    if data.startswith("prov:"):
        await self.handle_province(callback, data); return True

    if data.startswith("prod"):
        await self.handle_production(callback, data); return True
    if data.startswith("warehouse"):
        await self.handle_warehouse(callback, data); return True

    if (data.startswith("army") or data.startswith("army-")
            or data.startswith("gen") or data.startswith("general")):
        await self.handle_army(callback, data); return True
    if data.startswith("air"):
        await self.handle_air(callback, data); return True
    if data.startswith("pvo"):
        await self.handle_pvo(callback, data); return True
    if data.startswith("navy"):
        await self.handle_navy(callback, data); return True

    if (data.startswith("diplo") or data.startswith("treaty")
            or data.startswith("war") or data.startswith("ultimatum")
            or data.startswith("ultimatumto:") or data.startswith("ultdemand:")
            or data.startswith("ultdeadline:") or data.startswith("ultsend:")
            or data.startswith("warningto:")):
        await self.handle_diplomacy(callback, data); return True
    if data.startswith("trade"):
        await self.handle_trade(callback, data); return True
    if data.startswith("decision"):
        await self.handle_decision(callback, data); return True
    if data.startswith("build"):
        await self.handle_construction(callback, data); return True
    if data.startswith("repair"):
        await self.handle_repair(callback, data); return True
    if data.startswith("journal"):
        await self.handle_journal(callback, data); return True
    if data.startswith("news"):
        await self.handle_news(callback, data); return True
    return False


async def _v38_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    uid = int(callback.from_user.id)
    data = str(callback.data or "").strip()
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")
    await self.answer_callback(callback)

    if bool(getattr(p, "banned", False)):
        await self.show(callback, "⛔ Вы заблокированы.", Keyboards.country_picker())
        return

    # Old opaque buttons from V34/V36 are never executed as game actions.
    # They also never produce a user-facing "old button" warning.
    if data.startswith("w:"):
        country = self.country_for(uid)
        if country and str(getattr(p, "current_screen", "home") or "home") != "home":
            await self.handle_screen(callback, str(getattr(p, "current_screen", "home")))
        else:
            await self.render_home(callback)
        return

    # Free navigation/auth routes.
    if data in {"", "noop"}:
        return
    if data in {"home", "main", "menu"}:
        p.clear_input()
        await self.render_home(callback)
        return
    if data == "country:picker":
        p.clear_input()
        await self.show(callback,
                        "🌍 <b>Выбор страны</b>\n\nВыберите страну, затем введите её код доступа.",
                        Keyboards.country_picker())
        return
    if data.startswith("country:") and data != "country:economy":
        await self.handle_country(callback, data.split(":", 1)[1])
        return
    if data in PLAYABLE_COUNTRIES or data == COUNTRY_TEST or data == "admin":
        await self.handle_country(callback, data)
        return

    # Back/navigation routes generated by the clean UI.
    if data == "country:economy":
        await self.handle_screen(callback, "country")
        return
    if data.startswith("screen:"):
        p.clear_input()
        await self.handle_screen(callback, data.split(":", 1)[1])
        return
    if data.startswith("croute:"):
        # Compatibility only for old messages. New UI never creates croute.
        parts = data.split(":", 2)
        country = self.country_for(uid)
        if len(parts) == 3 and country and parts[1] == country:
            p.clear_input()
            if parts[2] == "home":
                await self.render_home(callback)
            else:
                await self.handle_screen(callback, parts[2])
        else:
            if country:
                await self.render_home(callback)
            else:
                await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
        return

    if data == "admin:home":
        p.clear_input()
        if self.is_admin(uid):
            p.admin_mode = True
            await self.render_admin_home(callback)
        else:
            p.pending_input = "admin_code"
            p.pending_data = {
                "expires_at": time.monotonic() + 180,
                "context": "admin_login",
                "owner_user_id": uid,
            }
            await self.show(callback,
                            "🛠️ <b>Вход администратора</b>\n\nВведите код администратора:",
                            Keyboards.simple_nav("home"))
        return
    if data == "admin:logout":
        p.admin_mode = False
        p.clear_input()
        country = self.country_for(uid)
        if country:
            await self.render_home(callback)
        else:
            await self.render_admin_home(callback)
        return
    if data.startswith("admin:"):
        try:
            await self.handle_admin(callback, data)
        except Exception as exc:
            self.world.add_log("admin_callback_error", uid, {"callback": data[:100], "error": repr(exc)[:300]})
            await self.show(callback, "❌ Ошибка административной панели.", Keyboards.simple_nav("admin:home"))
        return
    if data.startswith("server:"):
        try:
            if await _v20_server_handle(self, callback, data):
                return
        except Exception as exc:
            self.world.add_log("server_callback_error", uid, {"data": data[:100], "error": repr(exc)[:300]})
        return

    country = self.country_for(uid)
    if not country:
        await self.show(callback, "🌍 Сначала выберите страну.", Keyboards.country_picker())
        return

    try:
        async with self.screen_lock(uid):
            handled = await _v38_dispatch_game(self, callback, data)
            if handled:
                return

            # For any unknown callback, do not show a technical error and do not
            # route through a legacy token system. Reopen the real current screen.
            self.world.add_log("unknown_callback_recovery", uid, {
                "callback": data[:120],
                "screen": str(getattr(p, "current_screen", "home") or "home"),
                "country": country,
            })
            screen = str(getattr(p, "current_screen", "home") or "home")
            if screen == "home":
                await self.render_home(callback)
            else:
                await self.handle_screen(callback, screen)
    except Exception as exc:
        self.world.add_log("callback_error", uid, {"callback": data[:120], "error": repr(exc)[:300]})
        try:
            await self.render_home(callback)
        except Exception:
            pass


# Activate the clean UI functions. These assignments happen before WorldApp()
# is constructed, so Router._bind_handlers registers these exact methods.
WorldApp.show = _v38_show
WorldApp.show_new = _v38_show_new
WorldApp.render_home = _v38_render_home
WorldApp.on_start = _v38_on_start
WorldApp.on_callback = _v38_on_callback

GAME_VERSION = V38_VERSION
SAVE_VERSION = 33


def _ws_runtime_source_text() -> str:
    # Colab/Jupyter may execute this file as a cell, so __file__ is often absent.
    # Prefer the exact injected source from the ONE CELL wrapper, then fall back
    # to the executing code object's filename via linecache.
    injected = globals().get("_WORLD_STRATEGY_SOURCE_TEXT")
    if isinstance(injected, str) and injected:
        return injected

    file_name = globals().get("__file__")
    if file_name:
        path = Path(file_name)
        if path.exists():
            try:
                text = path.read_text(encoding="utf-8")
                if text:
                    return text
            except Exception:
                pass

    try:
        import inspect as _inspect
        import linecache as _linecache
        frame = _inspect.currentframe()
        while frame is not None:
            code_file = frame.f_code.co_filename
            if code_file:
                lines = _linecache.getlines(code_file)
                if lines:
                    text = "".join(lines)
                    if text:
                        return text
            frame = frame.f_back
    except Exception:
        pass

    return ""

def _v38_callback_audit() -> dict[str, Any]:
    """Audit all source-level button families against the clean router."""
    import ast as _ast
    source_text = _ws_runtime_source_text()
    if not source_text:
        return {"button_prefix_count": 0, "missing_prefixes": []}
    tree = _ast.parse(source_text)
    prefixes: set[str] = set()

    class _Visitor(_ast.NodeVisitor):
        def visit_Call(self, node: _ast.Call) -> None:
            if (isinstance(node.func, _ast.Attribute)
                    and node.func.attr == "btn" and len(node.args) >= 2):
                value = node.args[1]
                if isinstance(value, _ast.Constant) and isinstance(value.value, str):
                    prefixes.add(value.value.split(":", 1)[0])
                elif isinstance(value, _ast.JoinedStr):
                    constants = []
                    for part in value.values:
                        if isinstance(part, _ast.Constant) and isinstance(part.value, str):
                            constants.append(part.value)
                        else:
                            break
                    if constants:
                        prefixes.add("".join(constants).split(":", 1)[0])
            self.generic_visit(node)

    _Visitor().visit(tree)
    handled_prefixes = {
        "admin", "air", "airfield", "airgroup", "airmission", "airmissionmode", "airmodel",
        "airqty", "airrebase", "airrebaseto", "airroute", "airrouteclear", "airroutecountry",
        "airrouteprov", "airtargetcountry", "airtargetown", "airtargetprov", "army",
        "army-target", "army-targetset", "armyattach", "armydisband", "armydiv", "armygen",
        "armymove", "armymoveto", "armyorder", "armyplace", "armyrename", "armytemplate", "armyup",
        "armyupset", "back", "build", "country", "croute", "decision", "decisioncat", "diplo",
        "gen", "genautosp", "gencells", "gencellsave", "gencelltoggle", "general", "genhq", "genhqset",
        "home", "journalcat", "key", "map", "navy", "navybase", "navygroup", "navymission",
        "navymissionmode", "navymodel", "navyqty", "navyrebase", "navyrebaseto", "news", "noop", "prodcat",
        "prodinput", "prodmodel", "prodset", "prov", "provneighbors", "pvo", "pvoactive", "pvocountry",
        "pvocover", "pvomode", "pvomodel", "pvomodeset", "pvomove", "pvomoveto", "pvoplace", "pvopriority",
        "pvopriorityset", "pvounit", "pvoqty", "repair", "screen", "server", "trade", "treaty", "ultdeadline",
        "ultdemand", "ultimatum", "ultimatumto", "ultsend", "warehousecat", "warningto", "war", "build", "journal", "news", "airrename", "airstrike", "airstriketargetcountry", "airstriketargetprov", "airstrikeweapon", "airstrikefire", "aircabroute", "aircabroutecountry", "aircabrouteprov", "aircabclear",
        "map", "prod", "warehouse", "army", "air", "pvo", "navy", "diplomacy", "decision", "trade", "repair",
        "airname", "airstatus", "aircheckready", "airtakeoff", "airattachgen", "airstrikev45", "airstrikev45type",
        "airstrikev45target", "airstrikev45country", "airstrikev45prov", "airmissilepick", "airmissileqty", "aircabpick",
        "airuavroute", "airplan", "airstormgen", "airfightermissions", "airfightermission", "airhelimissions",
        "airhelimission", "aircustomqty", "aircustomqtyconfirm", "pvomodel", "pvoqty", "pvoprov", "pvoinput",
    }
    missing = sorted(p for p in prefixes if p and p not in handled_prefixes and p != "{...}")
    return {"button_prefix_count": len(prefixes), "missing_prefixes": missing}


V38_BUTTON_AUDIT = _v38_callback_audit()
if V38_BUTTON_AUDIT["missing_prefixes"]:
    raise RuntimeError("V38 button audit failed: " + ", ".join(V38_BUTTON_AUDIT["missing_prefixes"]))




# =============================================================================
# WORLD STRATEGY V38.1 — ADMIN ROUTING AUDIT FIXES
# =============================================================================
# Fixes two concrete admin callback mismatches found in the full audit:
#   1) admin:countrymsg / admin:countrymsgto:<country>
#   2) admin:news:publish:<news_id>
# Also restores the "Написать стране" shortcut in the active admin home.

V38_1_VERSION = "38.1.0-admin-audit-fixed"

async def _v38_1_render_admin_home(self: WorldApp, target: types.Message | types.CallbackQuery) -> None:
    if not self.is_admin(target.from_user.id):
        await self.show(target, "❌ Нет прав администратора.", Keyboards.country_picker())
        return
    result = self.diagnostics.run()
    active_wars = result["counts"]["wars"]
    text = (
        "🛠️ <b>Панель администратора</b>\n\n"
        f"Игровое время: {game_time_text(self.world)}\n"
        f"Скорость: x{self.world.speed:g}\n"
        f"Статус: {'⏸️ Пауза' if self.world.paused else '▶️ Игра'}\n"
        f"Провинций: {len(self.world.provinces)}\n"
        f"Игроков: {len(self.world.players)}\n"
        f"Войн: {active_wars}\n"
        f"Диагностика: {'✅ OK' if result['ok'] else '❌ Ошибки'}"
    )
    action_items = list(ADMIN_ACTIONS.items())
    rows: list[list[types.InlineKeyboardButton]] = []
    for i in range(0, len(action_items), 2):
        row = [Keyboards.btn(action_items[i][1], f"admin:section:{action_items[i][0]}")]
        if i + 1 < len(action_items):
            row.append(Keyboards.btn(action_items[i + 1][1], f"admin:section:{action_items[i + 1][0]}"))
        rows.append(row)
    rows.append([Keyboards.btn("🖥️ Сервер", "admin:server"), Keyboards.btn("📨 Написать стране", "admin:countrymsg")])
    rows.append([
        Keyboards.btn("⏱️ x1", "admin:speed:1"),
        Keyboards.btn("x2", "admin:speed:2"),
        Keyboards.btn("x5", "admin:speed:5"),
        Keyboards.btn("x10", "admin:speed:10"),
    ])
    rows.append([Keyboards.btn("⏸️ Пауза", "admin:pause:1"), Keyboards.btn("▶️ Продолжить", "admin:pause:0")])
    rows.append([Keyboards.btn("💾 Сохранить", "admin:save"), Keyboards.btn("🩺 Диагностика", "admin:diag")])
    rows.append([Keyboards.btn("🚪 Выйти из админки", "admin:logout")])
    await self.show(target, text, types.InlineKeyboardMarkup(inline_keyboard=rows))


async def _v38_1_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    data = str(callback.data or "").strip()
    uid = int(callback.from_user.id)
    await self.answer_callback(callback)

    # These two routes were the only concrete admin callback mismatches found
    # in the full-source audit. They are handled before the generic admin router.
    if data.startswith("admin:countrymsg"):
        if await _v12_admin_countrymsg(self, callback, data):
            return

    if data.startswith("admin:news:publish:"):
        if not self.is_admin(uid):
            await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker())
            return
        nid = data.split(":", 3)[3]
        item = self.world.news.get(nid)
        if item is None:
            await self.show(callback, "❌ Новость не найдена.", Keyboards.simple_nav("admin:section:news"))
            return
        ok, reason = self.news.publish(nid, uid)
        if ok:
            self.spawn(self.broadcast_news(nid))
            self.spawn(self.save_light())
        await self.show(
            callback,
            ("✅ " if ok else "❌ ") + reason,
            Keyboards.simple_nav("admin:section:news"),
        )
