def _v38_1_admin_static_audit() -> None:
    # Confirm every static admin callback visible in source is either handled
    # directly by the V38.1 front router or by the existing handle_admin chain.
    source_text = _ws_runtime_source_text()
    # Some notebook hosts do not expose cell source through either __file__ or
    # linecache. In that case the runtime callback routing remains testable, but
    # this source-presence audit must not abort an otherwise valid bot startup.
    if not source_text:
        return
    required_direct = (
        "admin:countrymsg",
        "admin:countrymsgto:",
        "admin:news:publish:",
    )
    for token in required_direct:
        if token not in source_text:
            raise RuntimeError(f"V38.1 admin audit failed: missing {token}")
    # Verify critical permission checks remain present.
    if "if not self.is_admin(uid):" not in source_text:
        raise RuntimeError("V38.1 admin audit failed: admin permission check missing")


_v38_1_admin_static_audit()



