# WORLD STRATEGY V39.1 — THIRD CHECK CRITICAL FIXES
# =============================================================================
# 1) Restore the visible admin -> server shortcut in the clean callback router.
# 2) Keep old reset callbacks safe.
# 3) Invalidate stale per-runtime country sessions after admin reassignment/kick/ban.

_v39_handle_admin_base = WorldApp.handle_admin

async def _v39_handle_admin(self: WorldApp, callback: types.CallbackQuery, data: str) -> None:
    uid = int(callback.from_user.id)
    if not self.is_admin(uid):
        await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker())
        return

    if data == "admin:server":
        self.world.set_server_admin(uid, True)
        self.world.mark_dirty()
        await _v12_server_panel(self, callback)
        return

    if data.startswith("admin:reset_country:"):
        code = data.split(":", 2)[2]
        if code not in PLAYABLE_COUNTRIES:
            await self.show(callback, "❌ Страна не найдена.", Keyboards.simple_nav("admin:home"))
            return
        ok, reason = self._v19_reset_country(code)
        if ok:
            for sid, sp in list(getattr(self, "_session_country", {}).items()):
                if sp == code:
                    self._session_country.pop(sid, None)
                    player = self.world.players.get(sid)
                    if player is not None and player.role != "admin":
                        player.active_country = None
            self.world.mark_dirty()
            self.spawn(self.save_light())
        await self.show(callback, ("✅ " if ok else "❌ ") + reason, Keyboards.simple_nav("admin:home"))
        return

    if data == "admin:reset_world":
        current_admins = [p.user_id for p in self.world.players.values() if p.is_admin]
        current_server_admins = [int(x) for x in getattr(self.world, "server_state", {}).get("admin_ids", [])]
        self.world._reset_world()
        self._session_country.clear()
        for auid in current_admins:
            self.world.set_admin(auid, True)
        for suid in current_server_admins:
            self.world.set_server_admin(suid, True)
        self.world.set_admin(uid, True)
        self.world.set_server_admin(uid, True)
        self.simulation.production_accum = 0.0
        self.simulation.daily_accum = 0.0
        self.simulation.army_accum = 0.0
        self.simulation.air_accum = 0.0
        self.simulation.trade_accum = 0.0
        self.simulation.last_loop_real = time.monotonic()
        self.world.mark_dirty()
        self.spawn(self.save_light())
        await self.show(callback, "✅ Весь мир сброшен к самому старту.", Keyboards.simple_nav("admin:home"))
        return

    if data.startswith("admin:section:reset"):
        p = self.player(uid)
        p.pending_input = "admin_reset_code"
        p.pending_data = {"expires_at": time.monotonic() + 300}
        await self.show(callback, "♻️ <b>Сброс данных</b>\n\nВведите специальный код подтверждения.", Keyboards.simple_nav("admin:home"))
        return

    await _v39_handle_admin_base(self, callback, data)

WorldApp.handle_admin = _v39_handle_admin

_v39_on_callback_base = WorldApp.on_callback
async def _v39_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    data = str(callback.data or "").strip()
    uid = int(callback.from_user.id)
    if data.startswith("admin:server") or data.startswith("admin:reset_country:") or data in {"admin:reset_world"} or data == "admin:section:reset":
        await self.answer_callback(callback)
        if not self.is_admin(uid):
            await self.show(callback, "❌ Нет прав администратора.", Keyboards.country_picker())
            return
        await self.handle_admin(callback, data)
        return
    await _v39_on_callback_base(self, callback)

WorldApp.on_callback = _v39_on_callback

