# =============================================================================
# WORLD STRATEGY V39.4 — FINAL HARDENING FOR STOP GATE + HELP
# =============================================================================
# 1) A stopped/maintenance server blocks already-authorized player gameplay
#    callbacks as well as text input; server/admin controls remain available.
# 2) Replace the short help with the complete user-facing explanation, without
#    exposing any secret/admin confirmation code.

_v39_4_on_callback_prev = WorldApp.on_callback
async def _v39_4_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    data = str(callback.data or "").strip()
    uid = int(callback.from_user.id)
    p = self.player(uid, getattr(callback.from_user, "username", "") or "")

    # Free/admin/server controls must stay reachable while the game is stopped.
    if data.startswith("server:") or data.startswith("admin:") or data in {"", "noop", "home", "main", "menu", "country:picker"} or data.startswith("country:"):
        await _v39_4_on_callback_prev(self, callback)
        return

    # Any already-authorized player action is blocked while the server is
    # stopped or in maintenance. The next screen is explicit and actionable.
    if not _v12_server_working(self.world) and not self.world.is_server_admin(uid) and not self.is_admin(uid):
        p.clear_input()
        await self.answer_callback(callback)
        await self.show(callback, "⛔ Сервер сейчас остановлен или находится на технических работах. Попробуйте позже.", Keyboards.country_picker())
        return

    await _v39_4_on_callback_prev(self, callback)

WorldApp.on_callback = _v39_4_on_callback

