# WORLD STRATEGY V42.0 — AVIATION ONLY EXTENSION
# =============================================================================
# This block changes only aviation plus the requested automatic city airfields.
# Existing economy, army, navy, diplomacy, trade, server and admin logic is left intact.

V42_VERSION = "42.0.0-aviation-orders"

# Every capital/city starts with an operational level-1 airfield.
V42_CITY_AIRFIELD_IDS = sorted({
    *set(SPECIAL_CAPITAL_IDS.values()),
    *{pid for ids in SPECIAL_CITY_IDS.values() for pid in ids},
})


def _v42_ensure_city_airfields(world: "WorldState") -> None:
    changed = False
    for pid in V42_CITY_AIRFIELD_IDS:
        if pid not in world.provinces:
            continue
        p = world.province(pid)
        level = p.building_level("airfield")
        if level < 1:
            p.add_building("airfield", 1)
            p.building_condition["airfield"] = 100.0
            changed = True
        elif p.condition_of("airfield") <= 0:
            p.building_condition["airfield"] = 100.0
            changed = True
    if changed:
        world.mark_dirty()

_v42_worldstate_init_prev = WorldState.__init__
def _v42_worldstate_init(self: "WorldState", *args: Any, **kwargs: Any) -> None:
    _v42_worldstate_init_prev(self, *args, **kwargs)
    _v42_ensure_city_airfields(self)
WorldState.__init__ = _v42_worldstate_init

