async def _v42_process_text_input(self: WorldApp, player: Any, value: str) -> str:
    action = str(player.pending_input or "")
    pdata = dict(player.pending_data or {})
    if action == "air_group_name":
        gid = str(pdata.get("group_id", ""))
        country = self.country_for(player.user_id)
        g = self.world.air_groups.get(gid)
        if not country or not g or g.get("country") != country:
            player.clear_input(); return "❌ Авиагруппа не найдена."
        player.clear_input()
