# --------------------------- stable country/session -------------------------
def _v44_game_country(self: WorldApp, user_id: int) -> Optional[str]:
    uid = int(user_id)
    p = self.world.players.get(uid)
    if p is None or bool(getattr(p, "banned", False)):
        return None
    # Authoritative persistent player country wins over transient notebook/session
    # state. This prevents HOME from opening another country's data.
    saved = getattr(p, "country", None)
    if saved in PLAYABLE_COUNTRIES:
        self._session_country[uid] = saved
        p.active_country = saved
        return saved
    active = getattr(p, "active_country", None)
    if active in PLAYABLE_COUNTRIES:
        p.country = active
        self._session_country[uid] = active
        return active
    runtime = getattr(self, "_session_country", {}).get(uid)
    if runtime in PLAYABLE_COUNTRIES:
        p.country = runtime
        p.active_country = runtime
        return runtime
    return None

WorldApp.country_for = _v44_game_country

def _v44_require_country(self: WorldApp, user_id: int) -> tuple[Optional[str], str]:
    p = self.world.players.get(int(user_id))
    if p is not None and bool(getattr(p, "banned", False)):
        return None, "⛔ Вы заблокированы."
    country = self.country_for(int(user_id))
    return (country, "") if country else (None, "🌍 Сначала выберите страну.")

WorldApp.require_country = _v44_require_country

