@classmethod
def _v44_home(cls):
    markup = _v44_home_prev.__func__(cls)
    rows = list(markup.inline_keyboard)
    rows = [list(r) for r in rows]
    rows.append([cls.btn("🚪 Выйти со страны", "country:exit")])
