Keyboards.home = _v44_home

_v44_callback_prev = WorldApp.on_callback
async def _v44_on_callback(self: WorldApp, callback: types.CallbackQuery) -> None:
    data = str(callback.data or "").strip()
    uid = int(callback.from_user.id)
    if data == "country:exit":
        await self.answer_callback(callback)
        p = self.player(uid, getattr(callback.from_user, "username", "") or "")
        old = self.country_for(uid)
        if old in PLAYABLE_COUNTRIES:
            self.world.add_log("country_release", uid, {"country": old})
        p.country = None
        p.active_country = None
        p.clear_input()
        self._session_country.pop(uid, None)
        self.world.mark_dirty()
        await self.show(callback, "🚪 <b>Вы вышли из страны.</b>\n\nТеперь выберите страну для нового входа.", Keyboards.country_picker())
        return
    await _v44_callback_prev(self, callback)
WorldApp.on_callback = _v44_on_callback

# --------------------------- robust numeric input ---------------------------
def _v44_parse_int(value: str) -> Optional[int]:
    s = str(value or "").strip().lower().replace(" ", "").replace("_", "")
    if not s:
        return None
    # Accept common Russian/English compact suffixes: к/кк/м/млн/б/млрд.
    mult = 1
    for suffix, factor in (("млрд", 1_000_000_000), ("млн", 1_000_000), ("кк", 1_000_000), ("к", 1_000), ("м", 1_000_000), ("б", 1_000_000_000)):
        if s.endswith(suffix):
            s = s[:-len(suffix)]
            mult = factor
            break
    s = s.replace(",", ".")
    try:
        if not s:
            return None
        return max(0, int(float(s) * mult))
    except (ValueError, TypeError):
        return None

