def _v44_equipment_lines(world: Any, division: dict[str, Any]) -> list[str]:
    template = DIVISION_TEMPLATES.get(str(division.get("template", "")), {})
    req = _equipment_total(template)
    country = str(division.get("country", ""))
    warehouse = world.country(country).warehouse if country in PLAYABLE_COUNTRIES else {}
    result = []
    for key, amount in req.items():
        model = PRODUCTION_CATALOG.get(key)
        label = model.name if model else model_display(key)
        have = int(warehouse.get(key, 0))
        result.append(f"• {esc(label)}: <b>{format_number(amount)}</b> шт. | склад: {format_number(have)}")
    return result

