_v44_process_text_prev = WorldApp.process_text_input
async def _v44_process_text_input(self: WorldApp, player: Any, value: str) -> str:
    action = str(player.pending_input or "")
    pdata = dict(player.pending_data or {})
    if action == "production_factories":
        country = str(pdata.get("country", ""))
        key = str(pdata.get("model", ""))
        player.clear_input()
        if country not in PLAYABLE_COUNTRIES or country != self.country_for(player.user_id):
            return "❌ Страна больше не является вашей активной страной."
        factories = _v44_parse_int(value)
        if factories is None:
            player.pending_input = "production_factories"
            player.pending_data = {"country": country, "model": key, "expires_at": time.monotonic()+300}
            return "❌ Введите целое число заводов, например 5."
        ok, reason = self.production.set_line(country, key, factories)
        if ok:
            self.spawn(self.save_light())
            return "✅ " + reason
        return "❌ " + reason
    return await _v44_process_text_prev(self, player, value)
WorldApp.process_text_input = _v44_process_text_input

