# WORLD STRATEGY V45 — ARMY AUTOPLAN + AIR OPERATIONS + PVO NETWORK
# =============================================================================
# This is a single final extension layer on top of the stable V44.1 UI.
# It keeps the stable country/session router and adds only the requested
# gameplay systems. Real-world weapon names below are GAME LABELS; values are
# intentionally game-balance parameters and are not real operational data.

V45_VERSION = "45.0.0-army-air-pvo-rework"
GAME_VERSION = V45_VERSION

# --------------------------- map contract ---------------------------
V45_MAP_CONTRACT = {
    COUNTRY_RAZBAGARE: {"capital": 1, "cities": [2, 3, 4]},
    COUNTRY_PEDAGOG: {"capital": 36, "cities": [37, 38, 39, 40]},
    COUNTRY_MARKLAND: {"capital": 79, "cities": [70, 75, 80, 89]},
}

# --------------------------- general automation --------------------
V45_MAX_GENERAL_PLAN_CELLS = MAX_DIVISIONS_PER_GENERAL
V45_GENERAL_ORDERS = {
    "hold": "🛑 Удерживать линию",
    "attack": "⚔️ Ручное наступление",
    "autoplan": "🤖 Автоплан наступления",
    "defense": "🛡️ Оборона",
    "stop": "⛔ Стоп",
}


def _v45_general_cells_allowed(world: Any, general: dict[str, Any]) -> int:
    return min(V45_MAX_GENERAL_PLAN_CELLS, len([d for d in general.get("divisions", []) if d in world.divisions]))


def _v45_front_targets(world: Any, country: str) -> list[int]:
    targets = []
    for pid in world.country(country).province_ids:
        for n in world.province(pid).neighbors:
            if world.province(n).country != country:
                targets.append(n)
    return sorted(set(targets))


def _v45_auto_assign(self: Army, general_id: str) -> tuple[bool, str]:
    g = self.world.generals.get(general_id)
    if not g:
        return False, "Генерал не найден."
    country = g.get("country")
    unassigned = [d for d in self.world.divisions.values() if d.get("country") == country and not d.get("general")]
    current = [d for d in self.world.divisions.values() if d.get("general") == general_id]
    capacity = MAX_DIVISIONS_PER_GENERAL - len(current)
    if capacity <= 0:
        return True, f"У генерала уже максимум {MAX_DIVISIONS_PER_GENERAL} дивизий."
    added = 0
    for d in sorted(unassigned, key=lambda x: (int(x.get("province", 0)), x.get("id", ""))):
        if added >= capacity:
            break
        self.attach_division(d["id"], general_id)
        added += 1
    self.world.mark_dirty()
    return True, f"✅ Автораспределение: назначено дивизий — {added}. Всего у генерала — {len(current)+added}/{MAX_DIVISIONS_PER_GENERAL}."
Army.auto_assign_general = _v45_auto_assign


def _v45_set_plan_cells(self: Army, general_id: str, cells: Iterable[int]) -> tuple[bool, str]:
    g = self.world.generals.get(general_id)
    if not g:
        return False, "Генерал не найден."
    count = len([d for d in g.get("divisions", []) if d in self.world.divisions])
    unique=[]
    for raw in cells:
        pid=int(raw)
        if pid in self.world.provinces and pid not in unique:
            unique.append(pid)
    if count == 0:
        return False, "Сначала назначьте дивизии генералу."
    if len(unique) != count:
        return False, f"Нужно выбрать ровно {count} клеток — по одной на каждую дивизию."
    if any(self.world.province(pid).country != g.get("country") for pid in unique):
        return False, "Клетки мирного плана должны быть на своей территории."
    g["cells"] = unique
    g["plan_cells"] = list(unique)
    g["hq_province"] = unique[0]
    for did, pid in zip(g.get("divisions", []), unique):
        if did not in self.world.divisions:
            continue
        d=self.world.divisions[did]
        old=int(d.get("province", pid))
        if old in self.world.provinces and did in self.world.province(old).armies:
            self.world.province(old).armies.remove(did)
        d["province"]=pid
        d["selected_cells"]=[pid]
        if did not in self.world.province(pid).armies:
            self.world.province(pid).armies.append(did)
    self.world.mark_dirty()
    return True, f"✅ План сохранён: {count} дивизий → {count} клеток."
Army.set_general_plan_cells = _v45_set_plan_cells


def _v45_set_general_order(self: Army, general_id: str, order: str, target: Optional[int] = None) -> tuple[bool, str]:
    g=self.world.generals.get(general_id)
    if not g:
        return False, "Генерал не найден."
    if order not in V45_GENERAL_ORDERS:
        return False, "Неизвестный приказ генерала."
    divisions=[self.world.divisions[d] for d in g.get("divisions",[]) if d in self.world.divisions]
    if not divisions and order in {"attack","autoplan","defense"}:
        return False, "У генерала нет дивизий."
    if order in {"attack","autoplan"}:
        if target is None or int(target) not in self.world.provinces:
            return False, "Для наступления выберите провинцию-цель."
        target=int(target)
        target_country=self.world.province(target).country
        if target_country == g.get("country"):
            return False, "Цель должна быть вне своей территории."
        if not _war_exists(self.world, g.get("country"), target_country):
            return False, "Для наступления нужна активная война с этой страной."
        if order == "autoplan":
            cells=list(g.get("plan_cells") or g.get("cells") or [])
            if len(cells) != len(divisions):
                return False, f"Для автоплана нужно ровно {len(divisions)} клеток."
            g["auto_plan"]={"target":target,"status":"active","started":self.world.game_minutes,"next_index":0}
        else:
            g["auto_plan"]={"target":target,"status":"manual","started":self.world.game_minutes,"next_index":0}
        g["order_target"]=target
    elif order == "stop":
        g["auto_plan"]={"target":None,"status":"stopped","started":self.world.game_minutes,"next_index":0}
        g["order_target"]=None
    else:
        g["auto_plan"]={"target":None,"status":order,"started":self.world.game_minutes,"next_index":0}
        g["order_target"]=None
        for d in divisions:
            d["order"]="defense" if order=="defense" else "hold"
    g["order"]=order
    self.world.mark_dirty()
    self.world.add_journal("army", "Приказ генерала", f"{g.get('name',general_id)}: {V45_GENERAL_ORDERS[order]}.")
    return True, f"✅ Приказ генерала: {V45_GENERAL_ORDERS[order]}."
Army.set_general_order = _v45_set_general_order


def _v45_army_autoplan_tick(self: Army, minutes: float) -> None:
    changed = False
    for g in self.world.generals.values():
        plan = g.get("auto_plan") or {}
        if g.get("order") != "autoplan" or plan.get("status") != "active":
            continue
        try:
            target = int(plan.get("target", -1))
        except (TypeError, ValueError):
            continue
        if target not in self.world.provinces:
            continue
        divisions = [self.world.divisions[d] for d in g.get("divisions", []) if d in self.world.divisions]
        cells = list(g.get("plan_cells") or g.get("cells") or [])
        if not divisions or len(cells) != len(divisions):
            continue
        # One division per planned cell; once free, it advances toward the common target.
        for d in divisions:
            if d.get("movement"):
                continue
            try:
                pid = int(d.get("province", 0))
            except (TypeError, ValueError):
                continue
            if pid == target:
                continue
            order = "attack" if self.world.province(target).country != d.get("country") else "advance"
            if d.get("order") != order or d.get("target_province") != target:
                changed = True
            d["order"] = order
            d["target_province"] = target
            if self._start_next_step(d):
                changed = True
        if all(int(d.get("province", -1)) == target for d in divisions):
            plan["status"] = "completed"
            g["order"] = "hold"
            self.world.add_journal(
                "army", "Автоплан завершён",
                f"Генерал {g.get('name') or g.get('id', 'без названия')} достиг цели {self.world.province(target).name}.",
            )
            changed = True
    # Avoid marking the entire world dirty on every tick when no plan changed.
    if changed:
        self.world.mark_dirty()

# The movement wrapper below calls this method through each Army instance.
Army._v45_autoplan_tick = _v45_army_autoplan_tick
_v45_army_tick_move_prev = Army.tick_movement
def _v45_tick_movement(self: Army, minutes: float) -> list[str]:
    self._v45_autoplan_tick(float(minutes))
    result=_v45_army_tick_move_prev(self, minutes)
    self._v45_autoplan_tick(0.0)
    return result
Army.tick_movement = _v45_tick_movement

# --------------------------- admin battle control ----------------
V45_BATTLE_BUFF = 0.20

def _v45_battle_key(war_id: str, province_id: int) -> str:
    return f"{war_id}:{int(province_id)}"


def _v45_active_battles(world: Any) -> list[dict[str, Any]]:
    rows=[]
    for war in world.wars.values():
        if not war.active:
            continue
        for pid,p in world.provinces.items():
            if p.country not in {war.attacker, war.defender}:
                continue
            a=[d for did in p.armies if (d:=world.divisions.get(did)) and d.get("country")==war.attacker]
            b=[d for did in p.armies if (d:=world.divisions.get(did)) and d.get("country")==war.defender]
            if a and b:
                rows.append({"war":war.id,"province":pid,"attacker":war.attacker,"defender":war.defender,
                             "attack_count":len(a),"defense_count":len(b),
                             "attack_power":province_army_strength(world,pid,war.attacker)["attack"],
                             "defense_power":province_army_strength(world,pid,war.defender)["defense"]})
    return rows


def _v45_admin_battle_control(self: WarEngine, war_id: str, province_id: int, action: str, country: Optional[str] = None) -> tuple[bool,str]:
    key=_v45_battle_key(war_id,province_id)
    battles={_v45_battle_key(x["war"],x["province"]): x for x in _v45_active_battles(self.world)}
    battle=battles.get(key)
    if not battle:
        return False,"Бой больше не идёт."
    controls=getattr(self.world,"admin_battle_controls",{})
    item=controls.setdefault(key,{"buffs":{},"verdict":None})
    if action=="buff":
        if country not in {battle["attacker"],battle["defender"]}:
            return False,"Неизвестная сторона боя."
        item["buffs"][country]=clamp(float(item["buffs"].get(country,0))+V45_BATTLE_BUFF, -0.90, 2.0)
        self.world.add_journal("admin", "Админ-бафф в бою", f"Сторона {country_display(country)} получила +20% к силе боя в провинции {self.world.province(province_id).name}.")
        self.world.mark_dirty()
        return True,"✅ Бафф +20% выдан стороне."
    if action=="verdict":
        if country not in {battle["attacker"],battle["defender"]}:
            return False,"Неизвестная сторона боя."
        item["verdict"]=country
        # Immediate admin verdict: move/retreat the losing side and transfer control.
        winner=country; loser=battle["defender"] if winner==battle["attacker"] else battle["attacker"]
        p=self.world.province(province_id)
        for did in list(p.armies):
            d=self.world.divisions.get(did)
            if not d or d.get("country")!=loser:
                continue
            candidates=[self.world.province(n) for n in p.neighbors if self.world.province(n).country==loser]
            candidates.sort(key=lambda x:(x.capital,x.city,x.condition), reverse=True)
            if candidates:
                self.army._move_finish(d,candidates[0].id)
            else:
                self.world.divisions.pop(did,None)
        self.army._transfer_province(province_id,winner)
        self.world.add_journal("admin", "Вердикт админа", f"Администратор определил исход боя: победа {country_display(winner)} в {p.name}.")
        item["verdict"]=winner
        self.world.mark_dirty()
        return True,f"✅ Вердикт вынесен: победа {country_display(winner)}."
    return False,"Неизвестное действие админа."
WarEngine.admin_battle_control = _v45_admin_battle_control

# Buffs are applied in a lightweight wrapper around battle calculations by
# temporarily amplifying effective unit stats for the duration of a resolve.
_v45_resolve_prev = WarEngine.resolve_battle
def _v45_resolve_battle(self: WarEngine, province_id: int, attacker_country: str, defender_country: str) -> dict[str,Any]:
    war=None
    for w in self.active_wars():
        if w.involves(attacker_country) and w.involves(defender_country):
            war=w; break
    key=_v45_battle_key(war.id,province_id) if war else None
    controls=getattr(self.world,"admin_battle_controls",{})
    item=controls.get(key,{}) if key else {}
    buffs=item.get("buffs",{}) if isinstance(item,dict) else {}
    old_attack=province_army_strength
    def wrapped_strength(world: Any, pid: int, code: Optional[str]=None):
        value=old_attack(world,pid,code)
        if code==attacker_country:
            factor=1.0+float(buffs.get(attacker_country,0))
            value={**value,"attack":value["attack"]*factor,"defense":value["defense"]*factor}
        elif code==defender_country:
            factor=1.0+float(buffs.get(defender_country,0))
            value={**value,"attack":value["attack"]*factor,"defense":value["defense"]*factor}
        return value
    globals()["province_army_strength"]=wrapped_strength
    try:
        result=_v45_resolve_prev(self,province_id,attacker_country,defender_country)
    finally:
        globals()["province_army_strength"]=old_attack
    if key and key in controls:
        # buffs last for one resolved battle
        controls.pop(key,None)
    return result
WarEngine.resolve_battle = _v45_resolve_battle

