def _v45_init_operation(g: dict[str,Any]) -> None:
    g.setdefault("operation",None)
    g.setdefault("strike_payload",None)
    g.setdefault("strike_route_mode",None)
    g.setdefault("strike_route",[])
    g.setdefault("strike_route_index",0)
    g.setdefault("attached_general",None)


def _v45_route(world: Any,start:int,end:int,allowed:Optional[set[int]]=None)->list[int]:
    start,end=int(start),int(end)
    if start not in world.provinces or end not in world.provinces:
        return []
    q=[start]; parent={start:None}
    while q:
        cur=q.pop(0)
        if cur==end: break
        for nxt in world.province(cur).neighbors:
            if nxt in parent: continue
            if allowed is not None and nxt not in allowed and nxt!=end: continue
            parent[nxt]=cur; q.append(nxt)
    if end not in parent: return []
    path=[end]
    while parent[path[-1]] is not None: path.append(parent[path[-1]])
    path.reverse(); return path


def _v45_city_radar_ids(world: Any,country:str)->list[int]:
    city=set(V45_MAP_CONTRACT[country]["cities"]+[V45_MAP_CONTRACT[country]["capital"]])
    eligible=[pid for pid in world.country(country).province_ids if pid not in city]
    rng=random.Random(4500+int(country))
    rng.shuffle(eligible)
    return sorted(city | set(eligible[:2]))


def _v45_init_world(world: WorldState)->None:
    # Exact map contract from the user's final map design.
    for code,meta in V45_MAP_CONTRACT.items():
        cap=meta["capital"]
        assert world.province(cap).name==SPECIAL_PROVINCE_NAMES[cap]
        for pid in meta["cities"]:
            assert world.province(pid).name==SPECIAL_PROVINCE_NAMES[pid]
        for pid in V45_MAP_CONTRACT[code]["cities"]+[cap]:
            p=world.province(pid)
            if p.building_level("airfield")<1: p.add_building("airfield",1)
            p.building_condition["airfield"]=100.0
            if p.building_level("radar")<1: p.add_building("radar",1)
            p.building_condition["radar"]=100.0
        for pid in _v45_city_radar_ids(world,code):
            p=world.province(pid)
            if p.building_level("radar")<1: p.add_building("radar",1)
            p.building_condition["radar"]=100.0
    if not hasattr(world,"admin_battle_controls"): world.admin_battle_controls={}
    if not hasattr(world,"pvo_engagements"): world.pvo_engagements=[]
    world.mark_dirty()

_v45_world_init_prev = WorldState.__init__
def _v45_world_init(self:WorldState,*args:Any,**kwargs:Any)->None:
    _v45_world_init_prev(self,*args,**kwargs)
    _v45_init_world(self)
WorldState.__init__=_v45_world_init

