    self.admin_battle_controls=copy.deepcopy(data.get("admin_battle_controls",{})) if isinstance(data.get("admin_battle_controls",{}),dict) else {}
    self.pvo_engagements=list(data.get("pvo_engagements",[]))[-100:] if isinstance(data.get("pvo_engagements",[]),list) else []
    _v45_init_world(self)
