def _v45_operation_duration(group:dict[str,Any],route:list[int],missile:Optional[str],target:int,launch:int,mode:str)->dict[str,float]:
    speed=_v45_air_speed(group)
    if missile:
        flight_to_launch=max(0,len(route)-1)*speed
        missile_dist=_v42_graph_distance(group.get("_world"),launch,target,1000) if group.get("_world") else None
        missile_dist=float(missile_dist or 0)
        missile_time=missile_dist*float(V45_MISSILES[missile]["speed"])
        return_to_base=flight_to_launch
        total=V45_AIR_ARMING_MINUTES+V45_AIR_TAKEOFF_MINUTES+flight_to_launch+missile_time+return_to_base
        return {"arming":60.0,"takeoff":5.0,"flight_to_launch":flight_to_launch,"missile_flight":missile_time,"return":return_to_base,"total":total}
    flight=max(0,len(route)-1)*speed
    total=V45_AIR_ARMING_MINUTES+V45_AIR_TAKEOFF_MINUTES+flight+flight
    return {"arming":60.0,"takeoff":5.0,"flight_to_target":flight,"return":flight,"total":total}


def _v45_find_launch(world:Any,country:str,target:int,mode:str)->tuple[int,list[int]]:
    owned=set(world.country(country).province_ids)
    candidates=[]
    for pid in owned:
        if mode=="sea" and not world.province(pid).sea_access: continue
        if mode=="own" and not any(world.province(n).country!=country for n in world.province(pid).neighbors): continue
        dist=_v42_graph_distance(world,pid,target,100)
        if dist is None: continue
        candidates.append((dist,pid))
    if not candidates: return -1,[]
    _,launch=min(candidates)
    route=_v45_route(world, None if launch<0 else next((x for x in owned if x==launch),launch), launch, owned) if False else None
    return launch,[]


def _v45_build_route(world:Any,group:dict[str,Any],target:int,mode:str,weapon_type:str)->tuple[bool,str,list[int],int]:
    start=_v42_group_position(group)
    country=group.get("country")
    owned=set(world.country(country).province_ids)
    if mode=="sea":
        sea=[pid for pid in owned if world.province(pid).sea_access]
        ranked=[(x:=_v42_graph_distance(world,pid,target,100),pid) for pid in sea]
        ranked=[x for x in ranked if x[0] is not None]
        if not ranked: return False,"Не найден морской маршрут.",[], -1
        _,launch=min(ranked,key=lambda x:x[0])
        outbound=_v45_route(world,start,launch,owned)
        if weapon_type=="missile":
            return True,"",outbound,launch
        after=_v45_route(world,launch,target,None)
        return True,"",outbound+after[1:],launch
    # own: keep the outbound route in own provinces until launch/border.
    if weapon_type=="missile":
        border=[pid for pid in owned if any(world.province(n).country!=country for n in world.province(pid).neighbors)]
        ranked=[(x:=_v42_graph_distance(world,pid,target,10),pid) for pid in border]
        ranked=[x for x in ranked if x[0] is not None and x[0]<=10]
        if not ranked: return False,"В пределах 10 провинций нет зоны пуска.",[], -1
        _,launch=min(ranked,key=lambda x:x[0])
        outbound=_v45_route(world,start,launch,owned)
        if not outbound: return False,"Не построен маршрут по своим провинциям.",[], -1
        return True,"",outbound,launch
    # bombs/UAV: own territory until first hostile cell, then target.
    border=[pid for pid in owned if any(world.province(n).country!=country for n in world.province(pid).neighbors)]
    ranked=[]
    for pid in border:
        path=_v45_route(world,start,pid,owned)
        if path: ranked.append((len(path),pid,path))
    if not ranked: return False,"Не найден маршрут через свои провинции.",[], -1
    _,bpid,own_path=min(ranked,key=lambda x:x[0])
    after=_v45_route(world,bpid,target,None)
    if not after: return False,"Не найден перелёт к цели.",[], -1
    return True,"",own_path+after[1:],bpid


def _v45_prepare_strike(self:Aviation,group_id:str,target_country:str,target_province:int,weapon:str,missile:str|None=None,route_mode:str="own",missile_qty:int=1)->tuple[bool,str]:
    g=self.world.air_groups.get(group_id)
    if not g: return False,"Авиагруппа не найдена."
    _v45_init_operation(g)
    if g.get("country")==target_country: return False,"Цель должна быть в другой стране."
    if target_country not in PLAYABLE_COUNTRIES or int(target_province) not in self.world.provinces: return False,"Цель не найдена."
    target_province=int(target_province)
    if self.world.province(target_province).country!=target_country: return False,"Провинция не принадлежит выбранной стране."
    model=g.get("model")
    if weapon=="missile":
        allowed=V45_CARRIER_MISSILES.get(model,set())
        if missile not in allowed: return False,"Эта ракета недоступна для данной авиагруппы."
        m=V45_MISSILES[missile]
        if missile_qty<1: return False,"Количество ракет должно быть больше нуля."
        maxq=int(g.get("quantity",0))*int(m["capacity"])
        if missile_qty>maxq: return False,f"Эта авиагруппа может взять максимум {maxq} ракет данного типа."
    elif weapon not in {"cab","uav_payload"}:
        return False,"Неизвестный тип удара."
    ok,reason,route,launch=_v45_build_route(self.world,g,target_province,route_mode,weapon if weapon=="missile" else "bomb")
    if not ok: return False,reason
    if weapon=="missile":
        dist=_v42_graph_distance(self.world,launch,target_province,1000)
        if dist is None or dist>V45_MISSILES[missile]["range"]: return False,"Цель вне дальности выбранной ракеты."
    g["strike_payload"]={"weapon":weapon,"missile":missile,"missile_qty":int(missile_qty),"target_country":target_country,"target_province":target_province}
    g["strike_route_mode"]=route_mode
    g["strike_route"]=route
    g["strike_route_index"]=0
    g["operation"]={"status":"arming","started_at":self.world.game_minutes,"arm_complete_at":self.world.game_minutes+V45_AIR_ARMING_MINUTES,
                     "phase":"arming","phase_started":self.world.game_minutes,"target":target_province,
                     "launch":launch,"weapon":weapon,"missile":missile,"missile_qty":int(missile_qty),"route":route,
                     "route_index":0,"allow_takeoff":False,"operation_mode":route_mode,"flight_minutes_done":0.0}
    g["manual"]=True
    self.world.mark_dirty()
    return True,f"✅ Операция запланирована. Вооружение: {int(V45_AIR_ARMING_MINUTES)} мин. Маршрут: {V45_STRIKE_ROUTE_MODES[route_mode]}."
Aviation.prepare_strike_v45=_v45_prepare_strike


def _v45_operation_remaining(world:Any,g:dict[str,Any])->float:
    op=g.get("operation") or {}
    if not op: return 0.0
    phase=op.get("phase")
    now=float(world.game_minutes)
    if phase=="arming": return max(0.0,float(op.get("arm_complete_at",now))-now)
    total=0.0
    return max(0.0,total)


def _v45_permit_takeoff(self:Aviation,group_id:str)->tuple[bool,str]:
    g=self.world.air_groups.get(group_id); op=g.get("operation") if g else None
    if not g or not op: return False,"Нет запланированной операции."
    if op.get("phase")!="arming": return False,"Операция уже не на этапе подготовки."
    if self.world.game_minutes<float(op.get("arm_complete_at",0)): return False,f"Вооружение ещё идёт. Осталось {int(round(float(op.get('arm_complete_at'))-self.world.game_minutes))} мин."
    op["phase"]="ready_takeoff"; op["allow_takeoff"]=True; op["phase_started"]=self.world.game_minutes
    self.world.mark_dirty(); return True,"✅ Подготовка завершена. Можно дать разрешение на взлёт."
Aviation.permit_takeoff=_v45_permit_takeoff


def _v45_start_takeoff(self:Aviation,group_id:str)->tuple[bool,str]:
    g=self.world.air_groups.get(group_id); op=g.get("operation") if g else None
    if not g or not op: return False,"Нет подготовленной операции."
    if op.get("phase")!="ready_takeoff": return False,"Сначала дождитесь окончания вооружения."
    op["phase"]="takeoff"; op["phase_started"]=self.world.game_minutes; op["takeoff_end"]=self.world.game_minutes+V45_AIR_TAKEOFF_MINUTES
    self.world.mark_dirty(); return True,"✅ Разрешение на взлёт получено. Взлёт займёт 5 мин."
Aviation.start_takeoff=_v45_start_takeoff


def _v45_render_operation_progress(world:Any,g:dict[str,Any])->str:
    op=g.get("operation") or {}
    if not op: return "Операция: нет."
    phase=op.get("phase")
    now=float(world.game_minutes)
    target=int(op.get("target",-1))
    target_name=world.province(target).name if target in world.provinces else "—"
    route=list(op.get("route") or [])
    idx=int(op.get("route_index",0))
    remain=0.0
    if phase=="arming": remain=max(0,float(op.get("arm_complete_at",now))-now)
    elif phase=="takeoff": remain=max(0,float(op.get("takeoff_end",now))-now)
    elif phase=="flight":
        remain=max(0,(len(route)-1-idx)*_v45_air_speed(g))
    elif phase=="missile":
        remain=max(0,float(op.get("missile_remaining",0)))
    elif phase=="return":
        remain=max(0,(len(route)-1-idx)*_v45_air_speed(g))
    payload=V45_MISSILES.get(op.get("missile"),{}) if op.get("missile") else {}
    weapon_name=payload.get("name") if payload else ("💣 КАБ" if op.get("weapon")=="cab" else "🛰️ БПЛА")
    done=0; total=1
    if phase=="arming": done=max(0,V45_AIR_ARMING_MINUTES-remain); total=V45_AIR_ARMING_MINUTES
    elif phase=="takeoff": done=max(0,V45_AIR_TAKEOFF_MINUTES-remain); total=V45_AIR_TAKEOFF_MINUTES
    elif phase in {"flight","return"}: total=max(1,(len(route)-1)*_v45_air_speed(g)); done=max(0,total-remain)
    elif phase=="missile": total=max(1,float(op.get("missile_total",remain))); done=max(0,total-remain)
    pct=min(100,max(0,100*done/total)) if total else 100
    bar="🟩"*min(10,int(pct//10))+"⬜"*max(0,10-int(pct//10))
    return f"📊 <b>Ход операции</b>\n\n{bar} <b>{pct:.0f}%</b>\nЭтап: <b>{phase}</b>\nСредство: <b>{esc(weapon_name)}</b>\nЦель: <b>{esc(target_name)}</b>\nОсталось: <b>{int(round(remain))} мин.</b>"


def _v45_air_progress_tick(self:Aviation,minutes:float)->list[dict[str,Any]]:
    events=[]
    remaining=float(minutes)
    while remaining>0:
        step=min(5.0,remaining)
        for g in self.world.air_groups.values():
            _v45_init_operation(g)
            op=g.get("operation")
            if not isinstance(op,dict): continue
            phase=op.get("phase")
            now=float(self.world.game_minutes)
            if phase=="arming" and now>=float(op.get("arm_complete_at",now)):
                op["phase"]="ready_takeoff"; op["allow_takeoff"]=True; op["phase_started"]=now
                self.world.add_log("air_operation_ready",None,{"group":g["id"]})
            elif phase=="takeoff":
                if now>=float(op.get("takeoff_end",now)):
                    op["phase"]="flight"; op["phase_started"]=now
                    g["flight_province"]=_v42_group_position(g); op["route_index"]=0
            elif phase=="flight":
                route=list(op.get("route") or []); idx=int(op.get("route_index",0))
                speed=max(0.5,_v45_air_speed(g)); op.setdefault("leg_progress",0.0); op["leg_progress"]+=step
                while op["leg_progress"]>=speed and idx < len(route)-1:
                    op["leg_progress"]-=speed; idx+=1; op["route_index"]=idx; g["flight_province"]=int(route[idx])
                    if op.get("weapon")=="missile" and int(g.get("flight_province",-1))==int(op.get("launch",-2)):
                        m=V45_MISSILES.get(op.get("missile"),{}); dist=_v42_graph_distance(self.world,int(op["launch"]),int(op["target"]),1000) or 0
                        op["phase"]="missile"; op["missile_total"]=float(dist)*float(m.get("speed",5)); op["missile_remaining"]=op["missile_total"]; op["phase_started"]=now
                        break
                if op.get("phase")=="flight" and idx>=len(route)-1:
                    if op.get("weapon") in {"cab","uav_payload"}:
                        # target reached: execute impact, then return on the reverse route.
                        events.append(self._v45_complete_impact(g))
                        op["phase"]="return"; op["phase_started"]=now; op["return_route"]=list(reversed(route)); op["route"]=list(reversed(route)); op["route_index"]=0; op["leg_progress"]=0.0
            elif phase=="missile":
                op["missile_remaining"]=max(0,float(op.get("missile_remaining",0))-step)
                if op["missile_remaining"]<=0:
                    events.append(self._v45_complete_impact(g))
                    route=list(op.get("route") or []); op["route"]=list(reversed(route)); op["route_index"]=0; op["phase"]="return"; op["phase_started"]=now; op["leg_progress"]=0.0
            elif phase=="return":
                route=list(op.get("route") or []); idx=int(op.get("route_index",0)); speed=max(0.5,_v45_air_speed(g)); op.setdefault("leg_progress",0.0); op["leg_progress"]+=step
                while op["leg_progress"]>=speed and idx<len(route)-1:
                    op["leg_progress"]-=speed; idx+=1; op["route_index"]=idx; g["flight_province"]=int(route[idx])
                if idx>=len(route)-1:
                    g["flight_province"]=int(g.get("airfield_province",route[-1] if route else -1)); g["operation"]={"phase":"completed","completed_at":self.world.game_minutes}
                    self.world.add_log("air_operation_complete",None,{"group":g["id"]})
        remaining-=step
    self.world.mark_dirty()
    return [e for e in events if e]


def _v45_complete_impact(self:Aviation,g:dict[str,Any])->dict[str,Any]:
    op=g.get("operation") or {}; target=int(op.get("target",-1)); country=op.get("target_country") or None
    payload=op.get("missile")
    if payload:
        m=V45_MISSILES[payload]; qty=int(op.get("missile_qty",1)); raw=float(m["damage_value"])*qty*max(1,int(g.get("quantity",1)))
        label=m["name"]
    else:
        raw=85.0*max(1,int(g.get("quantity",1))); label="КАБ" if op.get("weapon")=="cab" else "БПЛА"
    event={"mission":"strike","group":g["id"],"target_country":country,"target_province":target,"raw_strike_power":raw,"power":raw,"strike_weapon":op.get("weapon"),"strike_weapon_label":label,"missile":payload}
    g["readiness"]=clamp(float(g.get("readiness",100))-6); g["condition"]=clamp(float(g.get("condition",100))-2)
    g["last_strike"]={"time":self.world.game_minutes,**copy.deepcopy(event)}
    self.world.add_journal("aviation","Удар выполнен",f"{g.get('name',g['id'])}: {label} → {self.world.province(target).name}.",g.get("country"))
    return event
Aviation._v45_complete_impact=_v45_complete_impact

_v45_air_tick_old = Aviation.tick
def _v45_air_tick(self:Aviation,minutes:float)->list[dict[str,Any]]:
    events=list(_v45_air_tick_old(self,minutes) or [])
    events.extend(_v45_air_progress_tick(self,minutes))
    return events
Aviation.tick=_v45_air_tick

