def _v45_radar_coverage(world:Any,country:str)->set[int]:
    covered=set()
    radars=[pid for pid in world.country(country).province_ids if world.province(pid).building_level("radar")>0 and world.province(pid).condition_of("radar")>0]
    for r in radars:
        covered.add(r)
        for n in world.province(r).neighbors:
            covered.add(n)
            for nn in world.province(n).neighbors:
                covered.add(nn)
    return covered


def _v45_pvo_can_cover(self:PVO,country:str,province_id:int,model_key:str)->bool:
    meta=V45_PVO_MODELS.get(model_key,{})
    if meta.get("type")=="anti_drone":
        return _province_owned(self.world,country,province_id)
    return int(province_id) in _v45_radar_coverage(self.world,country)
PVO.can_cover=_v45_pvo_can_cover

_v45_pvo_deploy_prev=PVO.deploy
def _v45_pvo_deploy(self:PVO,country_code:str,model_key:str,quantity:int,province_id:int):
    if model_key in V45_PVO_MODELS:
        meta=V45_PVO_MODELS[model_key]; province_id=int(province_id)
        if not _province_owned(self.world,country_code,province_id): return False,"Провинция должна быть вашей.",None
        if meta["type"]!="anti_drone" and not _v45_pvo_can_cover(self,country_code,province_id,model_key):
            return False,"Для этого комплекса нужна зона покрытия радаров.",None
    result=_v45_pvo_deploy_prev(self,country_code,model_key,quantity,province_id)
    if result[0] and model_key in V45_PVO_MODELS:
        uid=result[2]; u=self.world.pvo_units[uid]; u["pvo_type"]=V45_PVO_MODELS[model_key]["type"]; u["interceptor_speed"]=V45_PVO_MODELS[model_key]["interceptor_speed"]; u["upgraded"] = bool(u.get("upgraded",False))
    return result
PVO.deploy=_v45_pvo_deploy


def _v45_upgrade_antidrone(self:PVO,unit_id:str)->tuple[bool,str]:
    u=self.world.pvo_units.get(unit_id)
    if not u: return False,"ПВО не найдено."
    model=V45_PVO_MODELS.get(u.get("model"),{})
    if model.get("type")!="anti_drone": return False,"Улучшать ракетами можно только противодронные комплексы."
    if u.get("upgraded"): return False,"Этот комплекс уже улучшен."
    c=self.world.country(u["country"])
    cost=80
    if c.resources.get("steel",0)<cost: return False,f"Нужно {cost} стали."
    c.resources["steel"]-=cost; u["upgraded"]=True; u["missile_chance"]=0.20; u["aircraft_missile_chance"]=0.10
    self.world.mark_dirty(); return True,"✅ Противодронный комплекс улучшен ракетным перехватчиком: ракета 20%, самолёт 10%."
PVO.upgrade_antidrone=_v45_upgrade_antidrone

_v45_pvo_intercept_prev=PVO.intercept
def _v45_pvo_intercept(self:PVO,country_code:str,province_id:int,incoming_power:float)->dict[str,Any]:
    units=self.units(country_code)
    local=[]; radar=[]
    covered=_v45_radar_coverage(self.world,country_code)
    for u in units:
        meta=V45_PVO_MODELS.get(u.get("model"))
        if not meta: continue
        if meta["type"]=="anti_drone":
            if int(u.get("province",-1))==int(province_id): local.append(u)
        elif int(province_id) in covered: radar.append(u)
    selected=local+radar
    if not selected:
        result={"detected":False,"prevented":False,"effect":0.0,"remaining":incoming_power,"targets":[]}
    else:
        strength=sum(float(u.get("strength",0))*clamp(float(u.get("readiness",0)))/100*clamp(float(u.get("condition",0)))/100 for u in selected)
        detection=min(100, sum(float(V45_PVO_MODELS.get(u.get("model"),{}).get("detection",0)) for u in selected))
        chance=clamp(detection*0.25+strength*0.55,0,95)/100
        # Keep baseline PVO stochasticity but record all selected targets.
        prevented=self._rng.random()<chance
        effect=min(incoming_power,max(10.0,strength*0.75)) if prevented else min(incoming_power*0.20,max(0.0,strength*0.10))
        result={"detected":detection>0,"prevented":prevented,"effect":effect,"remaining":max(0.0,incoming_power-effect),"targets":[u["id"] for u in selected]}
        for u in selected:
            u["readiness"]=clamp(float(u.get("readiness",100))-2.0); u["condition"]=clamp(float(u.get("condition",100))-0.35)
    entry={"time":self.world.game_minutes,"country":country_code,"province":int(province_id),"incoming_power":incoming_power,**copy.deepcopy(result)}
    self.world.pvo_engagements.append(entry); self.world.pvo_engagements=self.world.pvo_engagements[-100:]
    self.world.mark_dirty()
    return result
PVO.intercept=_v45_pvo_intercept

# --------------------------- fighter/general coupling ----------------------
def _v45_attach_storm(self:Aviation,group_id:str,general_id:Optional[str])->tuple[bool,str]:
    g=self.world.air_groups.get(group_id)
    if not g: return False,"Авиагруппа не найдена."
    if g.get("model")!="stormtrooper": return False,"Прикрепить к генералу можно только штурмовики."
    if general_id is None:
        g["attached_general"]=None; self.world.mark_dirty(); return True,"Штурмовики откреплены от генерала."
    gen=self.world.generals.get(general_id)
    if not gen or gen.get("country")!=g.get("country"): return False,"Генерал не найден."
    g["attached_general"]=general_id; self.world.mark_dirty(); return True,f"✅ Штурмовики прикреплены к генералу {gen.get('name')}."
Aviation.attach_to_general=_v45_attach_storm


def _v45_cas_bonus(world:Any,country:str,pid:int)->float:
    bonus=0.0
    for g in world.air_groups.values():
        if g.get("country")!=country or g.get("model")!="stormtrooper" or not g.get("attached_general"): continue
        pos=_v42_group_position(g); dist=_v42_graph_distance(world,pos,pid,5)
        if dist is not None:
            bonus+=min(0.25,0.10/(dist+1))*max(1,int(g.get("quantity",0))/12)
    return min(0.30,bonus)

_v45_div_attack_prev=division_attack_power
def _v45_division_attack_power(world:Any,division_id:str,province_id:Optional[int]=None)->float:
    base=_v45_div_attack_prev(world,division_id,province_id)
    d=world.divisions.get(division_id)
    if not d: return base
    pid=int(province_id if province_id is not None else d.get("province",0))
    return base*(1.0+_v45_cas_bonus(world,d.get("country"),pid))
globals()["division_attack_power"]=_v45_division_attack_power

# --------------------------- aviation UI -------------------------
_v45_handle_air_prev=WorldApp.handle_air
async def _v45_handle_air(self:WorldApp,callback:types.CallbackQuery,data:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback,error,Keyboards.country_picker()); return
    if data.startswith("airname:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        p=self.player(callback.from_user.id); p.pending_input="air_group_name"; p.pending_data={"group_id":gid,"expires_at":time.monotonic()+600}
        await self.show(callback,"✏️ Введите название авиагруппы:",Keyboards.simple_nav(f"airgroup:{gid}")); return
    if data.startswith("airstatus:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        _v45_init_operation(g); progress=_v45_render_operation_progress(self.world,g)
        rows=[]
        if (g.get("operation") or {}).get("phase")=="arming":
            rows.append([Keyboards.btn("✅ Проверить подготовку","aircheckready:"+gid)])
        if (g.get("operation") or {}).get("phase")=="ready_takeoff":
            rows.append([Keyboards.btn("🛫 Разрешить взлёт","airtakeoff:"+gid)])
        rows += Keyboards.nav(f"airgroup:{gid}")
        await self.show(callback,f"✈️ <b>{esc(g.get('name',''))}</b>\n\n{progress}",types.InlineKeyboardMarkup(inline_keyboard=rows))
        return
    if data.startswith("aircheckready:"):
        gid=data.split(":",1)[1]; ok,reason=self.aviation.permit_takeoff(gid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"airstatus:{gid}")); return
    if data.startswith("airtakeoff:"):
        gid=data.split(":",1)[1]; ok,reason=self.aviation.start_takeoff(gid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"airstatus:{gid}")); return
    if data.startswith("airattachgen:"):
        _,gid,general=data.split(":",2); gid=str(gid); ok,reason=self.aviation.attach_to_general(gid,None if general=="none" else general); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"airgroup:{gid}")); return
    if data.startswith("airstrikev45:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        if g.get("model") in UAV_MODELS:
            rows=[[Keyboards.btn("🎯 Выбрать цель",f"airstrikev45target:{gid}")],[Keyboards.btn("📊 Текущая операция",f"airstatus:{gid}")],*Keyboards.nav(f"airgroup:{gid}")]
            await self.show(callback,"🛰️ <b>Удар БПЛА</b>\n\nВыберите цель, затем один из двух маршрутов. Для БПЛА отдельная ракета не выбирается.",types.InlineKeyboardMarkup(inline_keyboard=rows))
            return
        rows=[[Keyboards.btn("🎯 Выбрать цель",f"airstrikev45target:{gid}")],[Keyboards.btn("📊 Текущая операция",f"airstatus:{gid}")],*Keyboards.nav(f"airgroup:{gid}")]
        await self.show(callback,"💥 <b>Планирование удара</b>\n\nЗдесь заранее выбираются цель, боеприпас/ракета, количество и маршрут.\n\nПосле подготовки нужно дождаться 60 мин вооружения, затем дать разрешение на взлёт.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airstrikev45type:"):
        _,gid,weapon,targettxt,qtxt=data.split(":",4)
        g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: return
        rows=[[Keyboards.btn(COUNTRY_NAMES[x],f"airstrikev45country:{gid}:{weapon}:{x}")] for x in PLAYABLE_COUNTRIES if x!=country]
        await self.show(callback,"🎯 Выберите страну-цель:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airgroup:{gid}")])); return
    if data.startswith("airstrikev45target:"):
        gid=data.split(":",1)[1]; rows=[[Keyboards.btn(COUNTRY_NAMES[x],f"airstrikev45country:{gid}:choose:{x}")] for x in PLAYABLE_COUNTRIES if x!=country]
        await self.show(callback,"🎯 Выберите страну-цель:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airgroup:{gid}")])); return
    if data.startswith("airstrikev45country:"):
        _,gid,mode,target=data.split(":",3); rows=[[Keyboards.btn(self.world.province(pid).name,f"airstrikev45prov:{gid}:{mode}:{target}:{pid}")] for pid in self.world.country(target).province_ids[:60]]
        await self.show(callback,"📍 Выберите провинцию-цель:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airstrikev45:{gid}")])); return
    if data.startswith("airstrikev45prov:"):
        _,gid,mode,target,pidtxt=data.split(":",4); pid=int(pidtxt); g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: return
        if g.get("model") in UAV_MODELS:
            rows=[[Keyboards.btn(v,f"airuavroute:{gid}:{target}:{pid}:{k}")] for k,v in V45_STRIKE_ROUTE_MODES.items()]
            await self.show(callback,f"🛰️ Цель: {esc(self.world.province(pid).name)}\n\nВыберите маршрут БПЛА:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airgroup:{gid}")])); return
        rows=[]
        for key in sorted(V45_CARRIER_MISSILES.get(g.get("model"),set())):
            m=V45_MISSILES[key]; rows.append([Keyboards.btn(f"🚀 {m['name']} — {m['damage']} / {m['speed']:.0f} мин/пров. / макс {m['capacity']} на самолёт",f"airmissilepick:{gid}:{target}:{pid}:{key}")])
        rows.append([Keyboards.btn("💣 КАБ",f"aircabpick:{gid}:{target}:{pid}")])
        await self.show(callback,f"💥 Цель: {esc(self.world.province(pid).name)}\n\nВыберите средство удара.",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airstrikev45:{gid}")])); return
    if data.startswith("airmissilepick:"):
        _,gid,target,pidtxt,missile=data.split(":",4); pid=int(pidtxt); g=self.world.air_groups.get(gid); m=V45_MISSILES.get(missile)
        if not g or not m: return
        maxq=int(g.get("quantity",0))*int(m["capacity"]); qs=dict.fromkeys([1,max(1,min(4,maxq)),maxq])
        rows=[[Keyboards.btn(f"{q} ракет",f"airmissileqty:{gid}:{target}:{pid}:{missile}:{q}")] for q in qs if q<=maxq]
        await self.show(callback,f"🚀 <b>{esc(m['name'])}</b>\n\nСкорость: {m['speed']:.0f} мин/пров.\nУрон: {m['damage']}\nДальность: {m['range']} пров.\nВместимость: {m['capacity']} на самолёт\nМаксимум для группы: {maxq}\n\nВыберите количество:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airstrikev45:{gid}")])); return
    if data.startswith("airmissileqty:"):
        _,gid,target,pidtxt,missile,qtxt=data.split(":",5); pid=int(pidtxt); q=int(qtxt)
        rows=[[Keyboards.btn(v,f"airplan:{gid}:missile:{missile}:{target}:{pid}:{q}:{k}")] for k,v in V45_STRIKE_ROUTE_MODES.items()]
        await self.show(callback,f"🚀 {V45_MISSILES[missile]['name']} ×{q}\n\nВыберите маршрут:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airstrikev45:{gid}")])); return
    if data.startswith("aircabpick:"):
        _,gid,target,pidtxt=data.split(":",3); pid=int(pidtxt)
        rows=[[Keyboards.btn(v,f"airplan:{gid}:cab:none:{target}:{pid}:0:{k}")] for k,v in V45_STRIKE_ROUTE_MODES.items()]
        await self.show(callback,"💣 КАБ\n\nВыберите маршрут:",types.InlineKeyboardMarkup(inline_keyboard=rows+[Keyboards.nav(f"airstrikev45:{gid}")])); return
    if data.startswith("airuavroute:"):
        _,gid,target,pidtxt,mode=data.split(":",4); pid=int(pidtxt)
        ok,reason=self.aviation.prepare_strike_v45(gid,target,pid,"uav_payload",None,mode,1); self.spawn(self.save_light());
        await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"airstatus:{gid}")); return
    if data.startswith("airplan:"):
        _,gid,weapon,missile,target,pidtxt,qtxt,mode=data.split(":",7); pid=int(pidtxt); q=int(qtxt)
        ok,reason=self.aviation.prepare_strike_v45(gid,target,pid,weapon,missile if missile!="none" else None,mode,q)
        self.spawn(self.save_light())
        await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"airstatus:{gid}")); return
    if data.startswith("airgroup:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if g and g.get("country")==country:
            _v45_init_operation(g); model=AIR_MODELS.get(g.get("model")) or UAV_MODELS.get(g.get("model")); progress=_v45_render_operation_progress(self.world,g) if g.get("operation") else "Операция не запланирована."
            rows=[[Keyboards.btn("✏️ Название",f"airname:{gid}"),Keyboards.btn("💥 Новый удар",f"airstrikev45:{gid}")],[Keyboards.btn("📊 Статус операции",f"airstatus:{gid}"),Keyboards.btn("🛫 Перебазировать",f"airrebase:{gid}")]]
            if g.get("model")=="stormtrooper":
                rows.append([Keyboards.btn("👤 Прикрепить к генералу",f"airstormgen:{gid}")])
            rows += Keyboards.nav("air:groups")
            text=f"✈️ <b>{esc(g.get('name',''))}</b>\n\nМодель: {esc(model.name if model else g.get('model'))}\nКоличество: {g.get('quantity',0)}\nСкорость: {_v45_air_speed(g):.0f} мин/пров.\nБаза: {self.world.province(g['airfield_province']).name}\nПоложение: {self.world.province(_v42_group_position(g)).name}\n\n{progress}"
            await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airstormgen:"):
        gid=data.split(":",1)[1]; gens=self.army.country_generals(country); rows=[[Keyboards.btn(g["name"],f"airattachgen:{gid}:{g['id']}")] for g in gens]; rows.append([Keyboards.btn("Без генерала",f"airattachgen:{gid}:none")]); rows+=Keyboards.nav(f"airgroup:{gid}"); await self.show(callback,"👤 Выберите генерала для штурмовиков:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    # Keep V42 old aviation functions available for everything else.
    await _v45_handle_air_prev(self,callback,data)
WorldApp.handle_air=_v45_handle_air

_v45_process_text_prev=WorldApp.process_text_input
async def _v45_process_text_input(self:WorldApp,player:Any,value:str)->str:
    action=str(player.pending_input or "")
    pdata=dict(player.pending_data or {})
    if action=="air_group_name":
        gid=str(pdata.get("group_id","")); country=self.country_for(player.user_id); g=self.world.air_groups.get(gid); player.clear_input()
        if not country or not g or g.get("country")!=country: return "❌ Авиагруппа не найдена."
        ok,reason=self.aviation.rename_group(gid,value); self.spawn(self.save_light()); player.pending_data["_post_route"]=f"airgroup:{gid}"; return ("✅ " if ok else "❌ ")+reason
    return await _v45_process_text_prev(self,player,value)
WorldApp.process_text_input=_v45_process_text_input

