# --------------------------- army UI extension --------------------
_v45_handle_army_prev=WorldApp.handle_army
async def _v45_handle_army(self:WorldApp,callback:types.CallbackQuery,data:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country: await self.show(callback,error,Keyboards.country_picker()); return
    if data=="army:battles":
        battles=_v45_active_battles(self.world)
        if not battles: await self.show(callback,"⚔️ <b>Активные битвы</b>\n\nСейчас боёв нет.",Keyboards.simple_nav("screen:army")); return
        rows=[]
        for b in battles[:30]: rows.append([Keyboards.btn(f"⚔️ {self.world.province(b['province']).name}: {b['attack_count']} vs {b['defense_count']}",f"army:battle:{b['war']}:{b['province']}")])
        rows+=Keyboards.nav("screen:army"); await self.show(callback,"⚔️ <b>Активные битвы</b>\n\nВыберите бой:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("army:battle:"):
        _,_,warid,pidtxt=data.split(":",3); pid=int(pidtxt); battles={(_v45_battle_key(b['war'],b['province'])):b for b in _v45_active_battles(self.world)}; b=battles.get(_v45_battle_key(warid,pid))
        if not b: await self.show(callback,"Бой уже завершён.",Keyboards.simple_nav("army:battles")); return
        text=(f"⚔️ <b>Битва за {esc(self.world.province(pid).name)}</b>\n\n"
              f"🟢 Атакующий: {country_display(b['attacker'])} — {b['attack_count']} дивизий / {b['attack_power']:.0f}\n"
              f"🔴 Защитник: {country_display(b['defender'])} — {b['defense_count']} дивизий / {b['defense_power']:.0f}\n\n"
              "🤖 Генералы продолжают выполнять приказы автоматически.")
        await self.show(callback,text,Keyboards.simple_nav("army:battles")); return
    if data.startswith("general:autoassign:"):
        gid=data.split(":",2)[2]; ok,reason=self.army.auto_assign_general(gid); self.spawn(self.save_light()); await self.show(callback,reason,Keyboards.simple_nav(f"gen:view:{gid}")); return
    if data.startswith("general:order:"):
        _,_,gid,order,targettxt=data.split(":",4); target=None if targettxt=="none" else int(targettxt); ok,reason=self.army.set_general_order(gid,order,target); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"gen:view:{gid}")); return
    if data.startswith("general:target:"):
        gid=data.split(":",2)[2]; g=self.world.generals.get(gid); enemies=[]
        if g:
            enemies=[pid for pid in _v45_front_targets(self.world,country) if pid in self.world.provinces and self.world.province(pid).country!=country]
        rows=[[Keyboards.btn(self.world.province(pid).name,f"general:targetpick:{gid}:{pid}")] for pid in enemies[:50]]; rows+=Keyboards.nav(f"gen:view:{gid}"); await self.show(callback,"🎯 Выберите цель автоплана/наступления:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("general:targetpick:"):
        _,_,_,gid,pidtxt=data.split(":",4); pid=int(pidtxt)
        rows=[[Keyboards.btn("🤖 Запустить автоплан",f"general:order:{gid}:autoplan:{pid}")],[Keyboards.btn("⚔️ Ручное наступление",f"general:order:{gid}:attack:{pid}")],*Keyboards.nav(f"gen:view:{gid}")]
        await self.show(callback,"Выберите приказ генерала:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("general:cells:"):
        gid=data.split(":",2)[2]; g=self.world.generals.get(gid)
        if not g: await self.show(callback,"Генерал не найден."); return
        divs=[d for d in g.get("divisions",[]) if d in self.world.divisions]; selected=list(g.get("plan_cells") or g.get("cells") or []); own=sorted(self.world.country(country).province_ids)
        rows=[]
        for pid in own[:70]:
            mark="✅" if pid in selected else "▫️"; rows.append([Keyboards.btn(f"{mark} {self.world.province(pid).name}",f"general:celltoggle:{gid}:{pid}")])
        rows.append([Keyboards.btn(f"✅ Сохранить {len(divs)} клеток",f"general:cellsave:{gid}")]); rows+=Keyboards.nav(f"gen:view:{gid}")
        await self.show(callback,f"🗺️ <b>Линия генерала</b>\n\nДивизий: {len(divs)}\nНужно выбрать ровно {len(divs)} клеток.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("general:celltoggle:"):
        _,_,_,gid,pidtxt=data.split(":",4); pid=int(pidtxt); g=self.world.generals.get(gid)
        if not g: return
        selected=list(g.get("plan_cells") or g.get("cells") or [])
        if pid in selected: selected.remove(pid)
        elif len(selected)<len([d for d in g.get("divisions",[]) if d in self.world.divisions]): selected.append(pid)
        g["plan_cells"]=selected; self.world.mark_dirty(); await self.show(callback,f"Выбрано клеток: {len(selected)}/{len([d for d in g.get('divisions',[]) if d in self.world.divisions])}",Keyboards.simple_nav(f"general:cells:{gid}")); return
    if data.startswith("general:cellsave:"):
        gid=data.split(":",2)[2]; ok,reason=self.army.set_general_plan_cells(gid,self.world.generals.get(gid,{}).get("plan_cells",[])); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"gen:view:{gid}")); return
    await _v45_handle_army_prev(self,callback,data)
WorldApp.handle_army=_v45_handle_army

