_v45_on_callback_prev=WorldApp.on_callback
async def _v45_on_callback(self:WorldApp,callback:types.CallbackQuery)->None:
    data=str(callback.data or "").strip(); uid=int(callback.from_user.id)
    # New army/general/air/pvo callbacks are dispatched before the stable router.
    if data.startswith(("army:battles","army:battle:","general:","gen:","airstatus:","aircheckready:","airtakeoff:","airattachgen:","airattach:","airstrikev45:","airstrikev45type:","airstrikev45target:","airstrikev45country:","airstrikev45prov:","airmissilepick:","airmissileqty:","aircabpick:","airuavroute:","airplan:","airname:","airstormgen:","pvo:type:","pvo:types","pvo:engagements","pvoupgrade:")):
        await self.answer_callback(callback)
        country,err=self.require_country(uid)
        if not country:
            await self.show(callback,err,Keyboards.country_picker()); return
        if data.startswith(("army:","general:","gen:")):
            await self.handle_army(callback,data); return
        if data.startswith("air") or data.startswith("airstormgen:"):
            await self.handle_air(callback,data); return
        await self.handle_pvo(callback,data); return
    await _v45_on_callback_prev(self,callback)
WorldApp.on_callback=_v45_on_callback

