# Final V45 static map/PVO/air validations used by startup diagnostics.
def _v45_validate_contract(world:WorldState)->list[str]:
    errors=[]
    if len(world.provinces)!=100: errors.append("map: provinces != 100")
    counts={c:len(world.country(c).province_ids) for c in PLAYABLE_COUNTRIES}
    if counts!={COUNTRY_RAZBAGARE:34,COUNTRY_PEDAGOG:33,COUNTRY_MARKLAND:33}: errors.append(f"map counts: {counts}")
    for code,meta in V45_MAP_CONTRACT.items():
        if not world.province(meta["capital"]).capital: errors.append(f"capital flag missing:{code}")
        for pid in meta["cities"]:
            if not world.province(pid).city: errors.append(f"city flag missing:{code}:{pid}")
    for code in PLAYABLE_COUNTRIES:
        expected=set(V45_MAP_CONTRACT[code]["cities"]+[V45_MAP_CONTRACT[code]["capital"]])
        actual={pid for pid in world.country(code).province_ids if world.province(pid).building_level("radar")>0}
        if not expected.issubset(actual): errors.append(f"radar city coverage missing:{code}")
        if len(actual)<len(expected)+2: errors.append(f"radar random coverage missing:{code}")
    return errors

_v45_world_app_init_prev=WorldApp.__init__
def _v45_world_app_init(self:WorldApp,*args:Any,**kwargs:Any)->None:
    _v45_world_app_init_prev(self,*args,**kwargs)
    errors=_v45_validate_contract(self.world)
    if errors:
        self.world.add_log("v45_validation",None,{"errors":errors})
WorldApp.__init__=_v45_world_app_init

