# WORLD STRATEGY V45.1 — HARDENED UI / TIMING / COMMAND CONTROLS
# =============================================================================
# Keep V44.1 as the stable base. This layer fixes only V45 presentation and
# command edge cases; it does not replace the stable country/session router.

# ---- precise operation timing/status ---------------------------------------
def _v451_operation_plan_minutes(world: Any, group: dict[str, Any]) -> float:
    op=group.get("operation") or {}
    route=list(op.get("route") or [])
    if not route: return float(V45_AIR_ARMING_MINUTES+V45_AIR_TAKEOFF_MINUTES)
    speed=_v45_air_speed(group)
    weapon=op.get("weapon")
    outbound=max(0,len(route)-1)*speed
    if weapon=="missile":
        launch=int(op.get("launch",route[-1]))
        target=int(op.get("target",route[-1]))
        dist=_v42_graph_distance(world,launch,target,1000) or 0
        m=V45_MISSILES.get(op.get("missile"),{})
        return V45_AIR_ARMING_MINUTES+V45_AIR_TAKEOFF_MINUTES+outbound+float(dist)*float(m.get("speed",5.0))+outbound
    return V45_AIR_ARMING_MINUTES+V45_AIR_TAKEOFF_MINUTES+outbound+outbound


def _v451_operation_remaining(world: Any, g: dict[str,Any]) -> float:
    op=g.get("operation") or {}
    if not op: return 0.0
    now=float(world.game_minutes)
    phase=str(op.get("phase",""))
    if phase=="arming": return max(0.0,float(op.get("arm_complete_at",now))-now)
    if phase=="takeoff": return max(0.0,float(op.get("takeoff_end",now))-now)
    route=list(op.get("route") or [])
    idx=int(op.get("route_index",0))
    speed=_v45_air_speed(g)
    if phase=="flight":
        rem=max(0,(len(route)-1-idx))*speed-float(op.get("leg_progress",0.0))
        if op.get("weapon")=="missile" and idx < len(route)-1:
            launch=int(op.get("launch",route[-1])); cur=int(g.get("flight_province",route[idx]))
            if cur==launch:
                m=V45_MISSILES.get(op.get("missile"),{})
                return max(0,float(op.get("missile_remaining",0)))
        return max(0,rem)
    if phase=="missile": return max(0,float(op.get("missile_remaining",0)))
    if phase=="return": return max(0,(len(route)-1-idx))*speed-float(op.get("leg_progress",0.0))
    return 0.0


def _v451_render_operation_progress(world: Any,g:dict[str,Any])->str:
    op=g.get("operation") or {}
    if not op: return "Операция: нет."
    phase=str(op.get("phase","")); remain=_v451_operation_remaining(world,g)
    target=int(op.get("target",-1)); target_name=world.province(target).name if target in world.provinces else "—"
    total=_v451_operation_plan_minutes(world,g)
    phase_totals={
        "arming": V45_AIR_ARMING_MINUTES,
        "takeoff": V45_AIR_TAKEOFF_MINUTES,
        "flight": max(1,(len(list(op.get("route") or []))-1)*_v45_air_speed(g)),
        "missile": max(1,float(op.get("missile_total",1))),
        "return": max(1,(len(list(op.get("route") or []))-1)*_v45_air_speed(g)),
    }
    ptotal=float(phase_totals.get(phase,1)); done=max(0,min(ptotal,ptotal-remain)); pct=100*done/ptotal
    bar="🟩"*min(10,int(pct//10))+"⬜"*max(0,10-int(pct//10))
    payload=V45_MISSILES.get(op.get("missile"),{})
    if payload: means=payload.get("name")
    elif op.get("weapon")=="cab": means="КАБ"
    elif op.get("weapon")=="uav_payload": means="БПЛА"
    else: means=str(op.get("weapon","—"))
    return (f"📊 <b>Ход операции</b>\n\n{bar} <b>{pct:.0f}%</b>\n"
            f"Этап: <b>{esc(phase)}</b>\nСредство: <b>{esc(str(means))}</b>\n"
            f"Цель: <b>{esc(target_name)}</b>\n"
            f"Операция целиком: <b>{int(round(total))} мин.</b>\n"
            f"Осталось: <b>{int(round(remain))} мин.</b>")

Aviation.operation_remaining=_v451_operation_remaining
_v45_render_operation_progress=_v451_render_operation_progress

