async def _v451_handle_air(self:WorldApp,callback:types.CallbackQuery,data:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country:
        await self.show(callback,error,Keyboards.country_picker()); return
    if data.startswith("aircustomqtyconfirm:"):
        _,key,qtxt=data.split(":",2); q=int(qtxt)
        fields=self.aviation.airfields(country)
        if not fields: await self.show(callback,"❌ У страны нет рабочего аэродрома.",Keyboards.simple_nav("screen:air")); return
        rows=[[Keyboards.btn(self.world.province(pid).name,f"airfield:{key}:{q}:{pid}")] for pid in fields]
        rows+=Keyboards.nav(f"airmodel:{key}")
        await self.show(callback,f"✈️ Количество: <b>{q}</b> ед.\n\nВыберите аэродром:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("aircustomqty:"):
        key=data.split(":",1)[1]
        stock=int(self.world.country(country).warehouse.get(key,0))
        model=AIR_MODELS.get(key) or UAV_MODELS.get(key)
        p=self.player(callback.from_user.id)
        p.pending_input="air_custom_quantity"; p.pending_data={"model":key,"stock":stock,"expires_at":time.monotonic()+300}
        await self.show(callback,f"✏️ <b>{esc(model.name if model else key)}</b>\n\nВведите количество машин. Доступно: {stock}.",Keyboards.simple_nav(f"airmodel:{key}")); return
    if data.startswith("airfightermission:"):
        gid,mission=data.split(":",1)[1].split(":",1)
        g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        if g.get("model")!="fighter": await self.show(callback,"Этот раздел только для истребителей.",Keyboards.simple_nav(f"airgroup:{gid}")); return
        labels={"patrol":"🛡️ Патрулирование","intercept":"🎯 Перехват","superiority":"⭐ Воздушное превосходство","escort":"🛫 Сопровождение"}
        if mission not in labels: await self.show(callback,"Неизвестная задача истребителей.",Keyboards.simple_nav(f"airgroup:{gid}")); return
        g["mission"]=mission; g["manual"]=True; self.world.mark_dirty(); self.spawn(self.save_light())
        await self.show(callback,f"✅ Истребителям назначено: {labels[mission]}.",Keyboards.simple_nav(f"airgroup:{gid}")); return
    if data.startswith("airhelimission:"):
        gid,mission=data.split(":",1)[1].split(":",1)
        g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        if g.get("model")!="helicopter": await self.show(callback,"Этот раздел только для вертолётов.",Keyboards.simple_nav(f"airgroup:{gid}")); return
        labels={"support":"⚔️ Поддержка фронта","patrol":"🛡️ Патруль","transport":"🚁 Переброска"}
        if mission not in labels: await self.show(callback,"Неизвестная задача вертолётов.",Keyboards.simple_nav(f"airgroup:{gid}")); return
        g["mission"]=mission; g["manual"]=True; self.world.mark_dirty(); self.spawn(self.save_light())
        await self.show(callback,f"✅ Вертолётам назначено: {labels[mission]}.",Keyboards.simple_nav(f"airgroup:{gid}")); return
    if data.startswith("airfightermissions:"):
        gid=data.split(":",1)[1]
        rows=[[Keyboards.btn("🛡️ Патрулирование",f"airfightermission:{gid}:patrol")],[Keyboards.btn("🎯 Перехват",f"airfightermission:{gid}:intercept")],[Keyboards.btn("⭐ Воздушное превосходство",f"airfightermission:{gid}:superiority")],[Keyboards.btn("🛫 Сопровождение",f"airfightermission:{gid}:escort")],*Keyboards.nav(f"airgroup:{gid}")]
        await self.show(callback,"✈️ <b>Задачи истребителей</b>\n\nВыберите режим работы группы.",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airhelimissions:"):
        gid=data.split(":",1)[1]
        rows=[[Keyboards.btn("⚔️ Поддержка фронта",f"airhelimission:{gid}:support")],[Keyboards.btn("🛡️ Патруль",f"airhelimission:{gid}:patrol")],[Keyboards.btn("🚁 Переброска",f"airhelimission:{gid}:transport")],*Keyboards.nav(f"airgroup:{gid}")]
        await self.show(callback,"🚁 <b>Задачи вертолётов</b>",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("aircreatecustom:"):
        key=data.split(":",1)[1]; p=self.player(callback.from_user.id); p.pending_input="air_custom_quantity"; p.pending_data={"model":key,"expires_at":time.monotonic()+300}; await self.show(callback,"✏️ Введите своё количество машин:",Keyboards.simple_nav(f"airmodel:{key}")); return
    if data.startswith("airmodel:"):
        key=data.split(":",1)[1]; stock=int(self.world.country(country).warehouse.get(key,0))
        if stock<=0 and not self.world.country(country).infinite_weapons:
            await self.show(callback,"❌ На складе 0 единиц. Сначала произведите технику.",Keyboards.simple_nav("air:create")); return
        model=AIR_MODELS.get(key) or UAV_MODELS.get(key)
        buttons=[Keyboards.btn(str(q)+" ед.",f"airqty:{key}:{q}") for q in dict.fromkeys([1,5,10,min(25,max(1,stock))]) if q<=stock or self.world.country(country).infinite_weapons]
        buttons.append(Keyboards.btn("✏️ Своё количество",f"aircustomqty:{key}"))
        await self.show(callback,f"✈️ <b>{esc(model.name if model else key)}</b>\nНа складе: {stock}\n\nВыберите количество:",types.InlineKeyboardMarkup(inline_keyboard=[[b] for b in buttons]+Keyboards.nav("air:create"))); return
    if data.startswith("airgroup:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if g and g.get("country")==country:
            _v45_init_operation(g); model=AIR_MODELS.get(g.get("model")) or UAV_MODELS.get(g.get("model")); progress=_v451_render_operation_progress(self.world,g) if g.get("operation") else "Операция не запланирована."
            rows=[[Keyboards.btn("✏️ Название",f"airname:{gid}"),Keyboards.btn("💥 Новый удар",f"airstrikev45:{gid}")],[Keyboards.btn("📊 Статус операции",f"airstatus:{gid}"),Keyboards.btn("🛫 Перебазировать",f"airrebase:{gid}")]]
            if g.get("model")=="fighter": rows.append([Keyboards.btn("🎯 Задачи истребителей",f"airfightermissions:{gid}")])
            if g.get("model")=="helicopter": rows.append([Keyboards.btn("🚁 Задачи вертолётов",f"airhelimissions:{gid}")])
            if g.get("model")=="stormtrooper": rows.append([Keyboards.btn("👤 Прикрепить к генералу",f"airstormgen:{gid}")])
            rows += Keyboards.nav("air:groups")
            text=f"✈️ <b>{esc(g.get('name',''))}</b>\n\nМодель: {esc(model.name if model else g.get('model'))}\nКоличество: {g.get('quantity',0)}\nСкорость: {_v45_air_speed(g):.0f} мин/пров.\nБаза: {self.world.province(g['airfield_province']).name}\nПоложение: {self.world.province(_v42_group_position(g)).name}\n\n{progress}"
            await self.show(callback,text,types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("airstatus:"):
        gid=data.split(":",1)[1]; g=self.world.air_groups.get(gid)
        if not g or g.get("country")!=country: await self.show(callback,"❌ Авиагруппа не найдена.",Keyboards.simple_nav("air:groups")); return
        progress=_v451_render_operation_progress(self.world,g)
        op=g.get("operation") or {}; rows=[]
        if op.get("phase")=="arming": rows.append([Keyboards.btn("✅ Проверить подготовку",f"aircheckready:{gid}")])
        if op.get("phase")=="ready_takeoff": rows.append([Keyboards.btn("🛫 Разрешить взлёт",f"airtakeoff:{gid}")])
        await self.show(callback,f"✈️ <b>{esc(g.get('name',''))}</b>\n\n{progress}",types.InlineKeyboardMarkup(inline_keyboard=rows+Keyboards.nav(f"airgroup:{gid}"))); return
    await _v451_handle_air_prev(self,callback,data)
