_v451_process_text_prev=WorldApp.process_text_input
async def _v451_process_text_input(self:WorldApp,player:Any,value:str)->str:
    if str(player.pending_input or "")=="air_custom_quantity":
        pdata=dict(player.pending_data or {}); key=str(pdata.get("model","")); player.clear_input(); country=self.country_for(player.user_id)
        if not country: return "❌ Сначала выберите страну."
        try: q=_v44_parse_int(value)
        except Exception: q=0
        stock=int(self.world.country(country).warehouse.get(key,0))
        if q<=0: return "❌ Количество должно быть больше нуля."
        if q>stock and not self.world.country(country).infinite_weapons: return f"❌ На складе только {stock} ед."
        setattr(player,"_v19_post_route",f"aircustomqtyconfirm:{key}:{q}")
        return f"✅ Количество принято: {q} ед. Выберите аэродром."
    return await _v451_process_text_prev(self,player,value)
WorldApp.process_text_input=_v451_process_text_input

