async def _v451_general_view(self:WorldApp,callback:types.CallbackQuery,gid:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country: await self.show(callback,error,Keyboards.country_picker()); return
    g=self.world.generals.get(gid)
    if not g or g.get("country")!=country: await self.show(callback,"❌ Генерал не найден.",Keyboards.simple_nav("army:generals")); return
    divs=[d for d in (self.world.divisions.get(x) for x in g.get("divisions",[])) if d]
    order=V45_GENERAL_ORDERS.get(g.get("order"),"🛑 Удержание")
    rows=[[Keyboards.btn("🤖 Автораспределить дивизии",f"general:autoassign:{gid}")],[Keyboards.btn("🗺️ Выбрать клетки линии",f"general:cells:{gid}")],[Keyboards.btn("🎯 Цель/приказ",f"general:target:{gid}")],[Keyboards.btn("⛔ Стоп",f"general:order:{gid}:stop:none")]]
    rows += Keyboards.nav("screen:army")
    await self.show(callback,f"👤 <b>{esc(g.get('name',gid))}</b>\n\nДивизий: <b>{len(divs)}/{MAX_DIVISIONS_PER_GENERAL}</b>\nТекущий приказ: <b>{order}</b>\nКлеток линии: <b>{len(g.get('plan_cells',g.get('cells',[])))}</b>\nШтаб: {esc(self.world.province(int(g.get('hq_province',0))).name)}",types.InlineKeyboardMarkup(inline_keyboard=rows))

_v451_handle_army_prev=WorldApp.handle_army
async def _v451_handle_army(self:WorldApp,callback:types.CallbackQuery,data:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country: await self.show(callback,error,Keyboards.country_picker()); return
    if data.startswith("gen:view:"):
        await _v451_general_view(self,callback,data.split(":",2)[2]); return
    if data.startswith("general:celltoggle:"):
        _,_,_,gid,pidtxt=data.split(":",4); pid=int(pidtxt); g=self.world.generals.get(gid)
        if not g or g.get("country")!=country: return
        selected=list(g.get("plan_cells",[])); limit=len([d for d in g.get("divisions",[]) if d in self.world.divisions])
        if pid in selected: selected.remove(pid)
        elif len(selected)<limit: selected.append(pid)
        g["plan_cells"]=selected; self.world.mark_dirty(); await self.show(callback,f"Выбрано клеток: {len(selected)}/{limit}",Keyboards.simple_nav(f"general:cells:{gid}")); return
    if data.startswith("general:order:"):
        _,_,gid,order,targettxt=data.split(":",4); target=None if targettxt=="none" else int(targettxt); ok,reason=self.army.set_general_order(gid,order,target); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav(f"gen:view:{gid}")); return
    await _v451_handle_army_prev(self,callback,data)
WorldApp.handle_army=_v451_handle_army

# ---- PVO full deploy flow + UI routing ------------------------------------
_v451_handle_pvo_prev=WorldApp.handle_pvo
async def _v451_handle_pvo(self:WorldApp,callback:types.CallbackQuery,data:str)->None:
    country,error=self.require_country(callback.from_user.id)
    if not country: await self.show(callback,error,Keyboards.country_picker()); return
    if data.startswith("pvomodel:"):
        key=data.split(":",1)[1]; m=V45_PVO_MODELS.get(key)
        if not m: return
        rows=[[Keyboards.btn("1 ед.",f"pvoqty:{key}:1")],[Keyboards.btn("3 ед.",f"pvoqty:{key}:3")],[Keyboards.btn("5 ед.",f"pvoqty:{key}:5")],[Keyboards.btn("✏️ Свое количество",f"pvoinput:{key}")],*Keyboards.nav("pvo:types")]
        await self.show(callback,f"🛡️ <b>{esc(m['name'])}</b>\n\nТип: {esc(V45_PVO_TYPES[m['type']]['name'])}\nСкорость перехвата: {m['interceptor_speed']:.1f} мин/пров.\nПротив дронов: {m['drone_chance']*100:.0f}%\nПротив самолётов: {m['aircraft_chance']*100:.0f}%\nПротив ракет: {m['missile_chance']*100:.0f}%",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvoqty:"):
        _,key,qtxt=data.split(":",2); q=int(qtxt); m=V45_PVO_MODELS.get(key)
        if not m: return
        provinces=[]
        for pid in self.world.country(country).province_ids:
            if _v45_pvo_can_cover(self.pvo,country,pid,key): provinces.append(pid)
        rows=[[Keyboards.btn(self.world.province(pid).name,f"pvoprov:{key}:{q}:{pid}")] for pid in provinces[:70]]+Keyboards.nav(f"pvomodel:{key}")
        await self.show(callback,"📍 Выберите провинцию размещения ПВО:",types.InlineKeyboardMarkup(inline_keyboard=rows)); return
    if data.startswith("pvoprov:"):
        _,key,qtxt,pidtxt=data.split(":",3); q=int(qtxt); pid=int(pidtxt); ok,reason,uid=self.pvo.deploy(country,key,q,pid); self.spawn(self.save_light()); await self.show(callback,("✅ " if ok else "❌ ")+reason,Keyboards.simple_nav("screen:pvo")); return
    if data.startswith("pvoinput:"):
        key=data.split(":",1)[1]; p=self.player(callback.from_user.id); p.pending_input="pvo_custom_quantity"; p.pending_data={"model":key,"expires_at":time.monotonic()+300}; await self.show(callback,"✏️ Введите количество ПВО:",Keyboards.simple_nav(f"pvomodel:{key}")); return
    await _v451_handle_pvo_prev(self,callback,data)
WorldApp.handle_pvo=_v451_handle_pvo
_v451_process_text2_prev=WorldApp.process_text_input
async def _v451_process_text_input2(self:WorldApp,player:Any,value:str)->str:
    if str(player.pending_input or "")=="pvo_custom_quantity":
        pdata=dict(player.pending_data or {}); key=str(pdata.get("model","")); player.clear_input();
        try:q=_v44_parse_int(value)
        except Exception:q=0
        if q<=0:return "❌ Количество должно быть больше нуля."
        setattr(player,"_v19_post_route",f"pvoqty:{key}:{q}")
        return f"✅ Количество принято: {q}. Выберите провинцию размещения."
    return await _v451_process_text2_prev(self,player,value)
