# ---- single final V45 router: all new prefixes are intercepted here --------
_v451_on_callback_prev=WorldApp.on_callback
async def _v451_on_callback(self:WorldApp,callback:types.CallbackQuery)->None:
    data=str(callback.data or "").strip(); uid=int(callback.from_user.id)
    new_prefixes=(
        "army:battles","army:battle:","gen:view:","general:","airname:","airstatus:","aircheckready:","airtakeoff:",
        "airattachgen:","airstrikev45:","airstrikev45type:","airstrikev45target:","airstrikev45country:","airstrikev45prov:",
        "airmissilepick:","airmissileqty:","aircabpick:","airuavroute:","airplan:","airstormgen:","airfightermissions:",
        "airfightermission:","airhelimissions:","airhelimission:","aircustomqty:","aircustomqtyconfirm:","airmodel:","pvomodel:","pvoqty:","pvoprov:",
        "pvoinput:","pvo:type:","pvo:types","pvo:engagements","pvoupgrade:"
    )
    if data.startswith(new_prefixes):
        await self.answer_callback(callback)
        country,err=self.require_country(uid)
        if not country:
            await self.show(callback,err,Keyboards.country_picker()); return
        if data.startswith(("army:","gen:","general:")):
            await self.handle_army(callback,data); return
        if data.startswith("air"):
            await self.handle_air(callback,data); return
        await self.handle_pvo(callback,data); return
    await _v451_on_callback_prev(self,callback)
WorldApp.on_callback=_v451_on_callback

