# V45.2 UX: expose active-battle control directly in the admin home menu.
async def _v452_render_admin_home(self: WorldApp, target: types.Message|types.CallbackQuery) -> None:
    if not self.is_admin(target.from_user.id):
        await self.show(target, "❌ Нет прав администратора.", Keyboards.country_picker()); return
    result=self.diagnostics.run(); active_wars=result["counts"]["wars"]
    battles_count=len(_v45_active_battles(self.world))
    text=("🛠️ <b>Панель администратора</b>\n\n"
          f"Игровое время: {game_time_text(self.world)}\n"
          f"Скорость: x{self.world.speed:g}\n"
          f"Статус: {'⏸️ Пауза' if self.world.paused else '▶️ Игра'}\n"
          f"Провинций: {len(self.world.provinces)}\n"
          f"Игроков: {len(self.world.players)}\n"
          f"Войн: {active_wars}\n"
          f"Активных боёв: {battles_count}\n"
          f"Диагностика: {'✅ OK' if result['ok'] else '❌ Ошибки'}")
    action_items=list(ADMIN_ACTIONS.items()); rows=[]
    for i in range(0,len(action_items),2):
        rows.append([Keyboards.btn(action_items[i][1],f"admin:section:{action_items[i][0]}")] +
                    ([Keyboards.btn(action_items[i+1][1],f"admin:section:{action_items[i+1][0]}")] if i+1<len(action_items) else []))
    rows.append([Keyboards.btn("⚔️ Контроль боёв", "admin:battles")])
    rows.append([Keyboards.btn("⏱️ x1", "admin:speed:1"),Keyboards.btn("x2","admin:speed:2"),Keyboards.btn("x5","admin:speed:5"),Keyboards.btn("x10","admin:speed:10")])
    rows.append([Keyboards.btn("⏸️ Пауза", "admin:pause:1"),Keyboards.btn("▶️ Продолжить","admin:pause:0")])
    rows.append([Keyboards.btn("💾 Сохранить","admin:save"),Keyboards.btn("🩺 Диагностика","admin:diag")])
    rows.append([Keyboards.btn("🚪 Выйти из админки","admin:logout")])
    await self.show(target,text,types.InlineKeyboardMarkup(inline_keyboard=rows))
WorldApp.render_admin_home=_v452_render_admin_home

