# V45.3: Ignore ordinary text messages unless the game is waiting for a text input.
# Keep all existing pending-input flows (country code, quantities, names, admin/server auth, etc.).
_v453_on_text_previous = WorldApp.on_text
async def _v453_on_text(self: WorldApp, message: types.Message) -> None:
    if not getattr(message, "text", None) or getattr(message, "from_user", None) is None:
        return
    uid = int(message.from_user.id)
    # Do not register a new player merely because they sent unrelated text.
    # A pending input can only exist for a player already known to the game.
    player = self.world.players.get(uid)
    if player is None or not str(getattr(player, "pending_input", "") or ""):
        return
    username = getattr(message.from_user, "username", "") or ""
    if username:
        player.touch(username)
    await _v453_on_text_previous(self, message)

WorldApp.on_text = _v453_on_text
GAME_VERSION = "45.3.0-ignore-unsolicited-text"

# V45.4 reliability fixes ------------------------------------------------------
# Keep conquered province ownership when loading a save. Older map-alignment
# wrappers normalized owners to the initial map, which erased territorial changes.
_ws_from_dict_before_persistence_fix = WorldState.from_dict

def _ws_from_dict_preserve_saved_owners(self: WorldState, data: dict[str, Any]) -> None:
    raw_provinces = data.get("provinces", {}) if isinstance(data, dict) else {}
    saved_owners: dict[int, str] = {}
    saved_sea_access: dict[int, bool] = {}
    if isinstance(raw_provinces, dict):
        for raw_pid, raw_province in raw_provinces.items():
            if not isinstance(raw_province, dict):
                continue
            try:
                pid = int(raw_pid)
            except (TypeError, ValueError):
                continue
            owner = raw_province.get("country")
            if owner in PLAYABLE_COUNTRIES:
                saved_owners[pid] = str(owner)
            if "sea_access" in raw_province:
                saved_sea_access[pid] = bool(raw_province.get("sea_access"))

    result = _ws_from_dict_before_persistence_fix(self, data)

    # Restore only valid country IDs from the saved world; unknown values are
    # left at the normalized fallback rather than creating invalid country keys.
    for pid, owner in saved_owners.items():
        province = self.provinces.get(pid)
        if province is not None and owner in self.countries:
            province.country = owner
    for pid, sea_access in saved_sea_access.items():
        province = self.provinces.get(pid)
        if province is not None:
            province.sea_access = sea_access

    for code, country in self.countries.items():
        country.province_ids = sorted(
            pid for pid, province in self.provinces.items() if province.country == code
        )
    return result

WorldState.from_dict = _ws_from_dict_preserve_saved_owners


# If the primary JSON is corrupt, attempt the backup and previous save before
# falling back to a clean world. The original loader only tried the backup when
# the primary file was absent, not when it existed but could not be parsed.
def _ws_save_manager_load_with_recovery(self: SaveManager, world: WorldState) -> list[str]:
    with self.lock:
        candidates = (
            (self.primary, "primary"),
            (self.backup, "backup"),
            (self.previous, "previous"),
        )
        failures: list[str] = []
        for path, label in candidates:
            if not path.exists():
                continue
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if not isinstance(data, dict):
                    raise ValueError("save root must be a JSON object")
                world.from_dict(data)
                warnings = list(world.validate())
                if label != "primary":
                    warnings.insert(0, f"Основное сохранение недоступно; загружена копия: {path.name}")
                return warnings
            except Exception as exc:
                failures.append(f"{path.name}: {type(exc).__name__}: {exc}")

        # Rebuild a clean, internally consistent starting world if all files are bad.
        if failures:
            world._reset_world()
            return ["Не удалось загрузить ни одно сохранение; создан новый мир.", *failures[:3]]
        return []

SaveManager.load = _ws_save_manager_load_with_recovery

# Flush pending changes on a graceful host shutdown, instead of relying only on
# the periodic autosave interval.
_ws_start_before_final_save = WorldApp.start
async def _ws_start_with_final_save(self: WorldApp, bot: Bot) -> None:
    try:
        await _ws_start_before_final_save(self, bot)
    finally:
        if self.world.dirty:
            try:
                await asyncio.to_thread(self.save_manager.save, self.world, True)
                self.world.dirty = False
            except Exception as exc:
                # Keep shutdown visible in hosting logs; never hide the original
                # polling/startup error with a second exception from saving.
                print(f"[WORLD STRATEGY] Final save failed: {type(exc).__name__}: {exc}")

WorldApp.start = _ws_start_with_final_save
